  public void ProfileTree_AfterSelect(object sender, TreeViewEventArgs e)
  {
    if (ccVars.Pages.Count == 0)
      return;
    buCadCamResVer5.TreeNodeSettings selectedNode = (buCadCamResVer5.TreeNodeSettings) ((TreeView) sender).SelectedNode;
    if (clsItem.FrmProfileJob.tree_jobs.Nodes != null & clsItem.FrmProfileJob.tree_jobs.SelectedNode != null && clsItem.FrmProfileJob.tree_jobs.SelectedNode.Parent != null)
    {
      for (int index1 = 0; index1 <= clsItem.FrmProfileJob.tree_jobs.Nodes.Count - 1; ++index1)
      {
        clsItem.FrmProfileJob.tree_jobs.Nodes[index1].ForeColor = Color.Black;
        if (clsItem.FrmProfileJob.tree_jobs.Nodes[index1].Nodes != null)
        {
          for (int index2 = 0; index2 <= clsItem.FrmProfileJob.tree_jobs.Nodes[index1].Nodes.Count - 1; ++index2)
            clsItem.FrmProfileJob.tree_jobs.Nodes[index1].Nodes[index2].ForeColor = buProfileCalc.varProfileVisualSettings.TreeItemColor;
        }
      }
    }
    switch (selectedNode.Command)
    {
      case "profileitemfirst":
        this.SelProfileTreeIndex = 0;
        if (buProfileCalc.varProfileRunSettings.activeProfileIndex != 0 && ccVars.Action != 0 & !ProfileTempVars.OperationEditing)
          this.doReset();
        if (this.activeProfile.FirstItem != null)
        {
          clsItem.FrmProfileJob.tree_jobs.Nodes[0].Nodes[0].ForeColor = buProfileCalc.varProfileVisualSettings.TreeItemSelectedColor;
          if (clsItem.FrmProfileJob.tree_jobs.SelectedNode != null)
          {
            clsItem.FrmProfileJob.tree_jobs.SelectedNode.ForeColor = buProfileCalc.varProfileVisualSettings.TreeItemSelectedColor;
            buProfileCalc.varProfileSettings.XDirRefType = this.activeProfile.FirstItem.XReferanceLocation;
          }
          clsInit.appProfile.doSetActiveProfile(0);
          buProfileCalc.varProfileRunSettings.activeOPIndex = -1;
        }
        this.profileOperation_0 = (buEyeBaseVer5.Apps.ProfileOperation) null;
        break;
      case "profileitemsecond":
        this.SelProfileTreeIndex = 1;
        if (buProfileCalc.varProfileRunSettings.activeProfileIndex != 1 && ccVars.Action != 0 & !ProfileTempVars.OperationEditing)
          this.doReset();
        if (this.activeProfile.SecondItem != null)
        {
          clsItem.FrmProfileJob.tree_jobs.Nodes[0].Nodes[1].ForeColor = buProfileCalc.varProfileVisualSettings.TreeItemSelectedColor;
          if (clsItem.FrmProfileJob.tree_jobs.SelectedNode != null)
          {
            clsItem.FrmProfileJob.tree_jobs.SelectedNode.ForeColor = buProfileCalc.varProfileVisualSettings.TreeItemSelectedColor;
            buProfileCalc.varProfileSettings.XDirRefType = this.activeProfile.SecondItem.XReferanceLocation;
          }
          clsInit.appProfile.doSetActiveProfile(1);
          buProfileCalc.varProfileRunSettings.activeOPIndex = -1;
        }
        this.profileOperation_0 = (buEyeBaseVer5.Apps.ProfileOperation) null;
        break;
      case "profileop":
        this.profileOperation_0 = (buEyeBaseVer5.Apps.ProfileOperation) null;
        if (selectedNode.ClassIndex >= 0 & selectedNode.ClassSubIndex >= 0)
        {
          if (buProfileCalc.varProfileRunSettings.activeProfileIndex != selectedNode.ClassIndex)
            clsInit.appProfile.doSetActiveProfile(selectedNode.ClassIndex);
          this.SelProfileTreeIndex = buProfileCalc.varProfileRunSettings.activeProfileIndex;
          clsInit.appProfile.doSetActiveProfileOP(selectedNode.ClassIndex, selectedNode.ClassSubIndex);
          if (selectedNode.ClassIndex == 0 & this.activeProfile.FirstItem != null)
          {
            if (selectedNode.ClassSubIndex <= this.activeProfile.FirstItem.Operations.Count - 1)
              this.profileOperation_0 = this.activeProfile.FirstItem.Operations[selectedNode.ClassSubIndex];
            clsItem.FrmProfileJob.tree_jobs.Nodes[0].Nodes[0].ForeColor = buProfileCalc.varProfileVisualSettings.TreeItemSelectedColor;
            buProfileCalc.varProfileSettings.XDirRefType = this.activeProfile.FirstItem.XReferanceLocation;
            if (ProfileTempVars.OperationEditing && buProfileCalc.varProfileRunSettings.activeProfileIndex >= 0 & buProfileCalc.varProfileRunSettings.activeOPIndex >= 0)
              this.doEditOperation(buProfileCalc.varProfileRunSettings.activeProfileIndex, buProfileCalc.varProfileRunSettings.activeOPName);
          }
          if (selectedNode.ClassIndex == 1 & this.activeProfile.SecondItem != null)
          {
            if (selectedNode.ClassSubIndex <= this.activeProfile.SecondItem.Operations.Count - 1)
              this.profileOperation_0 = this.activeProfile.SecondItem.Operations[selectedNode.ClassSubIndex];
            clsItem.FrmProfileJob.tree_jobs.Nodes[0].Nodes[1].ForeColor = buProfileCalc.varProfileVisualSettings.TreeItemSelectedColor;
            buProfileCalc.varProfileSettings.XDirRefType = this.activeProfile.SecondItem.XReferanceLocation;
            if (ProfileTempVars.OperationEditing && buProfileCalc.varProfileRunSettings.activeProfileIndex >= 0 & buProfileCalc.varProfileRunSettings.activeOPIndex >= 0)
              this.doEditOperation(buProfileCalc.varProfileRunSettings.activeProfileIndex, buProfileCalc.varProfileRunSettings.activeOPName);
          }
        }
        this.ProfileTree_OpColorUpdate();
        if (!(buProfileCalc.varProfileSettings.MultipleEdit & ProfileTempVars.OperationEditing))
          break;
        this.doAddSelectedOperations();
        break;
    }
  }

  public void ProfileTree_AfterCheck(object sender, TreeViewEventArgs e)
  {
    if (ccVars.Pages.Count == 0)
      return;
    buCadCamResVer5.TreeNodeSettings node = (buCadCamResVer5.TreeNodeSettings) e.Node;
    if (this.Changing || node == null)
      return;
    bool flag = node.Checked;
    switch (node.Command)
    {
      case "profileitem":
        if (node.ClassIndex >= 0)
          break;
        break;
      case "profileop":
        if (node.ClassIndex == 0 && this.activeProfile.FirstItem != null && node.ClassSubIndex >= 0 & node.ClassSubIndex <= this.activeProfile.FirstItem.Operations.Count - 1)
        {
          this.activeProfile.FirstItem.Operations[node.ClassSubIndex].Selected = flag;
          this.DrawActiveProfile();
          if (buProfileCalc.varProfileSettings.MultipleEdit)
            this.doAddSelectedOperations();
        }
        if (node.ClassIndex != 1 || this.activeProfile.SecondItem == null || !(node.ClassSubIndex >= 0 & node.ClassSubIndex <= this.activeProfile.SecondItem.Operations.Count - 1))
          break;
        this.activeProfile.SecondItem.Operations[node.ClassSubIndex].Selected = flag;
        this.DrawActiveProfile();
        if (!buProfileCalc.varProfileSettings.MultipleEdit)
          break;
        this.doAddSelectedOperations();
        break;
    }
  }

  public void ProfileTree_KeyDown(object sender, KeyEventArgs e)
  {
    if (e.KeyCode == Keys.Delete && buProfileCalc.varProfileRunSettings.activeProfileIndex >= 0 & buProfileCalc.varProfileRunSettings.activeProfileIndex <= 1)
    {
      if (buProfileCalc.varProfileRunSettings.activeOPIndex == -1)
        this.cmdMenuCommand((object) clsItem.FrmProfileJob.mnu_deleteprofile, (EventArgs) null);
      else
        this.cmdMenuCommand((object) clsItem.FrmProfileJob.mnu_remove, (EventArgs) null);
    }
    if (e.KeyCode == Keys.E && buProfileCalc.varProfileRunSettings.activeProfileIndex >= 0 & buProfileCalc.varProfileRunSettings.activeProfileIndex <= 1)
    {
      if (buProfileCalc.varProfileRunSettings.activeOPIndex == -1)
        this.cmdMenuCommand((object) clsItem.FrmProfileJob.mnu_editprofile, (EventArgs) null);
      else
        this.cmdMenuCommand((object) clsItem.FrmProfileJob.mnu_edit, (EventArgs) null);
    }
    if (e.KeyCode == Keys.C && buProfileCalc.varProfileRunSettings.activeProfileIndex >= 0 & buProfileCalc.varProfileRunSettings.activeProfileIndex <= 1)
    {
      if (buProfileCalc.varProfileRunSettings.activeOPIndex == -1)
        this.cmdMenuCommand((object) clsItem.FrmProfileJob.mnu_copyprofile, (EventArgs) null);
      else
        this.cmdMenuCommand((object) clsItem.FrmProfileJob.mnu_copy, (EventArgs) null);
    }
    if (e.KeyCode != Keys.M || !(buProfileCalc.varProfileRunSettings.activeProfileIndex >= 0 & buProfileCalc.varProfileRunSettings.activeProfileIndex <= 1) || buProfileCalc.varProfileRunSettings.activeOPIndex < 0)
      return;
    this.cmdMenuCommand((object) clsItem.FrmProfileJob.mnu_move, (EventArgs) null);
  }

