  public void ProfileTree_OpColorUpdate()
  {
    buEyeBaseVer5.Apps.ProfileItem profileItem = clsInit.cProfile.SelectActiveProfile(this.activeProfile.FirstItem, this.activeProfile.SecondItem, ref buProfileCalc.varProfileRunSettings.activeProfileIndex);
    if (profileItem == null)
      return;
    buCadCamResVer5.TreeNodeSettings node = clsItem.FrmProfileJob.tree_jobs.Nodes[0] as buCadCamResVer5.TreeNodeSettings;
    if (!(node.Nodes != null & buProfileCalc.varProfileRunSettings.activeProfileIndex >= 0 & buProfileCalc.varProfileRunSettings.activeProfileIndex <= node.Nodes.Count - 1) || node.Nodes == null)
      return;
    for (int index1 = 0; index1 <= node.Nodes.Count - 1; ++index1)
    {
      for (int index2 = 0; index2 <= node.Nodes[index1].Nodes.Count - 1; ++index2)
      {
        node.Nodes[index1].Nodes[index2].ForeColor = Color.Black;
        if (index2 <= profileItem.Operations.Count - 1)
        {
          if (profileItem.Operations[index2].infoList.Count > 0)
            node.Nodes[index1].Nodes[index2].ForeColor = buProfileCalc.varProfileVisualSettings.TreeOPInfoColor;
          if (profileItem.Operations[index2].warningList.Count > 0)
            node.Nodes[index1].Nodes[index2].ForeColor = buProfileCalc.varProfileVisualSettings.TreeOPWarningColor;
          if (profileItem.Operations[index2].errorList.Count > 0)
            node.Nodes[index1].Nodes[index2].ForeColor = buProfileCalc.varProfileVisualSettings.TreeOPErrorColor;
        }
        if (index1 == buProfileCalc.varProfileRunSettings.activeProfileIndex & index2 == buProfileCalc.varProfileRunSettings.activeOPIndex)
          node.Nodes[buProfileCalc.varProfileRunSettings.activeProfileIndex].Nodes[index2].ForeColor = buProfileCalc.varProfileVisualSettings.TreeOPSelectedColor;
      }
    }
  }

  public void DepthDGV_CellValueChanged(object sender, DataGridViewCellEventArgs e)
  {
    try
    {
      if (!ProfileTempVars.DepthInited)
        return;
      ProfileTempVars.DepthForced = true;
      ProfileTempVars.DepthInited = false;
      ProfileTempVars.OperationDepths.Clear();
      ShapeUpdateArg Data2 = new ShapeUpdateArg(buProfileCalc.varProfileRunSettings.ShapeDataParameters);
      Data2.Command = "DepthChanged";
      for (int index1 = 0; index1 <= clsItem.FrmProfileDepths.DGV_Depths.Rows.Count - 1; ++index1)
      {
        DepthPositions depthPositions = new DepthPositions();
        bool flag = false;
        for (int index2 = 1; index2 <= clsItem.FrmProfileDepths.DGV_Depths.Columns.Count - 1; ++index2)
        {
          if (index2 == 1)
          {
            if (buNumeric5.IsNumeric(clsItem.FrmProfileDepths.DGV_Depths.Rows[index1].Cells[index2].Value.ToString()))
              depthPositions.TopPosition = double.Parse(clsItem.FrmProfileDepths.DGV_Depths.Rows[index1].Cells[index2].Value.ToString());
            else
              flag = true;
          }
          if (index2 == 2)
          {
            if (buNumeric5.IsNumeric(clsItem.FrmProfileDepths.DGV_Depths.Rows[index1].Cells[index2].Value.ToString()))
            {
              if (buProfileCalc.varProfileRunSettings.ShapeDataParameters.selectedPlane == planeBoxNames.Top | buProfileCalc.varProfileRunSettings.ShapeDataParameters.selectedPlane == planeBoxNames.Back | buProfileCalc.varProfileRunSettings.ShapeDataParameters.selectedPlane == planeBoxNames.Free)
              {
                depthPositions.Depth = -double.Parse(clsItem.FrmProfileDepths.DGV_Depths.Rows[index1].Cells[index2].Value.ToString());
                depthPositions.BottomPosition = depthPositions.TopPosition - Math.Abs(depthPositions.Depth);
              }
              if (buProfileCalc.varProfileRunSettings.ShapeDataParameters.selectedPlane == planeBoxNames.Front | buProfileCalc.varProfileRunSettings.ShapeDataParameters.selectedPlane == planeBoxNames.Bottom)
              {
                depthPositions.Depth = double.Parse(clsItem.FrmProfileDepths.DGV_Depths.Rows[index1].Cells[index2].Value.ToString());
                depthPositions.BottomPosition = depthPositions.TopPosition + Math.Abs(depthPositions.Depth);
              }
            }
            else
              flag = true;
          }
          if (index2 == 3)
            depthPositions.PeckingUp = bool.Parse(clsItem.FrmProfileDepths.DGV_Depths.Rows[index1].Cells[index2].Value.ToString());
          if (index2 == 4)
          {
            if (buNumeric5.IsNumeric(clsItem.FrmProfileDepths.DGV_Depths.Rows[index1].Cells[index2].Value.ToString()))
              depthPositions.PeckingUpDistance = double.Parse(clsItem.FrmProfileDepths.DGV_Depths.Rows[index1].Cells[index2].Value.ToString());
            else
              flag = true;
          }
          if (index2 == 5)
          {
            if (buNumeric5.IsNumeric(clsItem.FrmProfileDepths.DGV_Depths.Rows[index1].Cells[index2].Value.ToString()))
              depthPositions.PlungeFeed = double.Parse(clsItem.FrmProfileDepths.DGV_Depths.Rows[index1].Cells[index2].Value.ToString());
            else
              flag = true;
          }
          if (index2 == 6)
          {
            if (buNumeric5.IsNumeric(clsItem.FrmProfileDepths.DGV_Depths.Rows[index1].Cells[index2].Value.ToString()))
              depthPositions.SpindleSpeed = double.Parse(clsItem.FrmProfileDepths.DGV_Depths.Rows[index1].Cells[index2].Value.ToString());
            else
              flag = true;
          }
          if (index2 == 7)
          {
            if (buNumeric5.IsNumeric(clsItem.FrmProfileDepths.DGV_Depths.Rows[index1].Cells[index2].Value.ToString()))
              depthPositions.Wait = double.Parse(clsItem.FrmProfileDepths.DGV_Depths.Rows[index1].Cells[index2].Value.ToString());
            else
              flag = true;
          }
        }
        if (!flag)
          ProfileTempVars.OperationDepths.Add(depthPositions);
      }
      this.OnlineOperation((object) null, (object) Data2, (object) null);
      ProfileTempVars.DepthInited = true;
    }
    catch (Exception ex)
    {
    }
  }

