      ProfileTempVars.DepthInited = true;
    }
  }

  public void DepthsFill(buEyeBaseVer5.Apps.ProfileOperationData OPData)
  {
    ProfileTempVars.DepthInited = false;
    clsItem.FrmProfileDepths.DGV_Depths.Rows.Clear();
    for (int index = 0; index <= OPData.DepthValues.Count - 1; ++index)
    {
      object[] objArray = this.AddNewDepthRow(index + 1, OPData.DepthValues[index].TopPosition, Math.Abs(OPData.DepthValues[index].Depth), OPData.DepthValues[index].PeckingUp, OPData.DepthValues[index].PeckingUpDistance, OPData.DepthValues[index].PlungeFeed, OPData.DepthValues[index].SpindleSpeed, OPData.DepthValues[index].Wait);
      clsItem.FrmProfileDepths.DGV_Depths.Rows.Add(objArray);
    }
    ProfileTempVars.DepthInited = true;
  }

  public object[] AddNewDepthRow(
    int index,
    double pos,
    double depth,
    bool pecking,
    double peckingup,
    double plunge,
    double spindle,
    double wait)
  {
    return new object[8]
    {
      (object) index,
      (object) Math.Round(pos, 3),
      (object) Math.Round(depth, 3),
      (object) pecking,
      (object) Math.Round(peckingup, 3),
      (object) Math.Round(plunge, 3),
      (object) Math.Round(spindle, 3),
      (object) Math.Round(wait, 3)
    };
  }

  public void PlaneTypesSelectedIndexChanged(object sender, EventArgs e)
  {
    ProfileTempVars.PlaneInited = false;
    if (clsItem.FrmProfilePlanes.lst_types.SelectedIndex >= 0 & clsItem.FrmProfilePlanes.lst_types.SelectedIndex <= clsProfile.selectedPlanes.Count - 1)
    {
      ProfileTempVars.PlaneSelectedIndex = clsItem.FrmProfilePlanes.lst_types.SelectedIndex;
      clsItem.FrmProfilePlanes.spn_angle.Value = (Decimal) clsProfile.selectedPlanes[ProfileTempVars.PlaneSelectedIndex].Angle;
      clsItem.FrmProfilePlanes.spn_y.Value = (Decimal) clsProfile.selectedPlanes[ProfileTempVars.PlaneSelectedIndex].pntPlane.Y;
      clsItem.FrmProfilePlanes.spn_z.Value = (Decimal) clsProfile.selectedPlanes[ProfileTempVars.PlaneSelectedIndex].pntPlane.Z;
      if (ProfileTempVars.PlaneSelectedIndex >= 0 & ProfileTempVars.PlaneSelectedIndex <= clsProfile.selectedPlanes.Count - 1)
      {
        buProfileCalc.varProfileRunSettings.OPData.selectedPlaneInfo = new SelectedPlaneInfo(clsProfile.selectedPlanes[ProfileTempVars.PlaneSelectedIndex]);
        buProfileCalc.varProfileRunSettings.OPData.selectedPlane = (Plane) clsProfile.selectedPlanes[ProfileTempVars.PlaneSelectedIndex].refPlane.Clone();
        this.DrawPlaneDepth(true, true, false);
        this.PlaneCommandOnline();
      }
    }
    ProfileTempVars.PlaneInited = true;
    this.viewportBottom.Invalidate();
  }

  public void DepthClick(object sender, EventArgs e)
  {
    buEyeBaseVer5.Apps.ProfileItem profileItem = clsInit.cProfile.SelectActiveProfile(this.activeProfile.FirstItem, this.activeProfile.SecondItem, ref buProfileCalc.varProfileRunSettings.activeProfileIndex);
    if (profileItem == null)
      return;
    System.Windows.Forms.Control control = sender as System.Windows.Forms.Control;
    if (control.Name == clsItem.FrmProfileDepths.btn_depthadd.Name)
    {
      if (ProfileTempVars.CreatingOperation.OperationData.DepthValues.Count > 0)
      {
        DepthPositions depthValue = ProfileTempVars.CreatingOperation.OperationData.DepthValues[ProfileTempVars.CreatingOperation.OperationData.DepthValues.Count - 1];
        if (buProfileCalc.varProfileRunSettings.ShapeDataParameters.selectedPlane == planeBoxNames.Top | buProfileCalc.varProfileRunSettings.ShapeDataParameters.selectedPlane == planeBoxNames.Back | buProfileCalc.varProfileRunSettings.ShapeDataParameters.selectedPlane == planeBoxNames.Free)
          depthValue.TopPosition -= 5.0;
        if (buProfileCalc.varProfileRunSettings.ShapeDataParameters.selectedPlane == planeBoxNames.Front | buProfileCalc.varProfileRunSettings.ShapeDataParameters.selectedPlane == planeBoxNames.Bottom)
          depthValue.TopPosition += 5.0;
        object[] objArray = this.AddNewDepthRow(ProfileTempVars.CreatingOperation.OperationData.DepthValues.Count + 1, depthValue.TopPosition, depthValue.Depth, buProfileCalc.varProfileSettings.AutoPeckingAddDefault, buProfileCalc.varProfileSettings.AutoPeckingUpDefaultDistance, 0.0, 0.0, 0.0);
        clsItem.FrmProfileDepths.DGV_Depths.Rows.Add(objArray);
      }
      else
      {
        DepthPositions depthPositions = new DepthPositions();
        if (buProfileCalc.varProfileRunSettings.ShapeDataParameters.selectedPlane == planeBoxNames.Top | buProfileCalc.varProfileRunSettings.ShapeDataParameters.selectedPlane == planeBoxNames.Free)
        {
          depthPositions.TopPosition = profileItem.Height;
          depthPositions.Depth = -5.0;
        }
        if (buProfileCalc.varProfileRunSettings.ShapeDataParameters.selectedPlane == planeBoxNames.Back)
        {
          depthPositions.TopPosition = 0.0;
          depthPositions.Depth = -5.0;
        }
        if (buProfileCalc.varProfileRunSettings.ShapeDataParameters.selectedPlane == planeBoxNames.Front)
        {
          depthPositions.TopPosition = -profileItem.Width;
          depthPositions.Depth = 5.0;
        }
        if (buProfileCalc.varProfileRunSettings.ShapeDataParameters.selectedPlane == planeBoxNames.Bottom)
        {
          depthPositions.TopPosition = 0.0;
          depthPositions.Depth = 5.0;
        }
        object[] objArray = this.AddNewDepthRow(1, depthPositions.TopPosition, depthPositions.Depth, buProfileCalc.varProfileSettings.AutoPeckingAddDefault, buProfileCalc.varProfileSettings.AutoPeckingUpDefaultDistance, 0.0, 0.0, 0.0);
        clsItem.FrmProfileDepths.DGV_Depths.Rows.Add(objArray);
      }
      this.DepthDGV_CellValueChanged((object) null, (DataGridViewCellEventArgs) null);
    }
    if (control.Name == clsItem.FrmProfileDepths.btn_depthdelete.Name && buString5.MessageBoxQuestion(buLangTranslate.preSentences.DoYouWanttoDeleteDepth) == DialogResult.Yes && ProfileTempVars.DepthSelectedIndex >= 0 & ProfileTempVars.DepthSelectedIndex <= clsItem.FrmProfileDepths.DGV_Depths.Rows.Count - 1)
    {
      clsItem.FrmProfileDepths.DGV_Depths.Rows.RemoveAt(ProfileTempVars.DepthSelectedIndex);
      ProfileTempVars.DepthForced = true;
      this.DepthDGV_CellValueChanged((object) null, (DataGridViewCellEventArgs) null);
    }
    if (control.Name == clsItem.FrmProfileDepths.btn_depthcalculate.Name)
    {
      ProfileTempVars.DepthForced = false;
      this.OnlineOperation((object) null, (object) new ShapeUpdateArg(buProfileCalc.varProfileRunSettings.ShapeDataParameters), (object) null);
      ProfileTempVars.DepthInited = true;
    }
    if (control.Name == clsItem.FrmProfileDepths.btn_depthopen.Name)
    {
      OpenFileDialog openFileDialog = new OpenFileDialog();
      openFileDialog.InitialDirectory = buProfileCalc.varProfileRunSettings.pathDepths;
      openFileDialog.Filter = "buCad/Cam Plane File (*.budepths)|*.budepths";
      openFileDialog.FilterIndex = 1;
      if (openFileDialog.ShowDialog() == DialogResult.OK)
      {
        ProfileTempVars.OperationDepths.Clear();
        this.OPData.DepthValues.Clear();
        DepthPositions.OpenFile(ref this.OPData.DepthValues, openFileDialog.FileName);
        this.DepthsFill(this.OPData);
        buProfileCalc.varProfileRunSettings.pathDepths = buFile5.GetPath(openFileDialog.FileName);
        ProfileTempVars.DepthForced = true;
        this.DepthDGV_CellValueChanged((object) null, (DataGridViewCellEventArgs) null);
        this.SaveByTick = true;
      }
    }
    if (!(control.Name == clsItem.FrmProfileDepths.btn_depthsave.Name))
      return;
    SaveFileDialog saveFileDialog = new SaveFileDialog();
    saveFileDialog.InitialDirectory = buProfileCalc.varProfileRunSettings.pathDepths;
    saveFileDialog.Filter = "buCad/Cam Plane File (*.budepths)|*.budepths";
    saveFileDialog.FilterIndex = 1;
    if (saveFileDialog.ShowDialog() != DialogResult.OK)
      return;
    DepthPositions.SaveFile(ProfileTempVars.CreatingOperation.OperationData.DepthValues, saveFileDialog.FileName);
    buProfileCalc.varProfileRunSettings.pathDepths = buFile5.GetPath(saveFileDialog.FileName);
    this.SaveByTick = true;
  }

  public void PlaneClick(object sender, EventArgs e)
  {
    System.Windows.Forms.Control control = sender as System.Windows.Forms.Control;
    buEyeBaseVer5.Apps.ProfileItem profileItem = clsInit.cProfile.SelectActiveProfile(this.activeProfile.FirstItem, this.activeProfile.SecondItem, ref buProfileCalc.varProfileRunSettings.activeProfileIndex);
    if (profileItem == null)
      return;
    if (control.Name == clsItem.FrmProfilePlanes.btn_addplane.Name)
    {
      F_PlaneList fPlaneList = new F_PlaneList();
      fPlaneList.PropertiesForm.FormCloseMode = FormCloseModeType.Dispose;
      fPlaneList.PropertiesForm.FormPosition = FormStartPosition.CenterScreen;
      fPlaneList.pntMinProfile = buVector5.ToPoint3D(profileItem.ProfileMinPoint);
      fPlaneList.pntMaxProfile = buVector5.ToPoint3D(profileItem.ProfileMaxPoint);
      fPlaneList.VarUcs = buProfileCalc.varUCSData;
      fPlaneList.PlaneThinkness = buProfileCalc.varProfileSettings.PlaneThickness;
      fPlaneList.Init();
      int num = (int) fPlaneList.ShowDialog();
      if (fPlaneList.PropertiesForm.Result == DialogResult.OK)
      {
        this.AddPlane(fPlaneList.Plane);
        ProfileTempVars.PlaneSelectedIndex = clsProfile.selectedPlanes.Count - 1;
        clsItem.FrmProfilePlanes.lst_types.SelectedIndex = ProfileTempVars.PlaneSelectedIndex;
      }
    }
    if (control.Name == clsItem.FrmProfilePlanes.btn_angminus.Name | control.Name == clsItem.FrmProfilePlanes.btn_angplus.Name | control.Name == clsItem.FrmProfilePlanes.btn_yminus.Name | control.Name == clsItem.FrmProfilePlanes.btn_yplus.Name | control.Name == clsItem.FrmProfilePlanes.btn_zminus.Name | control.Name == clsItem.FrmProfilePlanes.btn_zplus.Name)
    {
      if (control.Name == clsItem.FrmProfilePlanes.btn_angminus.Name)
        clsItem.FrmProfilePlanes.spn_angle.Value -= (Decimal) ProfileTempVars.PlaneIncrement;
      if (control.Name == clsItem.FrmProfilePlanes.btn_angplus.Name)
        clsItem.FrmProfilePlanes.spn_angle.Value += (Decimal) ProfileTempVars.PlaneIncrement;
      if (control.Name == clsItem.FrmProfilePlanes.btn_yminus.Name)
        clsItem.FrmProfilePlanes.spn_y.Value -= (Decimal) ProfileTempVars.PlaneIncrement;
      if (control.Name == clsItem.FrmProfilePlanes.btn_yplus.Name)
        clsItem.FrmProfilePlanes.spn_y.Value += (Decimal) ProfileTempVars.PlaneIncrement;
      if (control.Name == clsItem.FrmProfilePlanes.btn_zminus.Name)
        clsItem.FrmProfilePlanes.spn_z.Value -= (Decimal) ProfileTempVars.PlaneIncrement;
      if (control.Name == clsItem.FrmProfilePlanes.btn_zplus.Name)
        clsItem.FrmProfilePlanes.spn_z.Value += (Decimal) ProfileTempVars.PlaneIncrement;
      this.PlaneCommandOnline();
    }
    if (control.Name == clsItem.FrmProfilePlanes.lbl_01.Name)
    {
      ProfileTempVars.PlaneIncrement = 0.1;
      this.PlaneIncrementSelect();
    }
    if (control.Name == clsItem.FrmProfilePlanes.lbl_05.Name)
    {
      ProfileTempVars.PlaneIncrement = 0.5;
      this.PlaneIncrementSelect();
    }
    if (control.Name == clsItem.FrmProfilePlanes.lbl_1.Name)
    {
      ProfileTempVars.PlaneIncrement = 1.0;
      this.PlaneIncrementSelect();
    }
    if (control.Name == clsItem.FrmProfilePlanes.lbl_5.Name)
    {
      ProfileTempVars.PlaneIncrement = 5.0;
      this.PlaneIncrementSelect();
    }
    if (control.Name == clsItem.FrmProfilePlanes.lbl_10.Name)
    {
      ProfileTempVars.PlaneIncrement = 10.0;
      this.PlaneIncrementSelect();
    }
    if (control.Name == clsItem.FrmProfilePlanes.btn_delete.Name && buString5.MessageBoxQuestion(AppLanguage.CadCamMessages[97]) == DialogResult.Yes && ProfileTempVars.PlaneSelectedIndex >= 0 & ProfileTempVars.PlaneSelectedIndex <= clsProfile.selectedPlanes.Count - 1)
      this.RemovePlane(ProfileTempVars.PlaneSelectedIndex);
    if (control.Name == clsItem.FrmProfilePlanes.btn_open.Name)
    {
      OpenFileDialog openFileDialog = new OpenFileDialog();
      openFileDialog.InitialDirectory = buProfileCalc.varProfileRunSettings.pathPlanes;
      openFileDialog.Filter = "buCad/Cam Plane File (*.buplane)|*.buplane";
      openFileDialog.FilterIndex = 1;
      openFileDialog.Multiselect = false;
      if (openFileDialog.ShowDialog() == DialogResult.OK)
      {
        buProfileCalc.varProfileRunSettings.pathPlanes = buFile5.GetPath(openFileDialog.FileName);
        buFile5.OpenPlaneFile(openFileDialog.FileName, ref clsProfile.selectedPlanes);
        clsItem.FrmProfilePlanes.lst_types.Items.Clear();
        for (int index = 0; index <= clsProfile.selectedPlanes.Count - 1; ++index)
          clsItem.FrmProfilePlanes.lst_types.Items.Add((object) clsProfile.selectedPlanes[index].Explanation);
        ProfileTempVars.PlaneInited = true;
      }
    }
    if (!(control.Name == clsItem.FrmProfilePlanes.btn_save.Name))
      return;
    SaveFileDialog saveFileDialog = new SaveFileDialog();
    saveFileDialog.InitialDirectory = buProfileCalc.varProfileRunSettings.pathPlanes;
    saveFileDialog.Filter = "buCad/Cam Plane File (*.buplane)|*.buplane";
    saveFileDialog.FilterIndex = 1;
    if (saveFileDialog.ShowDialog() != DialogResult.OK)
      return;
    buFile5.SavePlaneFile(saveFileDialog.FileName, clsProfile.selectedPlanes);
    buProfileCalc.varProfileRunSettings.pathPlanes = buFile5.GetPath(saveFileDialog.FileName);
  }

  public void RemovePlane(int indexPlane, bool OnlyDrawing = false)
  {
    if (!(indexPlane >= 0 & indexPlane <= clsProfile.selectedPlanes.Count - 1))
      return;
    this.viewportBottom.Entities.ClearSelection();
    for (int index = 0; index <= this.viewportBottom.Entities.Count - 1; ++index)
    {
      if ((this.viewportBottom.Entities[index].EntityData == null ? 0 : (this.viewportBottom.Entities[index].EntityData is CustomData ? 1 : 0)) != 0)
      {
        CustomData entityData = this.viewportBottom.Entities[index].EntityData as CustomData;
        if (entityData.typeDefination == entityTypeDefination.Plane & entityData.RefIndex == indexPlane)
          this.viewportBottom.Entities[index].Selected = true;
      }
    }
    this.viewportBottom.Entities.DeleteSelected();
    if (!OnlyDrawing)
    {
      clsProfile.selectedPlanes.RemoveAt(indexPlane);
      clsItem.FrmProfilePlanes.lst_types.Items.RemoveAt(indexPlane);
      --indexPlane;
    }
    this.viewportBottom.Invalidate();
  }

  public void AddPlane(SelectedPlaneInfo P, bool OnlyDrawing = false)
  {
    clsProfile.selectedPlanes.Add(new SelectedPlaneInfo(P));
    ProfileTempVars.PlaneInited = true;
    if (OnlyDrawing)
      return;
    clsItem.FrmProfilePlanes.lst_types.Items.Add((object) P.Explanation);
  }

  public void FillPlanes()
  {
    ProfileTempVars.PlaneInited = false;
    clsItem.FrmProfilePlanes.lst_types.Items.Clear();
    for (int index = 0; index <= clsProfile.selectedPlanes.Count - 1; ++index)
      clsItem.FrmProfilePlanes.lst_types.Items.Add((object) clsProfile.selectedPlanes[index].Explanation);
    ProfileTempVars.PlaneInited = true;
  }

  public void PlaneIncrementSelect()
  {
    clsItem.FrmProfilePlanes.lbl_01.BackColor = Color.PowderBlue;
    clsItem.FrmProfilePlanes.lbl_05.BackColor = Color.PowderBlue;
    clsItem.FrmProfilePlanes.lbl_1.BackColor = Color.PowderBlue;
    clsItem.FrmProfilePlanes.lbl_5.BackColor = Color.PowderBlue;
    clsItem.FrmProfilePlanes.lbl_10.BackColor = Color.PowderBlue;
    if (ProfileTempVars.PlaneIncrement == 0.1)
      clsItem.FrmProfilePlanes.lbl_01.BackColor = Color.Gold;
    else if (ProfileTempVars.PlaneIncrement == 0.5)
      clsItem.FrmProfilePlanes.lbl_05.BackColor = Color.Gold;
    else if (ProfileTempVars.PlaneIncrement == 1.0)
      clsItem.FrmProfilePlanes.lbl_1.BackColor = Color.Gold;
    else if (ProfileTempVars.PlaneIncrement == 5.0)
      clsItem.FrmProfilePlanes.lbl_5.BackColor = Color.Gold;
    else
      clsItem.FrmProfilePlanes.lbl_10.BackColor = Color.Gold;
  }

  public void PlaneValueChanged(object sender, EventArgs e)
  {
    buEyeBaseVer5.Apps.ProfileItem profileItem = clsInit.cProfile.SelectActiveProfile(this.activeProfile.FirstItem, this.activeProfile.SecondItem, ref buProfileCalc.varProfileRunSettings.activeProfileIndex);
    if (profileItem == null || !ProfileTempVars.PlaneInited || !(ProfileTempVars.PlaneSelectedIndex >= 0 & ProfileTempVars.PlaneSelectedIndex <= clsProfile.selectedPlanes.Count - 1))
      return;
    SelectedPlaneInfo selectedPlane = clsProfile.selectedPlanes[ProfileTempVars.PlaneSelectedIndex];
    selectedPlane.pntPlane.Y = (double) clsItem.FrmProfilePlanes.spn_y.Value;
    selectedPlane.pntPlane.Z = (double) clsItem.FrmProfilePlanes.spn_z.Value;
    selectedPlane.Angle = (double) clsItem.FrmProfilePlanes.spn_angle.Value;
    clsInit.cProfile.CreatePlane(selectedPlane.PlaneType, 0, false, profileItem.ProfileMinPoint, profileItem.ProfileMaxPoint, buProfileCalc.varProfileSettings.PlaneThickness, buProfileCalc.varUCSData, ref selectedPlane);
    buProfileCalc.varProfileRunSettings.OPData.selectedPlaneInfo = selectedPlane;
    buProfileCalc.varProfileRunSettings.OPData.selectedPlane = (Plane) selectedPlane.refPlane.Clone();
    this.DrawPlaneDepth(false, true, false);
  }

  public void DrawPlaneDepth(bool CleanAll, bool DrawPlanes, bool DrawDepths)
  {
    bool flag = false;
    buEyeBaseVer5.Apps.ProfileItem profileItem = clsInit.cProfile.SelectActiveProfile(this.activeProfile.FirstItem, this.activeProfile.SecondItem, ref buProfileCalc.varProfileRunSettings.activeProfileIndex);
    if (profileItem == null)
      return;
    for (int index = 0; index <= ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Layers.Count - 1; ++index)
    {
      if (!clsInit.cVector5.IsLayerNameAvailable(this.viewportBottom.Layers, ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Layers[index].Name))
        this.viewportBottom.Layers.Add(new Layer(ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Layers[index].Name, ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Layers[index].Color));
    }
    if (CleanAll)
    {
      this.viewportBottom.Entities.Clear();
      for (int index = 0; index <= profileItem.Drawings.Count - 1; ++index)
      {
        if (profileItem.Drawings[index].SolidEntity != null)
        {
          Entity entity = buVector5.CopyEntities(profileItem.Drawings[index].SolidEntity);
          entity.Color = Color.FromArgb(70, entity.Color);
          this.viewportBottom.Entities.Add(entity);
        }
      }
      flag = true;
    }
    else
    {
      for (int index = 0; index <= this.viewportBottom.Entities.Count - 1; ++index)
      {
        if ((this.viewportBottom.Entities[index].EntityData == null ? 0 : (this.viewportBottom.Entities[index].EntityData is CustomData ? 1 : 0)) != 0)
        {
          CustomData entityData = this.viewportBottom.Entities[index].EntityData as CustomData;
          if (entityData.typeDefination == entityTypeDefination.Plane | entityData.typeDefination == entityTypeDefination.Operation | entityData.typeDefination == entityTypeDefination.None)
            this.viewportBottom.Entities[index].Selected = true;
        }
      }
      this.viewportBottom.Entities.DeleteSelected();
      if (this.viewportBottom.Entities.Count == 0)
      {
        for (int index = 0; index <= profileItem.Drawings.Count - 1; ++index)
        {
          if (profileItem.Drawings[index].SolidEntity != null)
          {
            Entity entity = buVector5.CopyEntities(profileItem.Drawings[index].SolidEntity);
            entity.Color = Color.FromArgb(70, entity.Color);
            this.viewportBottom.Entities.Add(entity);
          }
        }
        flag = true;
      }
    }
    if (DrawPlanes)
    {
      if ((buProfileCalc.varProfileRunSettings.OPData == null ? 0 : (buProfileCalc.varProfileRunSettings.OPData.selectedPlaneInfo != null ? 1 : 0)) != 0)
      {
        if (buProfileCalc.varProfileRunSettings.OPData.selectedPlaneInfo.entityPlane != null)
        {
          Entity entity = buVector5.CopyEntities(buProfileCalc.varProfileRunSettings.OPData.selectedPlaneInfo.entityPlane);
          entity.LayerName = "Default";
          entity.ColorMethod = colorMethodType.byEntity;
          entity.Color = Color.FromArgb(200, Color.Lime);
          entity.Regen(buSystem.RegenDeviation);
          entity.EntityData = (object) new CustomData()
          {
            typeDefination = entityTypeDefination.Plane,
            RefIndex = buProfileCalc.varProfileRunSettings.OPData.selectedPlaneInfo.Index
          };
          entity.Selected = true;
          this.viewportBottom.Entities.Add(entity);
        }
        if (buProfileCalc.varProfileRunSettings.OPData.selectedPlaneInfo.entityXVector != null)
        {
          Entity entity = buVector5.CopyEntities(buProfileCalc.varProfileRunSettings.OPData.selectedPlaneInfo.entityXVector);
          entity.LayerName = "Default";
          entity.ColorMethod = colorMethodType.byEntity;
          entity.Color = Color.FromArgb((int) byte.MaxValue, Color.Red);
          entity.Selectable = true;
          entity.Regen(buSystem.RegenDeviation);
          entity.EntityData = (object) new CustomData()
          {
            typeDefination = entityTypeDefination.Plane,
            RefIndex = buProfileCalc.varProfileRunSettings.OPData.selectedPlaneInfo.Index
          };
          this.viewportBottom.Entities.Add(entity);
        }
        if (buProfileCalc.varProfileRunSettings.OPData.selectedPlaneInfo.entityYVector != null)
        {
          Entity entity = buVector5.CopyEntities(buProfileCalc.varProfileRunSettings.OPData.selectedPlaneInfo.entityYVector);
          entity.LayerName = "Default";
          entity.ColorMethod = colorMethodType.byEntity;
          entity.Color = Color.FromArgb((int) byte.MaxValue, Color.Green);
          entity.Regen(buSystem.RegenDeviation);
          entity.Selectable = true;
          entity.EntityData = (object) new CustomData()
          {
            typeDefination = entityTypeDefination.Plane,
            RefIndex = buProfileCalc.varProfileRunSettings.OPData.selectedPlaneInfo.Index
          };
          this.viewportBottom.Entities.Add(entity);
        }
        if (buProfileCalc.varProfileRunSettings.OPData.selectedPlaneInfo.entityZVector != null)
        {
          Entity entity = buVector5.CopyEntities(buProfileCalc.varProfileRunSettings.OPData.selectedPlaneInfo.entityZVector);
          entity.LayerName = "Default";
          entity.ColorMethod = colorMethodType.byEntity;
          entity.Color = Color.FromArgb((int) byte.MaxValue, Color.Blue);
          entity.Selectable = true;
          entity.Regen(buSystem.RegenDeviation);
          entity.EntityData = (object) new CustomData()
          {
            typeDefination = entityTypeDefination.Plane,
            RefIndex = buProfileCalc.varProfileRunSettings.OPData.selectedPlaneInfo.Index
          };
          this.viewportBottom.Entities.Add(entity);
        }
        if (buProfileCalc.varProfileRunSettings.OPData.selectedPlaneInfo.entityBall != null)
        {
          Entity entity = buVector5.CopyEntities(buProfileCalc.varProfileRunSettings.OPData.selectedPlaneInfo.entityBall);
          entity.LayerName = "Default";
          entity.ColorMethod = colorMethodType.byEntity;
          entity.Color = Color.FromArgb((int) byte.MaxValue, Color.Gray);
          entity.Regen(buSystem.RegenDeviation);
          entity.EntityData = (object) new CustomData()
          {
            typeDefination = entityTypeDefination.Plane,
            RefIndex = buProfileCalc.varProfileRunSettings.OPData.selectedPlaneInfo.Index
          };
          this.viewportBottom.Entities.Add(entity);
        }
        this.viewportBottom.ZoomFit(true, 5);
      }
      if (flag)
      {
        if (buProfileCalc.varProfileRunSettings.OPData.selectedPlaneInfo.entityPlane != null)
        {
          this.viewportBottom.SetView(viewType.Left);
          this.viewportBottom.ZoomFit(5);
          if (buProfileCalc.varProfileRunSettings.OPData.selectedPlane.Equation.Y > 0.0)
            this.viewportBottom.RotateCamera(new Vector3D(-1.0, 0.0, 0.0), new Vector3D(-0.95, 0.05, -0.05));
          else if (buProfileCalc.varProfileRunSettings.OPData.selectedPlane.Equation.Y <= 0.0)
            this.viewportBottom.RotateCamera(new Vector3D(-1.0, 0.0, 0.0), new Vector3D(-0.95, 0.05, 0.05));
          this.viewportBottom.ZoomFit(true, 5);
        }
        else
        {
          this.viewportBottom.SetView(viewType.vcFrontFaceTopLeft);
          this.viewportBottom.ZoomFit(5);
        }
      }
    }
    if (DrawDepths)
    {
      if (ProfileTempVars.CreatingOperation != null)
      {
        for (int index = 0; index <= ProfileTempVars.CreatingOperation.EntityMultiSolidDepth.Count - 1; ++index)
        {
          Entity copiedEntity = (Entity) null;
          buEntity.Copy(ProfileTempVars.CreatingOperation.EntityMultiSolidDepth[index], ref copiedEntity);
          copiedEntity.EntityData = (object) new CustomData()
          {
            typeDefination = entityTypeDefination.Operation
          };
          this.viewportBottom.Entities.Add(copiedEntity);
        }
      }
      if (flag)
      {
        this.viewportBottom.SetView(viewType.Left);
        this.viewportBottom.ZoomFit(5);
      }
    }
    this.viewportBottom.Invalidate();
  }

