  public bool cmdAddProfile(buEyeBaseVer5.Apps.ProfileItem profile, bool BoxProfile = false)
  {
    try
    {
      if (ccVars.Pages[ccVars.Pages.Count - 1].Layers.Count >= 2)
      {
        if (ccVars.Pages[ccVars.Pages.Count - 1].Layers[1].Name != ProfileTempVars.LayerNameProfile)
        {
          buString5.MessageBoxWarning(AppLanguage.CadCamMessages[99]);
          return false;
        }
        if (this.FrmProfile == null)
        {
          this.FrmProfile = new buEyeBaseVer5.Forms.Profile.F_ProfileAdd();
          this.FrmProfile.EditDxf += new OkCommandWithTwoDataEventHandler(this.doEditDxf);
        }
        this.FrmProfile.MaterialIndex = clsVar.varInterface.MaterialSkinIndex;
        this.FrmProfile.Materials.Clear();
        for (int index = 0; index <= ccVars.Textures.Count - 1; ++index)
          this.FrmProfile.Materials.Add(new MaterialSkin(ccVars.Textures[index].Name, ccVars.Textures[index].Specular));
        this.FrmProfile.RigthProfile = buProfileCalc.varProfileSettings.RightProfileActive;
        this.FrmProfile.ProfileSet = new buEyeBaseVer5.Apps.ProfileSettings(buProfileCalc.varProfileSettings);
        if (this.SelProfileTreeIndex == 0)
          this.FrmProfile.ProfileSet.XDirRefType = LeftRightType.Left;
        else if (this.SelProfileTreeIndex == 1)
          this.FrmProfile.ProfileSet.XDirRefType = LeftRightType.Right;
        buProfileCalc.varProfileRunSettings.ProfileType = ProfileNewType.Drawing;
        if (BoxProfile)
          buProfileCalc.varProfileRunSettings.ProfileType = ProfileNewType.Rectangle;
        this.FrmProfile.ProfileRunTimeSet = new buEyeBaseVer5.Apps.ProfileRuntimeSettings(buProfileCalc.varProfileRunSettings);
        if (profile != null)
        {
          this.FrmProfile.ProfileRunTimeSet.ProfileLength = profile.Length;
          this.FrmProfile.ProfileRunTimeSet.NewProfileWidth = profile.Width;
          this.FrmProfile.ProfileRunTimeSet.NewProfileHeight = profile.Height;
          this.FrmProfile.ProfileRunTimeSet.NewProfileThickness = profile.Thickness;
          buProfileCalc.varProfileRunSettings.ProfileType = profile.ProfileType;
        }
        this.FrmProfile.StartPosition = FormStartPosition.CenterParent;
        this.FrmProfile.PropertiesForm.FormCloseMode = FormCloseModeType.Invisible;
        this.FrmProfile.Init(profile, BoxProfile);
        int num = (int) this.FrmProfile.ShowDialog();
        if (this.FrmProfile.PropertiesForm.Result != DialogResult.OK)
          return false;
        this.activeOP = (buEyeBaseVer5.Apps.ProfileOperation) null;
        ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.ClearSelection();
        buProfileCalc.varProfileSettings.MaterialTranspancy = this.FrmProfile.ProfileSet.MaterialTranspancy;
        buProfileCalc.varProfileRunSettings = new buEyeBaseVer5.Apps.ProfileRuntimeSettings(this.FrmProfile.ProfileRunTimeSet);
        buProfileCalc.varProfileSettings = new buEyeBaseVer5.Apps.ProfileSettings(this.FrmProfile.ProfileSet);
        buEyeBaseVer5.Apps.ProfileItem Profile = new buEyeBaseVer5.Apps.ProfileItem(this.FrmProfile.Profile);
        Profile.ClamperSettings = new buEyeBaseVer5.Apps.ProfileClamperSettings(buProfileCalc.varProfileClamperSettings);
        if (!buProfileCalc.varProfileSettings.RightProfileActive)
          Profile.XReferanceLocation = LeftRightType.Left;
        buProfileCalc.varProfileRunSettings.LastLoadedProfileName = Profile.FileNameFull;
        this.SaveByTick = true;
        Profile.MaxClamperNumber = buProfileCalc.varProfileSettings.ProfileMaxClamper;
        if (profile == null)
        {
          this.doCreateProfile(ref Profile, true);
          clsInit.appCommand.cmdViewZoomFit();
        }
        else
          this.doCreateProfile(ref Profile, true);
        clsItem.ModelMainPreview.ZoomFit();
        if (buProfileCalc.varProfileSettings.AutoOpenLastLoadedProfile | buProfileCalc.varProfileSettings.AutoOpenLastLoadedProfileAndOperations)
          this.SaveProfileJobFile(AppPath.Base + "\\AutoSave\\LastProfile.buprofile", Profile, false);
        this.DrawActiveProfile();
        this.DrawPreview(Profile, new List<Entity>());
        this.doCheckProfileError();
        return true;
      }
      buString5.MessageBoxWarning(AppLanguage.CadCamMessages[100]);
      return false;
    }
    catch (Exception ex)
    {
      string str = "";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, true, str);
      return false;
    }
  }

