  public void cmdOperation(
    actionTypeBU action,
    bool NewOperation = false,
    ProfileNotchOperationType NotchType = ProfileNotchOperationType.Side)
  {
    if (this.activeProfile.FirstItem == null & this.activeProfile.SecondItem == null)
      buString5.MessageBoxWarning(buProfile.LangProfileMessage[31 /*0x1F*/]);
    else if (action == actionTypeBU.profileFreeDraw)
    {
      this.cmdDrawEditor();
    }
    else
    {
      buEyeBaseVer5.Apps.ProfileItem profileItem = clsInit.cProfile.SelectActiveProfile(this.activeProfile.FirstItem, this.activeProfile.SecondItem, ref buProfileCalc.varProfileRunSettings.activeProfileIndex);
      if (profileItem == null)
        return;
      if (NewOperation)
      {
        buProfileCalc.varProfileRunSettings.OPData.CamParNotch.Notch.NotchCutType = ProfileNotchCutType.BySaw;
        buProfileCalc.varProfileRunSettings.OPData.Mirror.MirrorEnable = false;
        buProfileCalc.varProfileRunSettings.OPData.Array.CircularEnable = false;
        buProfileCalc.varProfileRunSettings.OPData.Array.LineerEnable = false;
        this.ToolChangeForced = false;
        buProfileCalc.varProfileRunSettings.OPData.Array.LineerEnable = false;
        buProfileCalc.varProfileRunSettings.OPData.Array.CircularEnable = false;
        buProfileCalc.varProfileRunSettings.OPData.Mirror.MirrorEnable = false;
      }
      this.ignoreOnlineChange = false;
      if (NewOperation)
        this.operationEditIndex = -1;
      buProfileCalc.varProfileRunSettings.ShapeDataParameters.SizeMaterailWidth = profileItem.Length;
      buProfileCalc.varProfileRunSettings.ShapeDataParameters.SizeMaterailHeight = profileItem.Width;
      buProfileCalc.varProfileRunSettings.ShapeDataParameters.SizeMaterailDepth = profileItem.Height;
      this.cntCreateOperation = 0;
      ccVars.Action = action;
      if (!ProfileTempVars.OperationEditing)
        ProfileTempVars.DepthForced = false;
      if (action == actionTypeBU.profileNotch)
        this.cmdNotch(action, NotchType);
      else
        this.cmdShapes(action);
    }
  }

