          clsInit.cVector5.FindToolSmallMillingDiameter(ccVars.Tools, ref ccVars.toolActive);
        if (ccVars.toolActive.Geometry.GeometryType != ToolType.Saw & this.frmMacro.Item.Operations[index1].OperationData.Action == actionTypeBU.profileNotch)
        {
          this.frmMacro.Item.Operations[index1].Tool = new ToolBase5(ccVars.toolActive);
          for (int index2 = 0; index2 <= ccVars.Tools.Count - 1; ++index2)
          {
            for (int index3 = 0; index3 <= ccVars.Tools[index2].Tools.Count - 1; ++index3)
            {
              if (ccVars.Tools[index2].Tools[index3].Geometry.GeometryType == ToolType.Saw)
              {
                ccVars.toolActive = new ToolBase5(ccVars.Tools[index2].Tools[index3]);
                this.frmMacro.Item.Operations[index1].ToolNotch = new ToolBase5(ccVars.toolActive);
              }
            }
