        Data2.NotOriginalTool = !flag;
        Data2.Parameters.Priority = this.frmMacro.Item.Operations[index1].Priority;
        if (!this.frmMacro.Item.Operations[index1].Enable)
          Data2.CommandList.Add("ForceDisable");
        this.UndoDontProfile = true;
        this.OPPriority = this.frmMacro.Item.Operations[index1].Priority;
        buShape buShape = new buShape();
        buShape.BasePoint = new Point3D(this.frmMacro.Item.Operations[index1].OperationData.basePosition.X, Math.Abs(this.frmMacro.Item.Operations[index1].OperationData.basePosition.Y), this.frmMacro.Item.Operations[index1].OperationData.basePosition.Z);
        if (buCompare5.EQ(buShape.BasePoint.X, 0.0) & buCompare5.EQ(buShape.BasePoint.Y, 0.0) & buCompare5.EQ(buShape.BasePoint.Y, 0.0))
        {
          buShape.BasePoint.X = this.frmMacro.Item.Operations[index1].OperationData.Position.X;
          buShape.BasePoint.Y = this.frmMacro.Item.Operations[index1].OperationData.Position.Y;
          buShape.BasePoint.Z = this.frmMacro.Item.Operations[index1].OperationData.Position.Z;
          buShape.Corner = CornerLocation.LeftTop;
        }
        clsInit.cVector5.CoordinateFromPlaneAndCorner(new SizeObject(data.Length, data.Width, data.Height), this.frmMacro.Item.Operations[index1].OperationData.Corner, buConversion5.PlaneNamesToPlaneBoxNames(this.frmMacro.Item.Operations[index1].OperationData.selectedPlaneName), ref buShape, ref this.frmMacro.Item.Operations[index1].OperationData.Position, this.shapeCreateParameters_0.SingX, this.shapeCreateParameters_0.SingY);
        if (this.frmMacro.Item.Operations[index1].Enable)
          this.OnlineOperation((object) null, (object) Data2, (object) this.frmMacro.Item.Operations[index1].OperationData);
        if (!flag)
          this.list_0.Add($"{buLangTranslate.preSentences.SavedOperationToolNotAvailableInRecentToolList} {buLangTranslate.preDef.Tool} = {toolName}");
        if (this.list_0.Count > 0)
        {
          int num2 = 0;
          while (num2 <= this.list_0.Count - 1)
            ++num2;
        }
        this.UndoDontProfile = false;
      }
      this.OPPriority = 0;
      this.DrawActiveProfile();
    }
    catch (Exception ex)
    {
