      clsVar5.ShapeDataParameters.EngravingHeight = MaxPoint.Y - MinPoint.Y;
      clsVar5.ShapeDataParameters.EngravingDepth = MaxPoint.Z - MinPoint.Z;
      if (clsItem.FrmEngraveList == null)
      {
        clsItem.FrmEngraveList = new F_EngraveList();
        CreateModelProperties Properties = new CreateModelProperties();
        clsInit.appCommand.EyeParameterToCreateModelProperties(clsVar.varPreviewViewport, clsVar.varMouse, ref Properties);
        Properties.CoordinateSystemIconVisible = false;
        Properties.ViewCubeIconVisible = false;
        Properties.OrigineCaptionVisible = false;
        Properties.ToolBorVisible = false;
        Properties.OrigineSymbol = originSymbolStyleType.CoordinateSystem;
        Properties.OriginSymbolVisible = false;
        Properties.OrigineSize = 3;
        clsItem.FrmEngraveList.viewportLayout = clsInit.cVector5.CreateModelControl(clsVar.UnlockKey, Properties);
        clsItem.FrmEngraveList.viewportLayout.CompileUserInterfaceElements();
        for (int index = 0; index <= ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Layers.Count - 1; ++index)
          clsItem.FrmEngraveList.viewportLayout.Layers.AddOrReplace(ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Layers[index]);
      }
      clsVar5.ShapeDataParameters.ShapeGroup = ShapeGroup.Engraving;
      clsItem.FrmEngraveList.parShape = new ShapeRuntimeData(clsVar5.ShapeDataParameters);
      clsItem.FrmEngraveList.selectedShape = (buShape) new buShapeEngrave(clsVar5.ShapeDataParameters.EngravingDepth, clsVar5.ShapeDataParameters.EngravingWidth, clsVar5.ShapeDataParameters.EngravingHeight, this.list_1[0]);
      clsItem.FrmEngraveList.selectedShape.CamPar = new camParameters5();
      clsItem.FrmEngraveList.CamPar = new camParameters5();
      clsItem.FrmEngraveList.PropertiesForm.TopMost = true;
      clsItem.FrmEngraveList.PropertiesForm.FormPosition = FormStartPosition.Manual;
      clsItem.FrmEngraveList.StartPosition = FormStartPosition.Manual;
      clsItem.FrmEngraveList.TopMost = true;
      if (clsItem.FrmEngraveList.pnl_model.Controls.Count == 0)
        clsItem.FrmEngraveList.pnl_model.Controls.Add((System.Windows.Forms.Control) clsItem.FrmEngraveList.viewportLayout);
      clsItem.FrmEngraveList.viewportLayout.Entities.Clear();
      clsItem.FrmEngraveList.PropertiesForm.FormCloseMode = FormCloseModeType.Invisible;
      if (clsItem.FrmMain != null)
        clsItem.FrmEngraveList.Owner = clsItem.FrmMain;
      clsItem.FrmEngraveList.Width = 410;
      if (this.list_1.Count > 0)
        ;
      buEntity.Copy(this.list_1, ref clsVar5.shapeCreatePar.entitiesEngraving);
      clsItem.FrmEngraveList.PropertiesForm.FormCloseMode = FormCloseModeType.Invisible;
      clsItem.FrmEngraveList.Init();
      clsItem.FrmEngraveList.StartPosition = FormStartPosition.CenterParent;
      clsItem.FrmEngraveList.Show();
      clsItem.FrmEngraveList.Top = 20;
      clsItem.FrmEngraveList.Left = Screen.PrimaryScreen.Bounds.Width - clsItem.FrmEngraveList.Width;
    }
    this.SaveByTick = true;
  }

  public void cmdMenuCommand(object sender, EventArgs e)
  {
    string str = "";
    if (sender is System.Windows.Forms.Control)
      str = (sender as System.Windows.Forms.Control).Name;
    else if (sender is ToolStripMenuItem)
      str = (sender as ToolStripMenuItem).Name;
    if (str == clsItem.FrmProfileJob.mnu_addprofile.Name)
    {
      if (ProfileTempVars.OperationEditing)
        clsInit.appCommand.Reset();
      this.cmdAddProfile((buEyeBaseVer5.Apps.ProfileItem) null);
    }
    if (str == clsItem.FrmProfileJob.mnu_addboxprofile.Name)
    {
      if (ProfileTempVars.OperationEditing)
        clsInit.appCommand.Reset();
      this.cmdAddProfile((buEyeBaseVer5.Apps.ProfileItem) null, true);
    }
    if (str == clsItem.FrmProfileJob.mnu_disableprofile.Name)
    {
      this.ProfileTreeUpdate();
      if (buProfileCalc.varProfileRunSettings.activeProfileIndex == 0 && this.activeProfile.FirstItem != null)
        this.doEnableDisableProfile(buProfileCalc.varProfileRunSettings.activeProfileIndex, false);
      if (buProfileCalc.varProfileRunSettings.activeProfileIndex == 1 && this.activeProfile.SecondItem != null)
        this.doEnableDisableProfile(buProfileCalc.varProfileRunSettings.activeProfileIndex, false);
      this.DrawActiveProfile();
      this.ProfileTreeUpdate();
    }
    if (str == clsItem.FrmProfileJob.mnu_enableprofile.Name)
    {
      if (buProfileCalc.varProfileRunSettings.activeProfileIndex == 0 && this.activeProfile.FirstItem != null)
        this.doEnableDisableProfile(buProfileCalc.varProfileRunSettings.activeProfileIndex, true);
      if (buProfileCalc.varProfileRunSettings.activeProfileIndex == 1 && this.activeProfile.SecondItem != null)
        this.doEnableDisableProfile(buProfileCalc.varProfileRunSettings.activeProfileIndex, true);
      this.DrawActiveProfile();
      this.ProfileTreeUpdate();
    }
    if (str == clsItem.FrmProfileJob.mnu_deleteprofile.Name)
    {
      if (ProfileTempVars.OperationEditing)
        clsInit.appCommand.Reset();
      if (this.activeProfile != null && buProfileCalc.varProfileRunSettings.activeProfileIndex >= 0 && buString5.MessageBoxQuestion(buProfile.LangProfileMessage[19]) == DialogResult.Yes)
        this.doDeleteProfile(buProfileCalc.varProfileRunSettings.activeProfileIndex);
    }
    if (str == clsItem.FrmProfileJob.mnu_editprofile.Name)
    {
      if (ProfileTempVars.OperationEditing)
        clsInit.appCommand.Reset();
      if (buProfileCalc.varProfileRunSettings.activeProfileIndex >= 0)
        this.doEditProfile(buProfileCalc.varProfileRunSettings.activeProfileIndex);
    }
    if (str == clsItem.FrmProfileJob.mnu_renameprofile.Name)
    {
      if (ProfileTempVars.OperationEditing)
        clsInit.appCommand.Reset();
      DialogBoxText dialogBoxText = new DialogBoxText();
      dialogBoxText.Caption = $"{buLangTranslate.preDef.Profile} {AppLanguage.CadCamDynamic[40]}";
      dialogBoxText.Text = $"{buLangTranslate.preDef.Profile} {AppLanguage.CadCamDynamic[40]}";
      if (buProfileCalc.varProfileRunSettings.activeProfileIndex >= 0)
      {
        dialogBoxText.Init(this.activeProfile.FirstItem.ItemName);
        int num = (int) dialogBoxText.ShowDialog();
        if (dialogBoxText.Result == DialogResult.OK)
        {
          this.activeProfile.FirstItem.ItemName = dialogBoxText.Value;
          clsItem.FrmProfileJob.tree_jobs.Nodes[0].Nodes[buProfileCalc.varProfileRunSettings.activeProfileIndex].Text = buProfileCalc.ProfileToString(this.activeProfile.FirstItem);
          ((buCadCamResVer5.TreeNodeSettings) clsItem.FrmProfileJob.tree_jobs.Nodes[0].Nodes[buProfileCalc.varProfileRunSettings.activeProfileIndex]).Info = dialogBoxText.Value;
        }
      }
      if (buProfileCalc.varProfileRunSettings.activeProfileIndex >= 1)
      {
        dialogBoxText.Init(this.activeProfile.SecondItem.ItemName);
        int num = (int) dialogBoxText.ShowDialog();
        if (dialogBoxText.Result == DialogResult.OK)
        {
          this.activeProfile.SecondItem.ItemName = dialogBoxText.Value;
          clsItem.FrmProfileJob.tree_jobs.Nodes[0].Nodes[buProfileCalc.varProfileRunSettings.activeProfileIndex].Text = buProfileCalc.ProfileToString(this.activeProfile.SecondItem);
          ((buCadCamResVer5.TreeNodeSettings) clsItem.FrmProfileJob.tree_jobs.Nodes[0].Nodes[buProfileCalc.varProfileRunSettings.activeProfileIndex]).Info = dialogBoxText.Value;
        }
      }
    }
    if (str == clsItem.FrmProfileJob.btn_add.Name | str == clsItem.FrmProfileJob.mnu_add.Name)
      this.cmdOperationMenu();
    if (str == clsItem.FrmProfileJob.mnu_copyprofile.Name)
    {
      if (buProfileCalc.varProfileRunSettings.activeProfileIndex == 0 & this.activeProfile.FirstItem != null)
      {
        if (buString5.MessageBoxQuestion(buProfile.LangProfileMessage[36]) == DialogResult.Yes)
        {
          if (!clsItem.FrmProfileJob.chk_selectmode.Checked)
          {
            buEyeBaseVer5.Apps.ProfileItem data = (buEyeBaseVer5.Apps.ProfileItem) null;
            if (this.activeProfile.SecondItem != null)
            {
              data = new buEyeBaseVer5.Apps.ProfileItem(this.activeProfile.FirstItem);
              clsInit.cProfile.CopyJustProfileProperties(this.activeProfile.SecondItem, ref this.activeProfile.FirstItem);
            }
            this.activeProfile.FirstItem.XReferanceLocation = LeftRightType.Right;
            for (int index = 0; index <= this.activeProfile.FirstItem.Operations.Count - 1; ++index)
            {
              if (buProfileCalc.varProfileSettings.LeftToRightCopyRotateKeyHole && this.activeProfile.FirstItem.Operations[index].OperationData.OperationType == ProfileOperationTypes.Barrel)
              {
                this.activeProfile.FirstItem.Operations[index].OperationData.BarelData.BarrelAngle += 180.0;
                if (this.activeProfile.FirstItem.Operations[index].OperationData.BarelData.BarrelAngle >= 360.0)
                  this.activeProfile.FirstItem.Operations[index].OperationData.BarelData.BarrelAngle -= 360.0;
              }
              if (buProfileCalc.varProfileSettings.LeftToRightCopyChangeCamDirection)
                this.activeProfile.FirstItem.Operations[index].CamOPData.directionContour = buConversion5.ChangeClockDirection(this.activeProfile.FirstItem.Operations[index].CamOPData.directionContour);
            }
            this.SaveProfileJobFile(AppPath.Base + "\\temp.job", this.activeProfile.FirstItem, false);
            this.activeProfile.FirstItem.XReferanceLocation = LeftRightType.Left;
            for (int index = 0; index <= this.activeProfile.FirstItem.Operations.Count - 1; ++index)
            {
              if (buProfileCalc.varProfileSettings.LeftToRightCopyRotateKeyHole && this.activeProfile.FirstItem.Operations[index].OperationData.OperationType == ProfileOperationTypes.Barrel)
              {
                this.activeProfile.FirstItem.Operations[index].OperationData.BarelData.BarrelAngle += 180.0;
                if (this.activeProfile.FirstItem.Operations[index].OperationData.BarelData.BarrelAngle >= 360.0)
                  this.activeProfile.FirstItem.Operations[index].OperationData.BarelData.BarrelAngle -= 360.0;
              }
              if (buProfileCalc.varProfileSettings.ChangeCwCCWDirForRightRefProfile)
                this.activeProfile.FirstItem.Operations[index].CamOPData.directionContour = buConversion5.ChangeClockDirection(this.activeProfile.FirstItem.Operations[index].CamOPData.directionContour);
            }
            bool clearAllProfiles = buProfileCalc.varProfileSettings.JobOpenClearAllProfiles;
            buProfileCalc.varProfileSettings.JobOpenClearAllProfiles = false;
            this.OpenProfileJobFile(AppPath.Base + "\\temp.job", true, true, false, ref this.activeProfile.SecondItem, false);
            this.activeProfile.SecondItem.ItemName += "_Copy";
            for (int index = 0; index <= this.activeProfile.SecondItem.Operations.Count - 1; ++index)
              this.activeProfile.SecondItem.Operations[index].Name += "_Copy";
            buProfileCalc.varProfileSettings.JobOpenClearAllProfiles = clearAllProfiles;
            if (data != null)
              this.activeProfile.FirstItem = new buEyeBaseVer5.Apps.ProfileItem(data);
          }
          else
          {
            buEyeBaseVer5.Apps.ProfileItem data = (buEyeBaseVer5.Apps.ProfileItem) null;
            if (this.activeProfile.SecondItem != null)
            {
              data = new buEyeBaseVer5.Apps.ProfileItem(this.activeProfile.FirstItem);
              clsInit.cProfile.CopyJustProfileProperties(this.activeProfile.SecondItem, ref this.activeProfile.FirstItem);
            }
            buEyeBaseVer5.Apps.ProfileItem Profile = new buEyeBaseVer5.Apps.ProfileItem(this.activeProfile.FirstItem);
            Profile.XReferanceLocation = LeftRightType.Right;
            Profile.Operations.Clear();
            for (int index = 0; index <= this.activeProfile.FirstItem.Operations.Count - 1; ++index)
            {
              if (this.activeProfile.FirstItem.Operations[index].Selected)
              {
                if (buProfileCalc.varProfileSettings.LeftToRightCopyRotateKeyHole && this.activeProfile.FirstItem.Operations[index].OperationData.OperationType == ProfileOperationTypes.Barrel)
                {
                  this.activeProfile.FirstItem.Operations[index].OperationData.BarelData.BarrelAngle += 180.0;
                  if (this.activeProfile.FirstItem.Operations[index].OperationData.BarelData.BarrelAngle >= 360.0)
                    this.activeProfile.FirstItem.Operations[index].OperationData.BarelData.BarrelAngle -= 360.0;
                }
                if (buProfileCalc.varProfileSettings.ChangeCwCCWDirForRightRefProfile)
                  this.activeProfile.FirstItem.Operations[index].CamOPData.directionContour = buConversion5.ChangeClockDirection(this.activeProfile.FirstItem.Operations[index].CamOPData.directionContour);
                Profile.Operations.Add(this.activeProfile.FirstItem.Operations[index]);
              }
            }
            this.SaveProfileJobFile(AppPath.Base + "\\temp.job", Profile, false);
            bool clearAllProfiles = buProfileCalc.varProfileSettings.JobOpenClearAllProfiles;
            buProfileCalc.varProfileSettings.JobOpenClearAllProfiles = false;
            this.OpenProfileJobFile(AppPath.Base + "\\temp.job", true, true, false, ref this.activeProfile.SecondItem, false);
            this.activeProfile.SecondItem.ItemName += "_Copy";
            for (int index = 0; index <= this.activeProfile.SecondItem.Operations.Count - 1; ++index)
              this.activeProfile.SecondItem.Operations[index].Name += "_Copy";
            buProfileCalc.varProfileSettings.JobOpenClearAllProfiles = clearAllProfiles;
            if (data != null)
              this.activeProfile.FirstItem = new buEyeBaseVer5.Apps.ProfileItem(data);
          }
          this.ProfileTreeUpdate();
          clsInit.appProfile.doSetActiveProfile(0);
        }
      }
      else if (buProfileCalc.varProfileRunSettings.activeProfileIndex == 1 & this.activeProfile.SecondItem != null && buString5.MessageBoxQuestion(buProfile.LangProfileMessage[37]) == DialogResult.Yes)
      {
        if (!clsItem.FrmProfileJob.chk_selectmode.Checked)
        {
          buEyeBaseVer5.Apps.ProfileItem data = (buEyeBaseVer5.Apps.ProfileItem) null;
          if (this.activeProfile.FirstItem != null)
          {
            data = new buEyeBaseVer5.Apps.ProfileItem(this.activeProfile.SecondItem);
            clsInit.cProfile.CopyJustProfileProperties(this.activeProfile.FirstItem, ref this.activeProfile.SecondItem);
          }
          this.activeProfile.SecondItem.XReferanceLocation = LeftRightType.Left;
          for (int index = 0; index < this.activeProfile.SecondItem.Operations.Count - 1; ++index)
          {
            if (buProfileCalc.varProfileSettings.LeftToRightCopyRotateKeyHole && this.activeProfile.SecondItem.Operations[index].OperationData.OperationType == ProfileOperationTypes.Barrel)
            {
              this.activeProfile.SecondItem.Operations[index].OperationData.BarelData.BarrelAngle += 180.0;
              if (this.activeProfile.SecondItem.Operations[index].OperationData.BarelData.BarrelAngle >= 360.0)
                this.activeProfile.SecondItem.Operations[index].OperationData.BarelData.BarrelAngle -= 360.0;
            }
            if (buProfileCalc.varProfileSettings.ChangeCwCCWDirForRightRefProfile)
              this.activeProfile.SecondItem.Operations[index].CamOPData.directionContour = buConversion5.ChangeClockDirection(this.activeProfile.SecondItem.Operations[index].CamOPData.directionContour);
          }
          this.SaveProfileJobFile(AppPath.Base + "\\temp.job", this.activeProfile.SecondItem, false);
          this.activeProfile.SecondItem.XReferanceLocation = LeftRightType.Right;
          bool clearAllProfiles = buProfileCalc.varProfileSettings.JobOpenClearAllProfiles;
          buProfileCalc.varProfileSettings.JobOpenClearAllProfiles = false;
          this.OpenProfileJobFile(AppPath.Base + "\\temp.job", true, true, false, ref this.activeProfile.FirstItem, false);
          this.activeProfile.FirstItem.ItemName += "_Copy";
          for (int index = 0; index <= this.activeProfile.FirstItem.Operations.Count - 1; ++index)
            this.activeProfile.FirstItem.Operations[index].Name += "_Copy";
          buProfileCalc.varProfileSettings.JobOpenClearAllProfiles = clearAllProfiles;
          if (data != null)
            this.activeProfile.SecondItem = new buEyeBaseVer5.Apps.ProfileItem(data);
        }
        else
        {
          buEyeBaseVer5.Apps.ProfileItem data = (buEyeBaseVer5.Apps.ProfileItem) null;
          if (this.activeProfile.FirstItem != null)
          {
            data = new buEyeBaseVer5.Apps.ProfileItem(this.activeProfile.SecondItem);
            clsInit.cProfile.CopyJustProfileProperties(this.activeProfile.FirstItem, ref this.activeProfile.SecondItem);
          }
          buEyeBaseVer5.Apps.ProfileItem Profile = new buEyeBaseVer5.Apps.ProfileItem(this.activeProfile.SecondItem);
          Profile.XReferanceLocation = LeftRightType.Left;
          Profile.Operations.Clear();
          for (int index = 0; index <= this.activeProfile.SecondItem.Operations.Count - 1; ++index)
          {
            if (this.activeProfile.SecondItem.Operations[index].Selected)
            {
              if (buProfileCalc.varProfileSettings.LeftToRightCopyRotateKeyHole && this.activeProfile.SecondItem.Operations[index].OperationData.OperationType == ProfileOperationTypes.Barrel)
              {
                this.activeProfile.SecondItem.Operations[index].OperationData.BarelData.BarrelAngle += 180.0;
                if (this.activeProfile.SecondItem.Operations[index].OperationData.BarelData.BarrelAngle >= 360.0)
                  this.activeProfile.SecondItem.Operations[index].OperationData.BarelData.BarrelAngle -= 360.0;
              }
              if (buProfileCalc.varProfileSettings.ChangeCwCCWDirForRightRefProfile)
                this.activeProfile.SecondItem.Operations[index].CamOPData.directionContour = buConversion5.ChangeClockDirection(this.activeProfile.SecondItem.Operations[index].CamOPData.directionContour);
              Profile.Operations.Add(this.activeProfile.SecondItem.Operations[index]);
            }
          }
          this.SaveProfileJobFile(AppPath.Base + "\\temp.job", Profile, false);
          bool clearAllProfiles = buProfileCalc.varProfileSettings.JobOpenClearAllProfiles;
          buProfileCalc.varProfileSettings.JobOpenClearAllProfiles = false;
          this.OpenProfileJobFile(AppPath.Base + "\\temp.job", true, true, false, ref this.activeProfile.FirstItem, false);
          this.activeProfile.FirstItem.ItemName += "_Copy";
          for (int index = 0; index <= this.activeProfile.FirstItem.Operations.Count - 1; ++index)
            this.activeProfile.FirstItem.Operations[index].Name += "_Copy";
          buProfileCalc.varProfileSettings.JobOpenClearAllProfiles = clearAllProfiles;
          if (data != null)
            this.activeProfile.SecondItem = new buEyeBaseVer5.Apps.ProfileItem(data);
        }
        this.ProfileTreeUpdate();
        clsInit.appProfile.doSetActiveProfile(1);
