  public void cmdPriorityOP()
  {
    try
    {
      if (buProfileCalc.varProfileRunSettings.activeProfileIndex == 0 & this.activeProfile.FirstItem != null && buProfileCalc.varProfileRunSettings.activeOPIndex >= 0 & buProfileCalc.varProfileRunSettings.activeOPIndex <= this.activeProfile.FirstItem.Operations.Count - 1)
        this.doSetPriority();
      if (!(buProfileCalc.varProfileRunSettings.activeProfileIndex == 1 & this.activeProfile.SecondItem != null) || !(buProfileCalc.varProfileRunSettings.activeOPIndex >= 0 & buProfileCalc.varProfileRunSettings.activeOPIndex <= this.activeProfile.SecondItem.Operations.Count - 1))
        return;
      this.doSetPriority();
    }
    catch (Exception ex)
    {
      buLog.addLog("", "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, true, "");
    }
  }

  public void cmdSelectPlane(bool FromOperation)
  {
    try
    {
      ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.ClearSelection();
      clsInit.appCommand.Reset(false);
      clsInit.appCommand.ShowViewportButtons(true, true, false);
      ccVars.Pages[ccVars.PageIndex].Form.viewportcad.SelectionFilterMode = selectionFilterType.Face;
      ccVars.Pages[ccVars.PageIndex].Form.viewportcad.ActionMode = devDept.Eyeshot.actionType.SelectVisibleByPickDynamic;
      ccVars.Action = actionTypeBU.profileSelectPlaneThenOperation;
      dynamicInfo.Command = AppLanguage.CadCamCommand[109];
      ccVars.stpDrawing = 1;
      ccVars.selectionProcess = false;
      for (int index = 0; index <= ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Count - 1; ++index)
        ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index].Selectable = true;
      ccVars.selectedFace = (Brep.Face) null;
    }
    catch (Exception ex)
    {
      buLog.addLog("", "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, true, "");
    }
  }

  public void cmdPlaneList()
  {
    F_SelectedPlanes fSelectedPlanes = new F_SelectedPlanes();
    for (int index = 0; index <= clsProfile.selectedPlanes.Count - 1; ++index)
    {
      fSelectedPlanes.Planes.Add(new SelectedPlaneInfo(clsProfile.selectedPlanes[index]));
      if ((Vector3D) clsProfile.selectedPlanes[index].refPlane.Equation == (Vector3D) buProfileCalc.varProfileRunSettings.OPData.selectedPlane.Equation)
        fSelectedPlanes.SelectedPlane = index;
    }
    buEyeBaseVer5.Apps.ProfileItem profileItem = clsInit.cProfile.SelectActiveProfile(this.activeProfile.FirstItem, this.activeProfile.SecondItem, ref buProfileCalc.varProfileRunSettings.activeProfileIndex);
    if (profileItem == null)
      return;
    if (profileItem.Drawings != null)
    {
      for (int index = 0; index <= profileItem.Drawings.Count - 1; ++index)
      {
        Entity entity = buVector5.CopyEntities(profileItem.Drawings[index].SolidEntity);
        entity.ColorMethod = colorMethodType.byEntity;
        entity.Color = Color.FromArgb(180, Color.DarkGray);
        entity.LayerName = "Default";
        fSelectedPlanes.PreviewEnts.Add(entity);
      }
    }
    fSelectedPlanes.pathString = buProfileCalc.varProfileRunSettings.pathPlanes;
    fSelectedPlanes.UcsData = buProfileCalc.varUCSData;
    fSelectedPlanes.PlaneThickess = buProfileCalc.varProfileSettings.PlaneThickness;
    fSelectedPlanes.Init();
    fSelectedPlanes.TopMost = true;
    int num = (int) fSelectedPlanes.ShowDialog();
    if (fSelectedPlanes.PropertiesForm.Result != DialogResult.OK)
      return;
    buProfileCalc.varProfileRunSettings.pathPlanes = fSelectedPlanes.pathString;
    clsProfile.selectedPlanes.Clear();
    clsProfile.selectedPlanes = new List<SelectedPlaneInfo>();
    for (int index = 0; index <= fSelectedPlanes.Planes.Count - 1; ++index)
      clsProfile.selectedPlanes.Add(new SelectedPlaneInfo(fSelectedPlanes.Planes[index]));
    if (fSelectedPlanes.Planes.Count > 0 && fSelectedPlanes.SelectedPlane >= 0)
    {
      if (profileItem.selectedFreePlanes.Count > 0)
      {
        SelectedPlaneInfo selectedPlaneInfo = new SelectedPlaneInfo(fSelectedPlanes.Planes[fSelectedPlanes.SelectedPlane]);
        profileItem.selectedFreePlanes.Clear();
        profileItem.selectedFreePlanes.Add(selectedPlaneInfo);
      }
      else
      {
        SelectedPlaneInfo selectedPlaneInfo = new SelectedPlaneInfo(fSelectedPlanes.Planes[fSelectedPlanes.SelectedPlane]);
        profileItem.selectedFreePlanes.Add(selectedPlaneInfo);
      }
      buProfileCalc.varProfileRunSettings.OPData.selectedPlane = (Plane) fSelectedPlanes.Planes[fSelectedPlanes.SelectedPlane].refPlane.Clone();
      buProfileCalc.varProfileRunSettings.OPData.selectedPlaneInfo = new SelectedPlaneInfo(fSelectedPlanes.Planes[fSelectedPlanes.SelectedPlane]);
    }
