  public void cmdSimulation(bool TopMost, bool ManuelSim = false, bool ReCalculate = false)
  {
    try
    {
      int num1 = 0;
      if (buProfileCalc.varProfileRunSettings.activeProfileIndex == 0 & this.activeProfile.FirstItem == null)
        return;
      if (this.activeProfile.FirstItem != null)
        num1 += this.activeProfile.FirstItem.Operations.Count;
      if (this.activeProfile.SecondItem != null)
        num1 += this.activeProfile.SecondItem.Operations.Count;
      if (num1 == 0)
      {
        buString5.MessageBoxWarning(buProfile.LangProfileMessage[10]);
      }
      else
      {
        buEyeBaseVer5.Apps.ProfileItem firstItem = this.activeProfile.FirstItem;
        buEyeBaseVer5.Apps.ProfileItem secondItem = this.activeProfile.SecondItem;
        bool flag1 = false;
        bool flag2 = false;
        bool GCodeToSim = false;
        if ((firstItem == null || !firstItem.Enable ? 0 : (firstItem.Operations.Count > 0 ? 1 : 0)) != 0)
        {
          flag1 = true;
          if (!firstItem.isGCodeCreated | firstItem.IsClamperDone)
            GCodeToSim = true;
        }
        if ((secondItem == null || !secondItem.Enable ? 0 : (secondItem.Operations.Count > 0 ? 1 : 0)) != 0)
        {
          flag2 = true;
          if (!secondItem.isGCodeCreated | secondItem.IsClamperDone)
            GCodeToSim = true;
        }
        if (!flag1 & !flag2)
        {
          buString5.MessageBoxWarning(buLangTranslate.preSentencesProfile.NoActiveProfile);
        }
        else
        {
          if (buProfileCalc.varProfileRunSettings.activeProfileIndex == 0 & !flag1)
            buProfileCalc.varProfileRunSettings.activeProfileIndex = 1;
          if (buProfileCalc.varProfileRunSettings.activeProfileIndex == 1 & !flag2)
            buProfileCalc.varProfileRunSettings.activeProfileIndex = 0;
          List<buEyeBaseVer5.Apps.ProfileClamper> ClamperList = new List<buEyeBaseVer5.Apps.ProfileClamper>();
          this.CollCheckIndex = 0;
          if (flag1 & !flag2 && firstItem.MaxClamperNumber != buProfileCalc.varProfileSettings.ProfileMaxClamper)
            firstItem.MaxClamperNumber = buProfileCalc.varProfileSettings.ProfileMaxClamper;
          if (!flag1 & flag2 && secondItem.MaxClamperNumber != buProfileCalc.varProfileSettings.ProfileMaxClamper)
            secondItem.MaxClamperNumber = buProfileCalc.varProfileSettings.ProfileMaxClamper;
          if (flag1 & flag2)
          {
            firstItem.MaxClamperNumber = buProfileCalc.varProfileSettings.ProfileMaxClamper / 2;
            secondItem.MaxClamperNumber = buProfileCalc.varProfileSettings.ProfileMaxClamper / 2;
          }
          if (buProfileCalc.varProfileRunSettings.activeProfileIndex == 1 & secondItem == null)
          {
            if (firstItem != null)
            {
              buProfileCalc.varProfileRunSettings.activeProfileIndex = 0;
            }
            else
            {
              buString5.MessageBoxWarning(buProfile.LangProfileMessage[38]);
              return;
            }
          }
          if (this.frmSim == null)
            this.frmSim = new F_ProfileSim();
          if (firstItem == null & secondItem == null)
          {
            buString5.MessageBoxWarning(buProfile.LangProfileMessage[38]);
          }
          else
          {
            if (flag1 & flag2)
              buProfileCalc.varProfileRunSettings.activeProfileIndex = 0;
            this.viewportSimilasyon.Entities.ClearSelection();
            this.cmdOnlineSimulationStart();
            this.listToCheck1.Clear();
            this.listToCheck2.Clear();
            this.listToCheck3.Clear();
            this.listToCheck4.Clear();
            if (flag1)
            {
              firstItem.isCollisionOnlineAvailable = false;
              if (firstItem.CalculationData.Count == 0)
                ManuelSim = false;
              for (int index = 0; index <= firstItem.Drawings.Count - 1; ++index)
              {
                if (firstItem.Drawings[index].SolidEntity != null)
                {
                  Entity entity = buVector5.CopyEntities(firstItem.Drawings[index].SolidEntity);
                  entity.Translate(firstItem.TotalOffset.X, firstItem.TotalOffset.Y, firstItem.TotalOffset.Z);
                  entity.Regen(0.1);
                  this.listToCheck3.Add(entity);
                }
              }
            }
            if (flag2)
            {
              secondItem.isCollisionOnlineAvailable = false;
              if (secondItem.CalculationData.Count == 0)
                ManuelSim = false;
              for (int index = 0; index <= secondItem.Drawings.Count - 1; ++index)
              {
                if (secondItem.Drawings[index].SolidEntity != null)
                {
                  double num2 = buProfileCalc.varProfileSettings.MachineLength - secondItem.Length;
                  Entity entity = buVector5.CopyEntities(secondItem.Drawings[index].SolidEntity);
                  entity.Translate(secondItem.TotalOffset.X + num2, secondItem.TotalOffset.Y, secondItem.TotalOffset.Z);
                  entity.Regen(0.1);
                  this.listToCheck3.Add(entity);
                }
              }
            }
            if (!ManuelSim)
            {
              if (flag1 & flag2)
              {
                firstItem.MaxClamperNumber = this.Clampers.Count / 2;
                secondItem.MaxClamperNumber = this.Clampers.Count / 2;
                bool Clamper = true;
                if (firstItem.IsClamperDone & secondItem.IsClamperDone)
                  Clamper = false;
                if (ReCalculate)
                  Clamper = true;
                bool all = this.doCalculateAll(ref firstItem, Clamper, true, GCodeToSim);
                bool flag3 = false;
                if (secondItem != null & buProfileCalc.varProfileSettings.RightProfileActive)
                  flag3 = this.doCalculateAll(ref secondItem, Clamper, true, GCodeToSim);
                if (all | flag3)
                {
                  if (!all)
                    buString5.MessageBoxWarning($"{buLangTranslate.preDef.First} {buLangTranslate.preDef.Profile} {buProfile.LangProfileMessage[10]}");
                  if (!flag3)
                    buString5.MessageBoxWarning($"{buLangTranslate.preDef.Second} {buLangTranslate.preDef.Profile} {buProfile.LangProfileMessage[10]}");
                  ClamperList = firstItem.CalculationData[buProfileCalc.varProfileRunSettings.activeCalcDataIndex].calcOperations[0].Clampers;
                }
              }
              else
              {
                if (buProfileCalc.varProfileRunSettings.activeProfileIndex == 0 & flag1)
                {
                  if (firstItem.Operations.Count > 0)
                  {
                    int num3 = 0;
                    if (firstItem.CalculationData.Count > 0 && firstItem.CalculationData[0].calcOperations.Count > 0)
                      num3 = firstItem.CalculationData[0].calcOperations[0].Clampers.Count;
                    bool Clamper = !firstItem.IsClamperDone | num3 == 0 | buProfileCalc.varProfileSettings.CalculateClamperEveryTime;
                    if (!this.doCalculateAll(ref firstItem, Clamper, true, GCodeToSim))
                      return;
                  }
                  this.SimIndex = 0;
                  if (firstItem.CalculationData[buProfileCalc.varProfileRunSettings.activeCalcDataIndex].calcOperations.Count > 0)
                  {
                    ClamperList = firstItem.CalculationData[buProfileCalc.varProfileRunSettings.activeCalcDataIndex].calcOperations[0].Clampers;
                  }
                  else
                  {
                    ClamperList.Clear();
                    for (int index = 0; index <= buProfileCalc.varProfileSettings.ProfileMaxClamper - 1; ++index)
                      ClamperList.Add(new buEyeBaseVer5.Apps.ProfileClamper(Convert.ToDouble(index + 1) * 300.0));
                  }
                  ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.ClearSelection();
                }
                if (buProfileCalc.varProfileRunSettings.activeProfileIndex == 1 & flag2)
                {
                  if (secondItem.Operations.Count > 0)
                  {
                    bool Clamper = !secondItem.IsClamperDone | secondItem.Operations[0].Clampers.Count == 0 | buProfileCalc.varProfileSettings.CalculateClamperEveryTime;
                    if (!this.doCalculateAll(ref secondItem, Clamper, true, GCodeToSim))
                      return;
                  }
                  this.SimIndex = 0;
                  if (secondItem.CalculationData[buProfileCalc.varProfileRunSettings.activeCalcDataIndex].calcOperations.Count > 0)
                  {
                    ClamperList = secondItem.CalculationData[buProfileCalc.varProfileRunSettings.activeCalcDataIndex].calcOperations[0].Clampers;
                  }
                  else
                  {
                    ClamperList.Clear();
                    for (int index = 0; index <= buProfileCalc.varProfileSettings.ProfileMaxClamper - 1; ++index)
                      ClamperList.Add(new buEyeBaseVer5.Apps.ProfileClamper(Convert.ToDouble(index + 1) * 300.0));
                  }
                  ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.ClearSelection();
                }
              }
            }
            if (this.activeProfile.GCodes == null)
              this.activeProfile.GCodes = new ArrayList();
            this.activeProfile.GCodes.Clear();
            this.doSetMissingClampers(ref firstItem, ref secondItem);
            if (flag1)
              this.activeProfile.GCodes.AddRange((ICollection) firstItem.GCodeList);
            if (flag2)
              this.activeProfile.GCodes.AddRange((ICollection) secondItem.GCodeList);
            this.BasicCollsionControl(ref firstItem);
            this.BasicCollsionControl(ref secondItem);
            this.DrawSimulationEntities(firstItem, secondItem, -1, ClamperList);
            this.frmSim.Properties.FormCloseMode = FormCloseModeType.Invisible;
            this.frmSim.Properties.FormPosition = FormStartPosition.CenterScreen;
            this.frmSim.TopMost = TopMost;
            this.frmSim.StartPosition = FormStartPosition.CenterScreen;
            this.frmSim.Init();
            if (!this.frmSim.Visible)
            {
              int num4 = (int) this.frmSim.ShowDialog();
            }
            if (flag1)
              this.doCheckProfileWarnings(ref firstItem);
            if (flag2)
              this.doCheckProfileWarnings(ref secondItem);
            this.doCheckProfileError();
            this.ProfileTreeUpdate();
          }
        }
      }
    }
    catch (Exception ex)
    {
      buLog.addLog("", "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, true, "");
    }
  }

