  public void cmdJobList()
  {
    if (this.Jobs == null)
      this.Jobs = new List<buEyeBaseVer5.Apps.ProfileItem>();
    if (this.Jobs.Count < 0)
      return;
    this.frmERPList.lst_items.Items.Clear();
    for (int index = 0; index <= this.Jobs.Count - 1; ++index)
    {
      if (this.Jobs[index] != null)
        this.frmERPList.lst_items.Items.Add((object) this.Jobs[index].ItemName);
    }
    this.frmERPList.chk_deleteloaded.Checked = buProfileCalc.varProfileRunSettings.JobListDeleteLoaded;
    this.frmERPList.PropertiesForm.FormCloseMode = FormCloseModeType.Invisible;
    this.frmERPList.radio_rightholder.Visible = buProfileCalc.varProfileSettings.RightProfileActive;
    this.frmERPList.pathString = buProfileCalc.varProfileRunSettings.pathJobList;
    this.frmERPList.Init();
    if (!this.frmERPList.Visible)
    {
      int num = (int) this.frmERPList.ShowDialog();
    }
    if (this.frmERPList.PropertiesForm.Result != DialogResult.OK)
      return;
    this.SaveByTick = true;
    buProfileCalc.varProfileRunSettings.pathJobList = this.frmERPList.pathString;
    buProfileCalc.varProfileRunSettings.JobListDeleteLoaded = this.frmERPList.chk_deleteloaded.Checked;
    if (!(this.frmERPList.SelectedJob >= 0 & this.frmERPList.SelectedJob <= this.Jobs.Count - 1))
      return;
    if (this.frmERPList.isLeftHolder)
    {
      this.activeProfile.FirstItem = new buEyeBaseVer5.Apps.ProfileItem(this.Jobs[this.frmERPList.SelectedJob]);
      clsItem.FrmProfileJob.tree_jobs.Nodes[0].Nodes[0].ForeColor = Color.Red;
      buProfileCalc.varProfileSettings.XDirRefType = this.activeProfile.FirstItem.XReferanceLocation;
      clsInit.appProfile.doSetActiveProfile(0);
    }
    else
    {
      this.activeProfile.SecondItem = new buEyeBaseVer5.Apps.ProfileItem(this.Jobs[this.frmERPList.SelectedJob]);
      clsItem.FrmProfileJob.tree_jobs.Nodes[0].Nodes[1].ForeColor = Color.Red;
      buProfileCalc.varProfileSettings.XDirRefType = this.activeProfile.SecondItem.XReferanceLocation;
      clsInit.appProfile.doSetActiveProfile(1);
    }
    if (buProfileCalc.varProfileRunSettings.JobListDeleteLoaded)
      this.Jobs.RemoveAt(this.frmERPList.SelectedJob);
    this.DrawActiveProfile();
    this.ProfileTreeUpdate();
  }

