  public void cmdDefaultValues()
  {
    if (AppSecurity.PasswordLevel < 2)
    {
      buString5.MessageBoxWarning(buLangTranslate.preSentences.LevelIsNotEnough);
    }
    else
    {
      if (buString5.MessageBoxQuestion(buLangTranslate.preSentences.DoyouWantToTurnDefaultValues) != DialogResult.Yes)
        return;
      Directory.Delete(AppPath.Settings, true);
      Directory.CreateDirectory(AppPath.Settings);
      buFile5.CopyFilesRecursively(AppPath.DefaultParameter, AppPath.Settings);
    }
  }

  public void Checked_Checked(object sender, EventArgs e)
  {
    buProfileCalc.varProfileRunSettings.SelectMode = clsItem.FrmProfileJob.chk_selectmode.Checked;
    clsItem.FrmProfileJob.tree_jobs.CheckBoxes = buProfileCalc.varProfileRunSettings.SelectMode;
    if (clsItem.FrmProfileJob.tree_jobs.Nodes != null && clsItem.FrmProfileJob.tree_jobs.Nodes.Count >= 1)
    {
      clsItem.FrmProfileJob.tree_jobs.Nodes[0].Expand();
      if (clsItem.FrmProfileJob.tree_jobs.Nodes[0].Nodes != null)
      {
        if (clsItem.FrmProfileJob.tree_jobs.Nodes[0].Nodes.Count >= 1)
          clsItem.FrmProfileJob.tree_jobs.Nodes[0].Nodes[0].Expand();
        if (clsItem.FrmProfileJob.tree_jobs.Nodes[0].Nodes.Count >= 2)
          clsItem.FrmProfileJob.tree_jobs.Nodes[0].Nodes[1].Expand();
      }
    }
    if (clsItem.FrmProfileJob.chk_selectmode.Checked)
      clsItem.FrmProfileJob.mnu_remove.Text = $"{buLangTranslate.preDef.Delete} {buLangTranslate.preDef.Selected} {buLangTranslate.preDef.Operation}";
    else
      clsItem.FrmProfileJob.mnu_remove.Text = $"{buLangTranslate.preDef.Delete} {buLangTranslate.preDef.Operation}";
    if (buProfileCalc.varProfileRunSettings.SelectMode)
      return;
    this.Changing = true;
    this.doUnSelectProfile(buProfileCalc.varProfileRunSettings.activeProfileIndex);
    for (int index = 0; index <= clsItem.FrmProfileJob.tree_jobs.Nodes.Count - 1; ++index)
      clsItem.FrmProfileJob.tree_jobs.Nodes[index].Expand();
    this.Changing = false;
  }

  private void viewportSimilasyon_WorkCompleted(object sender, WorkCompletedEventArgs e)
  {
    try
    {
      if (!clsInit.appProfile.timSim.Enabled)
        return;
      this.isCollisionRunning = false;
      if (clsProfile.colDetect.Result != null)
      {
        if (clsProfile.colDetect.Result.Length != 0)
        {
          Class5.smethod_165((IList<CollisionResult>) clsProfile.colDetect.Result, this);
          this.timSim.Enabled = false;
          this.viewportSimilasyon.Invalidate();
        }
      }
      else
        this.viewportSimilasyon.TempEntities.Clear();
      ++this.CollCheckIndex;
      if (this.CollCheckIndex < 2)
        return;
      this.CollCheckIndex = 0;
    }
    catch (Exception ex)
    {
    }
  }

  private void viewportSimilasyon_WorkFailed(object sender, WorkFailedEventArgs e)
  {
    this.isCollisionRunning = false;
    this.viewportSimilasyon.TempEntities.Clear();
  }

  private void viewportSimilasyon_WorkCancelled(object sender, EventArgs e)
  {
    this.isCollisionRunning = false;
    this.viewportSimilasyon.TempEntities.Clear();
  }

  public void DrawMacroEntities(buEyeBaseVer5.Apps.ProfileItem FirstProfile, bool cam = true, bool contour = true)
  {
    this.viewportCommon.Entities.Clear();
    double num = 0.0;
    if (FirstProfile != null)
    {
      for (int index = 0; index <= FirstProfile.Drawings.Count - 1; ++index)
      {
        if (FirstProfile.Drawings[index].SolidEntity != null)
        {
          Entity entity = buVector5.CopyEntities(FirstProfile.Drawings[index].SolidEntity);
          entity.Color = Color.FromArgb(buProfileCalc.varProfileSettings.MaterialTranspancy, FirstProfile.colorProfile);
          entity.ColorMethod = colorMethodType.byEntity;
          entity.EntityData = (object) new CustomData()
          {
            typeDefination = entityTypeDefination.Profile,
            ActionName = "profile",
            EntityName = nameof (FirstProfile),
            OriginalEntityIndex = this.viewportCommon.Entities.Count
          };
          entity.Translate(FirstProfile.TotalOffset.X + num, FirstProfile.TotalOffset.Y, FirstProfile.TotalOffset.Z);
          entity.Regen(0.01);
          entity.LayerName = "Profile";
          this.viewportCommon.Entities.Add(entity);
        }
      }
      for (int index1 = 0; index1 <= FirstProfile.Operations.Count - 1; ++index1)
      {
        buEyeBaseVer5.Apps.ProfileOperation operation = FirstProfile.Operations[index1];
        if (operation != null && operation.EntityMultiSolidDepth != null)
        {
          for (int index2 = 0; index2 <= operation.EntityMultiSolidDepth.Count - 1; ++index2)
          {
            Entity copiedEnt = (Entity) null;
            buVector5.CopyEntities(operation.EntityMultiSolidDepth[index2], ref copiedEnt);
            ((CustomData) copiedEnt.EntityData).OriginalEntityIndex = this.viewportCommon.Entities.Count;
            ((CustomData) copiedEnt.EntityData).RefIndex = 0;
            ((CustomData) copiedEnt.EntityData).Sequence = index1;
            ((CustomData) copiedEnt.EntityData).typeDefination = entityTypeDefination.Operation;
            copiedEnt.ColorMethod = colorMethodType.byEntity;
            copiedEnt.LineTypeMethod = colorMethodType.byEntity;
            copiedEnt.Color = !operation.Enable ? Color.FromArgb(150, Color.Orange) : Color.FromArgb(150, Color.Cyan);
            if (operation.Error)
              copiedEnt.Color = Color.FromArgb(180, Color.Red);
            copiedEnt.LineWeight = 1f;
            copiedEnt.Translate(FirstProfile.TotalOffset.X + num, FirstProfile.TotalOffset.Y, FirstProfile.TotalOffset.Z);
            copiedEnt.Regen(0.01);
            copiedEnt.LayerName = "Operation";
            this.viewportCommon.Entities.Add(copiedEnt);
          }
          if (cam)
          {
            for (int index3 = 0; index3 <= operation.EntityMultiCam.Count - 1; ++index3)
            {
              Entity copiedEntity = (Entity) null;
              buEntity.Copy(operation.EntityMultiCam[index3], ref copiedEntity);
              ((CustomData) copiedEntity.EntityData).OriginalEntityIndex = this.viewportCommon.Entities.Count;
              copiedEntity.ColorMethod = colorMethodType.byEntity;
              copiedEntity.LineTypeMethod = colorMethodType.byEntity;
              copiedEntity.Color = Color.Red;
              copiedEntity.LineWeight = 2f;
              copiedEntity.Translate(FirstProfile.TotalOffset.X + num, FirstProfile.TotalOffset.Y, FirstProfile.TotalOffset.Z);
              copiedEntity.Regen(0.01);
              copiedEntity.LayerName = "Cam";
              if (operation.Action == actionTypeBU.profileNotch && operation.EntityMultiCam[index3].Info.Offset != (Point3D) null)
                copiedEntity.Translate(operation.EntityMultiCam[index3].Info.Offset.X, operation.EntityMultiCam[index3].Info.Offset.Y, operation.EntityMultiCam[index3].Info.Offset.Z);
              this.viewportCommon.Entities.Add(copiedEntity);
            }
          }
          if (contour)
          {
            for (int index4 = 0; index4 <= operation.EntityMultiContour.Count - 1; ++index4)
            {
              Entity copiedEntity = (Entity) null;
              buEntity.Copy(operation.EntityMultiContour[index4], ref copiedEntity);
              ((CustomData) copiedEntity.EntityData).OriginalEntityIndex = this.viewportCommon.Entities.Count;
              copiedEntity.ColorMethod = colorMethodType.byEntity;
              copiedEntity.LineTypeMethod = colorMethodType.byEntity;
              copiedEntity.Color = Color.Lime;
              copiedEntity.LineWeight = 2f;
              copiedEntity.Translate(FirstProfile.TotalOffset.X + num, FirstProfile.TotalOffset.Y, FirstProfile.TotalOffset.Z);
              copiedEntity.Regen(0.01);
              copiedEntity.LayerName = "Drawing";
              this.viewportCommon.Entities.Add(copiedEntity);
            }
          }
        }
      }
    }
    this.viewportCommon.Invalidate();
  }

  private void viewportSimilasyon_MouseDown(object sender, MouseEventArgs e)
  {
    if ((e.Button != MouseButtons.Left || this.viewportSimilasyon.ActionMode != devDept.Eyeshot.actionType.None ? 1 : (this.viewportSimilasyon.Viewports[0].ToolBar.Contains(e.Location) ? 1 : 0)) != 0)
      return;
    if (!buProfileCalc.varTemps.MeasureActive)
      this.entityIndex = this.viewportSimilasyon.GetEntityUnderMouseCursor(e.Location);
    if (this.entityIndex < 0 & !buProfileCalc.varTemps.MeasureActive)
      return;
    if (this.entityIndex >= 0)
    {
      if (this.viewportSimilasyon.Entities[this.entityIndex].EntityData != null)
      {
        if (((CustomData) this.viewportSimilasyon.Entities[this.entityIndex].EntityData).typeDefination != entityTypeDefination.Clamper)
        {
          this.entityIndex = -1;
          return;
        }
      }
      else
      {
        this.entityIndex = -1;
        return;
      }
    }
    this.viewportSimilasyon.ScreenToPlane(e.Location, this.planeActive, out this.point3D_0);
    if (this.point3D_0 != (Point3D) null & !buProfileCalc.varTemps.MeasureActive)
      this.point3D_1 = new Point3D(this.point3D_0.X, this.point3D_0.Y, this.point3D_0.Z);
    if (!(buProfileCalc.varTemps.MeasureActive & !buProfileCalc.varTemps.DrawMouseDown))
      return;
    buProfileCalc.varTemps.DrawMouseDown = true;
    buProfileCalc.varTemps.pntMouseDown = new Point3D(this.point3D_0.X, this.point3D_0.Y, this.point3D_0.Z);
  }

  private void viewportSimilasyon_MouseMove(object sender, MouseEventArgs e)
  {
    Point3D intPoint1 = new Point3D();
    this.viewportSimilasyon.ScreenToPlane(e.Location, this.planeActive, out intPoint1);
    if (intPoint1 != (Point3D) null && this.frmSim != null && this.frmSim != null)
    {
      this.frmSim.lbl_x.Text = "X: " + intPoint1.X.ToString("f3");
      this.frmSim.lbl_y.Text = "Y: " + intPoint1.Y.ToString("f3");
      this.frmSim.lbl_z.Text = "Z: " + intPoint1.Z.ToString("f3");
    }
    if (((e.Button != MouseButtons.Left || this.viewportSimilasyon.ActionMode != devDept.Eyeshot.actionType.None ? 1 : (this.viewportSimilasyon.Viewports[0].ToolBar.Contains(e.Location) ? 1 : 0)) & (!buProfileCalc.varTemps.MeasureActive ? 1 : 0)) != 0)
      return;
    if ((this.entityIndex == -1 ? 0 : (e.Button == MouseButtons.Left & !buProfileCalc.varTemps.MeasureActive ? 1 : 0)) != 0)
    {
      Entity entity = this.viewportSimilasyon.Entities[this.entityIndex];
      buEyeBaseVer5.Apps.ProfileItem profileItem = clsInit.cProfile.SelectActiveProfile(this.activeProfile.FirstItem, this.activeProfile.SecondItem, ref buProfileCalc.varProfileRunSettings.activeProfileIndex);
      Point3D intPoint2;
      this.viewportSimilasyon.ScreenToPlane(e.Location, new Plane(), out intPoint2);
      if (intPoint2 != (Point3D) null)
      {
        if (buProfileCalc.varProfileRunSettings.activeProfileIndex == 0)
        {
          double num = profileItem.Length;
          if (!buProfileCalc.varProfileSettings.ClamperCanMoveInsideProfileLength)
            num = buProfileCalc.varProfileSettings.MachineLength;
          if (intPoint2.X >= 0.0 & intPoint2.X <= num)
          {
            if (this.point3D_0 != (Point3D) null)
            {
              Vector3D v = Vector3D.Subtract(new Point3D(intPoint2.X, 0.0, 0.0), new Point3D(this.point3D_0.X, 0.0, 0.0));
              entity.Translate(v);
            }
            this.viewportSimilasyon.Entities.Regen();
            this.viewportSimilasyon.Invalidate();
          }
        }
        if (buProfileCalc.varProfileRunSettings.activeProfileIndex == 1)
        {
          double num = buProfileCalc.varProfileSettings.MachineLength - profileItem.Length;
          if (!buProfileCalc.varProfileSettings.ClamperCanMoveInsideProfileLength)
            num = 0.0;
          if (intPoint2.X >= num & intPoint2.X <= buProfileCalc.varProfileSettings.MachineLength)
          {
            if (this.point3D_0 != (Point3D) null)
            {
              Vector3D v = Vector3D.Subtract(new Point3D(intPoint2.X, 0.0, 0.0), new Point3D(this.point3D_0.X, 0.0, 0.0));
              entity.Translate(v);
            }
            this.viewportSimilasyon.Entities.Regen();
            this.viewportSimilasyon.Invalidate();
          }
        }
        this.point3D_0 = intPoint2;
      }
    }
    if (!(buProfileCalc.varTemps.MeasureActive & buProfileCalc.varTemps.DrawMouseDown))
      return;
    this.DrawMeasureLine(intPoint1, false);
  }

  private void viewportSimilasyon_MouseUp(object sender, MouseEventArgs e)
  {
    if (this.entityIndex >= 0)
    {
      buEyeBaseVer5.Apps.ProfileItem curItem = clsInit.cProfile.SelectActiveProfile(this.activeProfile.FirstItem, this.activeProfile.SecondItem, ref buProfileCalc.varProfileRunSettings.activeProfileIndex);
      if (this.viewportSimilasyon.Entities[this.entityIndex].EntityData != null & curItem.CalculationData.Count > 0)
      {
        CustomData entityData = this.viewportSimilasyon.Entities[this.entityIndex].EntityData as CustomData;
        ProfileItemCalc CalcData = curItem.CalculationData[buProfileCalc.varProfileRunSettings.activeCalcDataIndex];
        if (entityData.typeDefination == entityTypeDefination.Clamper & this.point3D_1 != (Point3D) null)
        {
          this.viewportSimilasyon.ScreenToPlane(e.Location, new Plane(), out this.point3D_2);
          int refIndex = entityData.RefIndex;
          if (!(this.point3D_2 != (Point3D) null))
            return;
          this.ClamperMove(this.point3D_2.X - this.point3D_1.X, entityData.RefIndex, ref curItem, ref CalcData, true);
          return;
        }
      }
    }
    if (buProfileCalc.varTemps.MeasureActive & buProfileCalc.varTemps.DrawMouseDown)
    {
      this.viewportSimilasyon.ScreenToPlane(e.Location, this.planeActive, out this.point3D_2);
      this.DrawMeasureLine(this.point3D_2, true);
      buProfileCalc.varTemps.MeasureActive = false;
      buProfileCalc.varTemps.DrawMouseDown = false;
    }
    this.entityIndex = -1;
  }

  public void viewportLayoutPreview_MouseMove(object sender, MouseEventArgs e)
  {
    string str = "";
    Point3D intPoint1 = new Point3D();
    clsItem.ModelMainPreview.ScreenToPlane(e.Location, Plane.YZ, out intPoint1);
    if (intPoint1 != (Point3D) null)
    {
      System.Drawing.Point mousePos = new System.Drawing.Point(5, 22);
      Point3D intPoint2 = new Point3D();
      clsItem.ModelMainPreview.ScreenToPlane(mousePos, Plane.YZ, out intPoint2);
      if (buProfileCalc.varProfileRunSettings.activeProfileIndex == 0)
        str = buLangTranslate.preDef.Left;
      if (buProfileCalc.varProfileRunSettings.activeProfileIndex == 1)
        str = buLangTranslate.preDef.Right;
      str = $"{str} - Y: {intPoint1.Y.ToString("f2")} , Z: {intPoint1.Z.ToString("f2")}";
    }
    clsItem.FrmProfileJob.lbl_info.Text = str;
  }

  public void viewportLayoutPreview_MouseDoubleClick(object sender, MouseEventArgs e)
  {
    string callMethod = nameof (viewportLayoutPreview_MouseDoubleClick);
    try
    {
      Point3D intPoint = new Point3D();
      clsItem.ModelMainPreview.ScreenToPlane(e.Location, Plane.YZ, out intPoint);
      if (!(intPoint != (Point3D) null) || ccVars.Action == 0)
        return;
      if (buProfileCalc.varProfileRunSettings.ShapeDataParameters.selectedPlane == planeBoxNames.Top | buProfileCalc.varProfileRunSettings.ShapeDataParameters.selectedPlane == planeBoxNames.Bottom)
      {
        DialogBoxInput dialogBoxInput = new DialogBoxInput();
        dialogBoxInput.FormCaption = buLangTranslate.preDef.Profile + " Y";
        dialogBoxInput.ValueCaption = "Y " + buLangTranslate.preDef.Value;
        dialogBoxInput.Value = Math.Round(Math.Abs(intPoint.Y), 2);
        dialogBoxInput.StartPosition = FormStartPosition.CenterScreen;
        dialogBoxInput.Init();
        int num = (int) dialogBoxInput.ShowDialog();
        if (dialogBoxInput.Result == DialogResult.OK && this.FrmOperationList.dgv_data.Rows.Count > 1)
          this.FrmOperationList.dgv_data.Rows[1].Cells[1].Value = (object) dialogBoxInput.Value;
      }
      if (!(buProfileCalc.varProfileRunSettings.ShapeDataParameters.selectedPlane == planeBoxNames.Front | buProfileCalc.varProfileRunSettings.ShapeDataParameters.selectedPlane == planeBoxNames.Back))
        return;
      DialogBoxInput dialogBoxInput1 = new DialogBoxInput();
      dialogBoxInput1.FormCaption = buLangTranslate.preDef.Profile + " Z";
      dialogBoxInput1.ValueCaption = "Z " + buLangTranslate.preDef.Value;
      dialogBoxInput1.Value = Math.Round(intPoint.Z, 2);
      dialogBoxInput1.StartPosition = FormStartPosition.CenterScreen;
      dialogBoxInput1.Init();
      int num1 = (int) dialogBoxInput1.ShowDialog();
      if (dialogBoxInput1.Result != DialogResult.OK || this.FrmOperationList.dgv_data.Rows.Count <= 1)
        return;
      this.FrmOperationList.dgv_data.Rows[1].Cells[1].Value = (object) dialogBoxInput1.Value;
    }
    catch (Exception ex)
    {
      buException.throwException(ex, this.string_1, callMethod, false, "");
    }
  }

  public void DrawMeasureLine(Point3D pntMove, bool Finished)
  {
    if (this.viewportSimilasyon.Entities.Count > 0)
    {
      Entity entity1 = this.viewportSimilasyon.Entities[this.viewportSimilasyon.Entities.Count - 1];
      if ((entity1.EntityData == null ? 0 : (entity1.EntityData is CustomData ? 1 : 0)) != 0 && ((CustomData) entity1.EntityData).typeDefination == entityTypeDefination.TempDraw | ((CustomData) entity1.EntityData).typeDefination == entityTypeDefination.TempText)
        this.viewportSimilasyon.Entities.RemoveAt(this.viewportSimilasyon.Entities.Count - 1);
      Entity entity2 = this.viewportSimilasyon.Entities[this.viewportSimilasyon.Entities.Count - 1];
      if ((entity2.EntityData == null ? 0 : (entity2.EntityData is CustomData ? 1 : 0)) != 0 && ((CustomData) entity2.EntityData).typeDefination == entityTypeDefination.TempDraw | ((CustomData) entity2.EntityData).typeDefination == entityTypeDefination.TempText)
        this.viewportSimilasyon.Entities.RemoveAt(this.viewportSimilasyon.Entities.Count - 1);
    }
    devDept.Eyeshot.Entities.Line line = new devDept.Eyeshot.Entities.Line(buProfileCalc.varTemps.pntMouseDown, new Point3D(pntMove.X, pntMove.Y, pntMove.Z));
    if (clsInit.cVector5.PointAngle(new Point3D(pntMove.X, pntMove.Y, pntMove.Z), buProfileCalc.varTemps.pntMouseDown, this.planeActive) % 90.0 < 2.0)
      ;
    line.Color = Color.Black;
    line.ColorMethod = colorMethodType.byEntity;
    line.LineWeight = 2f;
    line.LineWeightMethod = colorMethodType.byEntity;
    line.EntityData = (object) new CustomData()
    {
      typeDefination = entityTypeDefination.TempDraw
    };
    this.viewportSimilasyon.Entities.Add((Entity) line);
    Text text = new Text(this.planeActive, pntMove, "  " + line.Length().ToString("f2"), 20.0, Text.alignmentType.MiddleLeft);
    text.Color = Color.Black;
    text.ColorMethod = colorMethodType.byEntity;
    text.EntityData = (object) new CustomData()
    {
      typeDefination = entityTypeDefination.TempText
    };
    this.viewportSimilasyon.Entities.Add((Entity) text);
    this.viewportSimilasyon.Invalidate();
  }

  public void Sim_Tick(object sender, EventArgs e)
  {
    try
    {
      if (this.isCollisionRunning)
        return;
      this.listToCheck2.Clear();
      this.listToCheck4.Clear();
      bool flag1 = false;
      ToolBase5 Tool = new ToolBase5();
      int num = buProfileCalc.varProfileRunSettings.SimStep;
      if (this.frmSim.chk_collisiondetect.Checked && num < buProfileCalc.varProfileSettings.CollisionControlMinStep)
        num = buProfileCalc.varProfileSettings.CollisionControlMinStep;
      buEyeBaseVer5.Apps.ProfileItem profileItem = clsInit.cProfile.SelectActiveProfile(this.activeProfile.FirstItem, this.activeProfile.SecondItem, ref buProfileCalc.varProfileRunSettings.activeProfileIndex);
      if (profileItem == null)
        return;
      if (this.SimIndex == 0)
        this.list_4.Clear();
      if (profileItem.CalculationData.Count > 0 & profileItem.Enable)
      {
        if (this.SimIndex >= 0 & this.SimIndex < profileItem.CalculationData[buProfileCalc.varProfileRunSettings.activeCalcDataIndex].SimMoves.Count - 1)
        {
          this.viewportSimilasyon.TempEntities.Clear();
          if (this.viewportSimilasyon.Entities.Count > 0)
          {
            this.viewportSimilasyon.Entities.ClearSelection();
            for (int index = 0; index <= this.viewportSimilasyon.Entities.Count - 1; ++index)
            {
              CustomData entityData = this.viewportSimilasyon.Entities[index].EntityData as CustomData;
              if (entityData.typeDefination == entityTypeDefination.Temp | entityData.typeDefination == entityTypeDefination.TempDraw | entityData.typeDefination == entityTypeDefination.TempText)
                this.viewportSimilasyon.Entities[index].Selected = true;
            }
            this.viewportSimilasyon.Entities.DeleteSelected();
          }
          Pnt6DSimMove PntMove = new Pnt6DSimMove(profileItem.CalculationData[buProfileCalc.varProfileRunSettings.activeCalcDataIndex].SimMoves[this.SimIndex]);
          if (PntMove.ToolName == null)
            PntMove.ToolName = "";
          for (int index = 0; index <= ccVars.Tools[0].Tools.Count - 1; ++index)
          {
            if (ccVars.Tools[0].Tools[index].Data.Name == PntMove.ToolName)
              Tool = new ToolBase5(ccVars.Tools[0].Tools[index]);
          }
          List<buEyeBaseVer5.Apps.ProfileClamper> ClampersPosition1 = new List<buEyeBaseVer5.Apps.ProfileClamper>();
          if (PntMove.Clampers != null)
          {
            for (int index = 0; index <= PntMove.Clampers.Count - 1; ++index)
            {
              if (PntMove.Clampers[index] > 0.0)
                ClampersPosition1.Add(new buEyeBaseVer5.Apps.ProfileClamper(PntMove.Clampers[index]));
            }
          }
          if (ClampersPosition1.Count > 0 & this.list_4.Count > 0 && ClampersPosition1.Count == this.list_4.Count)
          {
            for (int index = 0; index <= ClampersPosition1.Count - 1; ++index)
            {
              if (!buCompare5.EQ(ClampersPosition1[index].XPosition, this.list_4[index].XPosition, 0.01))
                flag1 = true;
            }
          }
          if (this.frmSim != null && this.frmSim.Visible)
          {
            this.frmSim.txt_simx.Text = PntMove.X.ToString("f3");
            this.frmSim.txt_simy.Text = PntMove.Y.ToString("f3");
            this.frmSim.txt_simz.Text = PntMove.Z.ToString("f3");
            this.frmSim.txt_sima.Text = PntMove.A.ToString("f3");
            this.frmSim.txt_simt.Text = PntMove.ToolNo.ToString("");
            this.frmSim.txt_simf.Text = PntMove.FeedRate.ToString("f1");
            this.frmSim.txt_sims.Text = PntMove.SpindleRpm.ToString();
            this.frmSim.txt_command.Text = PntMove.Command;
            this.frmSim.panel5.Refresh();
          }
          PntMove.Z += profileItem.SupportBlock.SupportBlockZHeight;
          PntMove.Y -= profileItem.SupportBlock.SupportBlockY2BackWidth;
          if (flag1)
          {
            double[,] numArray = new double[ClampersPosition1.Count, 10];
            for (int index1 = 0; index1 <= ClampersPosition1.Count - 1; ++index1)
            {
              List<double> Values = new List<double>();
              buNumeric5.DevideMinMaxValueByNumber(this.list_4[index1].XPosition, ClampersPosition1[index1].XPosition, 10, ref Values);
              for (int index2 = 0; index2 <= Values.Count - 1; ++index2)
                numArray[index1, index2] = Values[index2];
            }
            if (numArray.Length > 0)
            {
              for (int index3 = 0; index3 < 10; index3 += 2)
              {
                List<buEyeBaseVer5.Apps.ProfileClamper> ClampersPosition2 = new List<buEyeBaseVer5.Apps.ProfileClamper>();
                for (int index4 = 0; index4 <= ClampersPosition1.Count - 1; ++index4)
                  ClampersPosition2.Add(new buEyeBaseVer5.Apps.ProfileClamper(numArray[index4, index3]));
                if (ClampersPosition2.Count > 0 & buProfileCalc.varProfileRunSettings.activeCalcDataIndex >= 0 & buProfileCalc.varProfileRunSettings.activeCalcDataIndex <= profileItem.CalculationData.Count - 1)
                  this.MoveSimPart(PntMove, ClampersPosition2, Tool, profileItem.CalculationData[buProfileCalc.varProfileRunSettings.activeCalcDataIndex]);
              }
            }
          }
          if (buProfileCalc.varProfileRunSettings.activeCalcDataIndex >= 0 & buProfileCalc.varProfileRunSettings.activeCalcDataIndex <= profileItem.CalculationData.Count - 1)
            this.MoveSimPart(PntMove, ClampersPosition1, Tool, profileItem.CalculationData[buProfileCalc.varProfileRunSettings.activeCalcDataIndex]);
          if (ClampersPosition1.Count > 0)
          {
            this.list_4.Clear();
            this.list_4 = new List<buEyeBaseVer5.Apps.ProfileClamper>();
            for (int index = 0; index <= ClampersPosition1.Count - 1; ++index)
              this.list_4.Add(new buEyeBaseVer5.Apps.ProfileClamper(ClampersPosition1[index]));
          }
          if (!this.viewportSimilasyon.IsBusy & this.CollCheckIndex == 0)
            this.CollisionCheck();
          if (!this.viewportSimilasyon.IsBusy & this.CollCheckIndex >= 1)
            this.CollisionCheckWithProfileAndHead();
          this.viewportSimilasyon.Invalidate();
          bool flag2 = false;
          for (int simIndex = this.SimIndex; simIndex <= this.SimIndex + num; ++simIndex)
          {
            if (simIndex <= profileItem.CalculationData[buProfileCalc.varProfileRunSettings.activeCalcDataIndex].SimMoves.Count - 1)
            {
              if (profileItem.CalculationData[buProfileCalc.varProfileRunSettings.activeCalcDataIndex].SimMoves[simIndex].isMCode)
                flag2 = true;
              if (profileItem.CalculationData[buProfileCalc.varProfileRunSettings.activeCalcDataIndex].SimMoves[simIndex].Clampers != null && profileItem.CalculationData[buProfileCalc.varProfileRunSettings.activeCalcDataIndex].SimMoves[simIndex].Clampers.Count > 0)
                flag2 = true;
            }
          }
          if (flag2)
            ++this.SimIndex;
          else
            this.SimIndex += num;
        }
        else
        {
          if (buProfileCalc.varProfileRunSettings.activeProfileIndex == 0)
          {
            if (this.activeProfile.FirstItem != null)
            {
              if (buProfileCalc.varProfileRunSettings.activeCalcDataIndex < profileItem.CalculationData.Count - 1)
              {
                ++buProfileCalc.varProfileRunSettings.activeCalcDataIndex;
                this.SimIndex = 0;
                return;
              }
              buProfileCalc.varProfileRunSettings.activeCalcDataIndex = 0;
              this.activeProfile.FirstItem.isSimulationDone = true;
              this.activeProfile.FirstItem.isCollisionControlDone = this.frmSim.chk_collisiondetect.Checked;
            }
            if (this.activeProfile.SecondItem != null)
            {
              buProfileCalc.varProfileRunSettings.activeCalcDataIndex = 0;
              buProfileCalc.varProfileRunSettings.activeProfileIndex = 1;
              this.SimIndex = 0;
              return;
            }
          }
          if (buProfileCalc.varProfileRunSettings.activeProfileIndex == 1)
          {
            if (buProfileCalc.varProfileRunSettings.activeCalcDataIndex < profileItem.CalculationData.Count - 1)
            {
              ++buProfileCalc.varProfileRunSettings.activeCalcDataIndex;
              this.SimIndex = 0;
              return;
            }
            if (this.activeProfile.FirstItem != null)
              buProfileCalc.varProfileRunSettings.activeProfileIndex = 0;
            if (this.activeProfile.SecondItem != null)
            {
              this.activeProfile.SecondItem.isSimulationDone = true;
              this.activeProfile.SecondItem.isCollisionControlDone = this.frmSim.chk_collisiondetect.Checked;
            }
          }
          ProfileItemCalc profileItemCalc = profileItem.CalculationData[buProfileCalc.varProfileRunSettings.activeCalcDataIndex];
          if (profileItemCalc.SimMoves.Count > 0)
          {
            Pnt6DSimMove PntMove = new Pnt6DSimMove(profileItemCalc.SimMoves[profileItemCalc.SimMoves.Count - 1]);
            PntMove.A = 0.0;
            PntMove.Z = buProfileCalc.varProfileSettings.ParkPositionZ + ccVars.KinematicOrjinal.RotateCenterOffsetOfA.Z + 100.0;
            List<buEyeBaseVer5.Apps.ProfileClamper> ClampersPosition = new List<buEyeBaseVer5.Apps.ProfileClamper>();
            if (PntMove.Clampers != null)
            {
              for (int index = 0; index <= PntMove.Clampers.Count - 1; ++index)
              {
                if (PntMove.Clampers[index] > 0.0)
                  ClampersPosition.Add(new buEyeBaseVer5.Apps.ProfileClamper(PntMove.Clampers[index]));
              }
            }
            if (buProfileCalc.varProfileRunSettings.activeCalcDataIndex >= 0 & buProfileCalc.varProfileRunSettings.activeCalcDataIndex <= profileItem.CalculationData.Count - 1)
              this.MoveSimPart(PntMove, ClampersPosition, Tool, profileItem.CalculationData[buProfileCalc.varProfileRunSettings.activeCalcDataIndex]);
          }
          this.SimIndex = -1;
          this.DeleteAllSimPartsFromViewport();
          this.viewportSimilasyon.Invalidate();
          this.timSim.Enabled = false;
          this.activeProfile.isSimulationDone = true;
        }
      }
      else if (buProfileCalc.varProfileRunSettings.activeProfileIndex == 0 && this.activeProfile.SecondItem != null)
      {
        buProfileCalc.varProfileRunSettings.activeProfileIndex = 1;
        this.SimIndex = 0;
      }
      else
      {
        if (buProfileCalc.varProfileRunSettings.activeProfileIndex == 1 && this.activeProfile.FirstItem != null)
          buProfileCalc.varProfileRunSettings.activeProfileIndex = 0;
        this.SimIndex = -1;
        this.DeleteAllSimPartsFromViewport();
        if (profileItem.CalculationData.Count > 0 & buProfileCalc.varProfileRunSettings.activeCalcDataIndex >= 0 & buProfileCalc.varProfileRunSettings.activeCalcDataIndex <= profileItem.CalculationData.Count - 1)
        {
          ProfileItemCalc ItemCalc = profileItem.CalculationData[buProfileCalc.varProfileRunSettings.activeCalcDataIndex];
          if (ItemCalc.SimMoves.Count > 0)
          {
            Pnt6DSimMove PntMove = new Pnt6DSimMove(profileItem.CalculationData[buProfileCalc.varProfileRunSettings.activeCalcDataIndex].SimMoves[profileItem.CalculationData[buProfileCalc.varProfileRunSettings.activeCalcDataIndex].SimMoves.Count - 1]);
            PntMove.A = 0.0;
            PntMove.Z = 100.0;
            List<buEyeBaseVer5.Apps.ProfileClamper> ClampersPosition = new List<buEyeBaseVer5.Apps.ProfileClamper>();
            if (PntMove.Clampers != null)
            {
              for (int index = 0; index <= PntMove.Clampers.Count - 1; ++index)
              {
                if (PntMove.Clampers[index] > 0.0)
                  ClampersPosition.Add(new buEyeBaseVer5.Apps.ProfileClamper(PntMove.Clampers[index]));
              }
            }
            this.MoveSimPart(PntMove, ClampersPosition, Tool, ItemCalc);
          }
        }
        this.timSim.Enabled = false;
        if (this.activeProfile.FirstItem != null)
        {
          this.activeProfile.FirstItem.isSimulationDone = true;
          this.activeProfile.FirstItem.isCollisionControlDone = this.frmSim.chk_collisiondetect.Checked;
        }
        if (this.activeProfile.SecondItem != null)
        {
          this.activeProfile.SecondItem.isSimulationDone = true;
          this.activeProfile.SecondItem.isCollisionControlDone = this.frmSim.chk_collisiondetect.Checked;
        }
        this.activeProfile.isSimulationDone = true;
      }
    }
    catch (Exception ex)
    {
      this.timSim.Enabled = false;
    }
  }

  public void DeleteSimulationTempEntities()
  {
    this.viewportSimilasyon.Entities.ClearSelection();
    for (int index = 0; index <= this.viewportSimilasyon.Entities.Count - 1; ++index)
    {
      CustomData entityData = this.viewportSimilasyon.Entities[index].EntityData as CustomData;
      if (entityData.typeDefination == entityTypeDefination.Temp | entityData.typeDefination == entityTypeDefination.TempDraw | entityData.typeDefination == entityTypeDefination.TempText)
        this.viewportSimilasyon.Entities[index].Selected = true;
    }
    this.viewportSimilasyon.Entities.DeleteSelected();
  }

  public void DrawSimulationEntities(
    buEyeBaseVer5.Apps.ProfileItem FirstProfile,
    buEyeBaseVer5.Apps.ProfileItem SecondProfile,
    int OperationIndex,
    List<buEyeBaseVer5.Apps.ProfileClamper> ClamperList,
