  }

  public void DrawSimulationEntities(
    buEyeBaseVer5.Apps.ProfileItem FirstProfile,
    buEyeBaseVer5.Apps.ProfileItem SecondProfile,
    bool profile,
    bool support,
    bool operation,
    bool clamper,
    bool cam,
    bool machine,
    bool machinebody,
    bool contour,
    int OperationIndex,
    List<buEyeBaseVer5.Apps.ProfileClamper> ClamperList,
    double ProfileXOffset = 0.0,
    double RotateFirstProfile = 0.0,
    double RotateSecondProfile = 0.0)
  {
    this.list_5.Clear();
    this.viewportSimilasyon.Entities.Clear();
    buProfileCalc.varProfileRunSettings.activeOPIndex = OperationIndex;
    buEyeBaseVer5.Apps.ProfileItem profileItem = clsInit.cProfile.SelectActiveProfile(this.activeProfile.FirstItem, this.activeProfile.SecondItem, ref buProfileCalc.varProfileRunSettings.activeProfileIndex);
    if (profileItem == null)
      return;
    for (int index1 = 0; index1 <= ccVars.SimMachine.MachineParts.Count - 1; ++index1)
    {
      bool flag = true;
      if (ccVars.SimMachine.MachineParts[index1].PartName.ToLower().IndexOf("cover") >= 0 & !buProfileCalc.varProfileSettings.ShowCabinet)
        flag = false;
      if (!machinebody && ccVars.SimMachine.MachineParts[index1].isBelongToBody)
        flag = false;
      if (flag)
      {
        for (int index2 = 0; index2 <= ccVars.SimMachine.MachineParts[index1].Entities.Count - 1; ++index2)
        {
          buMachinePart buMachinePart = new buMachinePart(ccVars.SimMachine.MachineParts[index1].PartName);
          buMachinePart.ARotation = ccVars.SimMachine.MachineParts[index1].MoveAxisPermision.A;
          buMachinePart.BRotation = ccVars.SimMachine.MachineParts[index1].MoveAxisPermision.B;
          buMachinePart.CRotation = ccVars.SimMachine.MachineParts[index1].MoveAxisPermision.C;
          buMachinePart.XMove = ccVars.SimMachine.MachineParts[index1].MoveAxisPermision.X;
          buMachinePart.YMove = ccVars.SimMachine.MachineParts[index1].MoveAxisPermision.Y;
          buMachinePart.ZMove = ccVars.SimMachine.MachineParts[index1].MoveAxisPermision.Z;
          buMachinePart.xRot = ccVars.SimMachine.MachineParts[index1].RotationCenter.X;
          buMachinePart.yRot = ccVars.SimMachine.MachineParts[index1].RotationCenter.Y;
          buMachinePart.zRot = ccVars.SimMachine.MachineParts[index1].RotationCenter.Z;
          buMachinePart.Color = ccVars.SimMachine.MachineParts[index1].Color;
          buMachinePart.ColorMethod = colorMethodType.byEntity;
          double dx = ccVars.SimMachine.MachineParts[index1].PositionBaseOffset.X + ccVars.SimMachine.MachineParts[index1].PositionAuxOffset.X;
          double dy = ccVars.SimMachine.MachineParts[index1].PositionBaseOffset.Y + ccVars.SimMachine.MachineParts[index1].PositionAuxOffset.Y;
          double dz = ccVars.SimMachine.MachineParts[index1].PositionBaseOffset.Z + ccVars.SimMachine.MachineParts[index1].PositionAuxOffset.Z;
          buMachinePart.Translate(dx, dy, dz);
          buMachinePart.Regen(new RegenParams(buSystem.RegenDeviation, (IWorkspace) this.viewportSimilasyon));
          buMachinePart.EntityData = (object) new CustomData()
          {
            typeDefination = entityTypeDefination.MachineBody,
            OriginalEntityIndex = this.viewportSimilasyon.Entities.Count,
            EntityName = ccVars.SimMachine.MachineParts[index1].PartName
          };
          buMachinePart.ColorMethod = colorMethodType.byEntity;
          buMachinePart.Color = ccVars.SimMachine.MachineParts[index1].Color;
          buMachinePart.Regen(new RegenParams(0.01, (IWorkspace) this.viewportSimilasyon));
          buMachinePart.LayerName = "Machine";
          this.viewportSimilasyon.Entities.Add((Entity) buMachinePart);
          this.list_5.Add(this.viewportSimilasyon.Entities.Count - 1);
        }
      }
    }
    if ((FirstProfile == null ? 0 : (FirstProfile.Enable ? 1 : 0)) != 0)
      this.DrawSimulationEntities(FirstProfile, 0, profile, support, operation, clamper, cam, machine, machinebody, contour, OperationIndex, ClamperList, ProfileXOffset, RotateFirstProfile);
    if ((SecondProfile == null ? 0 : (SecondProfile.Enable ? 1 : 0)) != 0)
      this.DrawSimulationEntities(SecondProfile, 1, profile, support, operation, clamper, cam, machine, machinebody, contour, OperationIndex, ClamperList, ProfileXOffset, RotateSecondProfile);
    List<buEyeBaseVer5.Apps.ProfileClamper> profileClamperList = new List<buEyeBaseVer5.Apps.ProfileClamper>();
    if (profileItem.CalculationData[buProfileCalc.varProfileRunSettings.activeCalcDataIndex].calcOperations.Count > 0)
    {
      GProfileOperation calcOperation = profileItem.CalculationData[buProfileCalc.varProfileRunSettings.activeCalcDataIndex].calcOperations[buProfileCalc.varProfileRunSettings.activeOPIndex];
      for (int index = 0; index <= calcOperation.Clampers.Count - 1; ++index)
      {
        buEyeBaseVer5.Apps.ProfileClamper profileClamper = new buEyeBaseVer5.Apps.ProfileClamper(calcOperation.Clampers[index]);
        if (index == calcOperation.CollisionClamperIndex)
          profileClamper.isCollision = calcOperation.isCollision;
        profileClamperList.Add(profileClamper);
      }
    }
    else if (ClamperList.Count > 0)
    {
      for (int index = 0; index <= ClamperList.Count - 1; ++index)
        profileClamperList.Add(new buEyeBaseVer5.Apps.ProfileClamper(ClamperList[index]));
    }
    if (clamper && profileClamperList.Count > 0)
    {
      for (int index3 = 0; index3 <= profileClamperList.Count - 1; ++index3)
      {
        bool flag1 = false;
        bool flag2 = false;
        for (int index4 = 0; index4 <= this.viewportSimilasyon.Blocks.Count - 1; ++index4)
        {
          if (this.viewportSimilasyon.Blocks[index4].Name == "Clamper")
            flag1 = true;
          if (this.viewportSimilasyon.Blocks[index4].Name == "ClamperMove")
            flag2 = true;
        }
        if (flag1)
        {
          string blockName = "Clamper";
          if (profileClamperList[index3].isCollision)
            blockName = "ClamperCollision";
          buMachinePart buMachinePart = new buMachinePart(blockName);
          buMachinePart.EntityData = (object) new CustomData()
          {
            typeDefination = entityTypeDefination.Clamper,
            EntityName = (blockName + index3.ToString()),
            RefIndex = index3,
            OriginalEntityIndex = this.viewportSimilasyon.Entities.Count
          };
          buMachinePart.XMove = true;
          buMachinePart.YMove = true;
          buMachinePart.xPos = profileClamperList[index3].XPosition;
          buMachinePart.ColorMethod = colorMethodType.byEntity;
          buMachinePart.LineTypeMethod = colorMethodType.byEntity;
          buMachinePart.Color = Color.DarkOrange;
          buMachinePart.LineWeight = 2f;
          buMachinePart.LayerName = "Clamper";
          buMachinePart.Regen(new RegenParams(0.01, (IWorkspace) this.viewportSimilasyon));
          this.viewportSimilasyon.Entities.Add((Entity) buMachinePart);
          this.list_5.Add(this.viewportSimilasyon.Entities.Count - 1);
        }
        if (flag2)
        {
          string blockName = "ClamperMove";
          if (profileClamperList[index3].isCollision)
            blockName = "ClamperMoveCollision";
          buMachinePart buMachinePart = new buMachinePart(blockName);
          buMachinePart.EntityData = (object) new CustomData()
          {
            typeDefination = entityTypeDefination.Clamper,
            EntityName = (blockName + index3.ToString()),
            RefIndex = index3,
            OriginalEntityIndex = this.viewportSimilasyon.Entities.Count
          };
          buMachinePart.xPos = profileClamperList[index3].XPosition;
          buMachinePart.yPos = -profileItem.Height - 40.0;
          buMachinePart.XMove = true;
          buMachinePart.YMove = true;
          buMachinePart.ColorMethod = colorMethodType.byEntity;
          buMachinePart.LineTypeMethod = colorMethodType.byEntity;
          buMachinePart.Color = Color.DarkRed;
          buMachinePart.LineWeight = 2f;
          buMachinePart.LayerName = "Clamper";
          buMachinePart.Regen(new RegenParams(0.01, (IWorkspace) this.viewportSimilasyon));
          this.viewportSimilasyon.Entities.Add((Entity) buMachinePart);
          this.list_5.Add(this.viewportSimilasyon.Entities.Count - 1);
        }
      }
    }
    this.MovePark();
    this.DrawGhostClamp(this.frmSim.selectedOP, this.frmSim.selectedCalcItem);
    this.viewportSimilasyon.Entities.Regen(new RegenOptions());
    this.viewportSimilasyon.Invalidate();
  }

  public void DrawSimulationEntities(
