          brep.ColorMethod = colorMethodType.byEntity;
          brep.Translate(0.0, -width);
          brep.EntityData = (object) new CustomData()
          {
            typeDefination = entityTypeDefination.SupportBlock,
            EntityName = ("SupportBlock1_" + ProfileIndex.ToString())
          };
          brep.LayerName = "SupportBlock";
          double num = 0.0;
          if (Item.MultiplyProfile.ProfileMultiplyEnable)
          {
            if (!Item.MultiplyProfile.ProfileMultiplyMirror)
              num = (Item.Width + Item.MultiplyProfile.ProfileMultiplySpace) * (double) index1;
            else if (index1 >= 1)
            {
              Mirror xform = new Mirror(new Plane(new Point3D(0.0, -Item.TotalWidth / 2.0, 0.0), Vector3D.AxisZ, Vector3D.AxisX));
              brep.TransformBy((Transformation) xform);
