          Brep brep = new devDept.Eyeshot.Entities.Region((ICurve) CompositeCurve.CreateRectangle(Plane.YZ, Item.SupportBlock.SupportBlockY1FrontWidth, Item.SupportBlock.SupportBlockY1FrontHeight)).ExtrudeAsBrep(new Vector3D(x, 0.0, 0.0));
          brep.Color = Item.colorSupportBlock;
