                    ((CustomData) copiedEnt.EntityData).typeDefination = entityTypeDefination.Operation;
                    copiedEnt.ColorMethod = colorMethodType.byEntity;
                    copiedEnt.LineTypeMethod = colorMethodType.byEntity;
                    copiedEnt.Color = !profileOperation.Enable ? Color.FromArgb(150, Color.Orange) : Color.FromArgb(150, Color.Cyan);
                    if (calcOperation.Error | calcOperation.isCollision)
                      copiedEnt.Color = Color.FromArgb(180, Color.Red);
                    copiedEnt.LineWeight = 1f;
                    double num = 0.0;
                    if (Item.MultiplyProfile.ProfileMultiplyEnable)
                    {
                      if (!Item.MultiplyProfile.ProfileMultiplyMirror)
                        num = (Item.Width + Item.MultiplyProfile.ProfileMultiplySpace) * (double) index1;
                      else if (index1 >= 1)
