                        copiedEnt.TransformBy((Transformation) xform1);
                        Mirror xform2 = new Mirror(new Plane(new Point3D(Item.Length / 2.0, 0.0, 0.0), Vector3D.AxisZ, Vector3D.AxisY));
                        copiedEnt.TransformBy((Transformation) xform2);
                      }
                    }
                    if (RotateProfile != 0.0)
                      copiedEnt.Rotate(buConversion5.DegreeToRadian(RotateProfile), Vector3D.AxisX, new Point3D(0.0, -Item.Width / 2.0, Item.Height / 2.0));
                    copiedEnt.Translate(Item.TotalOffset.X + dx + ProfileXOffset, Item.TotalOffset.Y - num, Item.TotalOffset.Z);
                    copiedEnt.Regen(0.01);
                    copiedEnt.LayerName = "Operation";
                    this.viewportSimilasyon.Entities.Add(copiedEnt);
                  }
                }
                if (cam)
                {
                  for (int index7 = 0; index7 <= profileOperation.EntityMultiCam.Count - 1; ++index7)
                  {
                    Entity copiedEntity = (Entity) null;
                    buEntity.Copy(profileOperation.EntityMultiCam[index7], ref copiedEntity);
                    ((CustomData) copiedEntity.EntityData).OriginalEntityIndex = this.viewportSimilasyon.Entities.Count;
                    copiedEntity.ColorMethod = colorMethodType.byEntity;
                    copiedEntity.LineTypeMethod = colorMethodType.byEntity;
                    copiedEntity.Color = Color.Red;
                    copiedEntity.LineWeight = 2f;
                    double num = 0.0;
                    if (Item.MultiplyProfile.ProfileMultiplyEnable)
                    {
                      if (!Item.MultiplyProfile.ProfileMultiplyMirror)
                        num = (Item.Width + Item.MultiplyProfile.ProfileMultiplySpace) * (double) index1;
                      else if (index1 >= 1)
                      {
                        Mirror xform3 = new Mirror(new Plane(new Point3D(0.0, -Item.TotalWidth / 2.0, 0.0), Vector3D.AxisZ, Vector3D.AxisX));
                        copiedEntity.TransformBy((Transformation) xform3);
                        Mirror xform4 = new Mirror(new Plane(new Point3D(Item.Length / 2.0, 0.0, 0.0), Vector3D.AxisZ, Vector3D.AxisY));
                        copiedEntity.TransformBy((Transformation) xform4);
                      }
