                    if (RotateProfile != 0.0)
                      copiedEntity.Rotate(buConversion5.DegreeToRadian(RotateProfile), Vector3D.AxisX, new Point3D(0.0, -Item.Width / 2.0, Item.Height / 2.0));
                    copiedEntity.Translate(Item.TotalOffset.X + dx + ProfileXOffset, Item.TotalOffset.Y - num, Item.TotalOffset.Z);
                    copiedEntity.Regen(0.01);
                    copiedEntity.LayerName = "Cam";
                    if (profileOperation.Action == actionTypeBU.profileNotch && profileOperation.EntityMultiCam[index7].Info.Offset != (Point3D) null)
                      copiedEntity.Translate(profileOperation.EntityMultiCam[index7].Info.Offset.X, profileOperation.EntityMultiCam[index7].Info.Offset.Y, profileOperation.EntityMultiCam[index7].Info.Offset.Z);
                    this.viewportSimilasyon.Entities.Add(copiedEntity);
