  public void DrawGhostClamp(GProfileOperation OP, ProfileItemCalc ItemCalc)
  {
    buEyeBaseVer5.Apps.ProfileItem profileItem = clsInit.cProfile.SelectActiveProfile(this.activeProfile.FirstItem, this.activeProfile.SecondItem, ref buProfileCalc.varProfileRunSettings.activeProfileIndex);
    if (profileItem == null)
      return;
    for (int index = 0; index <= clsInit.appProfile.viewportSimilasyon.Entities.Count - 1; ++index)
    {
      clsInit.appProfile.viewportSimilasyon.Entities[index].Selected = false;
      if (clsInit.appProfile.viewportSimilasyon.Entities[index].EntityData != null && clsInit.appProfile.viewportSimilasyon.Entities[index].EntityData is CustomData)
      {
        CustomData entityData = clsInit.appProfile.viewportSimilasyon.Entities[index].EntityData as CustomData;
        if (entityData.typeDefination == entityTypeDefination.Temp | entityData.typeDefination == entityTypeDefination.TempDraw | entityData.typeDefination == entityTypeDefination.TempText)
          clsInit.appProfile.viewportSimilasyon.Entities[index].Selected = true;
      }
    }
    clsInit.appProfile.viewportSimilasyon.Entities.DeleteSelected();
    if (!(OP != null & this.frmSim.chk_ghostright.Checked))
      return;
    double x1 = 0.0;
    double x2 = 0.0;
    if (OP.OperationData.selectedPlaneName == planeNames.Top | OP.OperationData.selectedPlaneName == planeNames.Bottom)
    {
      x1 = OP.SizePoint.MinPoint.X - buProfileCalc.varProfileClamperSettings.OperationTopLeftMinDistance - buProfileCalc.varProfileClamperSettings.ClamperWidth / 2.0;
      x2 = OP.SizePoint.MaxPoint.X + buProfileCalc.varProfileClamperSettings.OperationTopRightMinDistance + buProfileCalc.varProfileClamperSettings.ClamperWidth / 2.0;
    }
    if (OP.OperationData.selectedPlaneName == planeNames.Front)
    {
      x1 = OP.SizePoint.MinPoint.X - buProfileCalc.varProfileClamperSettings.OperationFrontLeftMinDistance - buProfileCalc.varProfileClamperSettings.ClamperWidth / 2.0;
      x2 = OP.SizePoint.MaxPoint.X + buProfileCalc.varProfileClamperSettings.OperationFrontRightMinDistance + buProfileCalc.varProfileClamperSettings.ClamperWidth / 2.0;
    }
    if (OP.OperationData.selectedPlaneName == planeNames.Back)
    {
      x1 = OP.SizePoint.MinPoint.X - buProfileCalc.varProfileClamperSettings.OperationBackLeftMinDistance - buProfileCalc.varProfileClamperSettings.ClamperWidth / 2.0;
      x2 = OP.SizePoint.MaxPoint.X + buProfileCalc.varProfileClamperSettings.OperationBackRightMinDistance + buProfileCalc.varProfileClamperSettings.ClamperWidth / 2.0;
    }
    if (OP.OperationData.selectedPlaneName == planeNames.Free)
    {
      x1 = OP.SizePoint.MinPoint.X - buProfileCalc.varProfileClamperSettings.OperationFrontLeftMinDistance - buProfileCalc.varProfileClamperSettings.ClamperWidth / 2.0;
      x2 = OP.SizePoint.MaxPoint.X + buProfileCalc.varProfileClamperSettings.OperationFrontRightMinDistance + buProfileCalc.varProfileClamperSettings.ClamperWidth / 2.0;
    }
    if (OP.XReferanceLocation == LeftRightType.Right)
    {
      if (buProfileCalc.varProfileSettings.RightProfileMakeAsMirror)
      {
        double machineLength = buProfileCalc.varProfileSettings.MachineLength;
        if (OP.OperationData.selectedPlaneName == planeNames.Top | OP.OperationData.selectedPlaneName == planeNames.Bottom)
        {
          x1 = machineLength - OP.SizePoint.MinPoint.X - buProfileCalc.varProfileClamperSettings.OperationTopLeftMinDistance - buProfileCalc.varProfileClamperSettings.ClamperWidth / 2.0;
          x2 = machineLength - OP.SizePoint.MaxPoint.X + buProfileCalc.varProfileClamperSettings.OperationTopRightMinDistance + buProfileCalc.varProfileClamperSettings.ClamperWidth / 2.0;
        }
        if (OP.OperationData.selectedPlaneName == planeNames.Front)
        {
          x1 = machineLength - OP.SizePoint.MaxPoint.X - buProfileCalc.varProfileClamperSettings.OperationFrontLeftMinDistance - buProfileCalc.varProfileClamperSettings.ClamperWidth / 2.0;
          x2 = machineLength - OP.SizePoint.MinPoint.X + buProfileCalc.varProfileClamperSettings.OperationFrontRightMinDistance + buProfileCalc.varProfileClamperSettings.ClamperWidth / 2.0;
        }
        if (OP.OperationData.selectedPlaneName == planeNames.Back)
        {
          x1 = machineLength - OP.SizePoint.MinPoint.X - buProfileCalc.varProfileClamperSettings.OperationBackLeftMinDistance - buProfileCalc.varProfileClamperSettings.ClamperWidth / 2.0;
          x2 = machineLength - OP.SizePoint.MaxPoint.X + buProfileCalc.varProfileClamperSettings.OperationBackRightMinDistance + buProfileCalc.varProfileClamperSettings.ClamperWidth / 2.0;
        }
        if (OP.OperationData.selectedPlaneName == planeNames.Free)
        {
          x1 = machineLength - OP.SizePoint.MinPoint.X - buProfileCalc.varProfileClamperSettings.OperationFrontLeftMinDistance - buProfileCalc.varProfileClamperSettings.ClamperWidth / 2.0;
          x2 = machineLength - OP.SizePoint.MaxPoint.X + buProfileCalc.varProfileClamperSettings.OperationFrontRightMinDistance + buProfileCalc.varProfileClamperSettings.ClamperWidth / 2.0;
        }
      }
      else
      {
        double num = ItemCalc == null ? buProfileCalc.varProfileSettings.MachineLength - profileItem.Length : buProfileCalc.varProfileSettings.MachineLength - ItemCalc.Length;
        if (OP.OperationData.selectedPlaneName == planeNames.Top | OP.OperationData.selectedPlaneName == planeNames.Bottom)
        {
          x1 = num + OP.SizePoint.MinPoint.X - buProfileCalc.varProfileClamperSettings.OperationTopLeftMinDistance - buProfileCalc.varProfileClamperSettings.ClamperWidth / 2.0;
          x2 = num + OP.SizePoint.MaxPoint.X + buProfileCalc.varProfileClamperSettings.OperationTopRightMinDistance + buProfileCalc.varProfileClamperSettings.ClamperWidth / 2.0;
        }
        if (OP.OperationData.selectedPlaneName == planeNames.Front)
        {
          x1 = num + OP.SizePoint.MinPoint.X - buProfileCalc.varProfileClamperSettings.OperationFrontLeftMinDistance - buProfileCalc.varProfileClamperSettings.ClamperWidth / 2.0;
          x2 = num + OP.SizePoint.MaxPoint.X + buProfileCalc.varProfileClamperSettings.OperationFrontRightMinDistance + buProfileCalc.varProfileClamperSettings.ClamperWidth / 2.0;
        }
        if (OP.OperationData.selectedPlaneName == planeNames.Back)
        {
          x1 = num + OP.SizePoint.MinPoint.X - buProfileCalc.varProfileClamperSettings.OperationBackLeftMinDistance - buProfileCalc.varProfileClamperSettings.ClamperWidth / 2.0;
          x2 = num + OP.SizePoint.MaxPoint.X + buProfileCalc.varProfileClamperSettings.OperationBackRightMinDistance + buProfileCalc.varProfileClamperSettings.ClamperWidth / 2.0;
        }
        if (OP.OperationData.selectedPlaneName == planeNames.Free)
        {
          x1 = num + OP.SizePoint.MinPoint.X - buProfileCalc.varProfileClamperSettings.OperationFrontLeftMinDistance - buProfileCalc.varProfileClamperSettings.ClamperWidth / 2.0;
          x2 = num + OP.SizePoint.MaxPoint.X + buProfileCalc.varProfileClamperSettings.OperationFrontRightMinDistance + buProfileCalc.varProfileClamperSettings.ClamperWidth / 2.0;
        }
      }
    }
    bool flag1 = false;
    bool flag2 = false;
    for (int index = 0; index <= this.viewportSimilasyon.Blocks.Count - 1; ++index)
    {
      if (this.viewportSimilasyon.Blocks[index].Name == "ClamperGhost")
        flag1 = true;
      if (this.viewportSimilasyon.Blocks[index].Name == "ClamperMoveGhost")
        flag2 = true;
    }
    if (flag1)
    {
      buMachinePart buMachinePart1 = new buMachinePart("ClamperGhost");
      buMachinePart1.EntityData = (object) new CustomData()
      {
        typeDefination = entityTypeDefination.Temp,
        EntityName = "Clamper",
        RefIndex = -1,
        OriginalEntityIndex = this.viewportSimilasyon.Entities.Count
      };
      buMachinePart1.XMove = true;
      buMachinePart1.xPos = x1;
      buMachinePart1.ColorMethod = colorMethodType.byEntity;
      buMachinePart1.LineTypeMethod = colorMethodType.byEntity;
      buMachinePart1.Color = Color.FromArgb(5, Color.LightPink);
      buMachinePart1.LineWeight = 2f;
      buMachinePart1.LayerName = "Clamper";
      buMachinePart1.Regen(new RegenParams(0.01, (IWorkspace) this.viewportSimilasyon));
      this.viewportSimilasyon.Entities.Add((Entity) buMachinePart1);
      buMachinePart buMachinePart2 = new buMachinePart("ClamperGhost");
      buMachinePart2.EntityData = (object) new CustomData()
      {
        typeDefination = entityTypeDefination.Temp,
        EntityName = "Clamper",
