  public void DeleteAllSimPartsFromViewport()
  {
    for (int index = 0; index <= this.viewportSimilasyon.Entities.Count - 1; ++index)
    {
      if (this.viewportSimilasyon.Entities[index].EntityData != null)
      {
        CustomData entityData = this.viewportSimilasyon.Entities[index].EntityData as CustomData;
        if (entityData.typeDefination == entityTypeDefination.Tool | entityData.typeDefination == entityTypeDefination.ToolParts)
          this.viewportSimilasyon.Entities[index].Selected = true;
      }
    }
    bool flag = false;
    for (int index = 0; index <= this.viewportSimilasyon.Blocks.Count - 1; ++index)
    {
      if (this.viewportSimilasyon.Blocks[index].Name == "Tool")
        flag = true;
    }
    if (flag)
      this.viewportSimilasyon.Blocks.Remove("Tool");
    this.viewportSimilasyon.Entities.DeleteSelected();
    this.viewportSimilasyon.Invalidate();
  }

  public void SimMachinePartAdd(ToolBase5 Tool, KinematicBase5 Kinematic)
  {
    try
    {
      List<Mesh> refMeshes = new List<Mesh>();
      clsInit.appMW.CreateTool(Tool, true, Tool.Geometry.DrawLength, Tool.Geometry.DrawArbor, Tool.Geometry.DrawHolder, ref refMeshes);
      Block block = new Block(nameof (Tool));
      this.string_0 = Tool.Data.Name;
      Mesh mesh = new Mesh();
      if (refMeshes.Count == 1)
      {
        for (int index = 0; index <= refMeshes.Count - 1; ++index)
        {
          refMeshes[index].ColorMethod = colorMethodType.byEntity;
          if (Tool.Geometry.GeometryType == ToolType.Saw)
            refMeshes[index].Translate(0.0 + Kinematic.MovePartRuntimeOffset.X, 0.0 + Kinematic.MovePartRuntimeOffset.Y, Kinematic.MovePartRuntimeOffset.Z);
          refMeshes[index].Regen(0.1);
          block.Entities.Add((Entity) refMeshes[index]);
        }
      }
      else
      {
        for (int index = 0; index <= refMeshes.Count - 1; ++index)
        {
          refMeshes[index].ColorMethod = colorMethodType.byEntity;
          if (Tool.Geometry.GeometryType == ToolType.Saw)
            refMeshes[index].Translate(0.0 + Kinematic.MovePartRuntimeOffset.X, 0.0 + Kinematic.MovePartRuntimeOffset.Y, Kinematic.MovePartRuntimeOffset.Z);
          refMeshes[index].Regen(0.1);
          block.Entities.Add((Entity) refMeshes[index]);
        }
      }
      for (int index = this.viewportSimilasyon.Blocks.Count - 1; index >= 0; --index)
      {
        if (this.viewportSimilasyon.Blocks[index].Name == nameof (Tool))
          this.viewportSimilasyon.Blocks.RemoveAt(index);
      }
      this.viewportSimilasyon.Blocks.Add(block);
      buTool buTool = new buTool(nameof (Tool));
      buTool.EntityData = (object) new CustomData()
      {
        typeDefination = entityTypeDefination.Tool
      };
      buTool.CRotation = Tool.Limits.RotationC;
      buTool.BRotation = Tool.Limits.RotationB;
      buTool.ARotation = true;
      buTool.Regen(new RegenParams(buSystem.RegenDeviation, (IWorkspace) this.viewportSimilasyon));
      this.viewportSimilasyon.Entities.Add((Entity) buTool);
      this.list_5.Clear();
      for (int index = 0; index <= this.viewportSimilasyon.Entities.Count - 1; ++index)
      {
        CustomData entityData = this.viewportSimilasyon.Entities[index].EntityData as CustomData;
        if (entityData.typeDefination == entityTypeDefination.Tool | entityData.typeDefination == entityTypeDefination.MachineParts | entityData.typeDefination == entityTypeDefination.MachineBody | entityData.typeDefination == entityTypeDefination.Clamper)
          this.list_5.Add(index);
      }
      this.viewportSimilasyon.Invalidate();
    }
    catch (Exception ex)
    {
      string str = "Tool: " + Tool.ToString();
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
    }
  }

  public void CollisionCheck()
  {
    if (!(this.listToCheck1.Count > 0 & this.listToCheck2.Count > 0))
      return;
    clsProfile.colDetect = new CollisionDetection((IList<Entity>) this.listToCheck1, (IList<Entity>) this.listToCheck2, this.viewportSimilasyon.Blocks, false, collisionCheckType.OBWithSubdivisionTree);
    if (this.isCollisionRunning || !this.frmSim.chk_collisiondetect.Checked)
      return;
    this.isCollisionRunning = true;
    this.viewportSimilasyon.StartWork((WorkUnit) clsProfile.colDetect);
  }

  public void CollisionCheckWithProfileAndHead()
  {
    clsProfile.colDetect = new CollisionDetection((IList<Entity>) this.listToCheck3, (IList<Entity>) this.listToCheck4, this.viewportSimilasyon.Blocks, false, collisionCheckType.OBWithSubdivisionTree);
    if (this.isCollisionRunning || !this.frmSim.chk_collisiondetect.Checked)
      return;
    this.isCollisionRunning = true;
    this.viewportSimilasyon.StartWork((WorkUnit) clsProfile.colDetect);
  }

