      {
        this.DrawSimulationEntities(this.activeProfile.FirstItem, this.activeProfile.SecondItem, -1, this.activeProfile.FirstItem.CalculationData[buProfileCalc.varProfileRunSettings.activeCalcDataIndex].calcOperations[0].Clampers, -PntMove.Aux1);
        this.SimMachinePartAdd(Tool, ccVars.KinematicOrjinal);
      }
      if (PntMove.MCode.ToString() == buProfileCalc.varProfileSettings.BottomProfileMCode & PntMove.Aux2 != 0.0)
      {
        if (buProfileCalc.varProfileRunSettings.activeProfileIndex == 0)
