        if (buProfileCalc.varProfileRunSettings.activeProfileIndex == 1)
          this.DrawSimulationEntities(this.activeProfile.FirstItem, this.activeProfile.SecondItem, -1, this.activeProfile.SecondItem.CalculationData[buProfileCalc.varProfileRunSettings.activeCalcDataIndex].calcOperations[0].Clampers, -PntMove.Aux1, RotateSecondProfile: 180.0);
        this.SimMachinePartAdd(Tool, ccVars.KinematicOrjinal);
      }
      if (PntMove.MCode.ToString() == buProfileCalc.varProfileSettings.LongBottomProfileMCode)
      {
        this.DrawSimulationEntities(this.activeProfile.FirstItem, this.activeProfile.SecondItem, -1, this.activeProfile.SecondItem.CalculationData[buProfileCalc.varProfileRunSettings.activeCalcDataIndex].calcOperations[0].Clampers, -PntMove.Aux1, 180.0);
        this.SimMachinePartAdd(Tool, ccVars.KinematicOrjinal);
      }
    }
    if (Tool != null)
      this.pnt6D_0 = new Pnt6D(Tool.CamData.SimMoveOffset);
    double num1 = 0.0;
    if ((ItemCalc == null ? 0 : (ItemCalc.XReferanceLocation == LeftRightType.Right ? 1 : 0)) != 0)
      num1 = buProfileCalc.varProfileSettings.MachineLength - ItemCalc.Length;
    else if (PntMove.Aux1 != 0.0)
      num1 = buProfileCalc.varProfileSettings.MachineLength - PntMove.Aux1;
    for (int index1 = 0; index1 <= this.list_5.Count - 1; ++index1)
    {
      if (this.list_5[index1] <= this.viewportSimilasyon.Entities.Count - 1)
      {
        CustomData entityData = this.viewportSimilasyon.Entities[this.list_5[index1]].EntityData as CustomData;
        int index2 = this.list_5[index1];
        ProfileTempVars.P3SimTool.X = PntMove.X + num1;
        ProfileTempVars.P3SimTool.Y = PntMove.Y;
        ProfileTempVars.P3SimTool.Z = PntMove.Z;
        ProfileTempVars.PAngleSimTool.A = PntMove.A;
        ProfileTempVars.P6SimMachine.X = PntMove.X + num1;
        ProfileTempVars.P6SimMachine.Y = PntMove.Y;
        ProfileTempVars.P6SimMachine.Z = PntMove.Z;
        ProfileTempVars.P6SimMachine.A = PntMove.A;
        if (this.list_5[index1] >= 0 & this.list_5[index1] <= this.viewportSimilasyon.Entities.Count - 1)
        {
          if (this.viewportSimilasyon.Entities[this.list_5[index1]].GetType() == typeof (buTool))
          {
            clsInit.cKinematic5.ReverseKinematix4Ax(Tool.Geometry.TotalLength, ccVars.KinematicOrjinal, VectorType.XVector, ProfileTempVars.PAngleSimTool, ProfileTempVars.P3SimTool, ref ProfileTempVars.P6SimTool);
            ((buTool) this.viewportSimilasyon.Entities[this.list_5[index1]]).xPos = ProfileTempVars.P6SimTool.X + this.pnt6D_0.X;
            ((buTool) this.viewportSimilasyon.Entities[this.list_5[index1]]).yPos = ProfileTempVars.P6SimTool.Y + this.pnt6D_0.Y;
            ((buTool) this.viewportSimilasyon.Entities[this.list_5[index1]]).zPos = ProfileTempVars.P6SimTool.Z + this.pnt6D_0.Z;
            ((buTool) this.viewportSimilasyon.Entities[this.list_5[index1]]).aPos = ProfileTempVars.P6SimTool.A;
            ((buTool) this.viewportSimilasyon.Entities[this.list_5[index1]]).cPos = ProfileTempVars.P6SimTool.C;
            Entity entity = buVector5.CopyEntities(this.viewportSimilasyon.Entities[this.list_5[index1]]);
            entity.Regen(new RegenParams(0.1, (IWorkspace) this.viewportSimilasyon));
            entity.Rotate(buConversion5.DegreeToRadian(ProfileTempVars.P6SimTool.A), new Vector3D(1.0, 0.0, 0.0), new Point3D(0.0, 0.0, 0.0));
            entity.Regen(new RegenParams(0.1, (IWorkspace) this.viewportSimilasyon));
            double num2 = Math.Sin(buConversion5.DegreeToRadian(ProfileTempVars.P6SimTool.A)) * (Tool.Geometry.TotalLength + ccVars.KinematicOrjinal.RotateCenterOffsetOfA.Z);
            double num3 = Math.Cos(buConversion5.DegreeToRadian(ProfileTempVars.P6SimTool.A)) * (Tool.Geometry.TotalLength + ccVars.KinematicOrjinal.RotateCenterOffsetOfA.Z);
            entity.Translate(ProfileTempVars.P3SimTool.X, ProfileTempVars.P3SimTool.Y + num2, ProfileTempVars.P3SimTool.Z + num3);
            entity.Regen(new RegenParams(0.1, (IWorkspace) this.viewportSimilasyon));
            this.listToCheck2.Add(entity);
          }
          if (this.viewportSimilasyon.Entities[this.list_5[index1]].GetType() == typeof (buMachinePart))
          {
            if (entityData.typeDefination == entityTypeDefination.MachineBody | entityData.typeDefination == entityTypeDefination.MachineParts)
            {
              ((buMachinePart) this.viewportSimilasyon.Entities[this.list_5[index1]]).xPos = ProfileTempVars.P6SimMachine.X + this.pnt6D_0.X;
              ((buMachinePart) this.viewportSimilasyon.Entities[this.list_5[index1]]).yPos = ProfileTempVars.P6SimMachine.Y + this.pnt6D_0.Y;
              ((buMachinePart) this.viewportSimilasyon.Entities[this.list_5[index1]]).zPos = ProfileTempVars.P6SimMachine.Z + this.pnt6D_0.Z;
              ((buMachinePart) this.viewportSimilasyon.Entities[this.list_5[index1]]).aPos = ProfileTempVars.P6SimMachine.A;
              ((buMachinePart) this.viewportSimilasyon.Entities[this.list_5[index1]]).cPos = ProfileTempVars.P6SimMachine.C;
              if (((BlockReference) this.viewportSimilasyon.Entities[this.list_5[index1]]).BlockName == "HolderLeft")
                ((buMachinePart) this.viewportSimilasyon.Entities[this.list_5[index1]]).bPos = 0.0;
              if (((BlockReference) this.viewportSimilasyon.Entities[this.list_5[index1]]).BlockName == "HolderRight")
                ((buMachinePart) this.viewportSimilasyon.Entities[this.list_5[index1]]).bPos = 0.0;
              if (((BlockReference) this.viewportSimilasyon.Entities[this.list_5[index1]]).BlockName == "ZBlock")
              {
                Entity refEnt = buVector5.CopyEntities(this.viewportSimilasyon.Entities[this.list_5[index1]]);
                refEnt.Translate(ProfileTempVars.P6SimMachine.X, ProfileTempVars.P6SimMachine.Y, ProfileTempVars.P6SimMachine.Z);
                this.listToCheck2.Add(refEnt);
                Entity entity = buVector5.CopyEntities(refEnt);
                ((CustomData) entity.EntityData).typeDefination = entityTypeDefination.Temp;
                entity.Color = Color.Red;
                entity.ColorMethod = colorMethodType.byEntity;
                entity.Regen(new RegenParams(0.01, (IWorkspace) this.viewportSimilasyon));
                entity.Selected = true;
              }
              if (((BlockReference) this.viewportSimilasyon.Entities[this.list_5[index1]]).BlockName == "ABlock")
              {
                Entity refEnt = buVector5.CopyEntities(this.viewportSimilasyon.Entities[this.list_5[index1]]);
                refEnt.Rotate(buConversion5.DegreeToRadian(ProfileTempVars.P6SimMachine.A), new Vector3D(1.0, 0.0, 0.0), new Point3D(0.0, 0.0, 0.0));
                refEnt.Translate(ProfileTempVars.P6SimMachine.X, ProfileTempVars.P6SimMachine.Y, ProfileTempVars.P6SimMachine.Z);
                this.listToCheck2.Add(refEnt);
                Entity entity1 = buVector5.CopyEntities(this.viewportSimilasyon.Entities[this.list_5[index1]]);
                entity1.Rotate(buConversion5.DegreeToRadian(ProfileTempVars.P6SimMachine.A), new Vector3D(1.0, 0.0, 0.0), new Point3D(0.0, 0.0, 0.0));
                entity1.Translate(ProfileTempVars.P6SimMachine.X, ProfileTempVars.P6SimMachine.Y, ProfileTempVars.P6SimMachine.Z);
                this.listToCheck4.Add(entity1);
                Entity entity2 = buVector5.CopyEntities(refEnt);
                ((CustomData) entity2.EntityData).typeDefination = entityTypeDefination.Temp;
                entity2.Color = Color.Red;
                entity2.ColorMethod = colorMethodType.byEntity;
                entity2.Regen(new RegenParams(0.01, (IWorkspace) this.viewportSimilasyon));
                entity2.Selected = true;
              }
            }
            if (entityData.typeDefination == entityTypeDefination.Clamper)
            {
              if (((BlockReference) this.viewportSimilasyon.Entities[index2]).BlockName == "Clamper" | ((BlockReference) this.viewportSimilasyon.Entities[index2]).BlockName == "ClamperCollision" && entityData.RefIndex >= 0 & entityData.RefIndex <= ClampersPosition.Count - 1)
              {
                ((buMachinePart) this.viewportSimilasyon.Entities[this.list_5[index1]]).xPos = ClampersPosition[entityData.RefIndex].XPosition;
                Entity entity = buVector5.CopyEntities(this.viewportSimilasyon.Entities[this.list_5[index1]]);
                entity.Translate(ClampersPosition[entityData.RefIndex].XPosition, 0.0);
                this.listToCheck1.Add(entity);
              }
              if (((BlockReference) this.viewportSimilasyon.Entities[index2]).BlockName == "ClamperMove" | ((BlockReference) this.viewportSimilasyon.Entities[index2]).BlockName == "ClamperMoveCollision")
              {
                double num4 = profileItem.Width;
                if (profileItem.TotalWidth > 0.0)
                  num4 = profileItem.TotalWidth;
                if (entityData.RefIndex >= 0 & entityData.RefIndex <= ClampersPosition.Count - 1)
                {
                  ((buMachinePart) this.viewportSimilasyon.Entities[this.list_5[index1]]).xPos = ClampersPosition[entityData.RefIndex].XPosition;
                  Entity entity = buVector5.CopyEntities(this.viewportSimilasyon.Entities[this.list_5[index1]]);
                  if (buProfileCalc.varProfileSettings.YDirection == ProfileYAxisDirection.NegativeDirection)
                  {
                    ((buMachinePart) this.viewportSimilasyon.Entities[this.list_5[index1]]).yPos = -num4 - profileItem.SupportBlock.SupportBlockY2BackWidth - profileItem.SupportBlock.SupportBlockY1FrontWidth;
                    entity.Translate(ClampersPosition[entityData.RefIndex].XPosition, -num4 - profileItem.SupportBlock.SupportBlockY2BackWidth - profileItem.SupportBlock.SupportBlockY1FrontWidth);
                  }
                  else
                  {
                    ((buMachinePart) this.viewportSimilasyon.Entities[this.list_5[index1]]).yPos = num4 + profileItem.SupportBlock.SupportBlockY2BackWidth + profileItem.SupportBlock.SupportBlockY1FrontWidth;
                    entity.Translate(ClampersPosition[entityData.RefIndex].XPosition, num4 + profileItem.SupportBlock.SupportBlockY2BackWidth + profileItem.SupportBlock.SupportBlockY1FrontWidth);
                  }
                  entity.Regen(new RegenParams(0.01, (IWorkspace) clsInit.appProfile.viewportSimilasyon));
                  this.listToCheck1.Add(entity);
                }
                else if (buProfileCalc.varProfileSettings.YDirection == ProfileYAxisDirection.NegativeDirection)
                  ((buMachinePart) this.viewportSimilasyon.Entities[this.list_5[index1]]).yPos = -num4 - profileItem.SupportBlock.SupportBlockY2BackWidth - profileItem.SupportBlock.SupportBlockY1FrontWidth;
                else
                  ((buMachinePart) this.viewportSimilasyon.Entities[this.list_5[index1]]).yPos = num4 + profileItem.SupportBlock.SupportBlockY2BackWidth + profileItem.SupportBlock.SupportBlockY1FrontWidth;
              }
            }
          }
        }
      }
    }
    this.viewportSimilasyon.Entities.Regen();
    this.viewportSimilasyon.Invalidate();
    if (!(PntMove.Index >= 0 & this.FrmSimCodes.Visible) || PntMove.Index >= this.FrmSimCodes.buMultiTextBox1.Lines.Count - 1)
