    this.SimGCodeLastLine = place.iLine;
  }

  public void MovePark()
  {
    buEyeBaseVer5.Apps.ProfileItem profileItem = (buEyeBaseVer5.Apps.ProfileItem) null;
    if (buProfileCalc.varProfileRunSettings.activeProfileIndex == -1)
      return;
    if (buProfileCalc.varProfileRunSettings.activeProfileIndex == 0)
    {
      buEyeBaseVer5.Apps.ProfileItem firstItem = this.activeProfile.FirstItem;
      if (firstItem == null || !firstItem.Enable)
        return;
    }
    if (buProfileCalc.varProfileRunSettings.activeProfileIndex == 1)
    {
      if (this.activeProfile.SecondItem == null)
        return;
      profileItem = this.activeProfile.SecondItem;
    }
    this.MoveSimPart(new Pnt6DSimMove(buProfileCalc.varProfileSettings.ParkPositionX, buProfileCalc.varProfileSettings.ParkPositionY, buProfileCalc.varProfileSettings.ParkPositionZ + ccVars.KinematicOrjinal.RotateCenterOffsetOfA.Z + 100.0, 0.0, 0.0, 0.0), new List<buEyeBaseVer5.Apps.ProfileClamper>(), (ToolBase5) null, (ProfileItemCalc) null);
  }

  public void BasicCollsionControl(ref buEyeBaseVer5.Apps.ProfileItem Item)
  {
    if (Item != null)
    {
      for (int index1 = 0; index1 <= Item.CalculationData.Count - 1; ++index1)
      {
        for (int index2 = 0; index2 <= Item.CalculationData[index1].calcOperations.Count - 1; ++index2)
        {
          bool flag = false;
          GProfileOperation calcOperation = Item.CalculationData[index1].calcOperations[index2];
          ClamperLeftRightPars Calc = new ClamperLeftRightPars();
          this.doClamperOpLeftRightLimits(Item, Item.CalculationData[index1], calcOperation, ref Calc, buProfileCalc.varProfileClamperSettings.ClamperWidth);
          calcOperation.Error = false;
          calcOperation.isCollision = false;
          calcOperation.CollisionClamperIndex = -1;
          double num1 = 0.0;
          if (calcOperation.OperationData.OperationType == ProfileOperationTypes.Notch)
          {
            buEyeBaseVer5.Apps.ProfileOperation foundOP = (buEyeBaseVer5.Apps.ProfileOperation) null;
            clsInit.cProfile.FindOperationFromCalculatedOperationsByID(Item, calcOperation.ID, ref foundOP);
            if ((calcOperation.OperationData.NotchData.NotchOPType == ProfileNotchOperationType.Horizontal ? 1 : (calcOperation.OperationData.NotchData.NotchOPType == ProfileNotchOperationType.Side ? 1 : 0)) != 0 && foundOP != null)
              num1 = foundOP.ToolNotch.Geometry.Diameter / 2.0;
          }
          if (calcOperation.SizePoint.MinPoint.Z + Item.SupportBlock.SupportBlockZHeight + num1 > buProfileCalc.varProfileClamperSettings.ClamperMaxHeight)
            flag = true;
          if ((Calc.LeftMinDis > 0.0 | Calc.LeftMaxDis > 0.0 | Calc.RightMinDis > 0.0 | Calc.RightMaxDis > 0.0) & !flag)
          {
            double MinPointX = calcOperation.SizePoint.MinPoint.X;
            double MaxPointX = calcOperation.SizePoint.MaxPoint.X;
            double num2 = Calc.LeftMinDis;
            double num3 = Calc.RightMinDis;
            if (Item.CalculationData[index1].XReferanceLocation == LeftRightType.Right)
            {
              if (buProfileCalc.varProfileSettings.RightProfileMakeAsMirror)
              {
                MinPointX = buProfileCalc.varProfileSettings.MachineLength - calcOperation.SizePoint.MaxPoint.X;
                MaxPointX = buProfileCalc.varProfileSettings.MachineLength - calcOperation.SizePoint.MinPoint.X;
                num2 = Calc.RightMinDis;
                num3 = Calc.LeftMinDis;
              }
              else
              {
                MinPointX = buProfileCalc.varProfileSettings.MachineLength - Item.CalculationData[index1].Length + calcOperation.SizePoint.MinPoint.X;
                MaxPointX = buProfileCalc.varProfileSettings.MachineLength - Item.CalculationData[index1].Length + calcOperation.SizePoint.MaxPoint.X;
                num3 = Calc.RightMinDis;
                num2 = Calc.LeftMinDis;
              }
            }
            for (int index3 = 0; index3 <= calcOperation.Clampers.Count - 1; ++index3)
            {
              if (clsInit.cProfile.isClamperInsideOperationRange(MinPointX, MaxPointX, num2 - 1.0, num3 - 1.0, calcOperation.Clampers[index3].XPosition, buProfileCalc.varProfileClamperSettings.ClamperWidth))
              {
                calcOperation.Error = true;
                calcOperation.isCollision = true;
                calcOperation.CollisionClamperIndex = index3;
              }
            }
          }
        }
      }
    }
    this.frmSim.UpdateTreeOperation();
  }

  public void DrawPreview(List<Entity> TempEntities)
  {
    if (buProfileCalc.varProfileRunSettings.activeProfileIndex == 0)
      this.DrawPreview(this.activeProfile.FirstItem, TempEntities);
    if (buProfileCalc.varProfileRunSettings.activeProfileIndex != 1)
      return;
    this.DrawPreview(this.activeProfile.SecondItem, TempEntities);
  }

  public void DrawPreview(buEyeBaseVer5.Apps.ProfileItem Profile, List<Entity> TempEntities, bool isPreview = true)
  {
    if (this.CancelPreview)
      return;
    Design design = !isPreview ? this.frmERPList.viewportPort : clsItem.ModelMainPreview;
    if (design == null)
      return;
    design.Entities.Clear();
    design.Invalidate();
    if (Profile == null)
      return;
    for (int index = 0; index <= ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Layers.Count - 1; ++index)
    {
      if (!clsInit.cVector5.IsLayerNameAvailable(design.Layers, ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Layers[index].Name))
      {
        Layer layer = new Layer(ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Layers[index].Name, ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Layers[index].Color);
        design.Layers.Add(layer);
      }
    }
    for (int index = 0; index <= Profile.Drawings.Count - 1; ++index)
    {
      if (Profile.Drawings[index].SolidEntity != null)
      {
        Entity entity = buVector5.CopyEntities(Profile.Drawings[index].SolidEntity);
        entity.Regen(buSystem.RegenDeviation);
        if (!isPreview)
          entity.Color = Color.FromArgb(70, entity.Color);
        design.Entities.Add(entity);
      }
    }
    for (int index1 = 0; index1 <= Profile.Operations.Count - 1; ++index1)
    {
      if (Profile.Operations[index1].EntityMultiSolidDepth != null)
      {
        for (int index2 = 0; index2 <= Profile.Operations[index1].EntityMultiSolidDepth.Count - 1; ++index2)
        {
          Entity entity = buVector5.CopyEntities(Profile.Operations[index1].EntityMultiSolidDepth[index2]);
          entity.Color = buProfileCalc.varProfileSettings.PreviewDoneOperationColor;
          entity.ColorMethod = colorMethodType.byEntity;
          design.Entities.Add(entity);
        }
      }
    }
    if (buProfileCalc.varProfileSettings.ShowPreviewSides & isPreview && buNumeric5.IsNumeric(Profile.Height.ToString()) & buNumeric5.IsNumeric(Profile.Width.ToString()))
    {
      if (buProfileCalc.varProfileSettings.YDirection == ProfileYAxisDirection.NegativeDirection)
      {
        Mesh box1 = Mesh.CreateBox(buProfileCalc.varProfileSettings.ProfilePreviewRefDrawingThickness, buProfileCalc.varProfileSettings.ProfilePreviewRefDrawingThickness, Profile.Height + buProfileCalc.varProfileSettings.ProfilePreviewRefDrawingExtraHeight);
        box1.Color = buProfileCalc.varProfileSettings.PreviewSideColor;
        box1.ColorMethod = colorMethodType.byEntity;
        design.Entities.Add((Entity) box1);
        Mesh box2 = Mesh.CreateBox(2.0, Profile.Width + buProfileCalc.varProfileSettings.ProfilePreviewRefDrawingExtraHeight, buProfileCalc.varProfileSettings.ProfilePreviewRefDrawingThickness);
        box2.Color = buProfileCalc.varProfileSettings.PreviewSideColor;
        box2.ColorMethod = colorMethodType.byEntity;
        box2.Translate(0.0, -(Profile.Width + buProfileCalc.varProfileSettings.ProfilePreviewRefDrawingExtraHeight - buProfileCalc.varProfileSettings.ProfilePreviewRefDrawingThickness), -buProfileCalc.varProfileSettings.ProfilePreviewRefDrawingThickness);
        design.Entities.Add((Entity) box2);
      }
      else
      {
        Mesh box3 = Mesh.CreateBox(buProfileCalc.varProfileSettings.ProfilePreviewRefDrawingThickness, buProfileCalc.varProfileSettings.ProfilePreviewRefDrawingThickness, Profile.Height + buProfileCalc.varProfileSettings.ProfilePreviewRefDrawingExtraHeight);
        box3.Color = buProfileCalc.varProfileSettings.PreviewSideColor;
        box3.ColorMethod = colorMethodType.byEntity;
        box3.Translate(0.0, -buProfileCalc.varProfileSettings.ProfilePreviewRefDrawingThickness);
        design.Entities.Add((Entity) box3);
        Mesh box4 = Mesh.CreateBox(2.0, Profile.Width + buProfileCalc.varProfileSettings.ProfilePreviewRefDrawingExtraHeight, buProfileCalc.varProfileSettings.ProfilePreviewRefDrawingThickness);
        box4.Color = buProfileCalc.varProfileSettings.PreviewSideColor;
        box4.ColorMethod = colorMethodType.byEntity;
        box4.Translate(0.0, -buProfileCalc.varProfileSettings.ProfilePreviewRefDrawingThickness, -buProfileCalc.varProfileSettings.ProfilePreviewRefDrawingThickness);
        design.Entities.Add((Entity) box4);
      }
    }
    for (int index = 0; index <= Profile.Drawings.Count - 1; ++index)
      design.Entities.Add((Entity) new LinearPath((ICollection<Point3D>) Profile.Drawings[index].OutterPoints));
    for (int index3 = 0; index3 <= Profile.Drawings.Count - 1; ++index3)
    {
      for (int index4 = 0; index4 <= Profile.Drawings[index3].InnerPoints.Count - 1; ++index4)
        design.Entities.Add((Entity) new LinearPath((ICollection<Point3D>) Profile.Drawings[index3].InnerPoints[index4]));
    }
    for (int index = 0; index <= TempEntities.Count - 1; ++index)
    {
      Entity entity = buVector5.CopyEntities(TempEntities[index]);
      entity.Color = buProfileCalc.varProfileSettings.PreviewActiveOperationColor;
      design.Entities.Add(entity);
    }
    if (design.Viewports.Count <= 0)
      return;
    design.ActiveViewport.DisplayMode = displayType.Flat;
    design.ActiveViewport.Camera.ProjectionMode = projectionType.Orthographic;
    bool flag = false;
    if (buCompare5.EQ(design.ActiveViewport.Camera.Rotation.W, 1.0, 0.01) && buCompare5.EQ(design.ActiveViewport.Camera.Rotation.X, 0.0, 0.01) && buCompare5.EQ(design.ActiveViewport.Camera.Rotation.Y, 0.0, 0.01) && buCompare5.EQ(design.ActiveViewport.Camera.Rotation.Z, 0.0, 0.01))
      flag = true;
    if (isPreview)
    {
      if (!flag)
      {
        viewType int32 = (viewType) Convert.ToInt32((object) buProfileCalc.varProfileSettings.PreviewViewType);
        design.SetView(int32);
        design.RotateLeft(180.0);
        design.ZoomFit();
      }
    }
    else
      design.SetView(viewType.vcFrontFaceTopLeft);
    design.Invalidate();
  }

  public void DrawMultiPreview(buEyeBaseVer5.Apps.ProfileItem Profile, List<Entity> TempEntities)
  {
    if (this.CancelPreview || Profile == null)
      return;
    for (int index = 0; index <= ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Layers.Count - 1; ++index)
    {
      if (!clsInit.cVector5.IsLayerNameAvailable(clsItem.FrmPreviewMulti.viewport_preview.Layers, ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Layers[index].Name))
      {
        Layer layer = new Layer(ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Layers[index].Name, ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Layers[index].Color);
        clsItem.FrmPreviewMulti.viewport_preview.Layers.Add(layer);
      }
    }
    clsItem.FrmPreviewMulti.viewport_preview.Entities.Clear();
    for (int index = 0; index <= Profile.Drawings.Count - 1; ++index)
    {
      if (Profile.Drawings[index].SolidEntity != null)
      {
        Entity entity = buVector5.CopyEntities(Profile.Drawings[index].SolidEntity);
        entity.Regen(buSystem.RegenDeviation);
        clsItem.FrmPreviewMulti.viewport_preview.Entities.Add(entity);
      }
    }
    for (int index1 = 0; index1 <= Profile.Operations.Count - 1; ++index1)
    {
      for (int index2 = 0; index2 <= Profile.Operations[index1].EntityMultiSolidDepth.Count - 1; ++index2)
      {
        Entity entity = buVector5.CopyEntities(Profile.Operations[index1].EntityMultiSolidDepth[index2]);
        entity.Color = buProfileCalc.varProfileSettings.PreviewDoneOperationColor;
        entity.ColorMethod = colorMethodType.byEntity;
        clsItem.FrmPreviewMulti.viewport_preview.Entities.Add(entity);
      }
    }
    if (buProfileCalc.varProfileSettings.ShowPreviewSides && buNumeric5.IsNumeric(this.activeProfile.FirstItem.Height.ToString()) & buNumeric5.IsNumeric(this.activeProfile.FirstItem.Width.ToString()))
    {
      Mesh box1 = Mesh.CreateBox(2.0, 2.0, this.activeProfile.FirstItem.Height + 10.0);
      box1.Color = buProfileCalc.varProfileSettings.PreviewSideColor;
      box1.ColorMethod = colorMethodType.byEntity;
      clsItem.FrmPreviewMulti.viewport_preview.Entities.Add((Entity) box1);
      Mesh box2 = Mesh.CreateBox(2.0, this.activeProfile.FirstItem.Width + 10.0, 2.0);
      box2.Color = buProfileCalc.varProfileSettings.PreviewSideColor;
      box2.ColorMethod = colorMethodType.byEntity;
      box2.Translate(0.0, -(this.activeProfile.FirstItem.Width + 10.0 - 2.0), -2.0);
      clsItem.FrmPreviewMulti.viewport_preview.Entities.Add((Entity) box2);
    }
    for (int index = 0; index <= TempEntities.Count - 1; ++index)
    {
      Entity entity = buVector5.CopyEntities(TempEntities[index]);
      entity.Color = buProfileCalc.varProfileSettings.PreviewActiveOperationColor;
      clsItem.FrmPreviewMulti.viewport_preview.Entities.Add(entity);
    }
    for (int index = 0; index < 3; ++index)
    {
      clsItem.FrmPreviewMulti.viewport_preview.Viewports[index].DisplayMode = displayType.Flat;
      clsItem.FrmPreviewMulti.viewport_preview.Viewports[index].Camera.ProjectionMode = projectionType.Orthographic;
      clsItem.FrmPreviewMulti.viewport_preview.Viewports[index].ZoomFit();
      clsItem.FrmPreviewMulti.viewport_preview.Viewports[3].ZoomFit();
    }
    clsItem.FrmPreviewMulti.viewport_preview.Invalidate();
  }

  public void DrawActiveProfile()
  {
    if (clsInit.cProfile.SelectActiveProfile(this.activeProfile.FirstItem, this.activeProfile.SecondItem, ref buProfileCalc.varProfileRunSettings.activeProfileIndex) == null)
      return;
    ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Clear();
    ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Invalidate();
    Transformation transformation = (Transformation) null;
    OriginSymbol originSymbol = (OriginSymbol) null;
    if (buProfileCalc.varProfileRunSettings.activeProfileIndex == 0)
    {
      transformation = (Transformation) new Translation(0.0, 0.0) * (Transformation) new Rotation(-1.0 * Math.PI / 2.0, Vector3D.AxisZ);
      originSymbol = new OriginSymbol(6, originSymbolStyleType.Ball, Color.Black, Color.Black, Color.Black, Color.Black, Color.Red, Color.Green, Color.Blue, "", "", "", "", true, transformation, false);
      this.DrawActiveProfile(this.activeProfile.FirstItem, buProfileCalc.varProfileRunSettings.activeProfileIndex);
    }
    if (buProfileCalc.varProfileRunSettings.activeProfileIndex == 1 & this.activeProfile.SecondItem != null)
    {
      transformation = (Transformation) new Translation(this.activeProfile.SecondItem.Length, 0.0) * (Transformation) new Rotation(-1.0 * Math.PI, Vector3D.AxisZ);
      originSymbol = new OriginSymbol(6, originSymbolStyleType.Ball, Color.Black, Color.Black, Color.Black, Color.Black, Color.Red, Color.Green, Color.Blue, "", "X", "Y", "Z", true, transformation, false);
      this.DrawActiveProfile(this.activeProfile.SecondItem, buProfileCalc.varProfileRunSettings.activeProfileIndex);
    }
    this.UndoDontProfile = false;
    if (ProfileTempVars.MainBottomTabIndex == 0)
      this.DrawPlaneDepth(true, true, false);
    else
      this.DrawPlaneDepth(true, false, true);
    if ((!(transformation != (Transformation) null) ? 0 : (originSymbol != null ? 1 : 0)) != 0)
    {
      ccVars.Pages[ccVars.PageIndex].Form.viewportcad.ActiveViewport.OriginSymbols[0] = originSymbol;
      ccVars.Pages[ccVars.PageIndex].Form.viewportcad.CompileUserInterfaceElements();
    }
    ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Invalidate();
  }

  public void DrawActiveProfile(buEyeBaseVer5.Apps.ProfileItem Item, int activeProfileIndex)
  {
    if (Item == null)
      return;
    this.UndoDontProfile = true;
    for (int index = 0; index <= Item.Drawings.Count - 1; ++index)
      this.CreateProfileEntity(ref Item.Drawings[index].SolidEntity, Item.TextureName, Item.ItemName, Item.Enable, Item.colorProfile);
    if (Item.LeftAngleEntity != null & buProfileCalc.varProfileSettings.RemoveProfileAngle & buProfileCalc.varProfileSettings.ShowProfileAngleDrawing & activeProfileIndex == 0)
      ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Add(Item.LeftAngleEntity);
    if (Item.RightAngleEntity != null & buProfileCalc.varProfileSettings.RemoveProfileAngle & buProfileCalc.varProfileSettings.ShowProfileAngleDrawing & activeProfileIndex == 1)
      ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Add(Item.RightAngleEntity);
    if (Item.ProfileReferanceEntity != null)
      ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Add(Item.ProfileReferanceEntity);
    if (Item.ProfileReferanceBottomEntity != null)
      ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Add(Item.ProfileReferanceBottomEntity);
    if (Item.ProfileReferanceBackEntity != null)
      ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Add(Item.ProfileReferanceBackEntity);
    for (int index = 0; index <= Item.Operations.Count - 1; ++index)
      this.CreateOperationEntity(Item.Operations[index], index);
    if (Item.auxEntities == null)
      return;
    for (int index = 0; index <= Item.auxEntities.Count - 1; ++index)
    {
      Entity Ent = buVector5.CopyEntities(Item.auxEntities[index]);
      Ent.LayerName = ProfileTempVars.LayerNameOperation;
      Ent.Color = Color.Gold;
      Ent.ColorMethod = colorMethodType.byEntity;
      Ent.Regen(buSystem.RegenDeviation);
      ccVars.UndoDont = true;
      clsInit.appCommand.AddEntity(Ent);
      ccVars.UndoDont = false;
    }
  }

  public void CreateProfileEntity(
    ref Entity entProfile,
    string TextureName,
    string ProfileName,
    bool Enable,
    Color colorProfile)
  {
    entProfile.ColorMethod = colorMethodType.byEntity;
    if (clsInit.cVector5.IsLayerNameAvailable(ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Layers, ProfileTempVars.LayerNameProfile))
      entProfile.LayerName = ProfileTempVars.LayerNameProfile;
    if (TextureName.Length > 0 && clsInit.cVector5.IsLayerNameAvailable(ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Layers, TextureName))
      entProfile.LayerName = TextureName;
    CustomData customData;
    if (entProfile.EntityData != null)
    {
      if (entProfile.EntityData is CustomData)
      {
        customData = (CustomData) entProfile.EntityData;
      }
      else
      {
        customData = new CustomData();
        customData.typeDefination = entityTypeDefination.Profile;
        customData.EntityName = ProfileName;
      }
    }
    else
    {
      customData = new CustomData();
      customData.typeDefination = entityTypeDefination.Profile;
      customData.EntityName = ProfileName;
    }
    if (customData.typeDefination == entityTypeDefination.Profile)
      entProfile.Color = Enable ? Color.FromArgb(buProfileCalc.varProfileSettings.MaterialTranspancy, colorProfile) : Color.FromArgb(buProfileCalc.varProfileSettings.MaterialTranspancy, Color.PaleVioletRed);
    entProfile.Selectable = false;
    ProfileTempVars.LastCreatedProfileEntityName = customData.EntityName;
    ProfileTempVars.LastCreatedProfileEntityIndex = ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Count;
    entProfile.EntityData = (object) customData;
    ccVars.UndoDont = true;
    clsInit.appCommand.AddEntity(entProfile);
    ccVars.UndoDont = false;
  }

  public void CreateOperationEntity(buEyeBaseVer5.Apps.ProfileOperation OP, int OPIndex)
  {
    if (OP.EntityMultiSolidDepth != null)
    {
      for (int index = 0; index <= OP.EntityMultiSolidDepth.Count - 1; ++index)
      {
        Entity Ent = buVector5.CopyEntities(OP.EntityMultiSolidDepth[index]);
        Ent.EntityData = (object) new CustomData()
        {
          typeDefination = entityTypeDefination.ProfileOperation,
          ID = OP.ID,
          EntityName = OP.ProfileName,
          ActionName = OP.Name
        };
        if (clsInit.cVector5.IsLayerNameAvailable(ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Layers, ProfileTempVars.LayerNameOperation))
        {
          Ent.LayerName = ProfileTempVars.LayerNameOperation;
          Ent.ColorMethod = colorMethodType.byLayer;
        }
        if (!OP.Enable)
        {
          Ent.Color = Color.Red;
          Ent.ColorMethod = colorMethodType.byEntity;
        }
        Ent.Regen(buSystem.RegenDeviation);
        ccVars.UndoDont = true;
        clsInit.appCommand.AddEntity(Ent);
        ccVars.UndoDont = false;
      }
    }
    if (OP.EntityMultiContour != null)
    {
      for (int index = 0; index <= OP.EntityMultiContour.Count - 1; ++index)
      {
        OP.EntityMultiContour[index].typeDefination = entityTypeDefination.ProfileOperation;
        OP.EntityMultiContour[index].Info.Data = OP.ProfileName;
        OP.EntityMultiContour[index].Info.RefIndex = OPIndex;
        OP.EntityMultiContour[index].Info.ID = OP.ID;
        Entity copiedEntity = (Entity) null;
        buEntity.Copy(OP.EntityMultiContour[index], ref copiedEntity);
        if (copiedEntity != null)
        {
          copiedEntity.EntityData = (object) new CustomData()
          {
            typeDefination = OP.EntityMultiContour[index].typeDefination,
            ID = OP.EntityMultiContour[index].Info.ID,
            EntityName = OP.ProfileName,
            ActionName = OP.Name
          };
          if (clsInit.cVector5.IsLayerNameAvailable(ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Layers, ProfileTempVars.LayerNameOperation))
          {
            copiedEntity.LayerName = ProfileTempVars.LayerNameContour;
            copiedEntity.ColorMethod = colorMethodType.byLayer;
          }
          copiedEntity.Regen(buSystem.RegenDeviation);
          ccVars.UndoDont = true;
          clsInit.appCommand.AddEntity(copiedEntity);
          ccVars.UndoDont = false;
        }
      }
    }
    if (OP.EntityMultiCam == null)
      return;
    for (int index = 0; index <= OP.EntityMultiCam.Count - 1; ++index)
    {
      OP.EntityMultiCam[index].Info.Data = OP.ProfileName;
      OP.EntityMultiCam[index].Info.RefIndex = OPIndex;
      OP.EntityMultiCam[index].Info.ID = OP.ID;
      Entity copiedEntity = (Entity) null;
      buEntity.Copy(OP.EntityMultiCam[index], ref copiedEntity);
      if (OP.Action == actionTypeBU.profileNotch && OP.EntityMultiCam[index].Info.Offset != (Point3D) null)
        copiedEntity.Translate(OP.EntityMultiCam[index].Info.Offset.X, OP.EntityMultiCam[index].Info.Offset.Y, OP.EntityMultiCam[index].Info.Offset.Z);
      copiedEntity.EntityData = (object) new CustomData()
      {
        typeDefination = OP.EntityMultiCam[index].typeDefination,
        ID = OP.EntityMultiCam[index].Info.ID,
        EntityName = OP.ProfileName,
        ActionName = OP.Name
      };
      if (clsInit.cVector5.IsLayerNameAvailable(ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Layers, ProfileTempVars.LayerNameOperation))
      {
        copiedEntity.LayerName = ProfileTempVars.LayerNameCam;
        copiedEntity.ColorMethod = colorMethodType.byLayer;
      }
      copiedEntity.Regen(buSystem.RegenDeviation);
      ccVars.UndoDont = true;
      clsInit.appCommand.AddEntity(copiedEntity);
      ccVars.UndoDont = false;
    }
  }

  public void LoadLanguage()
  {
    try
    {
      List<string> stringList = new List<string>();
      FileInfo fileInfo = clsVar.appModes_0.DeveloperPCMode ? new FileInfo("D:\\PCProjects\\Generation5\\CommonFolder\\Language\\buProfile.lng") : new FileInfo(AppPath.Language + "\\buProfile.lng");
      if (fileInfo.Exists)
      {
        List<string> StringList = new List<string>();
        buFile.OpenFromFile(fileInfo.FullName, ref StringList);
        buString.GetItemsAccordingToTheLang(buString.ReadXmlItem("<Status>", "</Status>", StringList), clsVar.varRuntime.Language, ref buProfile.LangProfileStatus);
        buString.GetItemsAccordingToTheLang(buString.ReadXmlItem("<Message>", "</Message>", StringList), clsVar.varRuntime.Language, ref buProfile.LangProfileMessage);
        buString.GetItemsAccordingToTheLang(buString.ReadXmlItem("<Captions>", "</Captions>", StringList), clsVar.varRuntime.Language, ref buProfile.LangProfileCaptions);
        buString.GetItemsAccordingToTheLang(buString.ReadXmlItem("<Command>", "</Command>", StringList), clsVar.varRuntime.Language, ref buProfile.LangProfileCommands);
        buString.GetItemsAccordingToTheLang(buString.ReadXmlItem("<MainForm>", "</MainForm>", StringList), clsVar.varRuntime.Language, ref buProfile.LangProfileMainForm);
        buString.GetItemsAccordingToTheLang(buString.ReadXmlItem("<Help>", "</Help>", StringList), clsVar.varRuntime.Language, ref buProfile.LangProfileHelp);
        StringList.Clear();
      }
      else
      {
        buLog.addLog("Profile Language", "Not Ok", MethodBase.GetCurrentMethod().Name);
        buString.MessageBoxError("Profile Language File Missing");
      }
      if (stringList.Count > 0)
        ;
    }
    catch (Exception ex)
    {
      string str = this.list_2[16 /*0x10*/];
      buLog.addLog("", "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, true, "");
    }
  }

