  public void OpenProfileFile()
  {
    ArrayList StringList1 = new ArrayList();
    ArrayList StringList2 = new ArrayList();
    FileInfo fileInfo1 = new FileInfo(AppPath.Settings + "\\Profile\\Profile.prm");
    if (fileInfo1.Exists)
    {
      buFile.OpenFromFile(fileInfo1.FullName, ref StringList1);
    }
    else
    {
      buLog.addLog("Profile Settings File Mising", "Not Ok", MethodBase.GetCurrentMethod().Name);
      buString.MessageBoxError("Profile Settings File Missing");
    }
    FileInfo fileInfo2 = new FileInfo(AppPath.Settings + "\\Profile\\mwProfileContour.bin");
    if (fileInfo2.Exists)
      buMWProfileVars.varCamContour.mwPar.Deserialize(fileInfo2.FullName);
    FileInfo fileInfo3 = new FileInfo(AppPath.Settings + "\\Profile\\mwProfileRough.bin");
    if (fileInfo3.Exists)
      buMWProfileVars.varCamRough.mwPar.Deserialize(fileInfo3.FullName);
    string str = AppPath.Settings + "\\Profile\\ProfileCam.bucamset";
    if (new FileInfo(str).Exists)
    {
      buFile.OpenFromFile(str, ref StringList2);
    }
    else
    {
      buLog.addLog("Profile Cam Settings File Mising", "Not Ok", MethodBase.GetCurrentMethod().Name);
      buString.MessageBoxError("Profile Cam Settings File Missing");
    }
    this.OpenProfileFile(StringList1, StringList2);
    if (clsInit.appEditor == null)
      return;
    clsInit.appEditor.OpenEditorFile();
  }

  public void OpenProfileFile(ArrayList ALSetting, ArrayList ALCam)
  {
    try
    {
      try
      {
        ArrayList CalcList1 = new ArrayList();
        buString.ListToSpecificList("<ProfileSettings>", "</ProfileSettings>", true, ALSetting, ref CalcList1);
        if (CalcList1.Count > 0)
        {
          buSerilization5.Decode(ALSetting, "", SerilizationMode5.MultiLine, (object) buProfileCalc.varProfileSettings);
          buLog.addLog("Profile Settings Variable Decoded", "Ok", MethodBase.GetCurrentMethod().Name);
        }
        ArrayList CalcList2 = new ArrayList();
        buString.ListToSpecificList("<buProfileCalc.varProfileVisualSettings>", "</buProfileCalc.varProfileVisualSettings>", true, ALSetting, ref CalcList2);
        if (CalcList2.Count > 0)
        {
          buSerilization5.Decode(ALSetting, "", SerilizationMode5.MultiLine, (object) buProfileCalc.varProfileVisualSettings);
          buLog.addLog("Profile VisualSettings Variable Decoded", "Ok", MethodBase.GetCurrentMethod().Name);
        }
        ArrayList CalcList3 = new ArrayList();
        buString.ListToSpecificList("<ProfileRuntimeSettings>", "</ProfileRuntimeSettings>", true, ALSetting, ref CalcList3);
        if (CalcList3.Count > 0)
        {
          buSerilization5.Decode(ALSetting, "", SerilizationMode5.MultiLine, (object) buProfileCalc.varProfileRunSettings);
          buLog.addLog("Profile RuntimeSettings Variable Decoded", "Ok", MethodBase.GetCurrentMethod().Name);
        }
        ArrayList CalcList4 = new ArrayList();
        buString.ListToSpecificList("<ClamperSettings>", "</ClamperSettings>", true, ALSetting, ref CalcList4);
        if (CalcList4.Count > 0)
        {
          buSerilization5.Decode(ALSetting, "", SerilizationMode5.MultiLine, (object) buProfileCalc.varProfileClamperSettings);
          buLog.addLog("Profile Clamper Settings Variable Decoded", "Ok", MethodBase.GetCurrentMethod().Name);
        }
        List<List<string>> CalcList5 = new List<List<string>>();
        buString5.ListToSpecificList("<ProfileClamper>", "</ProfileClamper>", true, ALSetting, ref CalcList5);
        for (int index = 0; index <= CalcList5.Count - 1; ++index)
        {
          ArrayList AL = new ArrayList();
          AL.AddRange((ICollection) CalcList5[index].ToArray());
          buEyeBaseVer5.Apps.ProfileClamper profileClamper = new buEyeBaseVer5.Apps.ProfileClamper();
          buSerilization5.Decode(AL, "", SerilizationMode5.MultiLine, (object) profileClamper);
          this.Clampers.Add(profileClamper);
        }
        List<List<string>> CalcList6 = new List<List<string>>();
        buString5.ListToSpecificList("<ProfileLengthClamperCount>", "</ProfileLengthClamperCount>", true, ALSetting, ref CalcList6);
        for (int index = 0; index <= CalcList6.Count - 1; ++index)
        {
          ArrayList AL = new ArrayList();
          AL.AddRange((ICollection) CalcList6[index].ToArray());
          ProfileLengthClamperCount lengthClamperCount = new ProfileLengthClamperCount();
          buSerilization5.Decode(AL, "", SerilizationMode5.MultiLine, (object) lengthClamperCount);
          this.list_3.Add(lengthClamperCount);
        }
        CalcList4.Clear();
        CalcList6.Clear();
      }
      catch (Exception ex)
      {
        buLog.addLog("Profile Settings Decoder Error", "Not Ok", MethodBase.GetCurrentMethod().Name);
        buException.throwException(ex, MethodBase.GetCurrentMethod().Name, true, "Profile Settings Decoder Error");
      }
      if (buProfileCalc.varProfileSettings.YDirection == ProfileYAxisDirection.PositiveDirection)
        this.shapeCreateParameters_0.SingY = 1.0;
      buLog.addLog("Profile Variable Decoded", "Ok", MethodBase.GetCurrentMethod().Name);
      try
      {
        ArrayList CalcList = new ArrayList();
        buString.ListToSpecificList("<MwCamSettings>", "</MwCamSettings>", true, ALCam, ref CalcList);
        if (CalcList.Count <= 0)
          return;
        buSerilization.Decode(ALCam, "_varCamContour", SerilizationMode.MultiLine, (object) buMWProfileVars.varCamContour);
        buSerilization.Decode(ALCam, "_varCamRough", SerilizationMode.MultiLine, (object) buMWProfileVars.varCamRough);
        buSerilization.Decode(ALCam, "_CamParMilling", SerilizationMode.MultiLine, (object) buProfileCalc.varProfileRunSettings.OPData.CamParMilling);
        buSerilization.Decode(ALCam, "_CamParNotch", SerilizationMode.MultiLine, (object) buProfileCalc.varProfileRunSettings.OPData.CamParNotch);
      }
      catch (Exception ex)
      {
        buLog.addLog("MW Profile Cam Settings Decoder Error", "Not Ok", MethodBase.GetCurrentMethod().Name);
        buException.throwException(ex, MethodBase.GetCurrentMethod().Name, true, "Profile Settings Decoder Error");
      }
    }
    catch (Exception ex)
    {
      string str = this.list_2[18];
      buLog.addLog("", "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, true, "");
    }
  }

