  public void SaveProfileJobFile(string FileName, bool AddRecent, bool AddSettings = false)
  {
    try
    {
      if (!AddSettings)
      {
        ArrayList AL = new ArrayList();
        this.SaveProfileJobFile(this.activeProfile, ref AL);
        buFile5.SaveToFile(AL, FileName);
      }
      else
      {
        ArrayList AL = new ArrayList();
        this.SaveProfileJobFile(this.activeProfile, ref AL);
        AL.Insert(0, (object) "<ProfileData>");
        AL.Add((object) "</ProfileData>");
        ArrayList ALSettings = new ArrayList();
        ArrayList ALCam = new ArrayList();
        this.SaveProfileFile(ref ALSettings, ref ALCam, false);
        AL.Add((object) " ");
        AL.Add((object) "<SettingsData>");
        AL.Add((object) "  <SettingsDataSet>");
        AL.AddRange((ICollection) ALSettings);
        AL.Add((object) "  </SettingsDataSet>");
        AL.Add((object) " ");
        AL.Add((object) "  <SettingsDataCam>");
        AL.AddRange((ICollection) ALCam);
        AL.Add((object) "  </SettingsDataCam>");
        AL.Add((object) "</SettingsData>");
        AL.Add((object) "------------------------------------------------------------------------");
        AL.Add((object) "   Tools ");
        AL.Add((object) "------------------------------------------------------------------------");
        AL.Add((object) "  <Tools>");
        for (int index1 = 0; index1 <= ccVars.Tools.Count - 1; ++index1)
        {
          AL.Add((object) "    <ToolGroup5>");
          ArrayList c = new ArrayList();
          c.AddRange((ICollection) ccVars.Tools[index1].ToDefAll("", 6, SerilizationMode5.MultiLine));
          c.RemoveAt(0);
          c.RemoveAt(c.Count - 1);
          AL.AddRange((ICollection) c);
          for (int index2 = 0; index2 <= ccVars.Tools[index1].Tools.Count - 1; ++index2)
            AL.AddRange((ICollection) ccVars.Tools[index1].Tools[index2].ToDefAll("", 6, SerilizationMode5.MultiLine));
          AL.Add((object) "    </ToolGroup5>");
        }
        AL.Add((object) "  </Tools>");
        buFile5.SaveToFile(AL, FileName);
      }
      if (!AddRecent)
        return;
      this.AddRecentSaveFile(FileName);
    }
    catch (Exception ex)
    {
      string str = "";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, true, str);
    }
  }

  public void OpenProfileJobFile(
    string FileName,
    bool AddOperations,
    bool CreateProfile,
    bool OnlyDrawing,
    ref buEyeBaseVer5.Apps.ProfileItem Profile,
    bool AddRecent,
    bool ShowProgress = true,
    bool PreviewDraw = true,
    bool UpdateTree = true)
  {
    try
    {
      if (buProfileCalc.varProfileSettings.JobOpenClearAllProfiles & CreateProfile)
      {
        this.activeProfile = new ProfileBase();
        buProfileCalc.varProfileRunSettings.activeProfileIndex = 0;
        buProfileCalc.varProfileRunSettings.activeOPIndex = -1;
      }
      if (FileName.Length <= 0)
        return;
      List<string> StringList = new List<string>();
      buFile5.OpenFromFile(FileName, ref StringList);
      this.OpenProfileJobFile(StringList, AddOperations, CreateProfile, OnlyDrawing, ShowProgress, ref Profile);
      if (AddRecent)
        this.AddRecentOpenFile(FileName);
      if (PreviewDraw)
        this.DrawPreview(this.activeProfile.FirstItem, new List<Entity>());
      if (UpdateTree)
        this.ProfileTreeUpdate();
      if (!ShowProgress)
        return;
      clsItem.FrmProgress.Visible = false;
    }
    catch (Exception ex)
    {
      string str = "";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, true, str);
    }
  }

  public void OpenProfileJobFile(
    string FileName,
    bool AddOperations,
    bool CreateProfile,
    bool OnlyDrawing,
    ref ProfileBase ProfileBase,
    bool AddRecent,
    bool AddSettings = false)
  {
    try
    {
      if (buProfileCalc.varProfileSettings.JobOpenClearAllProfiles & CreateProfile)
      {
        ProfileBase = new ProfileBase();
        buProfileCalc.varProfileRunSettings.activeProfileIndex = 0;
        buProfileCalc.varProfileRunSettings.activeOPIndex = -1;
      }
      CalculationEventArg e = new CalculationEventArg();
      e.ActiveProgressPercentage = 25.0;
      e.Job = $"{buLangTranslate.preDef.File} {buLangTranslate.preDef.Open}";
      e.ShowOnMainForm = true;
      e.ShowForm = false;
      clsInit.appCommand.CalculationInProgressCmd(e);
      ArrayList StringList = new ArrayList();
      List<List<string>> CalcList1 = new List<List<string>>();
      buFile5.OpenFromFile(FileName, ref StringList);
      if (AddSettings)
      {
        e.ActiveProgressPercentage = 50.0;
        e.Job = $"{buLangTranslate.preDef.Settings} {buLangTranslate.preDef.Open}";
        e.ShowOnMainForm = true;
        e.ShowForm = false;
        clsInit.appCommand.CalculationInProgressCmd(e);
        List<string> CalcList2 = new List<string>();
        List<string> CalcList3 = new List<string>();
        List<string> CalcList4 = new List<string>();
        buStatics.ListToSpecificList("<SettingsData>", "</SettingsData>", false, StringList, ref CalcList2);
        buStatics.ListToSpecificList("<ProfileData>", "</ProfileData>", false, StringList, ref CalcList3);
        buStatics.ListToSpecificList("<Tools>", "</Tools>", false, StringList, ref CalcList4);
        if (CalcList3.Count > 0)
        {
          StringList.Clear();
          StringList.AddRange((ICollection) CalcList3);
        }
        if (CalcList2.Count > 0)
        {
          ArrayList CalcList5 = new ArrayList();
          ArrayList CalcList6 = new ArrayList();
          buStatics.ListToSpecificList("<SettingsDataSet>", "</SettingsDataSet>", false, CalcList2, ref CalcList5);
          buStatics.ListToSpecificList("<SettingsDataCam>", "</SettingsDataCam>", false, CalcList2, ref CalcList6);
          this.OpenProfileFile(CalcList5, CalcList6);
        }
        if (CalcList4.Count > 0)
        {
          ccVars.Tools.Clear();
          CalcList1 = new List<List<string>>();
          List<List<string>> CalcList7 = new List<List<string>>();
          buString5.ListToSpecificList("<ToolGroup5>", "</ToolGroup5>", true, CalcList4, ref CalcList7);
          for (int index1 = 0; index1 <= CalcList7.Count - 1; ++index1)
          {
            ToolGroup5 toolGroup5 = new ToolGroup5();
            buSerilization5.Decode(CalcList7[index1], "", SerilizationMode5.MultiLine, (object) toolGroup5);
            buString5.ListToSpecificList("<ToolBase5>", "</ToolBase5>", true, CalcList7[index1], ref CalcList1);
            List<ToolBase5> toolBase5List = new List<ToolBase5>();
            for (int index2 = 0; index2 <= CalcList1.Count - 1; ++index2)
            {
              ArrayList AL = new ArrayList();
              AL.AddRange((ICollection) CalcList1[index2].ToArray());
              ToolBase5 toolBase5 = new ToolBase5();
              buSerilization5.Decode(AL, "", SerilizationMode5.MultiLine, (object) toolBase5);
              toolGroup5.Tools.Add(toolBase5);
            }
            ccVars.Tools.Add(toolGroup5);
          }
        }
        if (ccVars.Tools.Count == 0)
          clsFiles.OpenParameter();
        else if (ccVars.Tools[0].Tools.Count == 0)
          clsFiles.OpenParameter();
      }
      if (ccVars.Tools.Count == 0)
        buString5.MessageBoxWarning(buLangTranslate.preSentences.ToolsAreMissing);
      else if (ccVars.Tools[0].Tools.Count == 0)
        buString5.MessageBoxWarning(buLangTranslate.preSentences.ToolsAreMissing);
      buStatics.ListToSpecificList("<ProfileItem>", "</ProfileItem>", true, StringList, ref CalcList1);
      List<string> stringList = new List<string>();
      for (int index = 0; index <= CalcList1.Count - 1; ++index)
      {
        buEyeBaseVer5.Apps.ProfileItem Profile = new buEyeBaseVer5.Apps.ProfileItem();
        this.OpenProfileJobFile(CalcList1[index], AddOperations, CreateProfile, OnlyDrawing, false, ref Profile);
      }
      if (AddRecent)
        this.AddRecentOpenFile(FileName);
      if (!OnlyDrawing)
      {
        if (this.activeProfile.FirstItem != null)
        {
          this.activeProfile.FirstItem.isCollisionControlDone = false;
          this.activeProfile.FirstItem.isGCodeCreated = false;
          this.activeProfile.FirstItem.isGCodeSimMoveCreated = false;
          this.activeProfile.FirstItem.isSimulationDone = false;
          this.activeProfile.FirstItem.IsClamperDone = false;
          this.doCheckProfileWarnings(ref this.activeProfile.FirstItem);
        }
        if (this.activeProfile.SecondItem != null)
        {
          this.activeProfile.SecondItem.isCollisionControlDone = false;
          this.activeProfile.SecondItem.isGCodeCreated = false;
          this.activeProfile.SecondItem.isGCodeSimMoveCreated = false;
          this.activeProfile.SecondItem.isSimulationDone = false;
          this.activeProfile.SecondItem.IsClamperDone = false;
          this.doCheckProfileWarnings(ref this.activeProfile.SecondItem);
        }
        this.ProfileTreeUpdate();
      }
      this.doCheckProfileError();
      ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Invalidate();
      clsItem.FrmProgress.Visible = false;
    }
    catch (Exception ex)
    {
      string str = "";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, true, str);
    }
  }

  public void OpenProfileJobFile(
    List<string> SL,
    bool AddOperations,
    bool CreateProfile,
    bool OnlyDrawing,
    bool ShowProgress,
    ref buEyeBaseVer5.Apps.ProfileItem Profile)
  {
    try
    {
      List<string> WarningList = new List<string>();
      Profile = new buEyeBaseVer5.Apps.ProfileItem();
      CalculationEventArg e = new CalculationEventArg();
      e.ActiveProgressPercentage = 25.0;
      e.Job = $"{buLangTranslate.preDef.Profile} {buLangTranslate.preDef.Analysis}";
      e.ShowOnMainForm = true;
      e.ShowForm = ShowProgress;
      clsInit.appCommand.CalculationInProgressCmd(e);
      ArrayList AL = new ArrayList();
      AL.AddRange((ICollection) SL);
      buEyeBaseVer5.Apps.ProfileItem.Decode(AL, ref Profile);
      if (Profile.MaxClamperNumber != buProfileCalc.varProfileSettings.ProfileMaxClamper)
        Profile.MaxClamperNumber = buProfileCalc.varProfileSettings.ProfileMaxClamper;
      buProfileCalc.varProfileSettings.XDirRefType = Profile.XReferanceLocation;
      ProfileTempVars.SelectedOperations.Clear();
      if (ShowProgress)
      {
        if (clsItem.FrmProgress == null)
          clsItem.FrmProgress = new F_ProgressCalculation();
        clsItem.FrmProgress.TopMost = true;
        clsItem.FrmProgress.Show();
      }
      this.JobOpening = true;
      buProfileCalc.varProfileRunSettings.IncrementalMode = false;
      this.operationEditIndex = -1;
      e.ActiveProgressPercentage = 50.0;
      e.Job = $"{buLangTranslate.preDef.Profile} {buLangTranslate.preDef.Drawing}";
      clsInit.appCommand.CalculationInProgressCmd(e);
      for (int index1 = 0; index1 <= Profile.Drawings.Count - 1; ++index1)
      {
        Profile.Drawings[index1].OutterPoints.Clear();
        clsInit.cVector5.EntitiesToPointsWithCamDirection(Profile.Drawings[index1].OutterEntitites, buSystem.RegenDeviation, ref Profile.Drawings[index1].OutterPoints);
        clsInit.cVector5.CheckDuplicatedPointsWithPrevious(buSystem.resolutionCompare, ref Profile.Drawings[index1].OutterPoints);
        e.OverallProgressPercentage = 25.0;
        clsInit.appCommand.CalculationInProgressCmd(e);
        Profile.Drawings[index1].InnerPoints.Clear();
        for (int index2 = 0; index2 <= Profile.Drawings[index1].InnerEntities.Count - 1; ++index2)
        {
          List<Point3D> Points = new List<Point3D>();
          clsInit.cVector5.EntitiesToPointsWithCamDirection(Profile.Drawings[index1].InnerEntities[index2], buSystem.RegenDeviation, ref Points);
          clsInit.cVector5.CheckDuplicatedPointsWithPrevious(ref Points);
          if (clsInit.cVector5.GetClockDirection(Points) == ClockDirectionType.CCW)
            Points.Reverse();
          clsInit.cVector5.CheckDuplicatedPointsWithPrevious(buSystem.resolutionCompare, ref Points);
          Profile.Drawings[index1].InnerPoints.Add(Points);
        }
      }
      List<buEyeBaseVer5.Apps.ProfileOperation> CopiedOperation = new List<buEyeBaseVer5.Apps.ProfileOperation>();
      buEyeBaseVer5.Apps.ProfileOperation.Copy(Profile.Operations, ref CopiedOperation);
      if (CreateProfile)
      {
        Profile.Operations.Clear();
        if (Profile.Drawings.Count > 0)
          this.doCreateProfile(ref Profile, true);
      }
      if (AddOperations)
      {
        ToolBase5 tool = new ToolBase5(ccVars.toolActive);
        for (int index3 = 0; index3 <= CopiedOperation.Count - 1; ++index3)
        {
          this.list_0.Clear();
          if (CopiedOperation[index3].Action == actionTypeBU.profileNotch)
            clsInit.cProfile.ProfileCamDataToCamParameter(CopiedOperation[index3].CamOPData, ref CopiedOperation[index3].OperationData.CamParNotch);
          else
            clsInit.cProfile.ProfileCamDataToCamParameter(CopiedOperation[index3].CamOPData, ref CopiedOperation[index3].OperationData.CamParMilling);
          buProfileCalc.varProfileRunSettings.OPData.selectedPlane = (Plane) CopiedOperation[index3].OperationData.selectedPlane.Clone();
          string toolName = CopiedOperation[index3].OperationData.ToolName;
          bool flag;
          if (!(flag = clsInit.cVector5.FindToolWithToolName(ccVars.Tools, CopiedOperation[index3].OperationData.ToolName, ref ccVars.toolActive)) & CopiedOperation[index3].OperationData.ToolDiameter > 0.0)
            flag = clsInit.cVector5.FindToolWithDiameter(ccVars.Tools, CopiedOperation[index3].OperationData.ToolDiameter, ref ccVars.toolActive);
          if (!flag)
            clsInit.cVector5.FindToolSmallMillingDiameter(ccVars.Tools, ref ccVars.toolActive);
          if (ccVars.toolActive.Geometry.GeometryType == ToolType.Saw & CopiedOperation[index3].OperationData.Action != actionTypeBU.profileNotch)
            clsInit.cVector5.FindToolSmallMillingDiameter(ccVars.Tools, ref ccVars.toolActive);
          if (ccVars.toolActive.Geometry.GeometryType != ToolType.Saw & CopiedOperation[index3].OperationData.Action == actionTypeBU.profileNotch)
          {
            CopiedOperation[index3].Tool = new ToolBase5(ccVars.toolActive);
            for (int index4 = 0; index4 <= ccVars.Tools.Count - 1; ++index4)
            {
              for (int index5 = 0; index5 <= ccVars.Tools[index4].Tools.Count - 1; ++index5)
              {
                if (ccVars.Tools[index4].Tools[index5].Geometry.GeometryType == ToolType.Saw)
                {
                  ccVars.toolActive = new ToolBase5(ccVars.Tools[index4].Tools[index5]);
                  CopiedOperation[index3].ToolNotch = new ToolBase5(ccVars.toolActive);
                }
              }
            }
          }
          ProfileTempVars.CamAssinged = true;
          buProfileCalc.varProfileRunSettings.ShapeDataParameters.CamPars.Speeds.SpindleSpeed = ccVars.toolActive.CamData.SpindleSpeed;
          buProfileCalc.varProfileRunSettings.ShapeDataParameters.CamPars.Speeds.Feed = ccVars.toolActive.CamData.FeedSpeed;
          buProfileCalc.varProfileRunSettings.ShapeDataParameters.CamPars.Speeds.Plunge = ccVars.toolActive.CamData.PlungeSpeed;
          buProfileCalc.varProfileRunSettings.ShapeDataParameters.CamPars.Speeds.Finish = ccVars.toolActive.CamData.FinishSpeed;
          if (this.shapeCreateParameters_0.entitiesCurveList == null)
            this.shapeCreateParameters_0.entitiesCurveList = new List<EntitiesList>();
          this.shapeCreateParameters_0.entitiesCurveList.Clear();
          if (CopiedOperation[index3].OperationData.OperationType == ProfileOperationTypes.FreeDraw)
          {
            Point3D MinPoint = new Point3D();
            Point3D MaxPoint = new Point3D();
            if (CopiedOperation[index3].EntityMultiXYPlane.Count > 0)
            {
              this.doAddExternalEntities(CopiedOperation[index3].EntityMultiXYPlane, false, true);
              clsInit.cVector5.BoxSizeCalculate(CopiedOperation[index3].EntityMultiXYPlane, ref MinPoint, ref MaxPoint);
            }
            else if (CopiedOperation[index3].EntityMultiContour.Count > 0)
            {
              this.doAddExternalEntities(CopiedOperation[index3].EntityMultiContour, false, true);
              clsInit.cVector5.BoxSizeCalculate(CopiedOperation[index3].EntityMultiContour, ref MinPoint, ref MaxPoint);
            }
            buProfileCalc.varProfileRunSettings.FreeDrawOrjinalHeight = MaxPoint.Y - MinPoint.Y;
            buProfileCalc.varProfileRunSettings.FreeDrawOrjinalWidth = MaxPoint.X - MinPoint.X;
          }
          if (ProfileTempVars.TemplateMode & this.activeItem != null)
          {
            if (Profile.Width > 0.0)
              ProfileTempVars.TemplateYZScaleRatio = this.activeItem.Width / Profile.Width;
            if (Profile.Length > 0.0)
              ProfileTempVars.TemplateXScaleRatio = this.activeItem.Length / Profile.Length;
            if (CopiedOperation[index3].OperationData.selectedPlaneName == planeNames.Top | CopiedOperation[index3].OperationData.selectedPlaneName == planeNames.Bottom)
            {
              CopiedOperation[index3].OperationData.Position.X = Math.Round(CopiedOperation[index3].OperationData.Position.X * ProfileTempVars.TemplateXScaleRatio, 5) + ProfileTempVars.TemplateXOffset;
              CopiedOperation[index3].OperationData.Position.Y = Math.Round(CopiedOperation[index3].OperationData.Position.Y * ProfileTempVars.TemplateYZScaleRatio);
            }
            else if (CopiedOperation[index3].OperationData.selectedPlaneName == planeNames.Front | CopiedOperation[index3].OperationData.selectedPlaneName == planeNames.Back)
            {
              CopiedOperation[index3].OperationData.Position.X = Math.Round(CopiedOperation[index3].OperationData.Position.X * ProfileTempVars.TemplateXScaleRatio, 5) + ProfileTempVars.TemplateXOffset;
              CopiedOperation[index3].OperationData.Position.Y = Math.Round(CopiedOperation[index3].OperationData.Position.Y * ProfileTempVars.TemplateYZScaleRatio);
            }
            else if (CopiedOperation[index3].OperationData.selectedPlaneName == planeNames.Free)
              CopiedOperation[index3].OperationData.Position.X = Math.Round(CopiedOperation[index3].OperationData.Position.X * ProfileTempVars.TemplateXScaleRatio, 5) + ProfileTempVars.TemplateXOffset;
          }
          ShapeUpdateArg Data2 = new ShapeUpdateArg()
          {
            Finished = true,
            Parameters = new ShapeRuntimeData(buProfileCalc.varProfileRunSettings.ShapeDataParameters)
          };
          Data2.Parameters.selectedCorner = CopiedOperation[index3].OperationData.Corner;
          Data2.Parameters.objectAlignment = CopiedOperation[index3].OperationData.Alignment;
          Data2.Tool = new ToolBase5(ccVars.toolActive);
          Data2.ToolName = ccVars.toolActive.Data.Name;
          Data2.ToolChangeForced = true;
          Data2.OpenFile = true;
          Data2.NotOriginalTool = !flag;
          Data2.Parameters.Priority = CopiedOperation[index3].Priority;
          if (!CopiedOperation[index3].Enable)
            Data2.CommandList.Add("ForceDisable");
          this.UndoDontProfile = true;
          this.OPPriority = CopiedOperation[index3].Priority;
          buShape buShape = new buShape();
          buShape.BasePoint = new Point3D(CopiedOperation[index3].OperationData.basePosition.X, Math.Abs(CopiedOperation[index3].OperationData.basePosition.Y), CopiedOperation[index3].OperationData.basePosition.Z);
          if (buCompare5.EQ(buShape.BasePoint.X, 0.0) & buCompare5.EQ(buShape.BasePoint.Y, 0.0) & buCompare5.EQ(buShape.BasePoint.Y, 0.0))
          {
            buShape.BasePoint.X = CopiedOperation[index3].OperationData.Position.X;
            buShape.BasePoint.Y = CopiedOperation[index3].OperationData.Position.Y;
            buShape.BasePoint.Z = CopiedOperation[index3].OperationData.Position.Z;
            buShape.Corner = CornerLocation.LeftTop;
          }
          clsInit.cVector5.CoordinateFromPlaneAndCorner(new SizeObject(Profile.Length, Profile.Width, Profile.Height), CopiedOperation[index3].OperationData.Corner, buConversion5.PlaneNamesToPlaneBoxNames(CopiedOperation[index3].OperationData.selectedPlaneName), ref buShape, ref CopiedOperation[index3].OperationData.Position, this.shapeCreateParameters_0.SingX, this.shapeCreateParameters_0.SingY);
          this.OnlineOperation((object) null, (object) Data2, (object) CopiedOperation[index3].OperationData);
          if (!flag)
            this.list_0.Add($"{buLangTranslate.preSentences.SavedOperationToolNotAvailableInRecentToolList} {buLangTranslate.preDef.Tool} = {toolName}");
          if (this.list_0.Count > 0)
          {
            for (int index6 = 0; index6 <= this.list_0.Count - 1; ++index6)
              WarningList.Add($"{this.list_0[index6]} - {(index3 + 1).ToString()}. {buLangTranslate.preDef.Operation} - {CopiedOperation[index3].OperationData.OperationType.ToString()}");
          }
          this.UndoDontProfile = false;
          e.Job = $"{(index3 + 1).ToString()}.{buLangTranslate.preDef.Profile} {buLangTranslate.preDef.Calculating} - {buProfileCalc.OperationItemString(CopiedOperation[index3])}";
          e.ActiveProgressPercentage = (double) (index3 + 1) / (double) CopiedOperation.Count * 100.0;
          clsInit.appCommand.CalculationInProgressCmd(e);
        }
        this.OPPriority = 0;
        ProfileTempVars.TemplateMode = false;
        ProfileTempVars.CamAssinged = false;
        this.RearrangeOperationID();
        ccVars.toolActive = new ToolBase5(tool);
        if (WarningList.Count > 0)
        {
          clsItem.FrmProgress.Visible = false;
          F_Warning fWarning = new F_Warning();
          fWarning.ShowOk = true;
          fWarning.ShowReset = false;
          fWarning.PropertiesForm.FormPosition = FormStartPosition.CenterScreen;
          fWarning.lst_warnig.Font = new Font("Arial", 10f, FontStyle.Bold);
          fWarning.Init(WarningList);
          int num = (int) fWarning.ShowDialog();
          if (fWarning.PropertiesForm.Result != DialogResult.OK)
          {
            this.DrawPreview(new List<Entity>());
            return;
          }
        }
      }
      this.JobOpening = false;
      Profile.isCollisionControlDone = false;
      Profile.isGCodeCreated = false;
      Profile.isGCodeSimMoveCreated = false;
      Profile.isSimulationDone = false;
      Profile.IsClamperDone = false;
      this.doCheckProfileWarnings(ref Profile);
      clsInit.appCommand.CalculationInProgressReset(e);
      clsItem.FrmProgress.Visible = false;
    }
    catch (Exception ex)
    {
      string str = "";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, true, str);
    }
  }

