  public void Open3DData(string FileName)
  {
    List<Entity> EntityList = new List<Entity>();
    List<Entity> Entities = new List<Entity>();
    buFile5.OpenStep(ref EntityList, FileName);
    Point3D MinPoint = new Point3D();
    Point3D MaxPoint = new Point3D();
    Point3D point3D = new Point3D();
    clsInit.cVector5.BoxSizeCalculate(EntityList, ref MinPoint, ref MaxPoint);
    CreateProfileFromDataOptions Options = new CreateProfileFromDataOptions();
    Options.color = buProfileCalc.varProfileSettings.ProfileColor;
    Options.Transparency = buProfileCalc.varProfileSettings.MaterialTranspancy;
    Options.FileName = "111";
    Options.FullName = FileName;
    Options.Name = "1111";
    Options.Length = MaxPoint.X - MinPoint.Y;
    Options.NeededHeight = MaxPoint.Z - MinPoint.Z;
    Options.NeededWidth = MaxPoint.Y - MinPoint.Y;
    Options.SupportBlockY1Height = 0.0;
    Options.SupportBlockY2Height = 0.0;
    Options.SupportBlockZHeight = 0.0;
    Options.SupportBlockY1Width = 0.0;
    Options.SupportBlockY2Width = 0.0;
    Options.SupportBlockZWidth = 0.0;
    Options.NextFroupRules = SortingNextGroupFindRulesType.ClosestLength;
    Options.MaxClamper = buProfileCalc.varProfileSettings.ProfileMaxClamper;
    buEyeBaseVer5.Apps.ProfileItem Profile = new buEyeBaseVer5.Apps.ProfileItem();
    if (!(EntityList[0] is Brep))
      return;
    Brep brep = EntityList[0] as Brep;
    brep.Regen(0.01);
    brep.Translate(-brep.BoxMin.X, -brep.BoxMin.Y, -brep.BoxMin.Z);
    brep.Regen(0.01);
    double factor = 1.0;
    if (brep.BoxMax.Z > 0.0 & brep.BoxMax.Z < 1.0)
    {
      double num = 10.0 / brep.BoxMax.Z;
      if (num > 1.0 & num <= 10.0)
        factor = 10.0;
      if (num > 10.0 & num <= 100.0)
        factor = 100.0;
      if (num > 100.0 & num <= 1000.0)
        factor = 1000.0;
    }
    if (factor > 1.0)
    {
      brep.Scale(factor);
      brep.Regen(0.01);
    }
    ccVars.Pages[ccVars.Pages.Count - 1].Form.viewportcad.Entities.Clear();
    for (int index1 = 0; index1 <= brep.Faces.Length - 1; ++index1)
    {
      Brep.Face face = brep.Faces[index1];
      if ((face.Surface == null ? 0 : (face.Surface.GetType() == typeof (PlanarSurf) ? 1 : 0)) != 0)
      {
        for (int index2 = 0; index2 <= face.Loops.Length - 1; ++index2)
        {
          ICurve[] trimLoops = new ICurve[face.Loops[index2].Segments.Length];
          for (int index3 = 0; index3 <= face.Loops[index2].Segments.Length - 1; ++index3)
          {
            Brep.OrientedEdge segment = face.Loops[index2].Segments[index3];
            Brep.Edge edge = brep.Edges[segment.CurveIndex];
            trimLoops[index3] = edge.Curve;
          }
          Surface[] surface = face.Surface.GetSurface((IList<ICurve>) trimLoops);
          if ((surface == null ? 0 : (surface.Length != 0 ? 1 : 0)) != 0 && ((PlanarSurface) surface[0]).Plane.Equation.X == 1.0 | ((PlanarSurface) surface[0]).Plane.Equation.X == -1.0)
          {
            surface[0].Regen(0.1);
            List<Entity> entityList = new List<Entity>();
            if (((Entity) trimLoops[0]).Vertices[0].X < MinPoint.X + 60.0)
            {
              for (int index4 = 0; index4 <= trimLoops.Length - 1; ++index4)
                entityList.Add((Entity) trimLoops[index4]);
            }
            List<Point3D> points = new List<Point3D>();
            if (entityList.Count > 0)
            {
              buVector5.Add(((Entity) trimLoops[0]).Vertices, ref points);
              for (int index5 = 1; index5 <= trimLoops.Length - 1; ++index5)
              {
                Entity entity = trimLoops[index5] as Entity;
                if (buCompare5.EQ(points[points.Count - 1], entity.Vertices[0]))
                {
                  List<Point3D> CopiedPnt = new List<Point3D>();
                  buVector5.Add(entity.Vertices, ref CopiedPnt);
                  points.AddRange((IEnumerable<Point3D>) CopiedPnt);
                }
                else if (buCompare5.EQ(points[points.Count - 1], entity.Vertices[entity.Vertices.Length - 1]))
                {
                  List<Point3D> CopiedPnt = new List<Point3D>();
                  buVector5.Add(entity.Vertices, ref CopiedPnt);
                  CopiedPnt.Reverse();
                  points.AddRange((IEnumerable<Point3D>) CopiedPnt);
                }
                else if (index5 == 1)
                {
                  points.Reverse();
                  if (buCompare5.EQ(points[points.Count - 1], entity.Vertices[0]))
                  {
                    List<Point3D> CopiedPnt = new List<Point3D>();
                    buVector5.Add(entity.Vertices, ref CopiedPnt);
                    points.AddRange((IEnumerable<Point3D>) CopiedPnt);
                  }
                  else if (buCompare5.EQ(points[points.Count - 1], entity.Vertices[entity.Vertices.Length - 1]))
                  {
                    List<Point3D> CopiedPnt = new List<Point3D>();
                    buVector5.Add(entity.Vertices, ref CopiedPnt);
                    CopiedPnt.Reverse();
                    points.AddRange((IEnumerable<Point3D>) CopiedPnt);
                  }
                }
              }
              if ((points.Count < 3 ? 0 : (buCompare5.EQ(points[points.Count - 1], points[0]) ? 1 : 0)) != 0)
              {
                clsInit.cVector5.CheckDuplicatedPointsWithPrevious(ref points);
                LinearPath linearPath = new LinearPath((ICollection<Point3D>) points);
                Entities.Add((Entity) linearPath);
              }
            }
          }
        }
      }
      else if ((face.Surface == null ? 0 : (face.Surface.GetType() == typeof (CylindricalSurf) ? 1 : 0)) != 0)
      {
        ICurve[] trimLoops = (ICurve[]) null;
        for (int index6 = 0; index6 <= face.Loops.Length - 1; ++index6)
        {
          trimLoops = new ICurve[face.Loops[index6].Segments.Length];
          for (int index7 = 0; index7 <= face.Loops[index6].Segments.Length - 1; ++index7)
          {
            Brep.OrientedEdge segment = face.Loops[index6].Segments[index7];
            Brep.Edge edge = brep.Edges[segment.CurveIndex];
            trimLoops[index7] = edge.Curve;
          }
        }
        Surface[] surface = face.Surface.GetSurface((IList<ICurve>) trimLoops);
        if ((surface == null ? 0 : (surface.Length != 0 ? 1 : 0)) != 0)
          ;
      }
      if (face.Surface != null)
        ;
    }
    MaterialBase5 materialBase5 = new MaterialBase5();
    if (Entities.Count > 0)
    {
      clsInit.cVector5.Rotate(new Point3D(), -90.0, Vector3D.AxisY, ref Entities);
      clsInit.cVector5.Rotate(new Point3D(), -90.0, Vector3D.AxisZ, ref Entities);
      clsInit.cVector5.CheckEntities(new CheckEntitesOption()
      {
        CompositeCurveToEntities = false
      }, ref Entities);
      clsInit.cProfile.CreateProfileFromData(Entities, Options, ref Profile);
    }
    this.doCreateProfile(ref Profile, true);
    clsInit.appCommand.cmdViewZoomFit();
    ccVars.Pages[ccVars.Pages.Count - 1].Form.viewportcad.Invalidate();
  }

