              if (profileOperation.OperationData.selectedPlaneName == planeNames.Bottom)
              {
                profileOperation.OperationData.Position.Y = -Profile.Width - double.Parse(s);
                profileOperation.OperationData.basePosition.Y = Math.Abs(-Profile.Width - double.Parse(s));
