              if (profileOperation.OperationData.selectedPlaneName == planeNames.Front)
              {
                profileOperation.OperationData.Position.Z = Profile.Height + double.Parse(s);
                profileOperation.OperationData.basePosition.Z = Profile.Height + double.Parse(s);
                profileOperation.OperationData.Position.Y = -Profile.Width;
                profileOperation.OperationData.basePosition.Y = -Profile.Width;
              }
              if (profileOperation.OperationData.selectedPlaneName == planeNames.Back)
              {
                profileOperation.OperationData.Position.Z = Profile.Height - double.Parse(s);
                profileOperation.OperationData.basePosition.Z = Profile.Height - double.Parse(s);
              }
              if (profileOperation.OperationData.selectedPlaneName == planeNames.Free)
              {
                profileOperation.OperationData.Position.Y = Math.Abs(double.Parse(s));
                profileOperation.OperationData.basePosition.Y = Math.Abs(double.Parse(s));
