            }
            if (str5 == "4")
            {
              profileOperation.OperationData.selectedPlaneName = planeNames.Left;
              profileOperation.OperationData.selectedPlane = Plane.YZ;
            }
            if (str5 == "5")
            {
              profileOperation.OperationData.selectedPlaneName = planeNames.Right;
