            }
          }
          if (stringListList2[index3][index4].IndexOf("WType") >= 0 & stringListList2[index3][index4].IndexOf("WTypeIndex") == -1)
          {
            string str6 = "";
            buString5.ReadStringValue(stringListList2[index3][index4], "WType", ref str6);
            str6 = str6.Replace('"', ' ').Trim();
            switch (str6)
            {
              case "C":
                profileOperation = (buEyeBaseVer5.Apps.ProfileOperation) new buEyeBaseVer5.Apps.ProfileOperationCircle();
                profileOperation.Name = str1;
                profileOperation.Priority = this.OPPriority;
                profileOperation.OperationData.Action = actionTypeBU.profileCircle;
                profileOperation.OperationData.ManuelZEnable = true;
                break;
              case "R":
                profileOperation = (buEyeBaseVer5.Apps.ProfileOperation) new buEyeBaseVer5.Apps.ProfileOperationRectangle();
                profileOperation.Name = str1;
                profileOperation.Priority = this.OPPriority;
                profileOperation.OperationData.Action = actionTypeBU.profileRectangle;
                profileOperation.OperationData.ManuelZEnable = true;
                break;
              case "L":
                profileOperation = (buEyeBaseVer5.Apps.ProfileOperation) new buEyeBaseVer5.Apps.ProfileOperationSlot();
                profileOperation.Name = str1;
                profileOperation.Priority = this.OPPriority;
                profileOperation.OperationData.Action = actionTypeBU.profileSlot;
                profileOperation.OperationData.ManuelZEnable = true;
                break;
              case "S":
                profileOperation = (buEyeBaseVer5.Apps.ProfileOperation) new buEyeBaseVer5.Apps.ProfileOperationNotch();
                profileOperation.Name = str1;
                profileOperation.Priority = this.OPPriority;
                profileOperation.OperationData.Action = actionTypeBU.profileNotch;
