                profileOperation = (buEyeBaseVer5.Apps.ProfileOperation) new buEyeBaseVer5.Apps.ProfileOperationHole();
                profileOperation.Name = str1;
                profileOperation.Priority = this.OPPriority;
                profileOperation.OperationData.Action = actionTypeBU.profileHole;
