              default:
                int num6 = (int) MessageBox.Show("Not Implemented Yet, Send sample file to Us");
                break;
            }
          }
        }
        if (flag6)
        {
          if (stringListList2[index3][index4].IndexOf("BLength") >= 0)
          {
            string s = "";
            buString5.ReadStringValue(stringListList2[index3][index4], "BLength", ref s);
            Options.Length = double.Parse(s);
          }
          if (stringListList2[index3][index4].IndexOf("BWidth") >= 0)
