  public void RestoreFromFile(string FileName)
  {
    DirectoryInfo directoryInfo1 = new DirectoryInfo(AppPath.Backup);
    if (!directoryInfo1.Exists)
      return;
    FileInfo fileInfo1 = new FileInfo($"{directoryInfo1.FullName}\\{FileName}.buBackup");
    if (!fileInfo1.Exists)
      return;
    DirectoryInfo directoryInfo2 = new DirectoryInfo(AppPath.Backup + "\\Temp");
    if (!directoryInfo2.Exists)
      directoryInfo2.Create();
    buFile5.ExtractToFolder(directoryInfo2.FullName, fileInfo1.FullName);
    DirectoryInfo directoryInfo3 = new DirectoryInfo(directoryInfo2.FullName + "\\PostProcessor");
    if (directoryInfo3.Exists)
      buFile5.CopyFilesRecursively(directoryInfo3.FullName, AppPath.PostProcessor);
    DirectoryInfo directoryInfo4 = new DirectoryInfo(directoryInfo2.FullName + "\\Kinematic");
    if (directoryInfo4.Exists)
      buFile5.CopyFilesRecursively(directoryInfo4.FullName, AppPath.Kinematic);
    DirectoryInfo directoryInfo5 = new DirectoryInfo(directoryInfo2.FullName + "\\Settings");
    if (directoryInfo5.Exists)
      buFile5.CopyFilesRecursively(directoryInfo5.FullName, AppPath.Settings);
    FileInfo fileInfo2 = new FileInfo(directoryInfo2.FullName + "\\mnbucfd.dll");
    if (fileInfo1.Exists)
      buFile5.CopyFileToFolder(fileInfo2.FullName, AppPath.Base);
    directoryInfo2.Delete(true);
    buString5.MessageBoxInfo(AppLanguage.CadCamMessages[129]);
  }

  public void CreateBackUp(string FileName)
  {
    DirectoryInfo directoryInfo1 = new DirectoryInfo(AppPath.Backup);
    if (!directoryInfo1.Exists)
      directoryInfo1.Create();
    DirectoryInfo directoryInfo2 = new DirectoryInfo(AppPath.Backup + "\\Temp");
    if (!directoryInfo2.Exists)
      directoryInfo2.Create();
    buFile5.CopyFilesRecursively(AppPath.Settings, directoryInfo2.FullName + "\\Settings");
    if (new FileInfo(ccVars.KinematicOrjinal.FileName).Exists)
      buFile5.CopyFileToFolder(ccVars.KinematicOrjinal.FileName, directoryInfo2.FullName + "\\Kinematic");
    if (new FileInfo(ccVars.PostActive.FileName).Exists)
      buFile5.CopyFileToFolder(ccVars.PostActive.FileName, directoryInfo2.FullName + "\\PostProcessor");
    FileInfo fileInfo1 = new FileInfo(AppPath.Base + "\\mnbucfd.dll");
    if (fileInfo1.Exists)
      buFile5.CopyFileToFolder(fileInfo1.FullName, directoryInfo2.FullName);
    FileInfo fileInfo2 = new FileInfo($"{AppPath.Backup}\\{FileName}.buBackup");
    if (fileInfo2.Exists)
      fileInfo2.Delete();
    buFile5.ZipFolderToFile(directoryInfo2.FullName, fileInfo2.FullName);
    directoryInfo2.Delete(true);
  }

  public void CreateArchive()
  {
    string str = buFile5.GetDesktopFolder() + "\\ProfileArchive";
    DirectoryInfo directoryInfo = new DirectoryInfo(str);
    if (!directoryInfo.Exists)
    {
      Directory.CreateDirectory(str);
    }
    else
    {
      Directory.Delete(directoryInfo.FullName, true);
      directoryInfo.Create();
    }
    if (new DirectoryInfo(AppPath.Settings).Exists)
    {
      Directory.CreateDirectory(str + "\\Settings");
      buFile5.CopyFilesRecursively(AppPath.Settings, str + "\\Settings");
    }
    if (new FileInfo(ccVars.KinematicOrjinal.FileName).Exists)
      buFile5.CopyFileToFolder(ccVars.KinematicOrjinal.FileName, str);
    if (new FileInfo(ccVars.PostActive.FileName).Exists)
      buFile5.CopyFileToFolder(ccVars.PostActive.FileName, str);
    FileInfo fileInfo1 = new FileInfo(AppPath.Base + "\\mnbucfd.dll");
    if (fileInfo1.Exists)
      buFile5.CopyFileToFolder(fileInfo1.FullName, str);
    this.SaveProfileJobFile(str + "\\LastProfile.buprofile", false);
    Bitmap SSBmp = (Bitmap) null;
    buImage5.GetScreenShot(clsItem.FrmMain, ref SSBmp);
    SSBmp?.Save(str + "\\ScreeenShot.bmp");
    FileInfo fileInfo2 = new FileInfo(buFile5.GetDesktopFolder() + "\\ProfileArchive.zip");
    if (fileInfo2.Exists)
      fileInfo2.Delete();
    buFile5.ZipFolderToFile(str, fileInfo2.FullName);
    directoryInfo.Delete(true);
    buString5.MessageBoxInfo($"{AppLanguage.CadCamMessages[126]} - {fileInfo2.FullName}");
  }

