  public void OperationCommand(object Cmd)
  {
    this.operationEditIndex = -1;
    if ((ProfileOperationTypes) Cmd == ProfileOperationTypes.Circle)
      this.cmdOperation(actionTypeBU.profileCircle, true);
    if ((ProfileOperationTypes) Cmd == ProfileOperationTypes.Rectangle)
      this.cmdOperation(actionTypeBU.profileRectangle, true);
    if ((ProfileOperationTypes) Cmd == ProfileOperationTypes.Barrel)
      this.cmdOperation(actionTypeBU.profileBarrel, true);
    if ((ProfileOperationTypes) Cmd == ProfileOperationTypes.Ellipse)
      this.cmdOperation(actionTypeBU.profileEllipse, true);
    if ((ProfileOperationTypes) Cmd == ProfileOperationTypes.Slot)
      this.cmdOperation(actionTypeBU.profileSlot, true);
    if ((ProfileOperationTypes) Cmd == ProfileOperationTypes.Hole)
      this.cmdOperation(actionTypeBU.profileHole, true);
    if ((ProfileOperationTypes) Cmd == ProfileOperationTypes.Tapping)
      this.cmdOperation(actionTypeBU.profileTapping, true);
    if ((ProfileOperationTypes) Cmd == ProfileOperationTypes.Cut)
      this.cmdOperation(actionTypeBU.profileCut, true);
    if ((ProfileOperationTypes) Cmd == ProfileOperationTypes.Notch)
      this.cmdOperation(actionTypeBU.profileNotch, true);
    if ((ProfileOperationTypes) Cmd == ProfileOperationTypes.RoundRectangle)
      this.cmdOperation(actionTypeBU.profileRoundRectangle, true);
    if ((ProfileOperationTypes) Cmd == ProfileOperationTypes.Text)
      this.cmdOperation(actionTypeBU.profileText, true);
    if ((ProfileOperationTypes) Cmd == ProfileOperationTypes.WireText)
      this.cmdOperation(actionTypeBU.profileWireText, true);
    if ((ProfileOperationTypes) Cmd == ProfileOperationTypes.FromFile)
      this.cmdAddFromFile();
    if ((ProfileOperationTypes) Cmd == ProfileOperationTypes.FromFileList)
      this.cmdAddFromList();
    if ((ProfileOperationTypes) Cmd == ProfileOperationTypes.FreeDraw)
      this.cmdOperation(actionTypeBU.profileFreeDraw, true);
    if ((ProfileOperationTypes) Cmd != ProfileOperationTypes.Library)
      return;
    this.cmdLibrary();
  }

  public void RearrangeOperationID()
  {
    buEyeBaseVer5.Apps.ProfileItem profileItem = clsInit.cProfile.SelectActiveProfile(this.activeProfile.FirstItem, this.activeProfile.SecondItem, ref buProfileCalc.varProfileRunSettings.activeProfileIndex);
    if (profileItem == null)
      return;
    this.IDCounter = 1;
    for (int index = 0; index <= profileItem.Operations.Count - 1; ++index)
    {
      profileItem.Operations[index].ID = this.IDCounter.ToString();
      ++this.IDCounter;
    }
  }

  public void ResetAllCalculationFlags()
  {
    if (this.activeProfile.FirstItem != null)
    {
      this.ResetCalculationFlags(false, false, false, false);
      this.doCheckProfileWarnings(ref this.activeProfile.FirstItem);
    }
    if (this.activeProfile.SecondItem == null)
      return;
    this.ResetCalculationFlags(false, false, false, false);
    this.doCheckProfileWarnings(ref this.activeProfile.SecondItem);
  }

  public void ResetCalculationFlags(
    bool isCollisionControlDone,
    bool isSimulationDone,
    bool IsClamperDone,
    bool isGCodeCreated)
  {
    if (this.activeProfile.FirstItem != null)
    {
      this.activeProfile.FirstItem.isCollisionControlDone = isCollisionControlDone;
      this.activeProfile.FirstItem.isSimulationDone = isSimulationDone;
      this.activeProfile.FirstItem.IsClamperDone = IsClamperDone;
      this.activeProfile.FirstItem.isGCodeCreated = isGCodeCreated;
      this.activeProfile.FirstItem.isGCodeSimMoveCreated = isGCodeCreated;
      this.activeProfile.FirstItem.isCollisionOnlineAvailable = false;
      this.activeProfile.FirstItem.isCollisionOfflineAvailable = false;
    }
    if (this.activeProfile.SecondItem == null)
      return;
    this.activeProfile.SecondItem.isCollisionControlDone = isCollisionControlDone;
    this.activeProfile.SecondItem.isSimulationDone = isSimulationDone;
    this.activeProfile.SecondItem.IsClamperDone = IsClamperDone;
    this.activeProfile.SecondItem.isGCodeCreated = isGCodeCreated;
    this.activeProfile.SecondItem.isGCodeSimMoveCreated = isGCodeCreated;
    this.activeProfile.SecondItem.isCollisionOnlineAvailable = false;
    this.activeProfile.SecondItem.isCollisionOfflineAvailable = false;
  }

  public string GetOperationInfo(GProfileOperation OP)
  {
    try
    {
      return $"{$"{OP.Name}{Environment.NewLine}" + OP.OperationData.selectedPlaneName.ToString() + Environment.NewLine}{OP.Tool.Data.Name} - T{OP.Tool.Data.No.ToString()} - D : {OP.Tool.Geometry.Diameter.ToString("f2")}";
    }
    catch (Exception ex)
    {
      return buLangTranslate.preDef.Error;
    }
  }

  public void ProfileOffsetCalculation(ref Point3D profileOffset, buEyeBaseVer5.Apps.ProfileItem Profile)
  {
    if (Profile == null)
      return;
    if (buProfileCalc.varProfileSettings.XDirection == ProfileXAxisDirection.Left)
      profileOffset.X = 0.0;
    if (buProfileCalc.varProfileSettings.XDirection == ProfileXAxisDirection.Center)
      profileOffset.X = -Profile.Length / 2.0;
    if (buProfileCalc.varProfileSettings.XDirection == ProfileXAxisDirection.Rigth)
      profileOffset.X = -Profile.Length;
    if (buProfileCalc.varProfileSettings.YDirection == ProfileYAxisDirection.PositiveDirection)
      profileOffset.Y = 0.0;
    if (buProfileCalc.varProfileSettings.YDirection == ProfileYAxisDirection.Center)
      profileOffset.Y = -Profile.Width / 2.0;
    if (buProfileCalc.varProfileSettings.YDirection != ProfileYAxisDirection.NegativeDirection)
      return;
    profileOffset.Y = -Profile.Width;
  }

  public void UndoGetBack()
  {
    if (this.UndoList.Count <= 0)
      return;
    this.UndoDontProfile = true;
    this.activeProfile = new ProfileBase(this.UndoList[this.UndoList.Count - 1]);
    this.DrawActiveProfile();
    this.DrawPreview(new List<Entity>());
    this.ProfileTreeUpdate();
    this.UndoList.RemoveAt(this.UndoList.Count - 1);
    this.UndoDontProfile = false;
  }

  public void UndoBuffer()
  {
    if (!(buProfileCalc.varProfileSettings.UseUndoBuffer & !this.UndoDontProfile))
      return;
    if (this.UndoList.Count > 20)
      this.UndoList.RemoveAt(0);
    if (!(this.activeProfile.FirstItem != null | this.activeProfile.SecondItem != null))
      return;
    this.UndoList.Add(new ProfileBase(this.activeProfile));
  }

  public void OperationToCam(
    ref buEyeBaseVer5.Apps.ProfileOperation OP,
    buEyeBaseVer5.Apps.ProfileItem Profile,
    List<buEntity> entCam,
    List<DepthPositions> calcDepth,
    int indexDepth,
    Vector3D VecTranslate,
    Vector3D VecDepth,
    double disMoveX,
    double disMoveY,
    double disMoveZ,
    bool MoveSmallSafe,
    int IndexRepeat,
    ref Point3D pntLastMoved)
  {
    if (entCam.Count == 0)
      return;
    if (OP.OperationData.OperationType == ProfileOperationTypes.Notch)
    {
      if (OP.ToolNotch == null)
        return;
    }
    else if (OP.OperationData.OperationType == ProfileOperationTypes.Tapping)
    {
      if (OP.Tool == null | OP.ToolAux == null)
        return;
    }
    else if (OP.Tool == null)
      return;
    Point3D point3D1 = buVector5.ToPoint3D(OP.OperationData.Position);
    if (buProfileCalc.varProfileSettings.XDirRefType == LeftRightType.Right)
    {
      point3D1.X = OP.OperationData.Position.X;
      if (buProfileCalc.varProfileSettings.RightProfileMakeAsMirror)
        point3D1.X = Profile.Length - OP.OperationData.Position.X;
    }
    if (OP.OperationData.selectedPlaneName == planeNames.Top | OP.OperationData.selectedPlaneName == planeNames.Bottom && buProfileCalc.varProfileSettings.XDirRefType == LeftRightType.Right)
    {
      point3D1.X = OP.OperationData.Position.X;
      if (buProfileCalc.varProfileSettings.RightProfileMakeAsMirror)
        point3D1.X = Profile.Length - OP.OperationData.Position.X;
    }
    if (entCam.Count > 0)
    {
      List<buEntity> refEntities = new List<buEntity>();
      buEntity.Copy(entCam, ref refEntities);
      bool flag = false;
      if (!clsInit.cVector5.isEntitiesClosed(refEntities) && indexDepth % 2 == 1)
        flag = true;
      if (flag)
        clsInit.cVector5.ChangeEntitiesDirection(ref refEntities);
      if (OP.OperationData.selectedPlaneName == planeNames.Free && entCam != null)
      {
        Vector3D vector3D = OP.OperationData.selectedPlane.AxisZ * OP.OperationData.CamParMilling.Distances.Safe;
        if (MoveSmallSafe)
          vector3D = OP.OperationData.selectedPlane.AxisZ * (OP.OperationData.CamParMilling.Distances.Rapid + Math.Abs(calcDepth[indexDepth].Depth));
        double a = clsInit.cVector5.PointAngle(new Point3D(-VecDepth.X, -VecDepth.Y, -VecDepth.Z), new Point3D(), Plane.YZ) - 90.0;
        if (indexDepth == 0)
        {
          Point3D end = new Point3D(refEntities[0].StartPoint.X, refEntities[0].StartPoint.Y, refEntities[0].StartPoint.Z);
