          OP.EntityMultiCam.Add(buEntity);
          pntLastMoved = buVector5.ToPoint3D(buEntity.EndPoint);
          if (buEntity.sortDirection == entitySortDirection.Reverse)
            pntLastMoved = buVector5.ToPoint3D(buEntity.StartPoint);
        }
        if (indexDepth == calcDepth.Count - 1)
        {
          Point3D end = new Point3D(pntLastMoved.X + vector3D.X, pntLastMoved.Y + vector3D.Y, Profile.ProfileMinPoint.Z + vector3D.Z);
          buLine buLine = new buLine(pntLastMoved, end);
          buLine.typeDefination = entityTypeDefination.CamLeave;
          buLine.Info.CamID = IndexRepeat;
          OP.EntityMultiCam.Add((buEntity) buLine);
        }
        else if (calcDepth[indexDepth].PeckingUp)
        {
          Point3D end = new Point3D(pntLastMoved.X + vector3D.X, pntLastMoved.Y + vector3D.Y, Profile.ProfileMinPoint.Z + vector3D.Z);
          if (calcDepth[indexDepth].PeckingUpDistance > 0.0)
            end = new Point3D(pntLastMoved.X + vector3D.X, pntLastMoved.Y + vector3D.Y, pntLastMoved.Z - calcDepth[indexDepth].PeckingUpDistance);
          buLine buLine = new buLine(pntLastMoved, end);
          buLine.typeDefination = entityTypeDefination.CamLeave;
          buLine.Info.CamID = IndexRepeat;
          OP.EntityMultiCam.Add((buEntity) buLine);
        }
      }
    }
    OP.CamCalculation = new List<camTp>();
    clsInit.cCam5.camEntitiesToCamPoints(OP.EntityMultiCam, OP.OperationData.CamParMilling, OP.Tool, ref OP.CamCalculation);
  }

  public void OperationToCam(
    ref buEyeBaseVer5.Apps.ProfileOperation OP,
    buEyeBaseVer5.Apps.ProfileItem Profile,
    List<List<buEntity>> entCam,
    List<DepthPositions> calcDepth,
    int indexDepth,
    Vector3D VecTranslate,
    Vector3D VecDepth,
    double disMoveX,
    double disMoveY,
    double disMoveZ,
    bool MoveSmallSafe,
    int IndexRepeat,
    ref Point3D pntLastMoved)
  {
    if (entCam.Count == 0)
      return;
    Point3D point3D1 = buVector5.ToPoint3D(OP.OperationData.Position);
    if (buProfileCalc.varProfileSettings.XDirRefType == LeftRightType.Right)
    {
      point3D1.X = OP.OperationData.Position.X;
      if (buProfileCalc.varProfileSettings.RightProfileMakeAsMirror)
        point3D1.X = Profile.Length - OP.OperationData.Position.X;
    }
    if (OP.OperationData.selectedPlaneName == planeNames.Top | OP.OperationData.selectedPlaneName == planeNames.Bottom && buProfileCalc.varProfileSettings.XDirRefType == LeftRightType.Right)
    {
      point3D1.X = OP.OperationData.Position.X;
      if (buProfileCalc.varProfileSettings.RightProfileMakeAsMirror)
        point3D1.X = Profile.Length - OP.OperationData.Position.X;
    }
    for (int index1 = 0; index1 <= entCam.Count - 1; ++index1)
    {
      if (entCam[index1].Count > 0)
      {
        List<buEntity> refEntities = new List<buEntity>();
        buEntity.Copy(entCam[index1], ref refEntities);
        bool flag = false;
        if (!clsInit.cVector5.isEntitiesClosed(refEntities) && indexDepth % 2 == 1)
          flag = true;
        if (flag)
          clsInit.cVector5.ChangeEntitiesDirection(ref refEntities);
        if (OP.OperationData.selectedPlaneName == planeNames.Free && entCam != null)
        {
          Vector3D vector3D = OP.OperationData.selectedPlane.AxisZ * OP.OperationData.CamParMilling.Distances.Safe;
          if (MoveSmallSafe)
            vector3D = OP.OperationData.selectedPlane.AxisZ * OP.OperationData.CamParMilling.Distances.Rapid;
          double a = clsInit.cVector5.PointAngle(new Point3D(-VecDepth.X, -VecDepth.Y, -VecDepth.Z), new Point3D(), Plane.YZ) - 90.0;
          if (indexDepth == 0)
          {
            Point3D end = new Point3D(refEntities[0].StartPoint.X, refEntities[0].StartPoint.Y, refEntities[0].StartPoint.Z);
            if (refEntities[0].sortDirection == entitySortDirection.Reverse)
              end = new Point3D(refEntities[0].EndPoint.X, refEntities[0].EndPoint.Y, refEntities[0].EndPoint.Z);
            buLine refEnt = new buLine(new Point3D(end.X + vector3D.X, end.Y + vector3D.Y, end.Z + vector3D.Z), end);
            refEnt.typeDefination = entityTypeDefination.CamPlunge;
            refEnt.Orientation = new OrientationAngle(a, 0.0, 0.0);
            buEntity buEntity = buVector5.CopyEntities((buEntity) refEnt);
            buEntity.Translate(point3D1.X + disMoveX, VecTranslate.Y, VecTranslate.Z + disMoveZ);
            buEntity.Translate(0.0, VecDepth.Y + disMoveY, VecDepth.Z);
            buEntity.Info.CamID = IndexRepeat;
            OP.EntityMultiCam.Add(buEntity);
          }
          else if (indexDepth > 0 & indexDepth <= calcDepth.Count - 1)
          {
            buEntity buEntity1 = buVector5.CopyEntities(refEntities[0]);
            buEntity1.Translate(point3D1.X + disMoveX, VecTranslate.Y, VecTranslate.Z + disMoveZ);
            buEntity1.Translate(0.0, VecDepth.Y + disMoveY, VecDepth.Z);
            Point3D point3D2 = new Point3D(buEntity1.StartPoint.X, buEntity1.StartPoint.Y, buEntity1.StartPoint.Z);
            if (refEntities[0].sortDirection == entitySortDirection.Reverse)
              point3D2 = new Point3D(buEntity1.EndPoint.X, buEntity1.EndPoint.Y, buEntity1.EndPoint.Z);
            buEntity buEntity2 = (buEntity) new buLine(pntLastMoved, point3D2);
            buEntity2.typeDefination = entityTypeDefination.CamPlunge;
            buEntity2.Orientation = new OrientationAngle(a, 0.0, 0.0);
            pntLastMoved = buVector5.ToPoint3D(point3D2);
            buEntity2.Info.CamID = IndexRepeat;
            OP.EntityMultiCam.Add(buEntity2);
          }
          for (int index2 = 0; index2 <= refEntities.Count - 1; ++index2)
          {
            buEntity buEntity = buVector5.CopyEntities(refEntities[index2]);
            buEntity.Translate(point3D1.X + disMoveX, VecTranslate.Y, VecTranslate.Z + disMoveZ);
            buEntity.Translate(0.0, VecDepth.Y + disMoveY, VecDepth.Z);
            buEntity.Orientation.A = a;
            if (buEntity is buPoint)
            {
              pntLastMoved = buVector5.ToPoint3D(buEntity.StartPoint);
            }
            else
            {
              buEntity.Info.CamID = IndexRepeat;
              OP.EntityMultiCam.Add(buEntity);
              pntLastMoved = buVector5.ToPoint3D(buEntity.EndPoint);
              if (buEntity.sortDirection == entitySortDirection.Reverse)
                pntLastMoved = buVector5.ToPoint3D(buEntity.StartPoint);
            }
          }
          if (indexDepth == calcDepth.Count - 1)
          {
            Point3D end = new Point3D(pntLastMoved.X + vector3D.X, pntLastMoved.Y + vector3D.Y, pntLastMoved.Z + vector3D.Z);
            buLine buLine = new buLine(pntLastMoved, end);
            buLine.typeDefination = entityTypeDefination.CamLeave;
            buLine.Orientation = new OrientationAngle(a, 0.0, 0.0);
            buLine.Info.CamID = IndexRepeat;
            OP.EntityMultiCam.Add((buEntity) buLine);
          }
        }
        if (OP.OperationData.selectedPlaneName == planeNames.Top && refEntities != null)
        {
          Vector3D vector3D = OP.OperationData.selectedPlane.AxisZ * OP.OperationData.CamParMilling.Distances.Safe;
          if (MoveSmallSafe)
            vector3D = OP.OperationData.selectedPlane.AxisZ * OP.OperationData.CamParMilling.Distances.Rapid;
          if (indexDepth == 0)
          {
            Point3D end = new Point3D(refEntities[0].StartPoint.X, refEntities[0].StartPoint.Y, calcDepth[indexDepth].TopPosition);
            if (refEntities[0].sortDirection == entitySortDirection.Reverse)
              end = new Point3D(refEntities[0].EndPoint.X, refEntities[0].EndPoint.Y, calcDepth[indexDepth].TopPosition);
            buLine refEnt = new buLine(new Point3D(end.X + vector3D.X, end.Y + vector3D.Y, OP.ProfileHeight + vector3D.Z), end);
            refEnt.typeDefination = entityTypeDefination.CamPlunge;
            buEntity buEntity = buVector5.CopyEntities((buEntity) refEnt);
            double dx = point3D1.X + disMoveX;
            buEntity.Translate(dx, VecTranslate.Y, VecTranslate.Z + disMoveZ);
            buEntity.Translate(0.0, VecDepth.Y + disMoveY, VecDepth.Z);
            buEntity.Info.CamID = IndexRepeat;
            OP.EntityMultiCam.Add(buEntity);
          }
          else if (indexDepth > 0 & indexDepth <= calcDepth.Count - 1)
          {
            buEntity buEntity3 = buVector5.CopyEntities(refEntities[0]);
            double dx = point3D1.X + disMoveX;
            buEntity3.Translate(dx, VecTranslate.Y, VecTranslate.Z + disMoveZ);
            buEntity3.Translate(0.0, VecDepth.Y + disMoveY, calcDepth[indexDepth].BottomPosition);
            Point3D point3D3 = new Point3D(buEntity3.StartPoint.X, buEntity3.StartPoint.Y, buEntity3.StartPoint.Z);
            if (refEntities[0].sortDirection == entitySortDirection.Reverse)
              point3D3 = new Point3D(buEntity3.EndPoint.X, buEntity3.EndPoint.Y, buEntity3.EndPoint.Z);
            double num = Math.Abs(point3D3.Z - pntLastMoved.Z);
            Point3D point3D4 = new Point3D(point3D3.X, point3D3.Y, point3D3.Z);
            buEntity buEntity4;
            if (num > buProfileCalc.varProfileSettings.EachLayerSafeDistance)
            {
              Point3D point3D5 = new Point3D(point3D3.X, point3D3.Y, calcDepth[indexDepth].TopPosition + buProfileCalc.varProfileSettings.EachLayerSafeDistance);
              buEntity buEntity5 = (buEntity) new buLine(pntLastMoved, point3D5);
              buEntity5.typeDefination = entityTypeDefination.CamPlungeFast;
              buEntity5.Orientation = new OrientationAngle(buEntity3.Orientation);
              buEntity5.Info.CamID = IndexRepeat;
              OP.EntityMultiCam.Add(buEntity5);
              buEntity4 = (buEntity) new buLine(point3D5, point3D3);
            }
            else
              buEntity4 = (buEntity) new buLine(pntLastMoved, point3D3);
            buEntity4.typeDefination = entityTypeDefination.CamPlunge;
            buEntity4.Info.CamID = IndexRepeat;
            OP.EntityMultiCam.Add(buEntity4);
            pntLastMoved = buVector5.ToPoint3D(point3D3);
          }
          for (int index3 = 0; index3 <= refEntities.Count - 1; ++index3)
          {
            buEntity buEntity = buVector5.CopyEntities(refEntities[index3]);
            double dx = point3D1.X + disMoveX;
            if (OP.OperationData.XRefFromProfileEnd)
              dx = Profile.Length - point3D1.X + disMoveX;
            buEntity.Translate(dx, VecTranslate.Y, VecTranslate.Z + disMoveZ);
            buEntity.Translate(0.0, VecDepth.Y + disMoveY, calcDepth[indexDepth].BottomPosition);
            buEntity.Info.CamID = IndexRepeat;
            OP.EntityMultiCam.Add(buEntity);
            pntLastMoved = buVector5.ToPoint3D(buEntity.EndPoint);
            if (buEntity.sortDirection == entitySortDirection.Reverse)
              pntLastMoved = buVector5.ToPoint3D(buEntity.StartPoint);
          }
          if (indexDepth == calcDepth.Count - 1)
          {
            Point3D end = new Point3D(pntLastMoved.X + vector3D.X, pntLastMoved.Y + vector3D.Y, OP.ProfileHeight + vector3D.Z);
            buLine buLine = new buLine(pntLastMoved, end);
            buLine.typeDefination = entityTypeDefination.CamLeave;
            buLine.Info.CamID = IndexRepeat;
            OP.EntityMultiCam.Add((buEntity) buLine);
          }
        }
        if (OP.OperationData.selectedPlaneName == planeNames.Front && refEntities != null)
        {
          Vector3D vector3D = OP.OperationData.selectedPlane.AxisZ * OP.OperationData.CamParMilling.Distances.Safe;
          if (MoveSmallSafe)
            vector3D = OP.OperationData.selectedPlane.AxisZ * OP.OperationData.CamParMilling.Distances.Rapid;
          if (indexDepth == 0)
          {
            Point3D end = new Point3D(refEntities[0].StartPoint.X, calcDepth[indexDepth].TopPosition, refEntities[0].StartPoint.Z);
            if (refEntities[0].sortDirection == entitySortDirection.Reverse)
              end = new Point3D(refEntities[0].EndPoint.X, calcDepth[indexDepth].TopPosition, refEntities[0].EndPoint.Z);
            buLine refEnt = new buLine(new Point3D(end.X + vector3D.X, -OP.ProfileWidth + vector3D.Y, end.Z + vector3D.Z), end);
            refEnt.typeDefination = entityTypeDefination.CamPlunge;
            refEnt.Orientation.A = 90.0;
            buEntity buEntity = buVector5.CopyEntities((buEntity) refEnt);
            buEntity.Translate(point3D1.X + disMoveX, VecTranslate.Y, VecTranslate.Z + disMoveZ);
            buEntity.Translate(0.0, VecDepth.Y + disMoveY, VecDepth.Z);
            buEntity.Info.CamID = IndexRepeat;
            OP.EntityMultiCam.Add(buEntity);
          }
          else if (indexDepth > 0 & indexDepth <= calcDepth.Count - 1)
          {
            buEntity buEntity6 = buVector5.CopyEntities(refEntities[0]);
            buEntity6.Translate(point3D1.X + disMoveX, VecTranslate.Y, VecTranslate.Z + disMoveZ);
            buEntity6.Translate(0.0, calcDepth[indexDepth].BottomPosition + disMoveY, VecDepth.Z);
            Point3D point3D6 = new Point3D(buEntity6.StartPoint.X, buEntity6.StartPoint.Y, buEntity6.StartPoint.Z);
            if (refEntities[0].sortDirection == entitySortDirection.Reverse)
              point3D6 = new Point3D(buEntity6.EndPoint.X, buEntity6.EndPoint.Y, buEntity6.EndPoint.Z);
            double num = Math.Abs(point3D6.Y - pntLastMoved.Y);
            Point3D point3D7 = new Point3D(point3D6.X, point3D6.Y, point3D6.Z);
            buEntity buEntity7;
            if (num > buProfileCalc.varProfileSettings.EachLayerSafeDistance)
            {
              Point3D point3D8 = new Point3D(point3D6.X, calcDepth[indexDepth].TopPosition - buProfileCalc.varProfileSettings.EachLayerSafeDistance, point3D6.Z);
              buEntity buEntity8 = (buEntity) new buLine(pntLastMoved, point3D8);
              buEntity8.typeDefination = entityTypeDefination.CamPlungeFast;
              buEntity8.Orientation.A = 90.0;
              buEntity8.Info.CamID = IndexRepeat;
              OP.EntityMultiCam.Add(buEntity8);
              buEntity7 = (buEntity) new buLine(point3D8, point3D6);
            }
            else
              buEntity7 = (buEntity) new buLine(pntLastMoved, point3D6);
            pntLastMoved = buVector5.ToPoint3D(point3D6);
            buEntity7.Orientation.A = 90.0;
            buEntity7.typeDefination = entityTypeDefination.CamPlunge;
            buEntity7.Info.CamID = IndexRepeat;
            OP.EntityMultiCam.Add(buEntity7);
          }
          for (int index4 = 0; index4 <= refEntities.Count - 1; ++index4)
          {
            buEntity buEntity = buVector5.CopyEntities(refEntities[index4]);
            buEntity.Translate(point3D1.X + disMoveX, VecTranslate.Y, VecTranslate.Z + disMoveZ);
            buEntity.Translate(0.0, calcDepth[indexDepth].TopPosition + VecDepth.Y + disMoveY, VecDepth.Z);
            buEntity.Orientation.A = 90.0;
            buEntity.Info.CamID = IndexRepeat;
            OP.EntityMultiCam.Add(buEntity);
            pntLastMoved = buVector5.ToPoint3D(buEntity.EndPoint);
            if (buEntity.sortDirection == entitySortDirection.Reverse)
              pntLastMoved = buVector5.ToPoint3D(buEntity.StartPoint);
          }
          if (indexDepth == calcDepth.Count - 1)
          {
            Point3D end = new Point3D(pntLastMoved.X + vector3D.X, -OP.ProfileWidth + vector3D.Y, pntLastMoved.Z + vector3D.Z);
            buLine buLine = new buLine(pntLastMoved, end);
            buLine.typeDefination = entityTypeDefination.CamLeave;
            buLine.Orientation.A = 90.0;
            buLine.Info.CamID = IndexRepeat;
            OP.EntityMultiCam.Add((buEntity) buLine);
          }
        }
        if (OP.OperationData.selectedPlaneName == planeNames.Back && refEntities != null)
        {
          Vector3D vector3D = OP.OperationData.selectedPlane.AxisZ * -(OP.OperationData.CamParMilling.Distances.Safe + Math.Abs(VecDepth.Y));
          if (MoveSmallSafe)
            vector3D = OP.OperationData.selectedPlane.AxisZ * -(OP.OperationData.CamParMilling.Distances.Rapid + Math.Abs(VecDepth.Y));
          if (indexDepth == 0)
          {
            Point3D end = new Point3D(refEntities[0].StartPoint.X, calcDepth[indexDepth].TopPosition, refEntities[0].StartPoint.Z);
            if (refEntities[0].sortDirection == entitySortDirection.Reverse)
              end = new Point3D(refEntities[0].EndPoint.X, calcDepth[indexDepth].TopPosition, refEntities[0].EndPoint.Z);
            buLine refEnt = new buLine(new Point3D(end.X + vector3D.X, end.Y + vector3D.Y, end.Z + vector3D.Z), end);
            CustomData customData = new CustomData();
            refEnt.typeDefination = entityTypeDefination.CamPlunge;
            refEnt.Orientation.A = -90.0;
            buEntity buEntity = buVector5.CopyEntities((buEntity) refEnt);
            buEntity.Translate(point3D1.X + disMoveX, VecTranslate.Y, VecTranslate.Z + disMoveZ);
            buEntity.Translate(0.0, VecDepth.Y + disMoveY, VecDepth.Z);
            buEntity.Info.CamID = IndexRepeat;
            OP.EntityMultiCam.Add(buEntity);
          }
          else if (indexDepth > 0 & indexDepth <= calcDepth.Count - 1)
          {
            buEntity buEntity9 = buVector5.CopyEntities(refEntities[0]);
            buEntity9.Translate(point3D1.X + disMoveX, VecTranslate.Y, VecTranslate.Z + disMoveZ);
            buEntity9.Translate(0.0, calcDepth[indexDepth].BottomPosition + disMoveY, VecDepth.Z);
            Point3D point3D9 = new Point3D(buEntity9.StartPoint.X, buEntity9.StartPoint.Y, buEntity9.StartPoint.Z);
            if (refEntities[0].sortDirection == entitySortDirection.Reverse)
              point3D9 = new Point3D(buEntity9.EndPoint.X, buEntity9.EndPoint.Y, buEntity9.EndPoint.Z);
            double num = Math.Abs(point3D9.Y - pntLastMoved.Y);
            Point3D point3D10 = new Point3D(point3D9.X, point3D9.Y, point3D9.Z);
            buEntity buEntity10;
            if (num > buProfileCalc.varProfileSettings.EachLayerSafeDistance)
            {
              Point3D point3D11 = new Point3D(point3D9.X, calcDepth[indexDepth].TopPosition + buProfileCalc.varProfileSettings.EachLayerSafeDistance, point3D9.Z);
              buEntity buEntity11 = (buEntity) new buLine(pntLastMoved, point3D11);
              buEntity11.typeDefination = entityTypeDefination.CamPlungeFast;
              buEntity11.Orientation.A = -90.0;
              buEntity11.Info.CamID = IndexRepeat;
              OP.EntityMultiCam.Add(buEntity11);
              buEntity10 = (buEntity) new buLine(point3D11, point3D9);
            }
            else
              buEntity10 = (buEntity) new buLine(pntLastMoved, point3D9);
            pntLastMoved = buVector5.ToPoint3D(point3D9);
            buEntity10.Orientation.A = -90.0;
            buEntity10.typeDefination = entityTypeDefination.CamPlunge;
            buEntity10.Info.CamID = IndexRepeat;
            OP.EntityMultiCam.Add(buEntity10);
          }
          for (int index5 = 0; index5 <= refEntities.Count - 1; ++index5)
          {
            buEntity buEntity = buVector5.CopyEntities(refEntities[index5]);
            buEntity.Translate(point3D1.X + disMoveX, VecTranslate.Y, VecTranslate.Z + disMoveZ);
            buEntity.Translate(0.0, calcDepth[indexDepth].TopPosition + VecDepth.Y, VecDepth.Z);
            buEntity.Orientation.A = -90.0;
            buEntity.Info.CamID = IndexRepeat;
            OP.EntityMultiCam.Add(buEntity);
            pntLastMoved = buVector5.ToPoint3D(buEntity.EndPoint);
            if (buEntity.sortDirection == entitySortDirection.Reverse)
              pntLastMoved = buVector5.ToPoint3D(buEntity.StartPoint);
          }
          if (indexDepth == calcDepth.Count - 1)
          {
            Point3D end = new Point3D(pntLastMoved.X + vector3D.X, Profile.ProfileMaxPoint.Y + vector3D.Y, pntLastMoved.Z + vector3D.Z);
            buLine buLine = new buLine(pntLastMoved, end);
            buLine.typeDefination = entityTypeDefination.CamLeave;
            buLine.Orientation.A = -90.0;
            buLine.Info.CamID = IndexRepeat;
            OP.EntityMultiCam.Add((buEntity) buLine);
          }
        }
        if (OP.OperationData.selectedPlaneName == planeNames.Bottom && refEntities != null)
        {
          Vector3D vector3D = OP.OperationData.selectedPlane.AxisZ * -OP.OperationData.CamParMilling.Distances.Safe;
          if (MoveSmallSafe)
            vector3D = OP.OperationData.selectedPlane.AxisZ * -OP.OperationData.CamParMilling.Distances.Rapid;
          if (indexDepth == 0)
          {
            Point3D end = new Point3D(refEntities[0].StartPoint.X, refEntities[0].StartPoint.Y, calcDepth[indexDepth].TopPosition);
            if (refEntities[0].sortDirection == entitySortDirection.Reverse)
              end = new Point3D(refEntities[0].EndPoint.X, refEntities[0].EndPoint.Y, calcDepth[indexDepth].TopPosition);
            buLine refEnt = new buLine(new Point3D(end.X + vector3D.X, end.Y + vector3D.Y, end.Z + vector3D.Z), end);
            refEnt.typeDefination = entityTypeDefination.CamPlunge;
            buEntity buEntity = buVector5.CopyEntities((buEntity) refEnt);
            buEntity.Translate(point3D1.X + disMoveX, VecTranslate.Y, VecTranslate.Z + disMoveZ);
            buEntity.Translate(0.0, VecDepth.Y + disMoveY, VecDepth.Z);
            buEntity.Info.CamID = IndexRepeat;
            OP.EntityMultiCam.Add(buEntity);
          }
          else if (indexDepth > 0 & indexDepth <= calcDepth.Count - 1)
          {
            buEntity buEntity12 = buVector5.CopyEntities(refEntities[0]);
            buEntity12.Translate(point3D1.X + disMoveX, VecTranslate.Y, VecTranslate.Z + disMoveZ);
            buEntity12.Translate(0.0, VecDepth.Y + disMoveY, calcDepth[indexDepth].BottomPosition);
            Point3D point3D12 = new Point3D(buEntity12.StartPoint.X, buEntity12.StartPoint.Y, buEntity12.StartPoint.Z);
            if (refEntities[0].sortDirection == entitySortDirection.Reverse)
              point3D12 = new Point3D(buEntity12.EndPoint.X, buEntity12.EndPoint.Y, buEntity12.EndPoint.Z);
            double num = Math.Abs(point3D12.Z - pntLastMoved.Z);
            Point3D point3D13 = new Point3D(point3D12.X, point3D12.Y, point3D12.Z);
            buEntity buEntity13;
            if (num > buProfileCalc.varProfileSettings.EachLayerSafeDistance)
            {
              Point3D point3D14 = new Point3D(point3D12.X, point3D12.Y, calcDepth[indexDepth].TopPosition - buProfileCalc.varProfileSettings.EachLayerSafeDistance);
              buEntity buEntity14 = (buEntity) new buLine(pntLastMoved, point3D14);
              buEntity14.typeDefination = entityTypeDefination.CamPlungeFast;
              buEntity14.Orientation = new OrientationAngle(buEntity12.Orientation);
              buEntity14.Info.CamID = IndexRepeat;
              OP.EntityMultiCam.Add(buEntity14);
              buEntity13 = (buEntity) new buLine(point3D14, point3D12);
            }
            else
              buEntity13 = (buEntity) new buLine(pntLastMoved, point3D12);
            buEntity13.typeDefination = entityTypeDefination.CamPlunge;
            buEntity13.Info.CamID = IndexRepeat;
            OP.EntityMultiCam.Add(buEntity13);
            pntLastMoved = buVector5.ToPoint3D(point3D12);
          }
          for (int index6 = 0; index6 <= refEntities.Count - 1; ++index6)
          {
            buEntity buEntity = buVector5.CopyEntities(refEntities[index6]);
            buEntity.Translate(point3D1.X + disMoveX, VecTranslate.Y, VecTranslate.Z + disMoveZ);
            buEntity.Translate(0.0, VecDepth.Y + disMoveY, calcDepth[indexDepth].BottomPosition);
            buEntity.Info.CamID = IndexRepeat;
            OP.EntityMultiCam.Add(buEntity);
            pntLastMoved = buVector5.ToPoint3D(buEntity.EndPoint);
            if (buEntity.sortDirection == entitySortDirection.Reverse)
              pntLastMoved = buVector5.ToPoint3D(buEntity.StartPoint);
          }
          if (indexDepth == calcDepth.Count - 1)
          {
            Point3D end = new Point3D(pntLastMoved.X + vector3D.X, pntLastMoved.Y + vector3D.Y, Profile.ProfileMinPoint.Z + vector3D.Z);
            buLine buLine = new buLine(pntLastMoved, end);
            buLine.typeDefination = entityTypeDefination.CamLeave;
            buLine.Info.CamID = IndexRepeat;
            OP.EntityMultiCam.Add((buEntity) buLine);
          }
        }
      }
    }
    OP.CamCalculation = new List<camTp>();
