  public void NotchToCam(ref buEyeBaseVer5.Apps.ProfileOperation OP, buEyeBaseVer5.Apps.ProfileItem Profile, List<List<buEntity>> entCam)
  {
    if (entCam.Count == 0)
      return;
    OP.CamCalculation = new List<camTp>();
    for (int index1 = 0; index1 <= entCam.Count - 1; ++index1)
    {
      if (entCam[index1] != null)
      {
        for (int index2 = 0; index2 <= entCam[index1].Count - 1; ++index2)
        {
          buEntity buEntity = buVector5.CopyEntities(entCam[index1][index2]);
          OP.EntityMultiCam.Add(buEntity);
        }
        List<camTp> Cam = new List<camTp>();
        if (entCam.Count == 1)
        {
          clsInit.cCam5.camEntitiesToCamPoints(entCam[index1], OP.OperationData.CamParNotch, OP.ToolNotch, ref OP.CamCalculation);
          if ((OP.CamCalculation.Count <= 0 ? 0 : (OP.CamCalculation[0].CamPoints.Count > 0 ? 1 : 0)) != 0)
          {
            camTpPoint camPoint1 = OP.CamCalculation[0].CamPoints[0];
            camTpPoint camPoint2 = OP.CamCalculation[OP.CamCalculation.Count - 1].CamPoints[OP.CamCalculation[OP.CamCalculation.Count - 1].CamPoints.Count - 1];
            if (camPoint1.Points.Count > 0 && camPoint1.Points[0].P9.Z > Profile.Height)
              camPoint1.Points[0].IsSafePosition = true;
            if (camPoint2.Points.Count > 0 && camPoint2.Points[camPoint2.Points.Count - 1].P9.Z > Profile.Height)
              camPoint2.Points[camPoint2.Points.Count - 1].IsSafePosition = true;
          }
        }
        else
        {
          if (index1 == 0)
            clsInit.cCam5.camEntitiesToCamPoints(entCam[index1], OP.OperationData.CamParNotch, OP.ToolNotch, ref Cam);
          else
            clsInit.cCam5.camEntitiesToCamPoints(entCam[index1], OP.OperationData.CamParNotch, OP.Tool, ref Cam);
          if (Cam.Count > 0)
            OP.CamCalculation.Add(Cam[0]);
          if ((OP.CamCalculation.Count <= 0 ? 0 : (OP.CamCalculation[0].CamPoints.Count > 0 ? 1 : 0)) != 0)
          {
            camTpPoint camPoint3 = OP.CamCalculation[0].CamPoints[0];
            camTpPoint camPoint4 = OP.CamCalculation[OP.CamCalculation.Count - 1].CamPoints[OP.CamCalculation[OP.CamCalculation.Count - 1].CamPoints.Count - 1];
            if (camPoint3.Points.Count > 0 && camPoint3.Points[0].P9.Z > Profile.Height)
              camPoint3.Points[0].IsSafePosition = true;
            if (camPoint4.Points.Count > 0 && camPoint4.Points[camPoint4.Points.Count - 1].P9.Z > Profile.Height)
              camPoint4.Points[camPoint4.Points.Count - 1].IsSafePosition = true;
          }
        }
      }
    }
    if (OP.CamCalculation.Count <= 0)
      return;
    for (int index = 0; index <= OP.CamCalculation.Count - 1; ++index)
    {
      TpPnt9D tpPnt9D1 = new TpPnt9D(OP.CamCalculation[index].CamPoints[0].Points[0]);
      tpPnt9D1.EnableAxes.Z = false;
      TpPnt9D tpPnt9D2 = new TpPnt9D(OP.CamCalculation[index].CamPoints[0].Points[0]);
      OP.CamCalculation[index].CamPoints[0].Points[0] = tpPnt9D1;
      OP.CamCalculation[index].CamPoints[0].Points.Insert(1, tpPnt9D2);
    }
  }

  public void ClamperSetTrackValue()
  {
    buEyeBaseVer5.Apps.ProfileItem profileItem = clsInit.cProfile.SelectActiveProfile(this.activeProfile.FirstItem, this.activeProfile.SecondItem, ref buProfileCalc.varProfileRunSettings.activeProfileIndex);
    if (profileItem == null || !(clsInit.appProfile.SelectedClamperIndex >= 0 & clsInit.appProfile.SelectedClamperIndex <= profileItem.CalculationData[buProfileCalc.varProfileRunSettings.activeCalcDataIndex].calcOperations[buProfileCalc.varProfileRunSettings.activeOPIndex].Clampers.Count - 1))
      return;
    buEyeBaseVer5.Apps.ProfileClamper profileClamper1 = (buEyeBaseVer5.Apps.ProfileClamper) null;
    buEyeBaseVer5.Apps.ProfileClamper profileClamper2 = (buEyeBaseVer5.Apps.ProfileClamper) null;
    buEyeBaseVer5.Apps.ProfileClamper clamper = profileItem.CalculationData[buProfileCalc.varProfileRunSettings.activeCalcDataIndex].calcOperations[buProfileCalc.varProfileRunSettings.activeOPIndex].Clampers[clsInit.appProfile.SelectedClamperIndex];
    if (clsInit.appProfile.SelectedClamperIndex > 0)
      profileClamper1 = profileItem.CalculationData[buProfileCalc.varProfileRunSettings.activeCalcDataIndex].calcOperations[buProfileCalc.varProfileRunSettings.activeOPIndex].Clampers[clsInit.appProfile.SelectedClamperIndex - 1];
    if (clsInit.appProfile.SelectedClamperIndex < clsInit.appProfile.Clampers.Count - 1)
      profileClamper2 = profileItem.CalculationData[buProfileCalc.varProfileRunSettings.activeCalcDataIndex].calcOperations[buProfileCalc.varProfileRunSettings.activeOPIndex].Clampers[clsInit.appProfile.SelectedClamperIndex + 1];
    double num1 = profileClamper1 == null ? clsInit.appProfile.Clampers[clsInit.appProfile.SelectedClamperIndex].MinPositionRange : profileClamper1.XPosition + buProfileCalc.varProfileClamperSettings.ClamperWidth + buProfileCalc.varProfileClamperSettings.ClamperSafeDistance;
    double num2 = profileClamper2 == null ? clsInit.appProfile.Clampers[clsInit.appProfile.SelectedClamperIndex].MaxPositionRange : profileClamper2.XPosition - buProfileCalc.varProfileClamperSettings.ClamperWidth - buProfileCalc.varProfileClamperSettings.ClamperSafeDistance;
    this.frmSim.track_clamper.MinimumValue = num1;
    this.frmSim.track_clamper.MaximumValue = num2;
    this.frmSim.track_clamper.Value = clamper.XPosition;
    if (this.ClamperUpdating)
      return;
    clsInit.appProfile.ClamperUpdate(false);
    clsInit.appProfile.DrawSimulationEntities(clsInit.appProfile.activeProfile.FirstItem, clsInit.appProfile.activeProfile.SecondItem, buProfileCalc.varProfileRunSettings.activeOPIndex, new List<buEyeBaseVer5.Apps.ProfileClamper>());
  }

  public void ClamperUpdate(bool ClearList)
  {
    buEyeBaseVer5.Apps.ProfileItem profileItem = clsInit.cProfile.SelectActiveProfile(this.activeProfile.FirstItem, this.activeProfile.SecondItem, ref buProfileCalc.varProfileRunSettings.activeProfileIndex);
    if (profileItem == null)
      return;
    this.ClamperUpdating = true;
    if (buProfileCalc.varProfileRunSettings.activeProfileIndex == 0)
    {
      if (ClearList)
      {
        this.frmSim.dgv_clamper.Rows.Clear();
        if (profileItem.CalculationData[buProfileCalc.varProfileRunSettings.activeCalcDataIndex].calcOperations.Count > 0)
        {
          int clamperIndex = profileItem.CalculationData[buProfileCalc.varProfileRunSettings.activeCalcDataIndex].calcOperations[buProfileCalc.varProfileRunSettings.activeOPIndex].ClamperIndex;
          if (clamperIndex >= 0 & clamperIndex <= profileItem.CalculationData[buProfileCalc.varProfileRunSettings.activeCalcDataIndex].ClamperLists.Count - 1)
            profileItem.CalculationData[buProfileCalc.varProfileRunSettings.activeCalcDataIndex].ClamperLists[clamperIndex].Clear();
          for (int index = 0; index <= profileItem.CalculationData[buProfileCalc.varProfileRunSettings.activeCalcDataIndex].calcOperations[buProfileCalc.varProfileRunSettings.activeOPIndex].Clampers.Count - 1; ++index)
          {
            this.frmSim.dgv_clamper.Rows.Add((object) (index + 1).ToString(), (object) ("X: " + profileItem.CalculationData[buProfileCalc.varProfileRunSettings.activeCalcDataIndex].calcOperations[buProfileCalc.varProfileRunSettings.activeOPIndex].Clampers[index].XPosition.ToString("f2")));
            this.frmSim.dgv_clamper.Rows[this.frmSim.dgv_clamper.Rows.Count - 1].Height = 34;
            profileItem.CalculationData[buProfileCalc.varProfileRunSettings.activeCalcDataIndex].ClamperLists[clamperIndex].Add(new buEyeBaseVer5.Apps.ProfileClamper(profileItem.CalculationData[buProfileCalc.varProfileRunSettings.activeCalcDataIndex].calcOperations[buProfileCalc.varProfileRunSettings.activeOPIndex].Clampers[index]));
          }
        }
      }
      if (profileItem.CalculationData[buProfileCalc.varProfileRunSettings.activeCalcDataIndex].calcOperations.Count == 0)
      {
        this.ClamperUpdating = false;
        return;
      }
      for (int index = 0; index <= profileItem.CalculationData[buProfileCalc.varProfileRunSettings.activeCalcDataIndex].calcOperations[buProfileCalc.varProfileRunSettings.activeOPIndex].Clampers.Count - 1; ++index)
      {
        if (!ClearList && index <= this.frmSim.dgv_clamper.Rows.Count - 1)
          this.frmSim.dgv_clamper.Rows[index].Cells[1].Value = (object) ("X: " + profileItem.CalculationData[buProfileCalc.varProfileRunSettings.activeCalcDataIndex].calcOperations[buProfileCalc.varProfileRunSettings.activeOPIndex].Clampers[index].XPosition.ToString("f2"));
      }
    }
    if (buProfileCalc.varProfileRunSettings.activeProfileIndex == 1)
    {
      if (ClearList)
      {
        this.frmSim.dgv_clamper.Rows.Clear();
        if (profileItem.CalculationData[buProfileCalc.varProfileRunSettings.activeCalcDataIndex].calcOperations.Count > 0)
        {
          int clamperIndex = profileItem.CalculationData[buProfileCalc.varProfileRunSettings.activeCalcDataIndex].calcOperations[buProfileCalc.varProfileRunSettings.activeOPIndex].ClamperIndex;
          if (clamperIndex >= 0 & clamperIndex <= profileItem.CalculationData[buProfileCalc.varProfileRunSettings.activeCalcDataIndex].ClamperLists.Count - 1)
            profileItem.CalculationData[buProfileCalc.varProfileRunSettings.activeCalcDataIndex].ClamperLists[clamperIndex].Clear();
          for (int index = 0; index <= profileItem.CalculationData[buProfileCalc.varProfileRunSettings.activeCalcDataIndex].calcOperations[buProfileCalc.varProfileRunSettings.activeOPIndex].Clampers.Count - 1; ++index)
          {
            this.frmSim.dgv_clamper.Rows.Add((object) (index + 1).ToString(), (object) ("X: " + profileItem.CalculationData[buProfileCalc.varProfileRunSettings.activeCalcDataIndex].calcOperations[buProfileCalc.varProfileRunSettings.activeOPIndex].Clampers[index].XPosition.ToString("f2")));
            this.frmSim.dgv_clamper.Rows[this.frmSim.dgv_clamper.Rows.Count - 1].Height = 34;
            profileItem.CalculationData[buProfileCalc.varProfileRunSettings.activeCalcDataIndex].ClamperLists[clamperIndex].Add(new buEyeBaseVer5.Apps.ProfileClamper(profileItem.CalculationData[buProfileCalc.varProfileRunSettings.activeCalcDataIndex].calcOperations[buProfileCalc.varProfileRunSettings.activeOPIndex].Clampers[index]));
          }
        }
      }
      if (profileItem.CalculationData[buProfileCalc.varProfileRunSettings.activeCalcDataIndex].calcOperations.Count == 0)
        return;
      for (int index = 0; index <= profileItem.CalculationData[buProfileCalc.varProfileRunSettings.activeCalcDataIndex].calcOperations[buProfileCalc.varProfileRunSettings.activeOPIndex].Clampers.Count - 1; ++index)
      {
        if (!ClearList && index <= this.frmSim.dgv_clamper.Rows.Count - 1)
          this.frmSim.dgv_clamper.Rows[index].Cells[1].Value = (object) ("X: " + profileItem.CalculationData[buProfileCalc.varProfileRunSettings.activeCalcDataIndex].calcOperations[buProfileCalc.varProfileRunSettings.activeOPIndex].Clampers[index].XPosition.ToString("f2"));
      }
    }
    for (int index = 0; index <= this.frmSim.dgv_clamper.Rows.Count - 1; ++index)
    {
      this.frmSim.dgv_clamper.Rows[index].DefaultCellStyle.BackColor = Color.WhiteSmoke;
      if (clsInit.appProfile.SelectedClamperIndex == index)
        this.frmSim.dgv_clamper.Rows[index].DefaultCellStyle.BackColor = Color.LightSteelBlue;
    }
    this.ClamperSetTrackValue();
    this.frmSim.SelectClamperGrid(clsInit.appProfile.SelectedClamperIndex);
    this.ClamperUpdating = false;
  }

  public void ClamperMoveBwdFwd(double Value)
  {
    buEyeBaseVer5.Apps.ProfileItem profileItem = clsInit.cProfile.SelectActiveProfile(this.activeProfile.FirstItem, this.activeProfile.SecondItem, ref buProfileCalc.varProfileRunSettings.activeProfileIndex);
    if (profileItem == null)
      return;
    double num1 = buProfileCalc.varProfileClamperSettings.ClamperWidth + buProfileCalc.varProfileClamperSettings.ClamperSafeDistance;
    if (!(this.SelectedClamperIndex >= 0 & this.SelectedClamperIndex <= profileItem.CalculationData[buProfileCalc.varProfileRunSettings.activeCalcDataIndex].calcOperations[buProfileCalc.varProfileRunSettings.activeOPIndex].Clampers.Count - 1))
      return;
    int selectedClamperIndex = this.SelectedClamperIndex;
    buEyeBaseVer5.Apps.ProfileClamper.Copy(profileItem.CalculationData[buProfileCalc.varProfileRunSettings.activeCalcDataIndex].calcOperations[buProfileCalc.varProfileRunSettings.activeOPIndex].Clampers, ref clsInit.appProfile.ClampersOldPosBeforeMove);
    if (Value > 0.0)
    {
      double xposition = profileItem.CalculationData[buProfileCalc.varProfileRunSettings.activeCalcDataIndex].calcOperations[buProfileCalc.varProfileRunSettings.activeOPIndex].Clampers[this.SelectedClamperIndex].XPosition;
      double num2 = 1000000.0;
      if (this.SelectedClamperIndex < profileItem.CalculationData[buProfileCalc.varProfileRunSettings.activeCalcDataIndex].calcOperations[buProfileCalc.varProfileRunSettings.activeOPIndex].Clampers.Count - 1)
        num2 = profileItem.CalculationData[buProfileCalc.varProfileRunSettings.activeCalcDataIndex].calcOperations[buProfileCalc.varProfileRunSettings.activeOPIndex].Clampers[this.SelectedClamperIndex + 1].XPosition;
      if (num2 - (xposition + Value) > num1 && xposition + Value < this.Clampers[this.SelectedClamperIndex].MaxPositionRange)
        profileItem.CalculationData[buProfileCalc.varProfileRunSettings.activeCalcDataIndex].calcOperations[buProfileCalc.varProfileRunSettings.activeOPIndex].Clampers[this.SelectedClamperIndex].XPosition += Value;
    }
    else if (Value < 0.0)
    {
      double xposition = profileItem.CalculationData[buProfileCalc.varProfileRunSettings.activeCalcDataIndex].calcOperations[buProfileCalc.varProfileRunSettings.activeOPIndex].Clampers[this.SelectedClamperIndex].XPosition;
      double num3 = -1000000.0;
      if (this.SelectedClamperIndex > 0)
        num3 = profileItem.CalculationData[buProfileCalc.varProfileRunSettings.activeCalcDataIndex].calcOperations[buProfileCalc.varProfileRunSettings.activeOPIndex].Clampers[this.SelectedClamperIndex - 1].XPosition;
      if (xposition + Value - num3 > num1 && xposition + Value > this.Clampers[this.SelectedClamperIndex].MinPositionRange)
        profileItem.CalculationData[buProfileCalc.varProfileRunSettings.activeCalcDataIndex].calcOperations[buProfileCalc.varProfileRunSettings.activeOPIndex].Clampers[this.SelectedClamperIndex].XPosition += Value;
    }
    this.ClamperSetUpdate(profileItem.CalculationData[buProfileCalc.varProfileRunSettings.activeCalcDataIndex].calcOperations[buProfileCalc.varProfileRunSettings.activeOPIndex].ClamperIndex, profileItem.CalculationData[buProfileCalc.varProfileRunSettings.activeCalcDataIndex].calcOperations[buProfileCalc.varProfileRunSettings.activeOPIndex].Clampers);
    this.ClamperUpdate(true);
    if (profileItem != null)
      this.BasicCollsionControl(ref profileItem);
    this.DrawSimulationEntities(this.activeProfile.FirstItem, this.activeProfile.SecondItem, buProfileCalc.varProfileRunSettings.activeOPIndex, new List<buEyeBaseVer5.Apps.ProfileClamper>());
    this.SelectedClamperIndex = selectedClamperIndex;
  }

  public void ClamperEdit()
  {
    buEyeBaseVer5.Apps.ProfileItem curItem = clsInit.cProfile.SelectActiveProfile(this.activeProfile.FirstItem, this.activeProfile.SecondItem, ref buProfileCalc.varProfileRunSettings.activeProfileIndex);
    if (curItem == null || !(this.SelectedClamperIndex >= 0 & this.SelectedClamperIndex <= curItem.CalculationData[buProfileCalc.varProfileRunSettings.activeCalcDataIndex].calcOperations[buProfileCalc.varProfileRunSettings.activeOPIndex].Clampers.Count - 1))
      return;
    DialogBoxInput dialogBoxInput = new DialogBoxInput();
    dialogBoxInput.FormCaption = "Clamper";
    dialogBoxInput.ValueCaption = "X Position";
    double num1 = Convert.ToDouble(curItem.CalculationData[buProfileCalc.varProfileRunSettings.activeCalcDataIndex].calcOperations[buProfileCalc.varProfileRunSettings.activeOPIndex].Clampers[this.SelectedClamperIndex].XPosition);
    dialogBoxInput.Value = num1;
    dialogBoxInput.Init();
    dialogBoxInput.StartPosition = FormStartPosition.CenterParent;
    int num2 = (int) dialogBoxInput.ShowDialog();
    if (dialogBoxInput.Result != DialogResult.OK)
      return;
    ProfileItemCalc CalcData = curItem.CalculationData[buProfileCalc.varProfileRunSettings.activeCalcDataIndex];
    if (this.frmSim != null)
      this.frmSim.dgv_clamper.Rows[this.SelectedClamperIndex].Cells[1].Value = (object) ("X: " + dialogBoxInput.Value.ToString("f2"));
    this.ClamperMove(dialogBoxInput.Value - num1, this.SelectedClamperIndex, ref curItem, ref CalcData, true);
  }

  public void ClamperMove(
    double dX,
    int ClampIndex,
    ref buEyeBaseVer5.Apps.ProfileItem curItem,
    ref ProfileItemCalc CalcData,
    bool ClamperListUpdate)
  {
    int index = ClampIndex;
    if (buProfileCalc.varProfileRunSettings.activeProfileIndex == 0)
    {
      double num1 = curItem.Length;
      double num2 = 0.0;
      if (!buProfileCalc.varProfileSettings.ClamperCanMoveInsideProfileLength)
        num1 = buProfileCalc.varProfileSettings.MachineLength;
      if (CalcData.calcOperations[buProfileCalc.varProfileRunSettings.activeOPIndex].Clampers[index].XPosition + dX > num1)
        dX = num1 - CalcData.calcOperations[buProfileCalc.varProfileRunSettings.activeOPIndex].Clampers[index].XPosition;
      if (CalcData.calcOperations[buProfileCalc.varProfileRunSettings.activeOPIndex].Clampers[index].XPosition + dX < num2)
        dX = num2 - CalcData.calcOperations[buProfileCalc.varProfileRunSettings.activeOPIndex].Clampers[index].XPosition;
      if (CalcData.calcOperations[buProfileCalc.varProfileRunSettings.activeOPIndex].Clampers[index].XPosition + dX <= num1 && CalcData.calcOperations[buProfileCalc.varProfileRunSettings.activeOPIndex].Clampers[index].XPosition + dX >= num2)
      {
        bool flag = true;
        buEyeBaseVer5.Apps.ProfileClamper.Copy(CalcData.calcOperations[buProfileCalc.varProfileRunSettings.activeOPIndex].Clampers, ref clsInit.appProfile.ClampersOldPosBeforeMove);
        double num3 = curItem.CalculationData[buProfileCalc.varProfileRunSettings.activeCalcDataIndex].calcOperations[buProfileCalc.varProfileRunSettings.activeOPIndex].Clampers[index].XPosition + dX;
        List<buEyeBaseVer5.Apps.ProfileClamper> clampers = curItem.CalculationData[buProfileCalc.varProfileRunSettings.activeCalcDataIndex].calcOperations[buProfileCalc.varProfileRunSettings.activeOPIndex].Clampers;
        if (index == 0)
        {
          if (clampers.Count >= 1)
          {
            double xposition = clampers[index + 1].XPosition;
            if (num3 > xposition - buProfileCalc.varProfileClamperSettings.ClamperWidth - buProfileCalc.varProfileClamperSettings.ClamperSafeDistance)
            {
              if (!buProfileCalc.varProfileClamperSettings.IfClamperOverOrCloseToAnotherOneMovetoLimit)
                flag = false;
              else
                num3 = xposition - buProfileCalc.varProfileClamperSettings.ClamperWidth - buProfileCalc.varProfileClamperSettings.ClamperSafeDistance;
            }
          }
        }
        else if (index == clampers.Count - 1)
        {
          if (clampers.Count > 0)
          {
            double xposition = clampers[index - 1].XPosition;
            if (num3 < xposition + buProfileCalc.varProfileClamperSettings.ClamperWidth + buProfileCalc.varProfileClamperSettings.ClamperSafeDistance)
            {
              if (!buProfileCalc.varProfileClamperSettings.IfClamperOverOrCloseToAnotherOneMovetoLimit)
                flag = false;
              else
                num3 = xposition + buProfileCalc.varProfileClamperSettings.ClamperWidth + buProfileCalc.varProfileClamperSettings.ClamperSafeDistance;
            }
          }
        }
        else
        {
          double xposition1 = clampers[index + 1].XPosition;
          double xposition2 = clampers[index - 1].XPosition;
          if (num3 > xposition1 - buProfileCalc.varProfileClamperSettings.ClamperWidth - buProfileCalc.varProfileClamperSettings.ClamperSafeDistance)
          {
            if (!buProfileCalc.varProfileClamperSettings.IfClamperOverOrCloseToAnotherOneMovetoLimit)
              flag = false;
            else
              num3 = xposition1 - buProfileCalc.varProfileClamperSettings.ClamperWidth - buProfileCalc.varProfileClamperSettings.ClamperSafeDistance;
          }
          if (num3 < xposition2 + buProfileCalc.varProfileClamperSettings.ClamperWidth + buProfileCalc.varProfileClamperSettings.ClamperSafeDistance)
          {
            if (!buProfileCalc.varProfileClamperSettings.IfClamperOverOrCloseToAnotherOneMovetoLimit)
              flag = false;
            else
              num3 = xposition2 + buProfileCalc.varProfileClamperSettings.ClamperWidth + buProfileCalc.varProfileClamperSettings.ClamperSafeDistance;
          }
        }
        if (flag)
