        if (index1 == -1)
          index1 = index2;
        if (refOP.SizePoint.MinPoint.X > OPList[index2].SizePoint.MinPoint.X)
        {
          if (index2 == 0)
            OPList.Insert(0, refOP);
          else if (index2 == OPList.Count - 1)
            OPList.Add(refOP);
          else
            OPList.Insert(index2, refOP);
          flag = true;
          index2 = OPList.Count;
        }
      }
      else if (!flag && index1 >= 0)
      {
        OPList.Insert(index1, refOP);
        flag = true;
        index2 = OPList.Count;
      }
    }
    if (!flag && index1 >= 0)
    {
      OPList.Insert(index1, refOP);
      flag = true;
    }
    if (flag)
      return;
    OPList.Insert(0, refOP);
  }

