  public bool CheckClamper(
    ref buEyeBaseVer5.Apps.ProfileClamper Clamper,
    double X,
    List<buEyeBaseVer5.Apps.ProfileClamper> ClamperList,
    int MaxClamper,
    int ExceptionClampedIndex)
  {
    string str = nameof (CheckClamper);
    try
    {
      if (X < 0.0)
        return false;
      Clamper = new buEyeBaseVer5.Apps.ProfileClamper();
      Clamper.Width = buProfileCalc.varProfileClamperSettings.ClamperWidth;
      Clamper.XPosition = X;
      Clamper.Used = true;
      Clamper.Enable = true;
      Clamper.GeometrixMaxX = Clamper.XPosition + buProfileCalc.varProfileClamperSettings.ClamperWidth / 2.0;
      Clamper.GeometrixMinX = Clamper.XPosition - buProfileCalc.varProfileClamperSettings.ClamperWidth / 2.0;
      bool flag1 = false;
      bool flag2 = false;
      for (int index = 0; index <= ClamperList.Count - 1; ++index)
      {
        bool flag3 = buNumeric5.IsValueInsideMinMaxValues(Clamper.GeometrixMinX, ClamperList[index].GeometrixMinX, ClamperList[index].GeometrixMaxX);
        bool flag4 = buNumeric5.IsValueInsideMinMaxValues(Clamper.GeometrixMaxX, ClamperList[index].GeometrixMinX, ClamperList[index].GeometrixMaxX);
        if (ExceptionClampedIndex < 0 | index != ExceptionClampedIndex)
        {
          flag1 |= flag3;
          flag2 |= flag4;
        }
        if (Clamper.XPosition <= ClamperList[index].XPosition)
          return false;
      }
      if (!(!flag1 & !flag2))
        return false;
      int count = ClamperList.Count;
      return ClamperList.Count <= MaxClamper - 1 && this.Clampers[count].MinPositionRange <= X & X <= this.Clampers[count].MaxPositionRange;
    }
    catch (Exception ex)
    {
      buLogVer5.addToLog(this.string_1, str, "Error", "", 0.0, 0.0, true);
      buException.throwException(ex, str, true, "");
      return false;
    }
  }

