              if (Data2_1.Parameters.Priority > 0)
                profileOperation.Priority = Data2_1.Parameters.Priority;
              if (this.OPPriority > 0)
                profileOperation.Priority = this.OPPriority;
              profileOperation.Locked = this.ToolChangeForced;
              profileOperation.ParentXReferance = profileItem.XReferanceLocation;
              if (ProfileTempVars.OperationEditing & this.operationEditIndex >= 0)
                profileOperation.Name = profileItem.Operations[this.operationEditIndex].Name;
              if (profileOperation.OperationData.OperationType == ProfileOperationTypes.Notch)
              {
                if (buProfileCalc.varProfileRunSettings.ShapeDataParameters.CamPars.Speeds.SpindleEnable)
                  profileOperation.ToolNotch.CamData.SpindleSpeed = buProfileCalc.varProfileRunSettings.ShapeDataParameters.CamPars.Speeds.SpindleSpeed;
                if (profileOperation.ToolNotch.CamData.SpindleSpeed > buProfileCalc.varProfileSettings.NotchMaxSpeed & buProfileCalc.varProfileSettings.NotchMaxSpeed > 0.0)
                  profileOperation.ToolNotch.CamData.SpindleSpeed = buProfileCalc.varProfileSettings.NotchMaxSpeed;
                if (buProfileCalc.varProfileSettings.NotchToolNo > 0)
                  profileOperation.ToolNotch.Data.No = buProfileCalc.varProfileSettings.NotchToolNo;
                if (profileOperation.Tool.CamData.SpindleSpeed < buProfileCalc.varProfileSettings.NotchMinSpeed)
                  clsInit.cProfile.AddErrorToOperation(this.ShowErrorOPMessage(buLangTranslate.preSentences.SpindleSpeedLowerThenMinLimit), ref profileOperation);
              }
              else if (profileOperation.Tool != null)
              {
                if (!Data2_1.OpenFile)
                {
                  this.toolBase5_0 = new ToolBase5(profileOperation.Tool);
                  buProfileCalc.varProfileRunSettings.lastToolName = this.toolBase5_0.Data.Name;
                }
                profileOperation.Tool.CamData.SpindleSpeed = buProfileCalc.varProfileRunSettings.ShapeDataParameters.CamPars.Speeds.SpindleSpeed;
                profileOperation.Tool.CamData.FeedSpeed = buProfileCalc.varProfileRunSettings.ShapeDataParameters.CamPars.Speeds.Feed;
                profileOperation.Tool.CamData.PlungeSpeed = buProfileCalc.varProfileRunSettings.ShapeDataParameters.CamPars.Speeds.Plunge;
                profileOperation.Tool.CamData.FinishSpeed = buProfileCalc.varProfileRunSettings.ShapeDataParameters.CamPars.Speeds.Finish;
                profileOperation.Tool.CamData.AreaClearanceSpeed = buProfileCalc.varProfileRunSettings.ShapeDataParameters.CamPars.Speeds.AreaClearance;
                if (profileOperation.Tool.CamData.SpindleSpeed < buProfileCalc.varProfileSettings.MinSpindleSpeed)
                  clsInit.cProfile.AddErrorToOperation(this.ShowErrorOPMessage(buLangTranslate.preSentences.SpindleSpeedLowerThenMinLimit), ref profileOperation);
              }
              if ((profileOperation.Tool == null ? 0 : (profileOperation.Tool.CamData.SpindleSpeed <= 0.1 ? 1 : 0)) != 0)
                clsInit.cProfile.AddErrorToOperation(this.ShowErrorOPMessage(buLangTranslate.preSentences.SpindleSpeedIsZero), ref profileOperation);
              ++this.counterProfileOP;
              profileOperation.ID = this.IDCounter.ToString();
              for (int index = 0; index <= Data2_1.CommandList.Count - 1; ++index)
              {
                if (Data2_1.CommandList[index].Trim() == "ForceDisable")
                  profileOperation.Enable = false;
              }
              if (profileOperation.CamCalculation.Count == 0)
                clsInit.cProfile.AddErrorToOperation(AppLanguage.CadCamError[6], ref profileOperation);
              else if (profileOperation.CamCalculation[0].CamPoints.Count == 0)
                clsInit.cProfile.AddErrorToOperation(AppLanguage.CadCamError[6], ref profileOperation);
              else if (profileOperation.CamCalculation[0].CamPoints[0].Points.Count == 0)
                clsInit.cProfile.AddErrorToOperation(AppLanguage.CadCamError[6], ref profileOperation);
              ++this.IDCounter;
              this.OPPriority = 0;
              buProfileCalc.varProfileRunSettings.ShapeDataParameters.Priority = 0;
              if (!profileOnlineOpOptions.OnlyDrawing & !this.JobOpening)
                this.bUndoBuffer = true;
              profileOperation.ProfileName = profileItem.ItemName;
              this.ResetCalculationFlags(false, false, false, false);
              this.CreateOperationEntity(profileOperation, profileItem.Operations.Count);
              if (!profileOnlineOpOptions.OnlyDrawing)
              {
                if (Action == actionTypeBU.profileNotch)
                  clsInit.cProfile.CamParameterToProfileCamData(profileOperation.OperationData.CamParNotch, ref profileOperation.CamOPData);
                else
                  clsInit.cProfile.CamParameterToProfileCamData(profileOperation.OperationData.CamParMilling, ref profileOperation.CamOPData);
              }
              if (this.operationEditIndex >= 0 & profileItem.Operations.Count - 1 < this.operationEditIndex)
                this.operationEditIndex = -1;
              if (this.operationEditIndex == -1)
              {
                if (buProfileCalc.varProfileRunSettings.activeProfileIndex == 0)
                  clsInit.cProfile.AddOperationToProfileOperationList(ref this.activeProfile.FirstItem, profileOperation, buProfileCalc.varProfileSettings.InsertOperationIfSamePositionAndSmallSize);
                if (buProfileCalc.varProfileRunSettings.activeProfileIndex == 1)
                  clsInit.cProfile.AddOperationToProfileOperationList(ref this.activeProfile.SecondItem, profileOperation, buProfileCalc.varProfileSettings.InsertOperationIfSamePositionAndSmallSize);
                if (buProfileCalc.varProfileRunSettings.activeProfileIndex == -1)
                  buProfileCalc.varProfileRunSettings.activeProfileIndex = 0;
              }
              else
              {
                buEyeBaseVer5.Apps.ProfileOperation CopiedOperation = new buEyeBaseVer5.Apps.ProfileOperation();
                buEyeBaseVer5.Apps.ProfileOperation.Copy(profileOperation, ref CopiedOperation);
                profileItem.Operations[this.operationEditIndex] = CopiedOperation;
                if (!ProfileTempVars.MultiOperationStarted)
                {
                  this.operationEditIndex = -1;
                  this.DrawActiveProfile();
                }
              }
              int activeProfileIndex = buProfileCalc.varProfileRunSettings.activeProfileIndex;
              if (!profileOnlineOpOptions.OnlyDrawing & !this.JobOpening & !Data2_1.DontUpdateTree)
                this.ProfileTreeUpdate();
              if (ProfileTempVars.OperationEditing)
              {
                if (this.FrmOperationList != null && this.FrmOperationList.Visible)
                  this.FrmOperationList.Visible = false;
                if (this.FrmNotchList != null && this.FrmNotchList.Visible)
                  this.FrmNotchList.Visible = false;
              }
              if (!this.JobOpening)
                this.SaveByTick = true;
              if (activeProfileIndex >= 0 & !Data2_1.OpenFile)
                clsItem.FrmProfileJob.tree_jobs.SelectedNode = clsItem.FrmProfileJob.tree_jobs.Nodes[0].Nodes[activeProfileIndex];
              if (ProfileTempVars.OperationEditing && !ProfileTempVars.MultiOperationStarted)
              {
                if ((this.activeOP == null ? 0 : (this.activeOP.OperationData.OperationType == ProfileOperationTypes.FreeDraw ? 1 : 0)) != 0)
                  this.OperationDataCancel();
                else if (!buProfileCalc.varProfileSettings.OperationEditChangeWithoutOk)
                  this.OperationDataCancel();
                else
                  this.doEditOperation(buProfileCalc.varProfileRunSettings.activeProfileIndex, buProfileCalc.varProfileRunSettings.activeOPName);
              }
            }
            if ((profileOnlineOpOptions == null ? 0 : (!profileOnlineOpOptions.OnlyDrawing & !this.JobOpening ? 1 : 0)) != 0)
            {
              this.doCheckProfileWarnings(ref profileItem);
              this.DrawPreview(TempEntities);
            }
          }
          if (!Data2_1.OpenFile)
            ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Invalidate();
          AppBool.Started = false;
        }
      }
    }
  }

