  public void DrawDimEntity(
    buEyeBaseVer5.Apps.ProfileOperation OP,
    buEyeBaseVer5.Apps.ProfileItem curItem,
    ShapeDataValueType ValueType,
    Point3D CornerPoint)
  {
    if (OP == null)
      return;
    Design design = OP.OperationData.Action == actionTypeBU.profileNotch ? this.FrmNotchList.viewportLayout : this.FrmOperationList.viewportLayout;
    for (int index = design.Entities.Count - 1; index >= 0; --index)
    {
      if ((design.Entities[index].EntityData == null ? 0 : (design.Entities[index].EntityData is CustomData ? 1 : 0)) != 0 && (design.Entities[index].EntityData as CustomData).typeDefination == entityTypeDefination.Operation)
        design.Entities[index].Selected = true;
      if (design.Entities[index] is Dimension)
        design.Entities.RemoveAt(index);
    }
    Entity dimEntity = (Entity) null;
    viewType ViewType = viewType.Top;
    Plane selectedPlane = OP.OperationData.selectedPlane;
    MaterialBase5 Material = new MaterialBase5(new SizeObject(curItem.Length, curItem.Width, curItem.Height));
    clsInit.cProfile.CreateDimensionEntity(OP, curItem, ValueType, Material, CornerPoint, ref dimEntity, ref ViewType, ref selectedPlane);
    if (dimEntity != null)
    {
      dimEntity.Selected = true;
      design.Entities.Add(dimEntity);
    }
    if (OP.OperationData.selectedPlaneName != planeNames.Free)
      design.SetView(ViewType);
    else
      design.SetView((Vector3D) selectedPlane.Equation, true);
    design.ZoomFit(true);
    design.ZoomOut(10);
    design.Entities.ClearSelection();
    design.Invalidate();
  }

  public bool doCalculateAll(
    ref buEyeBaseVer5.Apps.ProfileItem Item,
    bool Clamper,
    bool Cam,
    bool GCodeToSim,
    bool JustCam = false)
  {
    bool flag1 = false;
    bool flag2 = false;
    if (!JustCam)
    {
      if ((this.activeProfile.FirstItem == null || !this.activeProfile.FirstItem.Enable ? 0 : (this.activeProfile.FirstItem.Operations.Count > 0 ? 1 : 0)) != 0)
        flag1 = true;
      if ((this.activeProfile.SecondItem == null || !this.activeProfile.SecondItem.Enable ? 0 : (this.activeProfile.SecondItem.Operations.Count > 0 ? 1 : 0)) != 0)
        flag2 = true;
      if (flag1 & flag2)
        buProfileCalc.varTemps.JobItemType = ProfileJobType.Both;
      else if (flag1 & !flag2)
        buProfileCalc.varTemps.JobItemType = ProfileJobType.Left;
      else if (!flag1 & flag2)
        buProfileCalc.varTemps.JobItemType = ProfileJobType.Right;
      int cntProfile = 0;
      clsInit.cProfile.TotalWidthOfProfile(ref Item, ref cntProfile);
      Item.isCollisionOnlineAvailable = false;
      Item.isCollisionOfflineAvailable = false;
    }
    bool all;
    if (Item.Operations.Count > 0)
    {
      buEyeBaseVer5.Apps.ProfileItem Profile = Item;
      if (!JustCam)
      {
        if (Profile.Length > buProfileCalc.varProfileSettings.MachineLength && this.activeProfile.SecondItem != null)
        {
          buString5.MessageBoxWarning(buProfile.LangProfileMessage[39]);
          all = false;
          goto label_61;
        }
        buProfileCalc.varProfileRunSettings.activeCalcDataIndex = 0;
        if (Clamper)
        {
          Profile.CalculationData.Clear();
          if (Profile.Length > buProfileCalc.varProfileSettings.MachineLength)
          {
            bool flag3 = clsInit.cProfile.isAllOperationInsideXLimit(Profile, buProfileCalc.varProfileSettings.MachineLength - 0.0);
            clsInit.cProfile.isBottomOperationAvailable(Profile);
            if (flag3)
            {
              this.doDevideProfileItemByLength(Profile, buProfileCalc.varProfileSettings.MachineLength - 0.0, ref Profile.CalculationData);
            }
            else
            {
              Profile.CalculationData.Clear();
              Profile.CalculationData.Add(new ProfileItemCalc(Profile, true)
              {
                CalcType = ProfileExcType.Normal,
                Length = buProfileCalc.varProfileSettings.MachineLength
              });
            }
          }
          else if (clsInit.cProfile.isBottomOperationAvailable(Profile))
          {
            this.doGetBottomOperations(Profile, ref Profile.CalculationData);
          }
          else
          {
            Profile.CalculationData.Clear();
            Profile.CalculationData.Add(new ProfileItemCalc(Profile, true)
            {
              CalcType = ProfileExcType.Normal
            });
          }
        }
        bool flag4 = buProfileCalc.varProfileSettings.CalculateClamperEveryTime;
        if (!Profile.IsClamperDone)
          flag4 = true;
        if (Profile.CalculationData.Count == 0)
          flag4 = true;
        if (Profile.CalculationData.Count > 0)
        {
          for (int index1 = 0; index1 <= Profile.CalculationData.Count - 1; ++index1)
          {
            if (Profile.CalculationData[index1].calcOperations.Count == 0)
              flag4 = true;
            for (int index2 = 0; index2 <= Profile.CalculationData[index1].calcOperations.Count - 1; ++index2)
            {
              if (Profile.CalculationData[index1].calcOperations[index2].Clampers.Count == 0)
                flag4 = true;
            }
          }
        }
        if (flag4 && Clamper)
        {
          Profile.isSupportBlockOffsetAdd = false;
          Profile.isError = false;
          for (int index = 0; index <= Profile.CalculationData.Count - 1; ++index)
          {
            ProfileItemCalc ItemCalc = Profile.CalculationData[index];
