            buEyeBaseVer5.Apps.ProfileClamper profileClamper6 = new buEyeBaseVer5.Apps.ProfileClamper(profileClamper1.XPosition - num5, true, true, profileClamper1.Width);
            LastClampers[num2] = profileClamper6;
            clsInit.cProfile.MoveBwdClampersFromIndex(num2, MinDisFor2Clamper, ref LastClampers);
            buEyeBaseVer5.Apps.ProfileClamper.Copy(LastClampers, ref activeOP.Clampers);
            activeOP.Calculated = true;
          }
        }
        else
        {
          double num8 = profileClamper1.XPosition - Calc1.LeftMinClamperPos;
          double num9 = Calc1.RightMinClamperPos - profileClamper1.XPosition;
          double num10 = profileClamper1.XPosition + num9;
          double num11 = profileClamper1.XPosition - num8;
          double num12 = profileClamper1.XPosition + num9 - LastClampers[index - 1].XPosition;
          double num13 = LastClampers[index + 1].XPosition - (profileClamper1.XPosition + num9);
          double num14 = profileClamper1.XPosition - num8 - LastClampers[index - 1].XPosition;
          double num15 = LastClampers[index + 1].XPosition - (profileClamper1.XPosition - num8);
          if (num13 < MinDisFor2Clamper & num12 > MinDisFor2Clamper)
            num9 = 100000.0;
          if (num10 > ItemCalc.Length - ProfileEndOffset)
            num9 = 100000.0;
          if (num11 - LastClampers[num2 - 1].XPosition < MinDisFor2Clamper)
            num8 = 100000.0;
          buEyeBaseVer5.Apps.ProfileClamper profileClamper7 = num8 >= num9 ? new buEyeBaseVer5.Apps.ProfileClamper(Calc1.RightMinClamperPos, true, true, profileClamper1.Width) : new buEyeBaseVer5.Apps.ProfileClamper(Calc1.LeftMinClamperPos, true, true, profileClamper1.Width);
          LastClampers[num2] = profileClamper7;
          clsInit.cProfile.MoveFwdClampersFromIndex(num2, MinDisFor2Clamper, ref LastClampers);
          if (clsInit.cProfile.HowManyClamperInsideProfile(ItemCalc, ProfileStartOffset, ProfileEndOffset, LastClampers) < 2)
            clsInit.cProfile.ReArrangeClampers(this.Clampers[0].MinPositionRange, ItemCalc.Length - ProfileEndOffset, Calc1.LeftMinClamperPos, Calc1.RightMinClamperPos, ItemCalc.MaxClamperNumber, MinDisFor2Clamper, buProfileCalc.varProfileClamperSettings.MaxDistanceFor2Clamper, ref LastClampers);
          buEyeBaseVer5.Apps.ProfileClamper.Copy(LastClampers, ref activeOP.Clampers);
          activeOP.Calculated = true;
        }
        flag = true;
      }
    }
    if (!flag)
    {
      if (LastClampers[0].XPosition > buProfileCalc.varProfileClamperSettings.StartMaxDistance)
      {
        if (Calc1.LeftMinClamperPos > FirstClamperMinRange & Calc1.LeftMinClamperPos < buProfileCalc.varProfileClamperSettings.StartMaxDistance)
        {
          LastClampers[0].XPosition = Calc1.LeftMinClamperPos;
          LastClampers[0].GeometrixMinX = LastClampers[0].XPosition - buProfileCalc.varProfileClamperSettings.ClamperWidth / 2.0;
          LastClampers[0].GeometrixMaxX = LastClampers[0].XPosition + buProfileCalc.varProfileClamperSettings.ClamperWidth / 2.0;
        }
        else if (Calc1.LeftMaxClamperPos > FirstClamperMinRange & Calc1.LeftMaxClamperPos < buProfileCalc.varProfileClamperSettings.StartMaxDistance)
        {
          LastClampers[0].XPosition = Calc1.LeftMaxClamperPos;
          LastClampers[0].GeometrixMinX = LastClampers[0].XPosition - buProfileCalc.varProfileClamperSettings.ClamperWidth / 2.0;
          LastClampers[0].GeometrixMaxX = LastClampers[0].XPosition + buProfileCalc.varProfileClamperSettings.ClamperWidth / 2.0;
        }
      }
      buEyeBaseVer5.Apps.ProfileClamper.Copy(LastClampers, ref activeOP.Clampers);
      activeOP.Calculated = true;
    }
    if (!activeOP.Calculated)
      return;
    activeOP.Used = true;
  }

