  public void doClamperMakeItRightAsSame(ref ProfileItemCalc ItemCalc)
  {
    double num1 = ItemCalc.Length;
    double num2 = buProfileCalc.varProfileSettings.MachineLength - ItemCalc.Length;
    if (ItemCalc.CalcType == ProfileExcType.LongSecondPart | ItemCalc.CalcType == ProfileExcType.LongSecondBottom)
    {
      num1 = buProfileCalc.varProfileSettings.MachineLength;
      num2 = 0.0;
    }
    for (int index1 = 0; index1 <= ItemCalc.calcOperations.Count - 1; ++index1)
    {
      List<buEyeBaseVer5.Apps.ProfileClamper> profileClamperList1 = new List<buEyeBaseVer5.Apps.ProfileClamper>();
      List<buEyeBaseVer5.Apps.ProfileClamper> profileClamperList2 = new List<buEyeBaseVer5.Apps.ProfileClamper>();
      for (int index2 = 0; index2 <= ItemCalc.calcOperations[index1].Clampers.Count - 1; ++index2)
      {
        if (ItemCalc.calcOperations[index1].Clampers[index2].XPosition > num1 + buProfileCalc.varProfileClamperSettings.ClamperWidth / 2.0)
        {
          buEyeBaseVer5.Apps.ProfileClamper profileClamper = new buEyeBaseVer5.Apps.ProfileClamper(ItemCalc.calcOperations[index1].Clampers[index2]);
          double num3 = buProfileCalc.varProfileSettings.MachineLength - profileClamper.XPosition;
          if (num3 < this.Clampers[0].MinPositionRange)
            num3 = this.Clampers[0].MinPositionRange;
          profileClamper.XPosition = num3;
          profileClamper.GeometrixMaxX = profileClamper.XPosition + profileClamper.Width / 2.0;
          profileClamper.GeometrixMinX = profileClamper.XPosition - profileClamper.Width / 2.0;
          profileClamperList2.Add(profileClamper);
        }
        else
        {
          buEyeBaseVer5.Apps.ProfileClamper profileClamper = new buEyeBaseVer5.Apps.ProfileClamper(ItemCalc.calcOperations[index1].Clampers[index2]);
          profileClamper.XPosition += num2;
          profileClamper.GeometrixMaxX += num2;
          profileClamper.GeometrixMinX += num2;
          profileClamperList1.Add(profileClamper);
        }
      }
      if (profileClamperList2.Count > 0)
        profileClamperList2.Reverse();
      ItemCalc.calcOperations[index1].Clampers = new List<buEyeBaseVer5.Apps.ProfileClamper>();
      for (int index3 = 0; index3 <= profileClamperList2.Count - 1; ++index3)
        ItemCalc.calcOperations[index1].Clampers.Add(profileClamperList2[index3]);
      for (int index4 = 0; index4 <= profileClamperList1.Count - 1; ++index4)
        ItemCalc.calcOperations[index1].Clampers.Add(profileClamperList1[index4]);
    }
  }

  public void doClamperSetManuelClamper(
    ProfileItemCalc ItemCalc,
    double StartOffset,
    double EndOffset,
    ref List<buEyeBaseVer5.Apps.ProfileClamper> clamperList,
    double MinDisClampers)
  {
    double num1 = EndOffset;
    double num2 = StartOffset;
    double num3 = ItemCalc.Length;
    if (ItemCalc.CalcType == ProfileExcType.LongSecondPart | ItemCalc.CalcType == ProfileExcType.LongSecondBottom)
      num3 = buProfileCalc.varProfileSettings.MachineLength;
    if (num3 >= 300.0 & num3 <= 500.0)
    {
      if (EndOffset > 50.0)
        num1 = 50.0;
      if (StartOffset > 50.0)
        num2 = 50.0;
    }
    if (num3 < 300.0)
    {
      num1 = 0.0;
      num2 = 0.0;
    }
    clamperList.Clear();
    clamperList = new List<buEyeBaseVer5.Apps.ProfileClamper>();
    double num4 = 0.0;
    double num5 = (num3 - this.Clampers[0].MinPositionRange - num2 - num1) / (double) (ItemCalc.MaxClamperNumber - 1) - 5.0;
    if (num5 < MinDisClampers)
      num5 = MinDisClampers;
    for (int index = 0; index < ItemCalc.MaxClamperNumber; ++index)
    {
      if (index == 0)
      {
        num4 += this.Clampers[0].MinPositionRange;
        if (num4 < num2)
          num4 = num2;
      }
      else
        num4 += num5;
      if (num4 < num3 - EndOffset)
      {
        buEyeBaseVer5.Apps.ProfileClamper profileClamper = new buEyeBaseVer5.Apps.ProfileClamper()
        {
          XPosition = num4,
          Used = true,
          Enable = true
        };
        profileClamper.GeometrixMaxX = profileClamper.XPosition + buProfileCalc.varProfileClamperSettings.ClamperWidth / 2.0;
        profileClamper.GeometrixMinX = profileClamper.XPosition - buProfileCalc.varProfileClamperSettings.ClamperWidth / 2.0;
        clamperList.Add(profileClamper);
      }
      else
      {
        double num6 = buProfileCalc.varProfileSettings.MachineLength - (buProfileCalc.varProfileClamperSettings.ClamperWidth + MinDisClampers) * (double) (ItemCalc.MaxClamperNumber - index + 1) + (buProfileCalc.varProfileClamperSettings.ClamperWidth + MinDisClampers);
        buEyeBaseVer5.Apps.ProfileClamper profileClamper = new buEyeBaseVer5.Apps.ProfileClamper()
        {
          XPosition = num6,
          Used = true,
          Enable = true
        };
        profileClamper.GeometrixMaxX = profileClamper.XPosition + buProfileCalc.varProfileClamperSettings.ClamperWidth / 2.0;
        profileClamper.GeometrixMinX = profileClamper.XPosition - buProfileCalc.varProfileClamperSettings.ClamperWidth / 2.0;
        clamperList.Add(profileClamper);
      }
    }
  }

  public void doClamperSortOP(
    ref buEyeBaseVer5.Apps.ProfileItem ItemCalc,
    ref List<GProfileOperation> sortOP,
    ProfileSortMethods SortType,
    bool UsePriority)
  {
    List<GProfileOperation> RefList1 = new List<GProfileOperation>();
    List<GProfileOperation> RefList2 = new List<GProfileOperation>();
    for (int index = 0; index <= ItemCalc.Operations.Count - 1; ++index)
    {
      if (ItemCalc.Operations[index].Enable & ItemCalc.Operations[index].OperationData.OperationType != ProfileOperationTypes.Notch)
      {
        if (SortType != 0)
        {
          if (ItemCalc.Operations[index].Priority <= 0)
            RefList2.Add(new GProfileOperation(ItemCalc.Operations[index])
            {
              Calculated = false
            });
          if (ItemCalc.Operations[index].Priority > 0)
          {
            if (UsePriority)
              RefList1.Add(new GProfileOperation(ItemCalc.Operations[index])
              {
                Calculated = false
              });
            else
              RefList2.Add(new GProfileOperation(ItemCalc.Operations[index])
              {
                Calculated = false
              });
          }
        }
        else
          RefList2.Add(new GProfileOperation(ItemCalc.Operations[index])
          {
            Calculated = false
          });
      }
    }
    if (RefList1.Count > 0)
    {
      if (SortType == ProfileSortMethods.OnlyXDirection)
        clsInit.cProfile.SortList(SortDirectionType.Lower, ref RefList1, buProfileCalc.varProfileClamperSettings.SortSequenceAtSamePosition);
      clsInit.cProfile.SortListByPriority(SortDirectionType.Lower, ref RefList1);
      for (int index = 0; index <= RefList1.Count - 1; ++index)
        sortOP.Add(new GProfileOperation(RefList1[index]));
    }
    switch (SortType)
    {
      case ProfileSortMethods.OnlyXDirection:
        clsInit.cProfile.SortList(SortDirectionType.Lower, ref RefList2, buProfileCalc.varProfileClamperSettings.SortSequenceAtSamePosition);
        for (int index = 0; index <= RefList2.Count - 1; ++index)
          sortOP.Add(new GProfileOperation(RefList2[index]));
        break;
      case ProfileSortMethods.OnlyToolUsage:
        List<List<GProfileOperation>> splitedOP = new List<List<GProfileOperation>>();
        clsInit.cProfile.SplitOperationByToolNo(RefList2, ref splitedOP);
        for (int index1 = 0; index1 <= splitedOP.Count - 1; ++index1)
        {
          for (int index2 = 0; index2 <= splitedOP[index1].Count - 1; ++index2)
            sortOP.Add(new GProfileOperation(splitedOP[index1][index2]));
        }
        break;
      default:
        for (int index = 0; index <= RefList2.Count - 1; ++index)
          sortOP.Add(new GProfileOperation(RefList2[index]));
        break;
    }
  }

  public void doClamperSortOP(
    ref ProfileItemCalc ItemCalc,
    ref List<GProfileOperation> sortOP,
    ProfileSortMethods SortType,
    bool UsePriority)
  {
    List<GProfileOperation> RefList1 = new List<GProfileOperation>();
    List<GProfileOperation> RefList2 = new List<GProfileOperation>();
    for (int index = 0; index <= ItemCalc.calcOperations.Count - 1; ++index)
    {
      if (ItemCalc.calcOperations[index].Enable & ItemCalc.calcOperations[index].OperationData.OperationType != ProfileOperationTypes.Notch)
      {
        if (SortType != 0)
        {
          if (ItemCalc.calcOperations[index].Priority <= 0)
            RefList2.Add(new GProfileOperation(ItemCalc.calcOperations[index])
            {
              Calculated = false
            });
          if (ItemCalc.calcOperations[index].Priority > 0)
          {
            if (UsePriority)
              RefList1.Add(new GProfileOperation(ItemCalc.calcOperations[index])
              {
                Calculated = false
              });
            else
              RefList2.Add(new GProfileOperation(ItemCalc.calcOperations[index])
              {
                Calculated = false
              });
          }
        }
        else
          RefList2.Add(new GProfileOperation(ItemCalc.calcOperations[index])
          {
            Calculated = false
          });
      }
    }
    if (RefList1.Count > 0)
    {
      if (SortType == ProfileSortMethods.OnlyXDirection)
        clsInit.cProfile.SortList(SortDirectionType.Lower, ref RefList1, buProfileCalc.varProfileClamperSettings.SortSequenceAtSamePosition);
      clsInit.cProfile.SortListByPriority(SortDirectionType.Lower, ref RefList1);
      for (int index = 0; index <= RefList1.Count - 1; ++index)
        sortOP.Add(new GProfileOperation(RefList1[index]));
    }
    switch (SortType)
    {
      case ProfileSortMethods.OnlyXDirection:
        clsInit.cProfile.SortList(SortDirectionType.Lower, ref RefList2, buProfileCalc.varProfileClamperSettings.SortSequenceAtSamePosition);
        for (int index = 0; index <= RefList2.Count - 1; ++index)
        {
          sortOP.Add(new GProfileOperation(RefList2[index]));
          clsInit.cProfile.CheckDepthAndChangeSequenceIfIntersect(ref sortOP);
        }
        break;
      case ProfileSortMethods.OnlyToolUsage:
        List<List<GProfileOperation>> splitedOP1 = new List<List<GProfileOperation>>();
        clsInit.cProfile.SplitOperationByToolNo(RefList2, ref splitedOP1);
        for (int index1 = 0; index1 <= splitedOP1.Count - 1; ++index1)
        {
          List<GProfileOperation> RefList3 = splitedOP1[index1];
          clsInit.cProfile.SortList(SortDirectionType.Lower, ref RefList3, buProfileCalc.varProfileClamperSettings.SortSequenceAtSamePosition);
          for (int index2 = 0; index2 <= RefList3.Count - 1; ++index2)
          {
            sortOP.Add(RefList3[index2]);
            clsInit.cProfile.CheckDepthAndChangeSequenceIfIntersect(ref sortOP);
          }
        }
        break;
      case ProfileSortMethods.ToolUsageThenPlane:
        clsInit.cProfile.SortList(SortDirectionType.Lower, ref RefList2, buProfileCalc.varProfileClamperSettings.SortSequenceAtSamePosition);
        List<List<GProfileOperation>> splitedOP2 = new List<List<GProfileOperation>>();
        clsInit.cProfile.SplitOperationByToolNo(RefList2, ref splitedOP2);
        for (int index3 = 0; index3 <= splitedOP2.Count - 1; ++index3)
        {
          List<List<GProfileOperation>> splitedOP3 = new List<List<GProfileOperation>>();
          clsInit.cProfile.SplitOperationByPlane(splitedOP2[index3], ref splitedOP3);
          for (int index4 = 0; index4 <= splitedOP3.Count - 1; ++index4)
          {
            List<GProfileOperation> RefList4 = splitedOP3[index4];
            clsInit.cProfile.SortList(SortDirectionType.Lower, ref RefList4, buProfileCalc.varProfileClamperSettings.SortSequenceAtSamePosition);
            for (int index5 = 0; index5 <= RefList4.Count - 1; ++index5)
              sortOP.Add(RefList4[index5]);
            clsInit.cProfile.CheckDepthAndChangeSequenceIfIntersect(ref sortOP);
          }
        }
        break;
      case ProfileSortMethods.OnlyPlane:
        List<List<GProfileOperation>> splitedOP4 = new List<List<GProfileOperation>>();
        clsInit.cProfile.SplitOperationByPlane(RefList2, ref splitedOP4);
        for (int index6 = 0; index6 <= splitedOP4.Count - 1; ++index6)
        {
          List<GProfileOperation> RefList5 = splitedOP4[index6];
          clsInit.cProfile.SortList(SortDirectionType.Lower, ref RefList5, buProfileCalc.varProfileClamperSettings.SortSequenceAtSamePosition);
          for (int index7 = 0; index7 <= RefList5.Count - 1; ++index7)
          {
            sortOP.Add(RefList5[index7]);
            clsInit.cProfile.CheckDepthAndChangeSequenceIfIntersect(ref sortOP);
          }
        }
        break;
      default:
        for (int index = 0; index <= RefList2.Count - 1; ++index)
          sortOP.Add(new GProfileOperation(RefList2[index]));
        break;
    }
  }

  public void doClamperNotchOP(
    ref ProfileItemCalc ItemCalc,
    ref List<GProfileOperation> NotchOpList,
    ref double NotchStartOffset,
    ref double NotchEndOffset,
    ref double ProfileStartOffset,
    ref double ProfileEndOffset)
  {
    NotchOpList = new List<GProfileOperation>();
    for (int index = ItemCalc.calcOperations.Count - 1; index >= 0; --index)
    {
      if (ItemCalc.calcOperations[index].Action == actionTypeBU.profileNotch)
      {
        GProfileOperation gprofileOperation = new GProfileOperation(ItemCalc.calcOperations[index]);
        NotchOpList.Add(gprofileOperation);
        if (gprofileOperation.OperationData.NotchData.NotchOPType == ProfileNotchOperationType.Side | gprofileOperation.OperationData.NotchData.NotchOPType == ProfileNotchOperationType.Vertical)
        {
          if (ItemCalc.XReferanceLocation == LeftRightType.Left)
          {
            if (gprofileOperation.OperationData.NotchData.NotchLocation == ProfileNotchLocationType.Left)
            {
              NotchStartOffset = gprofileOperation.SizePoint.MaxPoint.X - gprofileOperation.SizePoint.MinPoint.X + buProfileCalc.varProfileClamperSettings.NotchSafeXDistance + buProfileCalc.varProfileClamperSettings.ClamperWidth / 2.0;
              if (gprofileOperation.OperationData.NotchData.NotchOPType == ProfileNotchOperationType.Vertical)
                NotchStartOffset = gprofileOperation.SizePoint.MaxPoint.X - gprofileOperation.SizePoint.MinPoint.X + buProfileCalc.varProfileClamperSettings.OperationFrontLeftMinDistance + buProfileCalc.varProfileClamperSettings.NotchSafeXDistance;
            }
            if (gprofileOperation.OperationData.NotchData.NotchLocation == ProfileNotchLocationType.Right)
            {
              NotchEndOffset = gprofileOperation.SizePoint.MaxPoint.X - gprofileOperation.SizePoint.MinPoint.X + buProfileCalc.varProfileClamperSettings.NotchSafeXDistance + buProfileCalc.varProfileClamperSettings.ClamperWidth / 2.0;
              if (gprofileOperation.OperationData.NotchData.NotchOPType == ProfileNotchOperationType.Vertical)
                NotchEndOffset = gprofileOperation.SizePoint.MaxPoint.X - gprofileOperation.SizePoint.MinPoint.X + buProfileCalc.varProfileClamperSettings.OperationFrontLeftMinDistance + buProfileCalc.varProfileClamperSettings.NotchSafeXDistance;
              if (NotchEndOffset < buProfileCalc.varProfileClamperSettings.OperationTopRightMinDistance + (gprofileOperation.SizePoint.MaxPoint.X - gprofileOperation.SizePoint.MinPoint.X))
                NotchEndOffset = buProfileCalc.varProfileClamperSettings.OperationTopRightMinDistance + (gprofileOperation.SizePoint.MaxPoint.X - gprofileOperation.SizePoint.MinPoint.X) + buProfileCalc.varProfileClamperSettings.NotchSafeXDistance;
            }
          }
          else
          {
            if (gprofileOperation.OperationData.NotchData.NotchLocation == ProfileNotchLocationType.Right)
            {
              NotchStartOffset = gprofileOperation.SizePoint.MaxPoint.X - gprofileOperation.SizePoint.MinPoint.X + buProfileCalc.varProfileClamperSettings.NotchSafeXDistance + buProfileCalc.varProfileClamperSettings.ClamperWidth / 2.0;
              if (gprofileOperation.OperationData.NotchData.NotchOPType == ProfileNotchOperationType.Vertical)
                NotchStartOffset = gprofileOperation.SizePoint.MaxPoint.X - gprofileOperation.SizePoint.MinPoint.X + buProfileCalc.varProfileClamperSettings.OperationFrontLeftMinDistance + buProfileCalc.varProfileClamperSettings.NotchSafeXDistance;
            }
            if (gprofileOperation.OperationData.NotchData.NotchLocation == ProfileNotchLocationType.Left)
            {
              NotchEndOffset = gprofileOperation.SizePoint.MaxPoint.X - gprofileOperation.SizePoint.MinPoint.X + buProfileCalc.varProfileClamperSettings.NotchSafeXDistance + buProfileCalc.varProfileClamperSettings.ClamperWidth / 2.0;
              if (gprofileOperation.OperationData.NotchData.NotchOPType == ProfileNotchOperationType.Vertical)
                NotchEndOffset = gprofileOperation.SizePoint.MaxPoint.X - gprofileOperation.SizePoint.MinPoint.X + buProfileCalc.varProfileClamperSettings.OperationFrontLeftMinDistance + buProfileCalc.varProfileClamperSettings.NotchSafeXDistance;
              if (NotchEndOffset < buProfileCalc.varProfileClamperSettings.OperationTopRightMinDistance + (gprofileOperation.SizePoint.MaxPoint.X - gprofileOperation.SizePoint.MinPoint.X))
                NotchEndOffset = buProfileCalc.varProfileClamperSettings.OperationTopRightMinDistance + (gprofileOperation.SizePoint.MaxPoint.X - gprofileOperation.SizePoint.MinPoint.X) + buProfileCalc.varProfileClamperSettings.NotchSafeXDistance;
            }
          }
        }
      }
    }
    if (NotchOpList.Count > 0)
      clsInit.cProfile.SortList(SortDirectionType.Lower, ref NotchOpList);
    if (NotchStartOffset > 0.0 & NotchStartOffset > ProfileStartOffset)
      ProfileStartOffset = NotchStartOffset;
    if (!(NotchEndOffset > 0.0 & NotchEndOffset > ProfileEndOffset))
      return;
    ProfileEndOffset = NotchEndOffset;
  }

  public void doClamperForbiddenAllowedAreas(
    buEyeBaseVer5.Apps.ProfileItem Item,
    ProfileItemCalc ItemCalc,
    List<GProfileOperation> sortOP,
    double ProfileStartOffset,
    double ProfileEndOffset,
    ref List<MinMax> ForbiddenAreas,
    ref List<MinMax> AllowedAreas)
  {
    ForbiddenAreas.Clear();
    AllowedAreas.Clear();
    double num1 = 0.0;
    for (int index = 0; index <= sortOP.Count - 1; ++index)
    {
      double num2 = 0.0;
      double num3 = 0.0;
      if (!sortOP[index].Used)
      {
        if (sortOP[index].OperationData.selectedPlaneName == planeNames.Free)
        {
          num2 = clsInit.cVector5.PointAngle(new Point3D(sortOP[index].OperationData.selectedPlane.AxisZ.X, sortOP[index].OperationData.selectedPlane.AxisZ.Y, sortOP[index].OperationData.selectedPlane.AxisZ.Z), new Point3D(), Plane.YZ);
          num3 = num2 <= 90.0 ? 90.0 - num2 : num2 - 90.0;
        }
        if (!clsInit.cProfile.isOperationSafeForClamps(Item, ItemCalc, sortOP[index], buProfileCalc.varProfileSettings, buProfileCalc.varProfileClamperSettings))
        {
          if (sortOP[index].OperationData.selectedPlaneName == planeNames.Top | sortOP[index].OperationData.selectedPlaneName == planeNames.Bottom | sortOP[index].OperationData.selectedPlaneName == planeNames.Free & num3 <= buProfileCalc.varProfileClamperSettings.FreePlaneToBackFrontAngleLimit)
          {
            double num4 = buProfileCalc.varProfileClamperSettings.OperationTopLeftMinDistance + buProfileCalc.varProfileClamperSettings.ClamperWidth / 2.0;
            double num5 = buProfileCalc.varProfileClamperSettings.OperationTopLeftMinDistance + buProfileCalc.varProfileClamperSettings.ClamperWidth / 2.0;
            if (num4 > 0.0 & num5 > 0.0)
              clsInit.cProfile.AddForbiddenAreaToList(new MinMax()
              {
                Min = buNumeric5.RoundTwoDigit(sortOP[index].SizePoint.MinPoint.X - num4),
                Max = buNumeric5.RoundTwoDigit(sortOP[index].SizePoint.MaxPoint.X + num5)
              }, ref ForbiddenAreas);
          }
          if (sortOP[index].OperationData.selectedPlaneName == planeNames.Back | sortOP[index].OperationData.selectedPlaneName == planeNames.Free & num3 > buProfileCalc.varProfileClamperSettings.FreePlaneToBackFrontAngleLimit & num2 < 90.0)
          {
            double num6 = buProfileCalc.varProfileClamperSettings.OperationBackLeftMinDistance + buProfileCalc.varProfileClamperSettings.ClamperWidth / 2.0;
            double num7 = buProfileCalc.varProfileClamperSettings.OperationBackRightMinDistance + buProfileCalc.varProfileClamperSettings.ClamperWidth / 2.0;
            if (num6 > 0.0 & num7 > 0.0)
              clsInit.cProfile.AddForbiddenAreaToList(new MinMax()
              {
                Min = buNumeric5.RoundTwoDigit(sortOP[index].SizePoint.MinPoint.X - num6),
                Max = buNumeric5.RoundTwoDigit(sortOP[index].SizePoint.MaxPoint.X + num7)
              }, ref ForbiddenAreas);
          }
          if (sortOP[index].OperationData.selectedPlaneName == planeNames.Front | sortOP[index].OperationData.selectedPlaneName == planeNames.Free & num3 > buProfileCalc.varProfileClamperSettings.FreePlaneToBackFrontAngleLimit & num2 > 90.0)
          {
            double num8 = buProfileCalc.varProfileClamperSettings.OperationFrontLeftMinDistance + buProfileCalc.varProfileClamperSettings.ClamperWidth / 2.0;
            double num9 = buProfileCalc.varProfileClamperSettings.OperationFrontRightMinDistance + buProfileCalc.varProfileClamperSettings.ClamperWidth / 2.0;
            if (num8 > 0.0 & num9 > 0.0)
              clsInit.cProfile.AddForbiddenAreaToList(new MinMax()
              {
                Min = buNumeric5.RoundTwoDigit(sortOP[index].SizePoint.MinPoint.X - num8),
                Max = buNumeric5.RoundTwoDigit(sortOP[index].SizePoint.MaxPoint.X + num9)
              }, ref ForbiddenAreas);
          }
        }
      }
    }
    clsInit.cProfile.SortList(SortDirectionType.Lower, ref ForbiddenAreas);
    if (ForbiddenAreas.Count == 0)
    {
      MinMax minMax = new MinMax();
      minMax.Min = 0.0;
      minMax.Max = Item.Length;
      if (minMax.Max > buProfileCalc.varProfileSettings.MachineLength)
        minMax.Max = buProfileCalc.varProfileSettings.MachineLength;
      if (minMax.Min < minMax.Max & minMax.Max - minMax.Min > buProfileCalc.varProfileClamperSettings.ClamperWidth + buProfileCalc.varProfileClamperSettings.ClamperSafeDistance)
        AllowedAreas.Add(minMax);
    }
    if (ForbiddenAreas.Count == 1)
    {
      if (ForbiddenAreas[0].Min > 0.0 & ForbiddenAreas[0].Min > buProfileCalc.varProfileClamperSettings.ClamperWidth + buProfileCalc.varProfileClamperSettings.ClamperSafeDistance * 2.0)
      {
        MinMax minMax = new MinMax();
        minMax.Min = 0.0;
        minMax.Max = ForbiddenAreas[0].Min;
        if (minMax.Max > buProfileCalc.varProfileSettings.MachineLength)
          minMax.Max = buProfileCalc.varProfileSettings.MachineLength;
        if (minMax.Min < minMax.Max & minMax.Max - minMax.Min > buProfileCalc.varProfileClamperSettings.ClamperWidth + buProfileCalc.varProfileClamperSettings.ClamperSafeDistance)
          AllowedAreas.Add(minMax);
      }
      double num10 = ItemCalc.Length - ForbiddenAreas[0].Max;
      if (num10 > 0.0 & num10 > buProfileCalc.varProfileClamperSettings.ClamperWidth + buProfileCalc.varProfileClamperSettings.ClamperSafeDistance * 2.0)
      {
        MinMax minMax = new MinMax();
        minMax.Min = ForbiddenAreas[0].Max;
        minMax.Max = ItemCalc.Length;
        if (minMax.Max > buProfileCalc.varProfileSettings.MachineLength)
          minMax.Max = buProfileCalc.varProfileSettings.MachineLength;
        if (minMax.Min < minMax.Max & minMax.Max - minMax.Min > buProfileCalc.varProfileClamperSettings.ClamperWidth + buProfileCalc.varProfileClamperSettings.ClamperSafeDistance)
          AllowedAreas.Add(minMax);
      }
    }
    if (ForbiddenAreas.Count > 1)
    {
      List<MinMax> minMaxList = new List<MinMax>();
      minMaxList.Add(new MinMax(ForbiddenAreas[0]));
      for (int index1 = 1; index1 <= ForbiddenAreas.Count - 1; ++index1)
      {
        bool flag = false;
        for (int index2 = 0; index2 <= minMaxList.Count - 1; ++index2)
        {
          if (buNumeric5.IsValueInsideMinMaxValues(ForbiddenAreas[index1].Min, minMaxList[index2].Min, minMaxList[index2].Max) & buNumeric5.IsValueInsideMinMaxValues(ForbiddenAreas[index1].Max, minMaxList[index2].Min, minMaxList[index2].Max))
            flag = true;
        }
        if (!flag)
        {
          for (int index3 = minMaxList.Count - 1; index3 >= 0; --index3)
          {
            if (buNumeric5.IsValueInsideMinMaxValues(minMaxList[index3].Min, ForbiddenAreas[index1].Min, ForbiddenAreas[index1].Max) & buNumeric5.IsValueInsideMinMaxValues(minMaxList[index3].Max, ForbiddenAreas[index1].Min, ForbiddenAreas[index1].Max))
              minMaxList.RemoveAt(index3);
          }
          minMaxList.Add(new MinMax(ForbiddenAreas[index1]));
        }
      }
      ForbiddenAreas.Clear();
      for (int index = 0; index <= minMaxList.Count - 1; ++index)
        ForbiddenAreas.Add(new MinMax(minMaxList[index]));
      for (int index = 0; index <= ForbiddenAreas.Count - 1; ++index)
      {
        if (ForbiddenAreas[index].Max > num1)
          num1 = ForbiddenAreas[index].Max;
      }
      for (int index = 0; index <= ForbiddenAreas.Count - 1; ++index)
      {
        if (index == 0)
        {
          if (ForbiddenAreas[index].Min > 0.0 & ForbiddenAreas[index].Min > buProfileCalc.varProfileClamperSettings.ClamperWidth + buProfileCalc.varProfileClamperSettings.ClamperSafeDistance * 2.0)
          {
            MinMax minMax = new MinMax();
            minMax.Min = 0.0;
            minMax.Max = ForbiddenAreas[index].Min;
            if (minMax.Max > buProfileCalc.varProfileSettings.MachineLength)
              minMax.Max = buProfileCalc.varProfileSettings.MachineLength;
            if (minMax.Min < minMax.Max & minMax.Max - minMax.Min > buProfileCalc.varProfileClamperSettings.ClamperWidth + buProfileCalc.varProfileClamperSettings.ClamperSafeDistance)
              AllowedAreas.Add(minMax);
          }
          else if (ForbiddenAreas[index].Min > 0.0 & this.Clampers[0].MinPositionRange <= ForbiddenAreas[index].Min)
          {
            MinMax minMax = new MinMax();
            minMax.Min = 0.0;
            minMax.Max = ForbiddenAreas[index].Min;
            if (minMax.Max > buProfileCalc.varProfileSettings.MachineLength)
              minMax.Max = buProfileCalc.varProfileSettings.MachineLength;
            if (minMax.Min < minMax.Max & minMax.Max - minMax.Min > buProfileCalc.varProfileClamperSettings.ClamperWidth + buProfileCalc.varProfileClamperSettings.ClamperSafeDistance)
              AllowedAreas.Add(minMax);
          }
        }
        else if (index == ForbiddenAreas.Count - 1)
        {
          double num11 = ForbiddenAreas[index].Min - ForbiddenAreas[index - 1].Max;
          if (num11 > 0.0 & num11 > buProfileCalc.varProfileClamperSettings.ClamperWidth + buProfileCalc.varProfileClamperSettings.ClamperSafeDistance * 2.0)
          {
            MinMax minMax = new MinMax();
            minMax.Min = ForbiddenAreas[index - 1].Max;
            minMax.Max = ForbiddenAreas[index].Min;
            if (minMax.Max > buProfileCalc.varProfileSettings.MachineLength)
              minMax.Max = buProfileCalc.varProfileSettings.MachineLength;
            if (minMax.Min < minMax.Max & minMax.Max - minMax.Min > buProfileCalc.varProfileClamperSettings.ClamperWidth + buProfileCalc.varProfileClamperSettings.ClamperSafeDistance)
              AllowedAreas.Add(minMax);
          }
          double num12 = ItemCalc.Length - num1;
          if (num12 > 0.0 & num12 > buProfileCalc.varProfileClamperSettings.ClamperWidth + buProfileCalc.varProfileClamperSettings.ClamperSafeDistance * 2.0)
          {
            MinMax minMax = new MinMax();
            minMax.Min = num1;
            minMax.Max = ItemCalc.Length;
            if (minMax.Max > buProfileCalc.varProfileSettings.MachineLength)
              minMax.Max = buProfileCalc.varProfileSettings.MachineLength;
            if (minMax.Min < minMax.Max & minMax.Max - minMax.Min > buProfileCalc.varProfileClamperSettings.ClamperWidth + buProfileCalc.varProfileClamperSettings.ClamperSafeDistance)
              AllowedAreas.Add(minMax);
          }
        }
        else if (ForbiddenAreas[index].Min > ForbiddenAreas[index - 1].Max)
        {
          double num13 = ForbiddenAreas[index].Min - ForbiddenAreas[index - 1].Max;
          if (num13 > 0.0 & num13 > buProfileCalc.varProfileClamperSettings.ClamperWidth + buProfileCalc.varProfileClamperSettings.ClamperSafeDistance * 2.0)
          {
            MinMax minMax = new MinMax();
            minMax.Min = ForbiddenAreas[index - 1].Max;
            minMax.Max = ForbiddenAreas[index].Min;
            if (minMax.Max > buProfileCalc.varProfileSettings.MachineLength)
              minMax.Max = buProfileCalc.varProfileSettings.MachineLength;
            if (minMax.Min < minMax.Max & minMax.Max - minMax.Min > buProfileCalc.varProfileClamperSettings.ClamperWidth + buProfileCalc.varProfileClamperSettings.ClamperSafeDistance)
              AllowedAreas.Add(minMax);
          }
        }
      }
    }
    if (AllowedAreas.Count <= 0)
      return;
    if (AllowedAreas[0].Min < ProfileStartOffset)
      AllowedAreas[0].Min = ProfileStartOffset;
    if (AllowedAreas[AllowedAreas.Count - 1].Max <= ItemCalc.Length - ProfileEndOffset)
      return;
    AllowedAreas[AllowedAreas.Count - 1].Max = ItemCalc.Length - ProfileEndOffset;
  }

  public void doClamperOpLeftRightLimits(
    buEyeBaseVer5.Apps.ProfileItem Item,
    ProfileItemCalc ItemCalc,
    GProfileOperation sortOP,
    ref ClamperLeftRightPars Calc,
    double ClamperWidth)
  {
    if (Calc == null)
      Calc = new ClamperLeftRightPars();
    Calc.OperationAboveClamper = false;
    double num1 = 0.0;
    double num2 = 0.0;
    if (sortOP.OperationData.selectedPlaneName == planeNames.Free)
    {
      num1 = clsInit.cVector5.PointAngle(new Point3D(sortOP.OperationData.selectedPlane.AxisZ.X, sortOP.OperationData.selectedPlane.AxisZ.Y, sortOP.OperationData.selectedPlane.AxisZ.Z), new Point3D(), Plane.YZ);
      num2 = num1 <= 90.0 ? 90.0 - num1 : num1 - 90.0;
    }
    if (!clsInit.cProfile.isOperationSafeForClamps(Item, ItemCalc, sortOP, buProfileCalc.varProfileSettings, buProfileCalc.varProfileClamperSettings))
    {
      if (sortOP.OperationData.selectedPlaneName == planeNames.Top | sortOP.OperationData.selectedPlaneName == planeNames.Bottom | sortOP.OperationData.selectedPlaneName == planeNames.Free & num2 <= buProfileCalc.varProfileClamperSettings.FreePlaneToBackFrontAngleLimit)
      {
        Calc.LeftMinDis = buProfileCalc.varProfileClamperSettings.OperationTopLeftMinDistance + ClamperWidth / 2.0;
        Calc.RightMinDis = buProfileCalc.varProfileClamperSettings.OperationTopLeftMinDistance + ClamperWidth / 2.0;
      }
      if (sortOP.OperationData.selectedPlaneName == planeNames.Back | sortOP.OperationData.selectedPlaneName == planeNames.Free & num2 > buProfileCalc.varProfileClamperSettings.FreePlaneToBackFrontAngleLimit & num1 < 90.0)
      {
        Calc.LeftMinDis = buProfileCalc.varProfileClamperSettings.OperationBackLeftMinDistance + ClamperWidth / 2.0;
        Calc.RightMinDis = buProfileCalc.varProfileClamperSettings.OperationBackRightMinDistance + ClamperWidth / 2.0;
      }
      if (sortOP.OperationData.selectedPlaneName == planeNames.Front | sortOP.OperationData.selectedPlaneName == planeNames.Free & num2 > buProfileCalc.varProfileClamperSettings.FreePlaneToBackFrontAngleLimit & num1 > 90.0)
      {
        Calc.LeftMinDis = buProfileCalc.varProfileClamperSettings.OperationFrontLeftMinDistance + ClamperWidth / 2.0;
        Calc.RightMinDis = buProfileCalc.varProfileClamperSettings.OperationFrontRightMinDistance + ClamperWidth / 2.0;
      }
    }
    else
    {
      Calc.LeftMinDis = 0.0;
      Calc.RightMinDis = 0.0;
    }
    if (ItemCalc.XReferanceLocation == LeftRightType.Right && buProfileCalc.varProfileSettings.RightProfileMakeAsMirror)
      buNumeric5.ExchangeTwoVaues(ref Calc.LeftMinDis, ref Calc.RightMinDis);
    Calc.LeftMinClamperPos = sortOP.SizePoint.MinPoint.X - Calc.LeftMinDis;
    Calc.RightMinClamperPos = sortOP.SizePoint.MaxPoint.X + Calc.RightMinDis;
    if (Calc.RightMinClamperPos > ItemCalc.Length)
      ;
    double num3 = buProfileCalc.varProfileClamperSettings.ClamperOptimisationLevel;
    if (num3 < 1.0)
      num3 = 1.0;
    if (num3 > 10.0)
      num3 = 10.0;
    Calc.LeftMaxDis = buProfileCalc.varProfileClamperSettings.OperationClamperLeftMaxDistance <= Calc.LeftMinDis ? Calc.LeftMinDis : Calc.LeftMinDis + (buProfileCalc.varProfileClamperSettings.OperationClamperLeftMaxDistance - Calc.LeftMinDis) * num3 / 10.0;
    Calc.RightMaxDis = buProfileCalc.varProfileClamperSettings.OperationClamperRightMaxDistance <= Calc.RightMinDis ? Calc.RightMinDis : Calc.RightMinDis + (buProfileCalc.varProfileClamperSettings.OperationClamperRightMaxDistance - Calc.RightMinDis) * num3 / 10.0;
    if (Calc.OperationAboveClamper)
    {
      Calc.LeftMaxDis = 0.0;
      Calc.RightMaxDis = 0.0;
    }
    Calc.LeftMaxClamperPos = sortOP.SizePoint.MinPoint.X - Calc.LeftMaxDis;
    Calc.RightMaxClamperPos = sortOP.SizePoint.MaxPoint.X + Calc.RightMaxDis;
    if (sortOP.OperationData.OperationType == ProfileOperationTypes.Notch)
    {
      Calc.LeftMaxClamperPos = Calc.LeftMinClamperPos;
      Calc.RightMaxClamperPos = Calc.RightMinClamperPos;
      if (sortOP.OperationData.NotchData.NotchOPType == ProfileNotchOperationType.Length)
      {
        Calc.LeftMaxDis = buProfileCalc.varProfileClamperSettings.ClamperWidth / 2.0 + buProfileCalc.varProfileClamperSettings.ClamperSafeDistance;
        Calc.RightMaxDis = buProfileCalc.varProfileClamperSettings.ClamperWidth / 2.0 + buProfileCalc.varProfileClamperSettings.ClamperSafeDistance;
        Calc.LeftMaxClamperPos = sortOP.SizePoint.MinPoint.X - Calc.LeftMaxDis;
        Calc.RightMaxClamperPos = sortOP.SizePoint.MaxPoint.X + Calc.RightMaxDis;
      }
    }
    if (Calc.RightMaxClamperPos > ItemCalc.Length)
      ;
  }

  public void doClamperCheckMaxDistanceFromLastClamper(
    double XPosition,
    ref List<buEyeBaseVer5.Apps.ProfileClamper> ClamperList,
    double MaxClamperDistance,
    double MinClamperDistance,
    int MaxClamperCount,
    double ActualOPMinX,
    double ActualOPMaxX,
    ref double LastClamperX,
    double MinDisClampers)
  {
    string str = nameof (doClamperCheckMaxDistanceFromLastClamper);
    try
    {
      if (ClamperList.Count <= 0)
        return;
      double num = XPosition - ClamperList[ClamperList.Count - 1].XPosition;
      if (num <= MaxClamperDistance)
        return;
      int int32 = Convert.ToInt32(buNumeric5.RoundToLower(num / MaxClamperDistance));
      for (int index = 1; index <= int32; ++index)
      {
        double X = Math.Round((double) index * MaxClamperDistance, 5);
        if (X > XPosition | XPosition - X < MinClamperDistance)
          X = XPosition - MinClamperDistance;
        bool flag = buNumeric5.IsValueInsideMinMaxValues(X, ActualOPMinX, ActualOPMaxX);
        if (X > 0.0)
        {
          if (!flag)
          {
            buEyeBaseVer5.Apps.ProfileClamper Clamper = (buEyeBaseVer5.Apps.ProfileClamper) null;
            this.CheckClamper(ref Clamper, X, ClamperList, MaxClamperCount, -1);
            ClamperList.Add(Clamper);
            LastClamperX = Clamper.XPosition;
          }
          else if (ActualOPMinX > ClamperList[ClamperList.Count - 1].GeometrixMaxX + MinDisClampers)
          {
            buEyeBaseVer5.Apps.ProfileClamper Clamper = (buEyeBaseVer5.Apps.ProfileClamper) null;
            this.CheckClamper(ref Clamper, ActualOPMinX, ClamperList, MaxClamperCount, -1);
            ClamperList.Add(Clamper);
            LastClamperX = Clamper.XPosition;
          }
          else
          {
            buEyeBaseVer5.Apps.ProfileClamper Clamper = (buEyeBaseVer5.Apps.ProfileClamper) null;
            this.CheckClamper(ref Clamper, ActualOPMaxX, ClamperList, MaxClamperCount, -1);
            ClamperList.Add(Clamper);
            LastClamperX = Clamper.XPosition;
          }
        }
      }
    }
    catch (Exception ex)
    {
      buLogVer5.addToLog(this.string_1, str, "Error", "", 0.0, 0.0, true);
      buException.throwException(ex, str, true, "");
    }
  }

  public void doCreateParabolicMoves(ref buEyeBaseVer5.Apps.ProfileItem Item)
  {
    try
    {
      if (buProfileCalc.varProfileSettings.ProfileSafeDistanceForPlanes == ProfileSafeDistanceMode.G53Mode)
        return;
      TpPnt9D tpPnt9D1 = new TpPnt9D();
      TpPnt9D tpPnt9D2 = new TpPnt9D();
      for (int index1 = 0; index1 <= Item.CalculationData.Count - 1; ++index1)
      {
        for (int index2 = 0; index2 <= Item.CalculationData[index1].Cams.Count - 1; ++index2)
        {
          bool flag1 = false;
          camTp cam1 = Item.CalculationData[index1].Cams[index2];
          camTp camTp = (camTp) null;
          if (index2 > 0)
            camTp = Item.CalculationData[index1].Cams[index2 - 1];
          if (index2 < Item.CalculationData[index1].Cams.Count - 1)
          {
            camTp cam2 = Item.CalculationData[index1].Cams[index2 + 1];
          }
          if (camTp != null && cam1.PlaneName != camTp.PlaneName)
            flag1 = true;
          if (flag1)
          {
            List<Pnt9D> controlPoints = new List<Pnt9D>();
            List<Pnt9D> calculatedPoints = new List<Pnt9D>();
            TpPnt9D point1 = camTp.CamPoints[camTp.CamPoints.Count - 1].Points[camTp.CamPoints[camTp.CamPoints.Count - 1].Points.Count - 1];
            TpPnt9D point2 = cam1.CamPoints[0].Points[0];
            bool flag2 = true;
            double num1 = 0.0;
            double num2 = 0.0;
            if (buProfileCalc.varProfileSettings.ParabolicAllowedAxes == ProfileParaolicAxesType.Axes3)
            {
              int num3 = 0;
              double num4 = point1.P9.X - point2.P9.X;
              if (!buCompare5.EQ(num4, 0.0))
              {
                ++num3;
                num1 = point2.P9.X;
                num2 = num4;
              }
              if (num3 > 0)
              {
                TpPnt9D tpPnt9D3 = new TpPnt9D(camTp.CamPoints[camTp.CamPoints.Count - 1].Points[camTp.CamPoints[camTp.CamPoints.Count - 1].Points.Count - 1]);
                tpPnt9D3.P9.X = point2.P9.X;
                camTp.CamPoints[camTp.CamPoints.Count - 1].Points.Add(tpPnt9D3);
                point1 = camTp.CamPoints[camTp.CamPoints.Count - 1].Points[camTp.CamPoints[camTp.CamPoints.Count - 1].Points.Count - 1];
              }
            }
            if (flag2)
            {
              OrientationAngle Orientation1 = new OrientationAngle(point1.P9.A, 0.0, 0.0);
              Point3D MovePoint1 = new Point3D(point1.P9.X, point1.P9.Y, point1.P9.Z);
              Pnt6D CalcPoint = new Pnt6D();
              clsInit.cKinematic5.ReverseKinematix4Ax(cam1.Tool.Geometry.TotalLength, ccVars.KinematicOrjinal, VectorType.XVector, Orientation1, MovePoint1, ref CalcPoint);
              controlPoints.Add(new Pnt9D(CalcPoint));
              OrientationAngle Orientation2 = new OrientationAngle(point1.P9.A, 0.0, 0.0);
              Point3D MovePoint2 = new Point3D(point1.P9.X, point1.P9.Y, point1.P9.Z + buProfileCalc.varProfileSettings.ParabolicSafeDistance);
              CalcPoint = new Pnt6D();
              clsInit.cKinematic5.ReverseKinematix4Ax(cam1.Tool.Geometry.TotalLength, ccVars.KinematicOrjinal, VectorType.XVector, Orientation2, MovePoint2, ref CalcPoint);
              controlPoints.Add(new Pnt9D(CalcPoint));
              OrientationAngle Orientation3 = new OrientationAngle(point2.P9.A, 0.0, 0.0);
              Point3D MovePoint3 = new Point3D(point2.P9.X, point2.P9.Y, point2.P9.Z + buProfileCalc.varProfileSettings.ParabolicSafeDistance);
              CalcPoint = new Pnt6D();
              clsInit.cKinematic5.ReverseKinematix4Ax(cam1.Tool.Geometry.TotalLength, ccVars.KinematicOrjinal, VectorType.XVector, Orientation3, MovePoint3, ref CalcPoint);
              controlPoints.Add(new Pnt9D(CalcPoint));
              OrientationAngle Orientation4 = new OrientationAngle(point2.P9.A, 0.0, 0.0);
              Point3D MovePoint4 = new Point3D(point2.P9.X, point2.P9.Y, point2.P9.Z);
              CalcPoint = new Pnt6D();
              clsInit.cKinematic5.ReverseKinematix4Ax(cam1.Tool.Geometry.TotalLength, ccVars.KinematicOrjinal, VectorType.XVector, Orientation4, MovePoint4, ref CalcPoint);
              controlPoints.Add(new Pnt9D(CalcPoint));
              clsInit.cVector5.BezeirCurve(controlPoints, 0.1, ref calculatedPoints);
              camTpPoint camPoint1 = camTp.CamPoints[camTp.CamPoints.Count - 1];
              camTpPoint camPoint2 = cam1.CamPoints[0];
              for (int index3 = 0; index3 <= calculatedPoints.Count - 1; ++index3)
              {
                OrientationAngle Orientation5 = new OrientationAngle(calculatedPoints[index3].A, 0.0, 0.0);
                Point3D MovePoint5 = new Point3D(calculatedPoints[index3].X, calculatedPoints[index3].Y, calculatedPoints[index3].Z);
                CalcPoint = new Pnt6D();
                clsInit.cKinematic5.ForwardKinematix4Ax(cam1.Tool.Geometry.TotalLength, ccVars.KinematicOrjinal, VectorType.XVector, Orientation5, MovePoint5, ref CalcPoint);
                TpPnt9D tpPnt9D4 = new TpPnt9D(CalcPoint);
                tpPnt9D4.Type = 1;
                tpPnt9D4.Feed = buProfileCalc.varProfileSettings.ParabolicMoveFeed;
                if (ccVars.PostActive.Mode == "KabanMode1" && index3 == 0 & !buCompare5.EQ(num2, 0.0))
                  tpPnt9D4.PreCodes.Add((object) $"M28 X{num1.ToString("f2")} F{buProfileCalc.varProfileSettings.ParabolicMoveFeed.ToString()}");
                camPoint1.Points.Add(tpPnt9D4);
              }
            }
          }
        }
      }
    }
    catch (Exception ex)
    {
    }
  }

  public bool doCheckMoveSafeDistance(GProfileOperation ActualOP, GProfileOperation PreOP)
  {
    bool flag = false;
    if (ActualOP.OperationData.selectedPlaneName == planeNames.Front)
    {
      if (PreOP.OperationData.selectedPlaneName != planeNames.Front)
        flag = true;
    }
    else if (ActualOP.OperationData.selectedPlaneName == planeNames.Back)
    {
      if (PreOP.OperationData.selectedPlaneName != planeNames.Back)
        flag = true;
    }
    else if (ActualOP.OperationData.selectedPlaneName == planeNames.Top | ActualOP.OperationData.selectedPlaneName == planeNames.Bottom && PreOP.OperationData.selectedPlaneName != 0 & PreOP.OperationData.selectedPlaneName != planeNames.Bottom | PreOP.OperationData.OperationType == ProfileOperationTypes.Notch)
      flag = true;
    if (ActualOP.OperationData.OperationType == ProfileOperationTypes.Notch & PreOP.OperationData.OperationType != ProfileOperationTypes.Notch)
      flag = true;
    if (ActualOP.OperationData.OperationType == ProfileOperationTypes.Notch & PreOP.OperationData.OperationType == ProfileOperationTypes.Notch)
    {
      if (ActualOP.OperationData.NotchData.NotchOPType != PreOP.OperationData.NotchData.NotchOPType)
        flag = true;
      else if (ActualOP.OperationData.NotchData.NotchLocation != PreOP.OperationData.NotchData.NotchLocation | ActualOP.OperationData.NotchData.NotchFrontBack != PreOP.OperationData.NotchData.NotchFrontBack)
        flag = true;
    }
    return flag;
  }

  public void doCreateCode(
    buEyeBaseVer5.Apps.ProfileItem Profile,
    string Mode,
    ref ArrayList GCodes,
    int ProfileIndex,
    bool SecondAvailable,
    bool CreateGCode = false,
    bool ShowCode = false)
  {
    if (Profile == null)
      return;
    if (Profile != null && Profile.MaxClamperNumber != buProfileCalc.varProfileSettings.ProfileMaxClamper)
      Profile.MaxClamperNumber = buProfileCalc.varProfileSettings.ProfileMaxClamper;
    if (Mode == "YilmazMode1")
    {
      if (!Profile.IsClamperDone && !this.doCalculateAll(ref Profile, true, true, false))
        return;
      string GCodeStr = "";
      if (CreateGCode)
      {
        buEyeBaseVer5.Apps.ProfileItem profileItem = new buEyeBaseVer5.Apps.ProfileItem(Profile);
        this.doAddSupportBlockOffsets(ref profileItem);
        this.doCreateJobYilmazMode1(ref profileItem, ref GCodeStr, ProfileIndex, SecondAvailable, CreateGCode);
      }
      else
        this.doCreateJobYilmazMode1(ref Profile, ref GCodeStr, ProfileIndex, SecondAvailable, CreateGCode);
      buString5.SplitStringByNewLine(GCodeStr, ref GCodes);
      GCodes.Insert(0, (object) "<GCodes>");
      GCodes.Add((object) "</GCodes>");
      if (!ShowCode)
      {
        ArrayList AL = new ArrayList();
        this.SaveProfileJobFile(this.activeProfile, ref AL);
        GCodes.Add((object) " ");
        GCodes.Add((object) "<ProfileCode>");
        GCodes.AddRange((ICollection) AL);
        GCodes.Add((object) "</ProfileCode>");
      }
    }
    if (Profile == null)
      return;
    if (Mode == "KabanMode1")
    {
      if (!Profile.IsClamperDone && !this.doCalculateAll(ref Profile, true, true, false))
        return;
      string GCodeStr = "";
      ProfileTempVars.LastClampers.Clear();
      if (CreateGCode)
      {
        buEyeBaseVer5.Apps.ProfileItem profileItem = new buEyeBaseVer5.Apps.ProfileItem(Profile);
        this.doAddSupportBlockOffsets(ref profileItem);
        this.doCreateJobKabanMode1(ref profileItem, ref GCodeStr, ProfileIndex, SecondAvailable, CreateGCode);
      }
      else
        this.doCreateJobKabanMode1(ref Profile, ref GCodeStr, ProfileIndex, SecondAvailable, CreateGCode);
      buString5.SplitStringByNewLine(GCodeStr, ref GCodes);
      if (buProfileCalc.varProfileSettings.ParabolicMoveBetweenPlanes)
      {
        for (int index = GCodes.Count - 1; index >= 0; --index)
        {
          if (index > 0 && GCodes[index].ToString().IndexOf("M28") >= 0 && GCodes[index - 1].ToString().IndexOf("M28") >= 0)
          {
            if (GCodes[index - 1].ToString().IndexOf("X") >= 0)
              GCodes.RemoveAt(index);
            else
              GCodes.RemoveAt(index - 1);
          }
        }
      }
      ArrayList AL = new ArrayList();
      this.SaveProfileJobFile(this.activeProfile, ref AL);
    }
    if (Mode == "KabanMode2")
    {
      if (!Profile.IsClamperDone && !this.doCalculateAll(ref Profile, true, true, false))
        return;
      string GCodeStr = "";
      if (CreateGCode)
      {
        buEyeBaseVer5.Apps.ProfileItem profileItem = new buEyeBaseVer5.Apps.ProfileItem(Profile);
        this.doAddSupportBlockOffsets(ref profileItem);
        this.doCreateJobKabanMode2(ref profileItem, ref GCodeStr, ProfileIndex, SecondAvailable, CreateGCode);
      }
      else
        this.doCreateJobKabanMode2(ref Profile, ref GCodeStr, ProfileIndex, SecondAvailable, CreateGCode);
      buString5.SplitStringByNewLine(GCodeStr, ref GCodes);
      ArrayList AL = new ArrayList();
      this.SaveProfileJobFile(this.activeProfile, ref AL);
    }
    if (Profile == null)
      return;
    if (Profile != null && Profile.MaxClamperNumber != buProfileCalc.varProfileSettings.ProfileMaxClamper)
      Profile.MaxClamperNumber = buProfileCalc.varProfileSettings.ProfileMaxClamper;
    if (!(Mode == "InfiniteMode1") || !Profile.IsClamperDone && !this.doCalculateAll(ref Profile, true, true, false))
      return;
    string GCodeStr1 = "";
    if (CreateGCode)
    {
      buEyeBaseVer5.Apps.ProfileItem profileItem = new buEyeBaseVer5.Apps.ProfileItem(Profile);
      this.doAddSupportBlockOffsets(ref profileItem);
      this.doCreateJobInfiniteMode1(ref profileItem, ref GCodeStr1, ProfileIndex, SecondAvailable, CreateGCode);
    }
    else
      this.doCreateJobInfiniteMode1(ref Profile, ref GCodeStr1, ProfileIndex, SecondAvailable, CreateGCode);
    buString5.SplitStringByNewLine(GCodeStr1, ref GCodes);
    GCodes.Insert(0, (object) "<GCodes>");
    GCodes.Add((object) "</GCodes>");
    if (ShowCode)
      return;
    ArrayList AL1 = new ArrayList();
    this.SaveProfileJobFile(this.activeProfile, ref AL1);
    GCodes.Add((object) " ");
    GCodes.Add((object) "<ProfileCode>");
    GCodes.AddRange((ICollection) AL1);
    GCodes.Add((object) "</ProfileCode>");
  }

  public void doSetMissingClampers(
    ref buEyeBaseVer5.Apps.ProfileItem FirstItem,
    ref buEyeBaseVer5.Apps.ProfileItem SecondItem,
    bool GCodeSim = true)
  {
    if (FirstItem != null & SecondItem != null)
    {
      List<buEyeBaseVer5.Apps.ProfileClamper> profileClamperList1 = new List<buEyeBaseVer5.Apps.ProfileClamper>();
      if (FirstItem.CalculationData.Count > 0)
      {
        ProfileItemCalc profileItemCalc = FirstItem.CalculationData[FirstItem.CalculationData.Count - 1];
        if (profileItemCalc.calcOperations.Count > 0)
        {
          GProfileOperation calcOperation = profileItemCalc.calcOperations[profileItemCalc.calcOperations.Count - 1];
          if (calcOperation.Clampers.Count > 0)
          {
            for (int index = 0; index <= calcOperation.Clampers.Count - 1; ++index)
              profileClamperList1.Add(new buEyeBaseVer5.Apps.ProfileClamper(calcOperation.Clampers[index]));
          }
        }
      }
      List<buEyeBaseVer5.Apps.ProfileClamper> profileClamperList2 = new List<buEyeBaseVer5.Apps.ProfileClamper>();
      if (SecondItem.CalculationData.Count > 0)
      {
        ProfileItemCalc profileItemCalc = SecondItem.CalculationData[0];
        if (profileItemCalc.calcOperations.Count > 0)
        {
          GProfileOperation calcOperation = profileItemCalc.calcOperations[0];
          if (calcOperation.Clampers.Count > 0)
          {
            for (int index = 0; index <= calcOperation.Clampers.Count - 1; ++index)
              profileClamperList2.Add(new buEyeBaseVer5.Apps.ProfileClamper(calcOperation.Clampers[index]));
          }
        }
      }
      for (int index1 = 0; index1 <= FirstItem.CalculationData.Count - 1; ++index1)
      {
        for (int index2 = 0; index2 <= FirstItem.CalculationData[index1].calcOperations.Count - 1; ++index2)
        {
          GProfileOperation calcOperation = FirstItem.CalculationData[index1].calcOperations[index2];
          for (int index3 = 0; index3 <= profileClamperList2.Count - 1; ++index3)
          {
            if (calcOperation.Clampers.Count < buProfileCalc.varProfileSettings.ProfileMaxClamper)
            {
              calcOperation.Clampers.Add(new buEyeBaseVer5.Apps.ProfileClamper(profileClamperList2[index3]));
              FirstItem.isGCodeSimMoveCreated = false;
              SecondItem.isGCodeSimMoveCreated = false;
            }
          }
        }
      }
      for (int index4 = 0; index4 <= SecondItem.CalculationData.Count - 1; ++index4)
      {
        for (int index5 = 0; index5 <= SecondItem.CalculationData[index4].calcOperations.Count - 1; ++index5)
        {
          GProfileOperation calcOperation = SecondItem.CalculationData[index4].calcOperations[index5];
          for (int index6 = 0; index6 <= profileClamperList1.Count - 1; ++index6)
          {
            if (calcOperation.Clampers.Count < buProfileCalc.varProfileSettings.ProfileMaxClamper)
            {
              calcOperation.Clampers.Insert(index6, new buEyeBaseVer5.Apps.ProfileClamper(profileClamperList1[index6]));
              FirstItem.isGCodeSimMoveCreated = false;
              SecondItem.isGCodeSimMoveCreated = false;
            }
          }
        }
      }
    }
    if (!GCodeSim)
      return;
    if ((FirstItem == null ? 0 : (FirstItem.CalculationData.Count > 0 ? 1 : 0)) != 0 && !FirstItem.isGCodeSimMoveCreated)
      this.doGCodeToSimulation(ref FirstItem);
    if ((SecondItem == null ? 0 : (SecondItem.CalculationData.Count > 0 ? 1 : 0)) == 0 || SecondItem.isGCodeSimMoveCreated)
      return;
    this.doGCodeToSimulation(ref SecondItem);
  }

  public void doCreateOperation(
    actionTypeBU Action,
    ToolBase5 Tool,
    bool OnlyDrawing,
    bool AutoTool,
    ref buEyeBaseVer5.Apps.ProfileOperation OP)
  {
    buEyeBaseVer5.Apps.ProfileItem profileItem = clsInit.cProfile.SelectActiveProfile(this.activeProfile.FirstItem, this.activeProfile.SecondItem, ref buProfileCalc.varProfileRunSettings.activeProfileIndex);
    if (profileItem == null)
      return;
    if (OP.Tool == null)
      OP.Tool = new ToolBase5(Tool);
    bool flag1 = true;
    bool flag2 = true;
    double FreePlaneYSing = 1.0;
    Point3D point3D1 = buVector5.ToPoint3D(OP.OperationData.Position);
    if (buProfileCalc.varProfileSettings.XDirRefType == LeftRightType.Right)
    {
      point3D1.X = profileItem.Length - OP.OperationData.Position.X;
      if (!buProfileCalc.varProfileSettings.RightProfileMakeAsMirror)
        point3D1.X = OP.OperationData.Position.X;
    }
    if (OP.OperationData.selectedPlaneName == planeNames.Top)
    {
      OP.OperationData.selectedPlane = Plane.XY;
      OP.OperationData.selectedPlane.Translate(OP.OperationData.movePlanePoint.X, OP.OperationData.movePlanePoint.Y, OP.OperationData.movePlanePoint.Z);
    }
    if (OP.OperationData.selectedPlaneName == planeNames.Front)
    {
      OP.OperationData.selectedPlane = Plane.XZ;
      OP.OperationData.selectedPlane.Translate(OP.OperationData.movePlanePoint.X, 0.0, OP.OperationData.movePlanePoint.Z);
    }
    if (OP.OperationData.selectedPlaneName == planeNames.Back)
    {
      OP.OperationData.selectedPlane = Plane.XZ;
      OP.OperationData.selectedPlane.Translate(OP.OperationData.movePlanePoint.X, OP.OperationData.movePlanePoint.Y, OP.OperationData.movePlanePoint.Z);
    }
    if (OP.OperationData.selectedPlaneName == planeNames.Bottom)
    {
      OP.OperationData.selectedPlane = Plane.XY;
      OP.OperationData.selectedPlane.Translate(OP.OperationData.movePlanePoint.X, OP.OperationData.movePlanePoint.Y, OP.OperationData.movePlanePoint.Z);
    }
    OP.OperationData.OperationType = clsInit.cProfile.ProfileActionToOperationType(Action);
    OP.Tool = new ToolBase5(Tool);
    OP.EntityMultiCam = new List<buEntity>();
    OP.EntityMultiContour = new List<buEntity>();
    OP.EntityMultiSolidDepth = new List<Entity>();
    OP.EntityMultiXYPlane = new List<buEntity>();
    OP.EntityDimension = new List<DimensionGroup>();
    List<buEntity> copiedEntities = new List<buEntity>();
    List<buEntity> entContourXY = new List<buEntity>();
    List<List<buEntity>> entCam1 = new List<List<buEntity>>();
    if (ProfileTempVars.CamAssinged)
      OP.CamAssinged = true;
    camTp Cam = new camTp();
    MWCalculationOptions MWCalcoptions = new MWCalculationOptions();
    if (!OnlyDrawing)
    {
      clsMW.CamEntities.Clear();
      clsMW.CamEntities = new List<Entity>();
      MWCalcoptions.NumberofAxis = 3;
      MWCalcoptions.CamWireframeType = CamWireFrameType.Contour;
      MWCalcoptions.Mode = CamMode.WireFrame;
      MWCalcoptions.DontApplyReset = true;
      MWCalcoptions.isBuWireframeCalculation = false;
      MWCalcoptions.AddToCamListInMWCalculation = false;
      MWCalcoptions.DontShowDialogBox = true;
      MWCalcoptions.isBuSort = false;
      MWCalcoptions.UseStartPoint = false;
      MWCalcoptions.UseConstantStartPoint = false;
      MWCalcoptions.StartPointX = 0.0;
      MWCalcoptions.StartPointY = 0.0;
      MWCalcoptions.ShowProgressForm = false;
      clsInit.cMwCalc.Settings.ShowProgressForm = false;
    }
    buEntity Entities1 = (buEntity) null;
    buEntity Entities2 = (buEntity) null;
    if (Action == actionTypeBU.profileRectangle)
    {
      if (OP.OperationData.RectangleData.RectangleRadius == 0.0 & OP.OperationData.RectangleData.RectangleChamfer == 0.0)
      {
        Entities1 = buEntity.Copy((Entity) CompositeCurve.CreateRectangle(OP.OperationData.selectedPlane, 0.0, 0.0, OP.OperationData.RectangleData.RectangleWidth, OP.OperationData.RectangleData.RectangleHeight, buConversion5.DegreeToRadian(OP.OperationData.RectangleData.RectangleAngle), true));
        Entities2 = buEntity.Copy((Entity) CompositeCurve.CreateRectangle(Plane.XY, 0.0, 0.0, OP.OperationData.RectangleData.RectangleWidth, OP.OperationData.RectangleData.RectangleHeight, buConversion5.DegreeToRadian(OP.OperationData.RectangleData.RectangleAngle), true));
      }
      else if (OP.OperationData.RectangleData.RectangleRadius > 0.0)
      {
        Entities1 = buEntity.Copy((Entity) CompositeCurve.CreateRoundedRectangle(OP.OperationData.selectedPlane, 0.0, 0.0, OP.OperationData.RectangleData.RectangleWidth, OP.OperationData.RectangleData.RectangleHeight, OP.OperationData.RectangleData.RectangleRadius, buConversion5.DegreeToRadian(OP.OperationData.RectangleData.RectangleAngle), true));
        Entities2 = buEntity.Copy((Entity) CompositeCurve.CreateRoundedRectangle(Plane.XY, 0.0, 0.0, OP.OperationData.RectangleData.RectangleWidth, OP.OperationData.RectangleData.RectangleHeight, OP.OperationData.RectangleData.RectangleRadius, buConversion5.DegreeToRadian(OP.OperationData.RectangleData.RectangleAngle), true));
      }
    }
    if (Action == actionTypeBU.profileSlot && OP.OperationData.SlotData.SlotWidth > 0.0 & OP.OperationData.SlotData.SlotDiameter > 0.0)
    {
      Entities1 = buEntity.Copy((Entity) CompositeCurve.CreateSlot(OP.OperationData.selectedPlane, 0.0, 0.0, OP.OperationData.SlotData.SlotWidth - OP.OperationData.SlotData.SlotDiameter, OP.OperationData.SlotData.SlotDiameter / 2.0, buConversion5.DegreeToRadian(OP.OperationData.SlotData.SlotAngle), true));
      Entities2 = buEntity.Copy((Entity) CompositeCurve.CreateSlot(Plane.XY, 0.0, 0.0, OP.OperationData.SlotData.SlotWidth - OP.OperationData.SlotData.SlotDiameter, OP.OperationData.SlotData.SlotDiameter / 2.0, buConversion5.DegreeToRadian(OP.OperationData.SlotData.SlotAngle), true));
    }
    if (Action == actionTypeBU.profileCut)
    {
      Entities1 = buEntity.Copy((Entity) CompositeCurve.CreateRectangle(OP.OperationData.selectedPlane, 0.0, 0.0, OP.OperationData.CutData.CutWidth, OP.OperationData.CutData.CutHeigth, buConversion5.DegreeToRadian(OP.OperationData.CutData.CutAngle), true));
      Entities2 = buEntity.Copy((Entity) CompositeCurve.CreateRectangle(Plane.XY, 0.0, 0.0, OP.OperationData.CutData.CutWidth, OP.OperationData.CutData.CutHeigth, buConversion5.DegreeToRadian(OP.OperationData.CutData.CutAngle), true));
    }
    if (Action == actionTypeBU.profileCircle && OP.OperationData.CircleData.CircleDiameter > 0.0)
    {
      Entities1 = buEntity.Copy((Entity) new Circle(OP.OperationData.selectedPlane, OP.OperationData.CircleData.CircleDiameter / 2.0));
      Entities2 = (buEntity) new buCircle(Plane.XY, OP.OperationData.CircleData.CircleDiameter / 2.0);
    }
    if (Action == actionTypeBU.profilePolygon)
    {
      if (OP.OperationData.selectedPlaneName != planeNames.Free)
      {
        List<Point3D> Vertices = new List<Point3D>();
        clsInit.cVector5.PolygonCenter(new Point3D(), OP.OperationData.PolygonData.PolygonDiameter / 2.0, OP.OperationData.PolygonData.PolygonSide, OP.OperationData.selectedPlane, ref Vertices);
        LinearPath linearPath1 = new LinearPath((ICollection<Point3D>) Vertices);
        linearPath1.Rotate(buConversion5.DegreeToRadian(OP.OperationData.PolygonData.PolygonAngle), OP.OperationData.selectedPlane.AxisZ);
        Entities1 = buEntity.Copy((Entity) new CompositeCurve((IEnumerable<ICurve>) new List<ICurve>()
        {
          (ICurve) linearPath1
        }));
        Vertices = new List<Point3D>();
        clsInit.cVector5.PolygonCenter(new Point3D(), OP.OperationData.PolygonData.PolygonDiameter / 2.0, OP.OperationData.PolygonData.PolygonSide, Plane.XY, ref Vertices);
        LinearPath linearPath2 = new LinearPath((ICollection<Point3D>) Vertices);
        linearPath2.Rotate(buConversion5.DegreeToRadian(OP.OperationData.PolygonData.PolygonAngle), Vector3D.AxisZ);
        Entities2 = buEntity.Copy((Entity) new CompositeCurve((IEnumerable<ICurve>) new List<ICurve>()
        {
          (ICurve) linearPath2
        }));
      }
      else
      {
        List<Point3D> points = new List<Point3D>();
        clsInit.cVector5.PolygonCenter(new Point3D(), OP.OperationData.PolygonData.PolygonDiameter / 2.0, OP.OperationData.PolygonData.PolygonSide, Plane.XY, ref points);
        clsInit.cVector5.Rotate(new Point3D(), OP.OperationData.PolygonData.PolygonAngle, Plane.XY, ref points);
        buLinearPath buLinearPath1 = new buLinearPath(points);
        entContourXY.Add((buEntity) buLinearPath1);
        points = new List<Point3D>();
        clsInit.cVector5.PolygonCenter(new Point3D(), OP.OperationData.PolygonData.PolygonDiameter / 2.0, OP.OperationData.PolygonData.PolygonSide, Plane.XY, ref points);
        clsInit.cVector5.Rotate(new Point3D(), OP.OperationData.PolygonData.PolygonAngle, Plane.XY, ref points);
        buLinearPath buLinearPath2 = new buLinearPath(OP.OperationData.selectedPlane, points);
        copiedEntities.Add((buEntity) buLinearPath2);
      }
    }
    if (Action == actionTypeBU.profileEllipse)
    {
      Ellipse refEntity = new Ellipse(OP.OperationData.selectedPlane, OP.OperationData.EllipseData.EllipseWidth / 2.0, OP.OperationData.EllipseData.EllipseHeight / 2.0);
      refEntity.Regen(0.01);
      refEntity.Rotate(buConversion5.DegreeToRadian(OP.OperationData.EllipseData.EllipseAngle), OP.OperationData.selectedPlane.AxisZ, refEntity.Center);
      Entities1 = buEntity.Copy((Entity) refEntity);
      Entities2 = (buEntity) new buEllipse(Plane.XY, OP.OperationData.EllipseData.EllipseWidth / 2.0, OP.OperationData.EllipseData.EllipseHeight / 2.0);
      Entities2.Rotate(OP.OperationData.EllipseData.EllipseAngle, new Vector3D(0.0, 0.0, 1.0));
    }
    if (Action == actionTypeBU.profileBarrel)
    {
      eArc HeadArc = new eArc();
      eArc TaleArc = new eArc();
      eLine FirstLine = new eLine();
      eLine SecondLine = new eLine();
      double num = OP.OperationData.BarelData.BarrelDiameter / 2.0 + OP.OperationData.BarelData.BarrelWidth / 2.0;
      if (!clsInit.cVector.Barrel(new Pnt3D(), OP.OperationData.BarelData.BarrelDiameter / 2.0, (OP.OperationData.BarelData.BarrelWidth + 0.01) / 2.0, OP.OperationData.BarelData.BarrelLength - num, 0.0, false, new WorkPlane(), new EntityResolution(), ref HeadArc, ref TaleArc, ref FirstLine, ref SecondLine))
        buString5.MessageBoxWarning(buProfile.LangProfileMessage[40]);
      List<buEntity> RefEntities1 = new List<buEntity>();
      RefEntities1.Add((buEntity) new buArc(buConversion5.Pnt3DToPoint3D(HeadArc.CenterPoint), HeadArc.Radius, HeadArc.StartAngle, HeadArc.EndAngle));
      RefEntities1.Add((buEntity) new buLine(buConversion5.Pnt3DToPoint3D(FirstLine.StartPoint), buConversion5.Pnt3DToPoint3D(FirstLine.EndPoint)));
