          {
            double disMoveX = (double) index12 * num3;
            double totDepth = 0.0;
            if (copiedEntities.Count > 0)
            {
              this.doCreateOperationDraw3D(copiedEntities, profileItem, totDepth, FreePlaneYSing, point3D1, disMoveX, disMoveY, disMoveZ, calcDepth, IndexRepeat, ref pntLastMoved, ref entCam1, ref OP);
              for (int index13 = 0; index13 <= entCam1.Count - 1; ++index13)
              {
                List<buEntity> entCam2 = new List<buEntity>();
                entCam2.AddRange((IEnumerable<buEntity>) entCam1[index13]);
                for (int index14 = 0; index14 <= calcDepth.Count - 1; ++index14)
                {
                  Vector3D VecTranslate = (Vector3D) null;
