              tool3 = new ToolBase5(ccVars.Tools[index11].Tools[index12]);
          }
        }
        if (tool3 != null)
        {
          if (tool3.Data.Name != OP.ToolNotch.Data.Name)
          {
            OP.Tool = new ToolBase5(tool3);
            this.cntCreateOperation = 0;
          }
        }
        else
          OP.Tool = tool3;
      }
      ToolBase5 tool4 = (ToolBase5) null;
      for (int index13 = 0; index13 <= ccVars.Tools.Count - 1; ++index13)
      {
        for (int index14 = 0; index14 <= ccVars.Tools[index13].Tools.Count - 1; ++index14)
        {
          double num = ccVars.Tools[index13].Tools[index14].Geometry.Diameter / 2.0 - buProfileCalc.varProfileSettings.ToolPensDiameter / 2.0 - 2.0;
          if (OP.OperationData.CamParNotch.Notch.NotchCutType == ProfileNotchCutType.BySaw && OP.OperationData.NotchData.NotchStart == 0.0 & OP.OperationData.NotchData.NotchOPType == ProfileNotchOperationType.Side & OP.OperationData.NotchData.NotchUpDown == UpDownLocationType.Up)
            num = ccVars.Tools[index13].Tools[index14].Geometry.Diameter * 1.0;
          if (num > profileOperationNotch.OperationData.NotchData.NotchDepth & ccVars.Tools[index13].Tools[index14].Geometry.GeometryType == ToolType.Saw)
            tool4 = new ToolBase5(ccVars.Tools[index13].Tools[index14]);
        }
      }
      if (tool4 != null)
      {
        if (!(tool4.Data.Name != OP.ToolNotch.Data.Name))
          return;
        OP.ToolNotch = new ToolBase5(tool4);
        ToolFound = new ToolBase5(tool4);
        this.cntCreateOperation = 0;
      }
      else
        OP.ToolNotch = tool4;
    }
  }

  public void doCreateOperationCam(
    buEyeBaseVer5.Apps.ProfileItem curItem,
    bool OnlyDrawing,
    MWCalculationOptions MWCalcoptions,
    actionTypeBU Action,
    List<buEntity> entContour,
    List<buEntity> entContourXY,
    ref buEyeBaseVer5.Apps.ProfileOperation OP,
    ref List<List<buEntity>> entCam,
    ref camTp Cam)
  {
    bool G1Original = false;
    if (OP.OperationData.selectedPlaneName == planeNames.Top | OP.OperationData.selectedPlaneName == planeNames.Bottom)
      G1Original = true;
    if (buProfileCalc.varProfileSettings.AllGCodeAsG1)
      G1Original = false;
    if (OP.OperationData.OperationType == ProfileOperationTypes.Notch)
    {
      if (OP.ToolNotch == null)
        return;
    }
    else if (OP.OperationData.OperationType == ProfileOperationTypes.Tapping)
    {
      if (OP.Tool == null | OP.ToolAux == null)
        return;
    }
    else if (OP.Tool == null)
      return;
    if (OnlyDrawing || entContourXY == null)
      return;
    switch (Action)
    {
      case actionTypeBU.profileHole:
        if (entContourXY.Count <= 0 || !(entContour[0] is buCircle))
          break;
        buEntity buEntity1 = (buEntity) new buPoint((entContour[0] as buCircle).Center);
        buEntity1.typeDefination = entityTypeDefination.CamDrill;
        entCam.Add(new List<buEntity>() { buEntity1 });
        break;
      case actionTypeBU.profileNotch:
        clsInit.cProfile.NotchCalc(ref OP, ref Cam, curItem, ccVars.Tools[0].Tools, buProfileCalc.varProfileSettings);
        List<buEntity> buEntityList1 = new List<buEntity>();
        TpPnt9D tpPnt9D = new TpPnt9D();
        for (int index1 = 0; index1 <= OP.CamCalculation.Count - 1; ++index1)
        {
          List<buEntity> buEntityList2 = new List<buEntity>();
          double x = 0.0;
          double y = 0.0;
          double z = 0.0;
          if (OP.CamCalculation[index1].Tool.Geometry.GeometryType == ToolType.Saw)
          {
            if (OP.OperationData.NotchData.NotchLocation == ProfileNotchLocationType.Left)
              x = OP.CamCalculation[index1].Tool.Geometry.Diameter / 2.0;
            if (OP.OperationData.NotchData.NotchLocation == ProfileNotchLocationType.Right)
              x = -OP.CamCalculation[index1].Tool.Geometry.Diameter / 2.0;
            if (OP.OperationData.NotchData.NotchLocation == ProfileNotchLocationType.Front)
              y = OP.CamCalculation[index1].Tool.Geometry.Diameter / 2.0;
            if (OP.OperationData.NotchData.NotchLocation == ProfileNotchLocationType.Back)
              y = -OP.CamCalculation[index1].Tool.Geometry.Diameter / 2.0;
          }
          if (index1 == OP.CamCalculation.Count - 1 & OP.OperationData.CamParNotch.Notch.NotchCutType == ProfileNotchCutType.BySawAndMilling && OP.OperationData.NotchData.NotchUpDown == UpDownLocationType.Up & OP.OperationData.NotchData.NotchStart == 0.0)
          {
            x = 0.0;
            y = 0.0;
          }
          if (OP.OperationData.NotchData.NotchOPType == ProfileNotchOperationType.Horizontal)
          {
            x = 0.0;
            if (OP.CamCalculation[index1].Tool.Geometry.GeometryType == ToolType.Saw)
              z = -OP.ToolNotch.Geometry.Diameter / 2.0;
          }
          for (int index2 = 0; index2 <= OP.CamCalculation[index1].CamPoints.Count - 1; ++index2)
          {
            for (int index3 = 1; index3 <= OP.CamCalculation[index1].CamPoints[index2].Points.Count - 1; ++index3)
            {
              TpPnt9D point1 = OP.CamCalculation[index1].CamPoints[index2].Points[index3 - 1];
              TpPnt9D point2 = OP.CamCalculation[index1].CamPoints[index2].Points[index3];
              if (index2 > 0 & index3 == 1 & !buCompare5.EQ(tpPnt9D, point1))
              {
                buLine buLine = new buLine(new Point3D(tpPnt9D.P9.X, tpPnt9D.P9.Y, tpPnt9D.P9.Z), new Point3D(point1.P9.X, point1.P9.Y, point1.P9.Z));
                buLine.Orientation.A = point1.P9.A;
                buLine.typeDefination = entityTypeDefination.CamG0;
                buLine.Info.Offset = new Point3D(x, y, z);
                buEntityList2.Add((buEntity) buLine);
              }
              if (point2.MoveType == CamMoveType.G0)
              {
                if (!buCompare5.EQ(point1, point2))
                {
                  buLine buLine = new buLine(new Point3D(point1.P9.X, point1.P9.Y, point1.P9.Z), new Point3D(point2.P9.X, point2.P9.Y, point2.P9.Z));
                  buLine.Orientation.A = point1.P9.A;
                  buLine.typeDefination = entityTypeDefination.CamG0;
                  buLine.Info.Offset = new Point3D(x, y, z);
                  buEntityList2.Add((buEntity) buLine);
                  tpPnt9D = new TpPnt9D(OP.CamCalculation[index1].CamPoints[index2].Points[index3]);
                }
              }
              else if (point2.MoveType == CamMoveType.G1)
              {
                if (!buCompare5.EQ(point1, point2))
                {
                  buLine buLine = new buLine(new Point3D(point1.P9.X, point1.P9.Y, point1.P9.Z), new Point3D(point2.P9.X, point2.P9.Y, point2.P9.Z));
                  buLine.Orientation.A = point1.P9.A;
                  buLine.typeDefination = entityTypeDefination.CamG1;
                  buLine.Info.Offset = new Point3D(x, y, z);
                  buEntityList2.Add((buEntity) buLine);
                  tpPnt9D = new TpPnt9D(OP.CamCalculation[index1].CamPoints[index2].Points[index3]);
                }
              }
              else if (point2.MoveType == CamMoveType.Plunge)
              {
                if (!buCompare5.EQ(point1, point2))
                {
                  buLine buLine = new buLine(new Point3D(point1.P9.X, point1.P9.Y, point1.P9.Z), new Point3D(point2.P9.X, point2.P9.Y, point2.P9.Z));
                  buLine.Orientation.A = point1.P9.A;
                  buLine.typeDefination = entityTypeDefination.CamPlunge;
                  buLine.Info.CamPlungeAxis = "X";
                  if (!buCompare5.EQ(point2.P9.Z, point1.P9.Z) & buCompare5.EQ(point2.P9.X, point1.P9.X))
                    buLine.Info.CamPlungeAxis = "Z";
                  buLine.Info.Offset = new Point3D(x, y, z);
                  buEntityList2.Add((buEntity) buLine);
                  tpPnt9D = new TpPnt9D(OP.CamCalculation[index1].CamPoints[index2].Points[index3]);
                }
              }
              else if (point2.MoveType == CamMoveType.Leave)
              {
                if (!buCompare5.EQ(point1, point2))
                {
                  buLine buLine = new buLine(new Point3D(point1.P9.X, point1.P9.Y, point1.P9.Z), new Point3D(point2.P9.X, point2.P9.Y, point2.P9.Z));
                  buLine.Orientation.A = point1.P9.A;
                  buLine.typeDefination = entityTypeDefination.CamLeave;
                  buLine.Info.CamLeaveAxis = "X";
                  if (!buCompare5.EQ(point2.P9.Z, point1.P9.Z) & buCompare5.EQ(point2.P9.X, point1.P9.X))
                    buLine.Info.CamLeaveAxis = "Z";
                  buLine.Info.Offset = new Point3D(x, y, z);
                  buEntityList2.Add((buEntity) buLine);
                  tpPnt9D = new TpPnt9D(OP.CamCalculation[index1].CamPoints[index2].Points[index3]);
                }
              }
              else if (!buCompare5.EQ(point1, point2))
              {
                buLine buLine = new buLine(new Point3D(point1.P9.X, point1.P9.Y, point1.P9.Z), new Point3D(point2.P9.X, point2.P9.Y, point2.P9.Z));
                buLine.Orientation.A = point1.P9.A;
                buLine.typeDefination = entityTypeDefination.CamOther;
                buLine.Info.Offset = new Point3D(x, y, z);
                buEntityList2.Add((buEntity) buLine);
                tpPnt9D = new TpPnt9D(OP.CamCalculation[index1].CamPoints[index2].Points[index3]);
              }
            }
          }
          entCam.Add(buEntityList2);
        }
        break;
      case actionTypeBU.profileCut:
        if (entContour.Count <= 0)
          break;
        Point3D EndPnt1 = new Point3D();
        Point3D EndPnt2 = new Point3D();
        clsInit.cVector5.LineWithLengthAndAngle(new Point3D(0.0, 0.0, 0.0), OP.OperationData.CutData.CutHeigth / 2.0, OP.OperationData.CutData.CutAngle + 90.0, ref EndPnt1);
        clsInit.cVector5.LineWithLengthAndAngle(new Point3D(0.0, 0.0, 0.0), OP.OperationData.CutData.CutHeigth / 2.0, OP.OperationData.CutData.CutAngle - 90.0, ref EndPnt2);
        buEntity buEntity2 = (buEntity) new buLine(OP.OperationData.selectedPlane, EndPnt2, EndPnt1);
        buEntity2.typeDefination = entityTypeDefination.CamG1;
        entCam.Add(new List<buEntity>() { buEntity2 });
        break;
      case actionTypeBU.profileTapping:
        if (entContourXY.Count <= 0 || !(entContour[0] is buCircle))
          break;
        buEntity buEntity3 = (buEntity) new buPoint((entContour[0] as buCircle).Center);
        buEntity3.typeDefination = entityTypeDefination.CamDrill;
        entCam.Add(new List<buEntity>() { buEntity3 });
        break;
      default:
        clsMW.CamEntities.Clear();
        bool flag = false;
        if (Action == actionTypeBU.profileSlot && buCompare5.EQ(OP.OperationData.SlotData.SlotDiameter, OP.Tool.Geometry.Diameter, 0.01))
        {
          devDept.Eyeshot.Entities.Line line = new devDept.Eyeshot.Entities.Line(new Point3D(-OP.OperationData.SlotData.SlotWidth / 2.0 + OP.OperationData.SlotData.SlotDiameter / 2.0, 0.0), new Point3D(OP.OperationData.SlotData.SlotWidth / 2.0 - OP.OperationData.SlotData.SlotDiameter / 2.0, 0.0));
          if (OP.OperationData.SlotData.SlotAngle != 0.0)
            line.Rotate(buConversion5.DegreeToRadian(OP.OperationData.SlotData.SlotAngle), Vector3D.AxisZ);
          clsMW.CamEntities.Add((Entity) line);
          flag = true;
        }
        if (!flag)
        {
          for (int index = 0; index <= entContourXY.Count - 1; ++index)
          {
            buEntity refEntity = buVector5.CopyEntities(entContourXY[index]);
            if (refEntity.GetType() == typeof (buCircle))
            {
              Arc arc1 = new Arc(((buCircle) refEntity).Center, ((buCircle) refEntity).Radius, buConversion5.DegreeToRadian(0.0), buConversion5.DegreeToRadian(90.0));
              Arc arc2 = new Arc(((buCircle) refEntity).Center, ((buCircle) refEntity).Radius, buConversion5.DegreeToRadian(90.0), buConversion5.DegreeToRadian(180.0));
              Arc arc3 = new Arc(((buCircle) refEntity).Center, ((buCircle) refEntity).Radius, buConversion5.DegreeToRadian(180.0), buConversion5.DegreeToRadian(270.0));
              Arc arc4 = new Arc(((buCircle) refEntity).Center, ((buCircle) refEntity).Radius, buConversion5.DegreeToRadian(270.0), buConversion5.DegreeToRadian(360.0));
              clsMW.CamEntities.Add((Entity) arc1);
              clsMW.CamEntities.Add((Entity) arc2);
              clsMW.CamEntities.Add((Entity) arc3);
              clsMW.CamEntities.Add((Entity) arc4);
            }
            else
            {
              Entity copiedEntity = (Entity) null;
              buEntity.Copy(refEntity, ref copiedEntity);
              if (copiedEntity != null)
              {
                copiedEntity.Regen(0.01);
                clsMW.CamEntities.Add(copiedEntity);
              }
            }
          }
        }
        if (clsMW.CamEntities.Count <= 0)
          break;
        CamEntitiesTobuEntities calcEntities1 = new CamEntitiesTobuEntities();
        if (OP.OperationData.CamParMilling.Operations.AreaClearanceEnable)
        {
          MWCalcoptions.CamWireframeType = CamWireFrameType.Pocket;
          this.doWireframeRough(MWCalcoptions, OP.OperationData.CamParMilling, OP.Tool, ref Cam);
          if (Cam.CamPoints.Count == 0)
            OP.errorList.Add(buProfile.LangProfileMessage[15]);
          clsInit.appMW.CamEntitesTobuEntities(Cam, new CamEntitiesToEntitiesOption(false, true, true, true, G1Original), ref calcEntities1);
          List<buEntity> buEntityList3 = new List<buEntity>();
          for (int index = 0; index <= calcEntities1.G1Entities.Count - 1; ++index)
          {
            buEntity entityPlane = clsInit.cVector5.EntityXYToEntityPlane(calcEntities1.G1Entities[index], OP.OperationData.selectedPlane);
            entityPlane.Info.CamSpeed = calcEntities1.G1Entities[index].Info.CamSpeed;
            entityPlane.typeDefination = entityTypeDefination.CamWireframePocket;
            buEntityList3.Add(entityPlane);
          }
          entCam.Add(buEntityList3);
          List<buEntity> buEntityList4 = new List<buEntity>();
          if (!OP.OperationData.CamParMilling.Operations.FinishEnable)
            break;
          MWCalcoptions.CamWireframeType = CamWireFrameType.Contour;
          camParameters5 OPCamParameter = new camParameters5(OP.OperationData.CamParMilling);
          OPCamParameter.Speeds.Feed = OP.OperationData.CamParMilling.Speeds.Finish;
          OPCamParameter.Offsets.AdditionalOffset = OP.OperationData.CamParMilling.Offsets.FinishOffset;
          if (buProfileCalc.varProfileSettings.ChangeCwCCWDirForRightRefProfile && curItem.XReferanceLocation == LeftRightType.Right)
            OPCamParameter.Operations.Direction = OPCamParameter.Operations.Direction != ClockDirectionType.CCW ? ClockDirectionType.CCW : ClockDirectionType.CW;
          this.doWireframeContour(MWCalcoptions, OPCamParameter, OP.Tool, ref Cam);
          if (Cam.CamPoints.Count == 0)
            OP.errorList.Add(buProfile.LangProfileMessage[15]);
          CamEntitiesTobuEntities calcEntities2 = new CamEntitiesTobuEntities();
          clsInit.appMW.CamEntitesTobuEntities(Cam, new CamEntitiesToEntitiesOption(false, true, true, true, G1Original), ref calcEntities2);
          for (int index = 0; index <= calcEntities2.LeadInEntities.Count - 1; ++index)
          {
            buEntity entityPlane = clsInit.cVector5.EntityXYToEntityPlane(calcEntities2.LeadInEntities[index], OP.OperationData.selectedPlane);
            entityPlane.typeDefination = entityTypeDefination.CamWireframeContour;
            buEntityList4.Add(entityPlane);
          }
          for (int index = 0; index <= calcEntities2.G1Entities.Count - 1; ++index)
          {
            buEntity entityPlane = clsInit.cVector5.EntityXYToEntityPlane(calcEntities2.G1Entities[index], OP.OperationData.selectedPlane);
            entityPlane.Info.CamSpeed = calcEntities2.G1Entities[index].Info.CamSpeed;
            entityPlane.typeDefination = entityTypeDefination.CamWireframeContourFinish;
            buEntityList4.Add(entityPlane);
          }
          for (int index = 0; index <= calcEntities2.LeadOutEntities.Count - 1; ++index)
          {
            buEntity entityPlane = clsInit.cVector5.EntityXYToEntityPlane(calcEntities2.LeadOutEntities[index], OP.OperationData.selectedPlane);
            entityPlane.typeDefination = entityTypeDefination.CamWireframeContour;
            buEntityList4.Add(entityPlane);
          }
          entCam.Add(buEntityList4);
          break;
        }
        MWCalcoptions.CamWireframeType = CamWireFrameType.Contour;
        camParameters5 OPCamParameter1 = new camParameters5(OP.OperationData.CamParMilling);
        if (OP.OperationData.selectedPlaneName == planeNames.Back)
          OPCamParameter1.Operations.Direction = OPCamParameter1.Operations.Direction != ClockDirectionType.CW ? ClockDirectionType.CW : ClockDirectionType.CCW;
        if (buProfileCalc.varProfileSettings.ChangeCwCCWDirForRightRefProfile && curItem.XReferanceLocation == LeftRightType.Right)
          OPCamParameter1.Operations.Direction = OPCamParameter1.Operations.Direction != ClockDirectionType.CCW ? ClockDirectionType.CCW : ClockDirectionType.CW;
        MWCalcoptions.AllowIntercetionCurve = false;
        if (Action == actionTypeBU.profileWireText)
        {
          OPCamParameter1.Offsets.ClosedContour = CamClosedContourType.Center;
          OPCamParameter1.Offsets.OpenContour = CamOpenContourType.Center;
          OPCamParameter1.LeadIn.Enable = false;
          OPCamParameter1.LeadOut.Enable = false;
          MWCalcoptions.AllowIntercetionCurve = true;
        }
        if (!clsInit.cVector5.isEntitiesClosed(clsMW.CamEntities))
        {
          OPCamParameter1.LeadIn.Enable = false;
          OPCamParameter1.LeadOut.Enable = false;
          OPCamParameter1.Operations.Overlap = 0.0;
        }
        this.doWireframeContour(MWCalcoptions, OPCamParameter1, OP.Tool, ref Cam);
        if (Cam.CamPoints.Count == 0)
          OP.errorList.Add(buProfile.LangProfileMessage[15]);
        CamEntitiesTobuEntities calcEntities3 = new CamEntitiesTobuEntities();
        clsInit.appMW.CamEntitesTobuEntities(Cam, new CamEntitiesToEntitiesOption(false, true, true, true, G1Original, true, true), ref calcEntities3);
        List<buEntity> BaseRefEntities = new List<buEntity>();
        for (int index = 0; index <= calcEntities3.LeadInEntities.Count - 1; ++index)
        {
          buEntity entityPlane = clsInit.cVector5.EntityXYToEntityPlane(calcEntities3.LeadInEntities[index], OP.OperationData.selectedPlane);
          entityPlane.typeDefination = entityTypeDefination.CamWireframeContour;
          BaseRefEntities.Add(entityPlane);
        }
        for (int index = 0; index <= calcEntities3.G1Entities.Count - 1; ++index)
        {
          buEntity entityPlane = clsInit.cVector5.EntityXYToEntityPlane(calcEntities3.G1Entities[index], OP.OperationData.selectedPlane);
          entityPlane.typeDefination = entityTypeDefination.CamWireframeContour;
          BaseRefEntities.Add(entityPlane);
        }
        for (int index = 0; index <= calcEntities3.LeadOutEntities.Count - 1; ++index)
        {
          buEntity entityPlane = clsInit.cVector5.EntityXYToEntityPlane(calcEntities3.LeadOutEntities[index], OP.OperationData.selectedPlane);
          entityPlane.typeDefination = entityTypeDefination.CamWireframeContour;
          BaseRefEntities.Add(entityPlane);
        }
        if (BaseRefEntities.Count > 0)
        {
          List<buEntity> SortedEntities = new List<buEntity>();
          SortbuSettings Settings = new SortbuSettings();
          SortbuResult Result = new SortbuResult();
          Settings.Option.IntersectionRules = SortingIntersectionRulesType.FromDrawing;
          Settings.Option.NextGroupRules = SortingNextGroupFindRulesType.ClosestLength;
          Point3D pntStart = new Point3D();
          clsInit.cVector5.GetEntityStartPointByCamDirection(BaseRefEntities[0], ref pntStart);
          clsInit.cVector5.SortEntitiesByRefPoint(pntStart, ref BaseRefEntities, Settings, ref SortedEntities, ref Result);
          clsInit.cVector5.EntitiesSplitByUpperLine(SortedEntities, ref entCam);
          for (int index = 0; index <= entCam.Count - 1; ++index)
          {
            if (clsInit.cVector5.EntitiesClockDirection(entCam[index], OP.OperationData.selectedPlane) != OPCamParameter1.Operations.Direction)
            {
              List<buEntity> ChangedEntities = entCam[index];
              clsInit.cVector5.ChangeEntitiesDirection(ref ChangedEntities);
            }
          }
        }
        List<buEntity> buEntityList5 = new List<buEntity>();
        if (!(OP.OperationData.CamParMilling.Operations.FinishEnable & OP.OperationData.CamParMilling.Offsets.FinishOffset != 0.0))
          break;
        MWCalcoptions.CamWireframeType = CamWireFrameType.Contour;
        camParameters5 OPCamParameter2 = new camParameters5(OP.OperationData.CamParMilling);
        OPCamParameter2.Speeds.Feed = OP.OperationData.CamParMilling.Speeds.Finish;
        OPCamParameter2.Offsets.AdditionalOffset = OP.OperationData.CamParMilling.Offsets.FinishOffset;
        if (buProfileCalc.varProfileSettings.ChangeCwCCWDirForRightRefProfile && curItem.XReferanceLocation == LeftRightType.Right)
          OPCamParameter2.Operations.Direction = OPCamParameter2.Operations.Direction != ClockDirectionType.CCW ? ClockDirectionType.CCW : ClockDirectionType.CW;
        this.doWireframeContour(MWCalcoptions, OPCamParameter2, OP.Tool, ref Cam);
        if (Cam.CamPoints.Count == 0)
          OP.errorList.Add(buProfile.LangProfileMessage[15]);
        CamEntitiesTobuEntities calcEntities4 = new CamEntitiesTobuEntities();
        clsInit.appMW.CamEntitesTobuEntities(Cam, new CamEntitiesToEntitiesOption(false, true, true, true, G1Original), ref calcEntities4);
        for (int index = 0; index <= calcEntities4.LeadInEntities.Count - 1; ++index)
        {
          buEntity entityPlane = clsInit.cVector5.EntityXYToEntityPlane(calcEntities4.LeadInEntities[index], OP.OperationData.selectedPlane);
          entityPlane.typeDefination = entityTypeDefination.CamWireframeContour;
          buEntityList5.Add(entityPlane);
        }
        for (int index = 0; index <= calcEntities4.G1Entities.Count - 1; ++index)
        {
          buEntity entityPlane = clsInit.cVector5.EntityXYToEntityPlane(calcEntities4.G1Entities[index], OP.OperationData.selectedPlane);
          entityPlane.Info.CamSpeed = calcEntities4.G1Entities[index].Info.CamSpeed;
          entityPlane.typeDefination = entityTypeDefination.CamWireframeContourFinish;
          buEntityList5.Add(entityPlane);
        }
        for (int index = 0; index <= calcEntities4.LeadOutEntities.Count - 1; ++index)
        {
          buEntity entityPlane = clsInit.cVector5.EntityXYToEntityPlane(calcEntities4.LeadOutEntities[index], OP.OperationData.selectedPlane);
          entityPlane.typeDefination = entityTypeDefination.CamWireframeContour;
          buEntityList5.Add(entityPlane);
        }
        entCam.Add(buEntityList5);
        break;
    }
  }

  public void doCreateOperationArrayCircular(ref buEyeBaseVer5.Apps.ProfileOperation OP)
  {
  }

  public void doOperationMoveDown()
  {
    buEyeBaseVer5.Apps.ProfileItem profileItem = clsInit.cProfile.SelectActiveProfile(this.activeProfile.FirstItem, this.activeProfile.SecondItem, ref buProfileCalc.varProfileRunSettings.activeProfileIndex);
    if (profileItem == null || !(profileItem.Operations.Count > 0 & buProfileCalc.varProfileRunSettings.activeOPIndex >= 0 & buProfileCalc.varProfileRunSettings.activeOPIndex <= profileItem.Operations.Count - 2))
      return;
    this.bUndoBuffer = true;
    buEyeBaseVer5.Apps.ProfileOperation operation = profileItem.Operations[buProfileCalc.varProfileRunSettings.activeOPIndex];
    profileItem.Operations.RemoveAt(buProfileCalc.varProfileRunSettings.activeOPIndex);
    ++buProfileCalc.varProfileRunSettings.activeOPIndex;
    profileItem.Operations.Insert(buProfileCalc.varProfileRunSettings.activeOPIndex, operation);
    this.ProfileTreeUpdate();
  }

  public void doOperationMoveUp()
  {
    buEyeBaseVer5.Apps.ProfileItem profileItem = clsInit.cProfile.SelectActiveProfile(this.activeProfile.FirstItem, this.activeProfile.SecondItem, ref buProfileCalc.varProfileRunSettings.activeProfileIndex);
    if (profileItem == null || !(profileItem.Operations.Count >= 0 & buProfileCalc.varProfileRunSettings.activeOPIndex > 0 & buProfileCalc.varProfileRunSettings.activeOPIndex <= profileItem.Operations.Count - 1))
      return;
    this.bUndoBuffer = true;
    buEyeBaseVer5.Apps.ProfileOperation operation = profileItem.Operations[buProfileCalc.varProfileRunSettings.activeOPIndex];
    profileItem.Operations.RemoveAt(buProfileCalc.varProfileRunSettings.activeOPIndex);
    --buProfileCalc.varProfileRunSettings.activeOPIndex;
    profileItem.Operations.Insert(buProfileCalc.varProfileRunSettings.activeOPIndex, operation);
    this.ProfileTreeUpdate();
  }

  public void doAddSelectedOperations()
  {
    string callMethod = nameof (doAddSelectedOperations);
    try
    {
      ProfileTempVars.SelectedOperations.Clear();
      if (buProfileCalc.varProfileRunSettings.activeProfileIndex == 0 & this.activeProfile.FirstItem != null)
      {
        for (int index = 0; index <= this.activeProfile.FirstItem.Operations.Count - 1; ++index)
        {
          if (this.activeProfile.FirstItem.Operations[index].Selected)
            ProfileTempVars.SelectedOperations.Add(this.activeProfile.FirstItem.Operations[index]);
        }
      }
      if (buProfileCalc.varProfileRunSettings.activeProfileIndex == 1 & this.activeProfile.SecondItem != null)
      {
        for (int index = 0; index <= this.activeProfile.SecondItem.Operations.Count - 1; ++index)
        {
          if (this.activeProfile.SecondItem.Operations[index].Selected)
            ProfileTempVars.SelectedOperations.Add(this.activeProfile.SecondItem.Operations[index]);
        }
      }
      ProfileTempVars.MultiSelectedProps.AllSamePlane = false;
      ProfileTempVars.MultiSelectedProps.AllSameShape = false;
      ProfileTempVars.MultiSelectedProps.AllSameSize = false;
      if (ProfileTempVars.SelectedOperations.Count < 2)
        return;
      ProfileTempVars.MultiSelectedProps.AllSamePlane = true;
      ProfileTempVars.MultiSelectedProps.AllSameShape = true;
      for (int index1 = 0; index1 <= ProfileTempVars.SelectedOperations.Count - 1; ++index1)
      {
        for (int index2 = index1 + 1; index2 <= ProfileTempVars.SelectedOperations.Count - 1; ++index2)
        {
          if (ProfileTempVars.SelectedOperations[index1].OperationData.selectedPlaneName != ProfileTempVars.SelectedOperations[index2].OperationData.selectedPlaneName)
            ProfileTempVars.MultiSelectedProps.AllSamePlane = false;
          if (ProfileTempVars.SelectedOperations[index1].OperationData.OperationType != ProfileTempVars.SelectedOperations[index2].OperationData.OperationType)
            ProfileTempVars.MultiSelectedProps.AllSameShape = false;
        }
      }
      if (!ProfileTempVars.MultiSelectedProps.AllSameShape)
        return;
      ProfileTempVars.MultiSelectedProps.AllSameSize = true;
      ProfileOperationTypes operationType = ProfileTempVars.SelectedOperations[0].OperationData.OperationType;
      double num1 = 0.0;
      double num2 = 0.0;
      double num3 = 0.0;
      switch (operationType)
      {
        case ProfileOperationTypes.Circle:
          num1 = ProfileTempVars.SelectedOperations[0].OperationData.CircleData.CircleDiameter;
          break;
        case ProfileOperationTypes.Rectangle:
          num1 = ProfileTempVars.SelectedOperations[0].OperationData.RectangleData.RectangleWidth;
          num2 = ProfileTempVars.SelectedOperations[0].OperationData.RectangleData.RectangleHeight;
          break;
        case ProfileOperationTypes.Barrel:
          num1 = ProfileTempVars.SelectedOperations[0].OperationData.BarelData.BarrelLength;
          num2 = ProfileTempVars.SelectedOperations[0].OperationData.BarelData.BarrelWidth;
          num3 = ProfileTempVars.SelectedOperations[0].OperationData.BarelData.BarrelDiameter;
          break;
        case ProfileOperationTypes.Ellipse:
          num1 = ProfileTempVars.SelectedOperations[0].OperationData.EllipseData.EllipseWidth;
          num2 = ProfileTempVars.SelectedOperations[0].OperationData.EllipseData.EllipseHeight;
          break;
        case ProfileOperationTypes.Hole:
          num1 = ProfileTempVars.SelectedOperations[0].OperationData.HoleData.HoleDiameter;
          break;
        case ProfileOperationTypes.Slot:
          num1 = ProfileTempVars.SelectedOperations[0].OperationData.SlotData.SlotWidth;
          num2 = ProfileTempVars.SelectedOperations[0].OperationData.SlotData.SlotDiameter;
          break;
        case ProfileOperationTypes.Cut:
          num1 = ProfileTempVars.SelectedOperations[0].OperationData.CutData.CutWidth;
          num2 = ProfileTempVars.SelectedOperations[0].OperationData.CutData.CutHeigth;
          break;
        case ProfileOperationTypes.Polygon:
          num1 = ProfileTempVars.SelectedOperations[0].OperationData.PolygonData.PolygonDiameter;
          break;
        default:
          ProfileTempVars.MultiSelectedProps.AllSameSize = false;
          break;
      }
      for (int index = 1; index <= ProfileTempVars.SelectedOperations.Count - 1; ++index)
      {
        switch (operationType)
        {
          case ProfileOperationTypes.Circle:
            if (num1 != ProfileTempVars.SelectedOperations[index].OperationData.CircleData.CircleDiameter)
            {
              ProfileTempVars.MultiSelectedProps.AllSameSize = false;
              break;
            }
            break;
          case ProfileOperationTypes.Rectangle:
            if (num1 != ProfileTempVars.SelectedOperations[index].OperationData.RectangleData.RectangleWidth | num2 != ProfileTempVars.SelectedOperations[index].OperationData.RectangleData.RectangleHeight)
            {
              ProfileTempVars.MultiSelectedProps.AllSameSize = false;
              break;
            }
            break;
          case ProfileOperationTypes.Barrel:
            if (num1 != ProfileTempVars.SelectedOperations[index].OperationData.BarelData.BarrelLength | num2 != ProfileTempVars.SelectedOperations[index].OperationData.BarelData.BarrelWidth | num3 != ProfileTempVars.SelectedOperations[index].OperationData.BarelData.BarrelDiameter)
            {
              ProfileTempVars.MultiSelectedProps.AllSameSize = false;
              break;
            }
            break;
          case ProfileOperationTypes.Ellipse:
            if (num1 != ProfileTempVars.SelectedOperations[index].OperationData.EllipseData.EllipseWidth | num2 != ProfileTempVars.SelectedOperations[index].OperationData.EllipseData.EllipseHeight)
            {
              ProfileTempVars.MultiSelectedProps.AllSameSize = false;
              break;
            }
            break;
          case ProfileOperationTypes.Hole:
            if (num1 != ProfileTempVars.SelectedOperations[index].OperationData.HoleData.HoleDiameter)
            {
              ProfileTempVars.MultiSelectedProps.AllSameSize = false;
              break;
            }
            break;
          case ProfileOperationTypes.Slot:
            if (num1 != ProfileTempVars.SelectedOperations[index].OperationData.SlotData.SlotWidth | num2 != ProfileTempVars.SelectedOperations[index].OperationData.SlotData.SlotDiameter)
            {
              ProfileTempVars.MultiSelectedProps.AllSameSize = false;
              break;
            }
            break;
          case ProfileOperationTypes.Cut:
            if (num1 != ProfileTempVars.SelectedOperations[index].OperationData.CutData.CutWidth | num2 != ProfileTempVars.SelectedOperations[index].OperationData.CutData.CutHeigth)
            {
              ProfileTempVars.MultiSelectedProps.AllSameSize = false;
              break;
            }
            break;
          case ProfileOperationTypes.Polygon:
            if (num1 != ProfileTempVars.SelectedOperations[index].OperationData.PolygonData.PolygonDiameter)
            {
              ProfileTempVars.MultiSelectedProps.AllSameSize = false;
              break;
            }
            break;
          default:
            ProfileTempVars.MultiSelectedProps.AllSameSize = false;
            break;
        }
      }
    }
    catch (Exception ex)
    {
      buException.throwException(ex, this.string_1, callMethod, false, "");
    }
  }

  public void doDeletePlaneOperation(int ProfileIndex, planeNames PlaneName)
  {
    if (ProfileIndex < 0)
      return;
    buEyeBaseVer5.Apps.ProfileItem profileItem = clsInit.cProfile.SelectActiveProfile(this.activeProfile.FirstItem, this.activeProfile.SecondItem, ref buProfileCalc.varProfileRunSettings.activeProfileIndex);
    if (profileItem == null)
      return;
    this.bUndoBuffer = true;
    for (int index = profileItem.Operations.Count - 1; index >= 0; --index)
    {
      if (profileItem.Operations[index].OperationData.selectedPlaneName == PlaneName)
        profileItem.Operations.RemoveAt(index);
    }
    this.DrawActiveProfile();
    this.ResetAllCalculationFlags();
    this.ProfileTreeUpdate();
    this.DrawPreview(new List<Entity>());
  }

  public void doDeleteOperation(int ProfileIndex, string OperationName)
  {
    if (!(ProfileIndex >= 0 & OperationName.Length > 0))
      return;
    buEyeBaseVer5.Apps.ProfileItem profileItem = clsInit.cProfile.SelectActiveProfile(this.activeProfile.FirstItem, this.activeProfile.SecondItem, ref buProfileCalc.varProfileRunSettings.activeProfileIndex);
    if (profileItem == null)
      return;
    this.bUndoBuffer = true;
    for (int index = 0; index <= ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Count - 1; ++index)
    {
      CustomData entityCustomData = clsInit.cVector5.GetEntityCustomData(ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index]);
      if (entityCustomData.typeDefination == entityTypeDefination.ProfileOperation)
      {
        if (entityCustomData.ActionName == OperationName)
          ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index].Selected = true;
      }
      else if (entityCustomData.ActionName == OperationName)
        ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index].Selected = true;
    }
    ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.DeleteSelected();
    if (buProfileCalc.varProfileRunSettings.activeProfileIndex == 0)
    {
      for (int index = profileItem.Operations.Count - 1; index >= 0; --index)
      {
        if (profileItem.Operations[index].Name == OperationName)
          profileItem.Operations.RemoveAt(index);
      }
    }
    if (buProfileCalc.varProfileRunSettings.activeProfileIndex == 1)
    {
      for (int index = this.activeProfile.SecondItem.Operations.Count - 1; index >= 0; --index)
      {
        if (this.activeProfile.SecondItem.Operations[index].Name == OperationName)
          this.activeProfile.SecondItem.Operations.RemoveAt(index);
      }
    }
    this.ResetAllCalculationFlags();
    ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Invalidate();
    this.ProfileTreeUpdate();
    this.DrawPreview(new List<Entity>());
  }

  public void doDeleteAllOperations(int ProfileIndex)
  {
    if (ProfileIndex < 0)
      return;
    buEyeBaseVer5.Apps.ProfileItem profileItem = clsInit.cProfile.SelectActiveProfile(this.activeProfile.FirstItem, this.activeProfile.SecondItem, ref buProfileCalc.varProfileRunSettings.activeProfileIndex);
    if (profileItem == null)
      return;
    this.bUndoBuffer = true;
    profileItem.Operations.Clear();
    for (int index = 0; index <= ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Count - 1; ++index)
    {
      if (ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index].EntityData != null & ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index].EntityData is CustomData)
      {
        CustomData entityData = ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index].EntityData as CustomData;
        if (entityData.EntityName == profileItem.ItemName && entityData.typeDefination == entityTypeDefination.ProfileSeperator | entityData.typeDefination == entityTypeDefination.ProfileOperation)
          ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index].Selected = true;
      }
    }
    ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.DeleteSelected();
    profileItem.Operations.Clear();
    if (profileItem.auxEntities != null)
      profileItem.auxEntities.Clear();
    this.DrawActiveProfile();
    this.ResetAllCalculationFlags();
    this.ProfileTreeUpdate();
    this.DrawPreview(new List<Entity>());
  }

