  public void doEditOperation(int ProfileIndex, string OperationName, ToolBase5 Tool = null)
  {
    buProfileCalc.varProfileRunSettings.IncrementalMode = false;
    if (!(this.activeProfile != null & ProfileIndex >= 0))
      return;
    if (buProfileCalc.varProfileSettings.MultipleEdit)
      this.doAddSelectedOperations();
    if (ProfileIndex == 0)
      this.doEditOperation(ref this.activeProfile.FirstItem, OperationName, Tool);
    if (ProfileIndex != 1)
      return;
    this.doEditOperation(ref this.activeProfile.SecondItem, OperationName, Tool);
  }

  public void doEditOperation(ref buEyeBaseVer5.Apps.ProfileItem Item, string OperationName, ToolBase5 Tool = null)
  {
    if (Item.Operations.Count <= 0)
      return;
    this.bUndoBuffer = true;
    for (int index = 0; index <= Item.Operations.Count - 1; ++index)
    {
      if (Item.Operations[index].Name == OperationName)
      {
        buProfileCalc.varProfileRunSettings.OPData = new buEyeBaseVer5.Apps.ProfileOperationData(Item.Operations[index].OperationData);
        clsInit.cProfile.OperationDataToShapeRunTime(buProfileCalc.varProfileRunSettings.OPData, ref buProfileCalc.varProfileRunSettings.ShapeDataParameters);
        this.operationEditIndex = index;
        this.ToolChangeForced = Item.Operations[index].Locked;
        ProfileTempVars.OperationEditing = true;
        if (Tool != null)
          Item.Operations[index].Tool = new ToolBase5(Tool);
        ProfileTempVars.OperationDepths.Clear();
        ProfileTempVars.DepthForced = false;
        if (buProfileCalc.varProfileRunSettings.OPData.DepthForced)
        {
          DepthPositions.Copy(buProfileCalc.varProfileRunSettings.OPData.DepthValues, ref ProfileTempVars.OperationDepths);
          ProfileTempVars.DepthForced = true;
        }
        if (Item.Operations[index].Tool != null && Item.Operations[index].Tool.CamData.SpindleSpeed < buProfileCalc.varProfileSettings.MinSpindleSpeed | Item.Operations[index].Tool.CamData.FeedSpeed <= 0.0 | Item.Operations[index].Tool.CamData.PlungeSpeed <= 0.0)
        {
          ToolBase5 foundTool = (ToolBase5) null;
          clsInit.cVector5.FindToolWithToolName(ccVars.Tools, Item.Operations[index].Tool.Data.Name, ref foundTool);
          if (foundTool != null)
            Item.Operations[index].Tool = foundTool;
        }
        ccVars.toolActive = new ToolBase5(Item.Operations[index].Tool);
        clsInit.cProfile.OperationDataToShapeRunTime(buProfileCalc.varProfileRunSettings.OPData, ref buProfileCalc.varProfileRunSettings.ShapeDataParameters);
        this.OPPriority = Item.Operations[index].Priority;
        if (buProfileCalc.varProfileRunSettings.OPData.Action != actionTypeBU.profileNotch)
          this.cmdOperation(Item.Operations[index].OperationData.Action);
        else
          this.cmdOperation(Item.Operations[index].OperationData.Action, NotchType: Item.Operations[index].OperationData.NotchData.NotchOPType);
      }
    }
  }

  public void doEnableDisableOperation(int indexOP, bool Status)
  {
    buEyeBaseVer5.Apps.ProfileItem profileItem = clsInit.cProfile.SelectActiveProfile(this.activeProfile.FirstItem, this.activeProfile.SecondItem, ref buProfileCalc.varProfileRunSettings.activeProfileIndex);
    if (profileItem == null || indexOP == -1 | profileItem.Operations.Count == 0)
      return;
    this.bUndoBuffer = true;
    profileItem.Operations[indexOP].Enable = Status;
    buCadCamResVer5.TreeNodeSettings node = clsItem.FrmProfileJob.tree_jobs.Nodes[0].Nodes[buProfileCalc.varProfileRunSettings.activeProfileIndex].Nodes[indexOP] as buCadCamResVer5.TreeNodeSettings;
    if (profileItem.Operations[indexOP].Enable)
    {
      clsItem.FrmProfileJob.tree_jobs.Nodes[0].Nodes[buProfileCalc.varProfileRunSettings.activeProfileIndex].Nodes[indexOP].ImageIndex = node.OldImageIndex;
      clsItem.FrmProfileJob.tree_jobs.Nodes[0].Nodes[buProfileCalc.varProfileRunSettings.activeProfileIndex].Nodes[indexOP].SelectedImageIndex = node.OldImageIndex;
    }
    else
    {
      clsItem.FrmProfileJob.tree_jobs.Nodes[0].Nodes[buProfileCalc.varProfileRunSettings.activeProfileIndex].Nodes[indexOP].ImageIndex = 26;
      clsItem.FrmProfileJob.tree_jobs.Nodes[0].Nodes[buProfileCalc.varProfileRunSettings.activeProfileIndex].Nodes[indexOP].SelectedImageIndex = 26;
    }
    profileItem.IsClamperDone = false;
  }

  public void doAddExternalEntities(List<buEntity> refEntities, bool Template, bool FileOpen)
  {
    if (refEntities.Count == 0)
      return;
    this.shapeCreateParameters_0.entitiesCurveList = new List<EntitiesList>();
    List<buEntity> SortedEntities = new List<buEntity>();
    List<List<buEntity>> SplitedEntitites = new List<List<buEntity>>();
    SortbuSettings Settings = new SortbuSettings();
    clsInit.cVector5.SortEntitiesByRefPoint(refEntities[0].StartPoint, ref refEntities, Settings, ref SortedEntities);
    clsInit.cVector5.EntitiesSplitByUpperLine(SortedEntities, ref SplitedEntitites);
    Point3D MinPoint = new Point3D();
    Point3D MaxPoint = new Point3D();
    clsInit.cVector5.BoxSizeCalculate(refEntities, ref MinPoint, ref MaxPoint);
    Point3D point3D1 = (Point3D) null;
    Point3D point3D2 = (Point3D) null;
    if (buProfileCalc.varProfileSettings.DontAddLineFromExternalFile)
    {
      for (int index1 = 0; index1 <= SplitedEntitites.Count - 1; ++index1)
      {
        if (!clsInit.cVector5.isEntitiesClosed(SplitedEntitites[index1]))
        {
          for (int index2 = SplitedEntitites[index1].Count - 1; index2 >= 0; --index2)
          {
            if (SplitedEntitites[index1][index2].GetType() == typeof (buLine))
            {
              buLine buLine = SplitedEntitites[index1][index2] as buLine;
              if (buCompare5.EQ(buLine.StartPoint.X, buLine.EndPoint.X) && buCompare5.EQ(buLine.StartPoint.X, MinPoint.X) | buCompare5.EQ(buLine.StartPoint.X, MaxPoint.X))
              {
                if (buCompare5.EQ(buLine.StartPoint.X, MinPoint.X))
                  point3D1 = new Point3D(MinPoint.X, 0.0, 0.0);
                if (buCompare5.EQ(buLine.StartPoint.X, MaxPoint.X))
                  point3D2 = new Point3D(MaxPoint.X, 0.0, 0.0);
                SplitedEntitites[index1].RemoveAt(index2);
              }
            }
            else if (SplitedEntitites[index1][index2].GetType() == typeof (buLinearPath))
            {
              buLinearPath buLinearPath = SplitedEntitites[index1][index2] as buLinearPath;
              if (buLinearPath.Vertices.Count == 2 & buCompare5.EQ(buLinearPath.Vertices[0].X, buLinearPath.Vertices[buLinearPath.Vertices.Count - 1].X) && buCompare5.EQ(buLinearPath.Vertices[0].X, MinPoint.X) | buCompare5.EQ(buLinearPath.Vertices[0].X, MaxPoint.X))
                SplitedEntitites[index1].RemoveAt(index2);
            }
          }
        }
      }
    }
    if (!FileOpen)
      clsInit.appEditor.SaveEditorFile();
    clsInit.cVector5.BoxSizeCalculate(SplitedEntitites, ref MinPoint, ref MaxPoint);
    if ((!(point3D1 != (Point3D) null) ? 0 : (point3D2 != (Point3D) null ? 1 : 0)) != 0)
    {
      ProfileTempVars.PatternDxfOperation = true;
      ProfileTempVars.PntPatternDxf.X = MinPoint.X;
      ProfileTempVars.PntPatternDxf.Y = MinPoint.Y;
    }
    buProfileCalc.varProfileRunSettings.ShapeDataParameters.FreeDrawWidth = MaxPoint.X - MinPoint.X;
    buProfileCalc.varProfileRunSettings.ShapeDataParameters.FreeDrawHeight = MaxPoint.Y - MinPoint.Y;
    List<buEntity> buEntityList = new List<buEntity>();
    if (SplitedEntitites.Count <= 0)
      return;
    for (int index = 0; index <= SplitedEntitites.Count - 1; ++index)
    {
      EntitiesList entitiesList = new EntitiesList();
      if (SplitedEntitites[index].Count > 1)
      {
        List<Point3D> Points = new List<Point3D>();
        clsInit.cVector5.EntitiesToPointsWithCamDirection(SplitedEntitites[index], 0.01, ref Points);
        buLinearPath buLinearPath = new buLinearPath(Points);
        if (buCompare5.EQ(buLinearPath.StartPoint, buLinearPath.EndPoint))
          entitiesList.Entities.Add((buEntity) buLinearPath);
      }
      else if (SplitedEntitites[index].Count > 0 && buCompare5.EQ(SplitedEntitites[index][0].StartPoint, SplitedEntitites[index][0].EndPoint))
        entitiesList.Entities.Add(SplitedEntitites[index][0]);
      if (entitiesList.Entities.Count > 0)
        this.shapeCreateParameters_0.entitiesCurveList.Add(entitiesList);
    }
    if (!(this.shapeCreateParameters_0.entitiesCurveList.Count > 0 & !FileOpen))
      return;
    this.cmdShapes(actionTypeBU.profileFreeDraw);
  }

  public void doOperationCheckWarnings(ref buEyeBaseVer5.Apps.ProfileOperation OP)
  {
    bool isToolLenShort = false;
    bool isToolCutLenShort = false;
    buEyeBaseVer5.Apps.ProfileItem profileItem = clsInit.cProfile.SelectActiveProfile(this.activeProfile.FirstItem, this.activeProfile.SecondItem, ref buProfileCalc.varProfileRunSettings.activeProfileIndex);
    if (profileItem == null)
      return;
    OP.Error = false;
    OP.errorList.Clear();
    OP.warningList.Clear();
    OP.infoList.Clear();
    if (this.FrmNotchList != null && OP.Action == actionTypeBU.profileNotch)
    {
      this.FrmNotchList.dgv_list.Rows.Clear();
      this.FrmNotchList.dgv_list.Visible = false;
    }
    if (this.FrmOperationList != null && OP.Action != actionTypeBU.profileNotch)
    {
      this.FrmOperationList.dgv_list.Rows.Clear();
      this.FrmOperationList.dgv_list.Visible = false;
    }
    if (OP.Action == actionTypeBU.profileNotch)
      clsInit.cProfile.CheckToolLength(OP, OP.ToolNotch, buProfileCalc.varProfileSettings.ToolHolderLength, ref isToolLenShort, ref isToolCutLenShort);
    else
      clsInit.cProfile.CheckToolLength(OP, OP.Tool, buProfileCalc.varProfileSettings.ToolHolderLength, ref isToolLenShort, ref isToolCutLenShort);
    if (isToolLenShort)
      clsInit.cProfile.AddWarningToOperation(this.ShowWarningOPMessage(AppLanguage.CadCamMessages[102]), ref OP);
    if (isToolCutLenShort)
    {
      if (OP.OperationData.OperationType == ProfileOperationTypes.Notch)
        clsInit.cProfile.AddWarningToOperation(this.ShowWarningOPMessage(buLangTranslate.preSentencesProfile.ToolDiameterLowerThanNotchDepth), ref OP);
      else
        clsInit.cProfile.AddWarningToOperation(this.ShowWarningOPMessage(AppLanguage.CadCamMessages[103]), ref OP);
    }
    if (OP.Action != actionTypeBU.profileNotch)
    {
      if (OP.OperationData.selectedPlaneName == planeNames.Top | OP.OperationData.selectedPlaneName == planeNames.Bottom && OP.OperationData.ExternalDepth + OP.OperationData.ExtraDepth > profileItem.ProfileMaxPoint.Z - profileItem.ProfileMinPoint.Z + buProfileCalc.varProfileSettings.ProfileSizeExceedDepthLimit)
        clsInit.cProfile.AddWarningToOperation(this.ShowWarningOPMessage(buLangTranslate.preSentencesProfile.TotalDepthisHigherthenProfileSize), ref OP);
      if (OP.OperationData.selectedPlaneName == planeNames.Front | OP.OperationData.selectedPlaneName == planeNames.Back && OP.OperationData.ExternalDepth + OP.OperationData.ExtraDepth > profileItem.ProfileMaxPoint.Y - profileItem.ProfileMinPoint.Y + buProfileCalc.varProfileSettings.ProfileSizeExceedDepthLimit)
        clsInit.cProfile.AddWarningToOperation(this.ShowWarningOPMessage(buLangTranslate.preSentencesProfile.TotalDepthisHigherthenProfileSize), ref OP);
      if (OP.MaxPoint.X > profileItem.Length + buProfileCalc.varProfileSettings.ProfileEndAllowedPositiveDistance)
        clsInit.cProfile.AddWarningToOperation(this.ShowWarningOPMessage($"{buLangTranslate.preSentencesProfile.OperationPositionOutoffromProfileSize} - X: {OP.MaxPoint.X.ToString("f2")} > {profileItem.Length.ToString()}"), ref OP);
      if (OP.MinPoint.X > profileItem.Length + buProfileCalc.varProfileSettings.ProfileEndAllowedPositiveDistance)
        clsInit.cProfile.AddWarningToOperation(this.ShowWarningOPMessage($"{buLangTranslate.preSentencesProfile.OperationPositionOutoffromProfileSize} - X: {OP.MinPoint.X.ToString("f2")} > {profileItem.Length.ToString()}"), ref OP);
      if (OP.MaxPoint.X < buProfileCalc.varProfileSettings.ProfileStartAllowedNegativeDistance)
        clsInit.cProfile.AddWarningToOperation(this.ShowWarningOPMessage($"{buLangTranslate.preSentencesProfile.OperationPositionOutoffromProfileSize} - X: {OP.MaxPoint.X.ToString("f2")} < {profileItem.Length.ToString()}"), ref OP);
      if (OP.MinPoint.X < buProfileCalc.varProfileSettings.ProfileStartAllowedNegativeDistance)
        clsInit.cProfile.AddWarningToOperation(this.ShowWarningOPMessage($"{buLangTranslate.preSentencesProfile.OperationPositionOutoffromProfileSize} - X: {OP.MinPoint.X.ToString("f2")} < {profileItem.Length.ToString()}"), ref OP);
      if (OP.OperationData.ExternalDepth <= 0.0)
        clsInit.cProfile.AddWarningToOperation(this.ShowWarningOPMessage(buLangTranslate.preSentencesProfile.DepthCantbeZero), ref OP);
    }
    if (OP.Action == actionTypeBU.profileTapping && (OP.Tool == null ? 0 : (OP.Tool.Purpose != ToolPurpose.Tapping ? 1 : 0)) != 0)
      clsInit.cProfile.AddWarningToOperation(this.ShowWarningOPMessage(buLangTranslate.preSentences.ToolMustBeTapping), ref OP);
    if (OP.Action == actionTypeBU.profileTapping && (OP.Tool == null ? 0 : (!buCompare5.EQ(OP.Tool.Data.TappingInfo, OP.OperationData.HoleData.TappingPitch) ? 1 : 0)) != 0)
      clsInit.cProfile.AddWarningToOperation(this.ShowWarningOPMessage(buLangTranslate.preSentences.TappingPitchNotSuitable), ref OP);
    if (OP.Action == actionTypeBU.profileHole & buProfileCalc.varProfileSettings.UseDrillToolForDrill && (OP.Tool == null ? 0 : (OP.Tool.Purpose != ToolPurpose.Drilling & OP.Tool.Purpose != ToolPurpose.Hole ? 1 : 0)) != 0)
      clsInit.cProfile.AddWarningToOperation(this.ShowWarningOPMessage(buLangTranslate.preSentences.ToolMustBeDrill), ref OP);
    if (OP.Action == actionTypeBU.profileHole && !buProfileCalc.varProfileSettings.alarmIfToolDiaDifferentThenHoleDia)
    {
      if ((OP.Tool == null ? 0 : (buCompare5.GT(OP.Tool.Geometry.Diameter, ((buEyeBaseVer5.Apps.ProfileOperationHole) OP).Diameter) ? 1 : 0)) != 0)
        clsInit.cProfile.AddWarningToOperation(this.ShowWarningOPMessage(buLangTranslate.preSentences.ToolDiameterGreaterForThisOperation), ref OP);
      if ((OP.Tool == null ? 0 : (buCompare5.LT(OP.Tool.Geometry.Diameter, ((buEyeBaseVer5.Apps.ProfileOperationHole) OP).Diameter) ? 1 : 0)) != 0)
        clsInit.cProfile.AddWarningToOperation(this.ShowWarningOPMessage(buLangTranslate.preSentences.ToolDiameterLowerForThisOperation), ref OP);
    }
    if (OP.Action == actionTypeBU.profileTapping)
    {
      if ((OP.ToolAux == null ? 0 : (buCompare5.GT(OP.ToolAux.Geometry.Diameter, ((buEyeBaseVer5.Apps.ProfileOperationHole) OP).Diameter) ? 1 : 0)) != 0)
        clsInit.cProfile.AddWarningToOperation(this.ShowWarningOPMessage(buLangTranslate.preSentences.ToolDiameterGreaterForThisOperation), ref OP);
      if ((OP.ToolAux == null ? 0 : (buCompare5.LT(OP.ToolAux.Geometry.Diameter, ((buEyeBaseVer5.Apps.ProfileOperationHole) OP).Diameter) ? 1 : 0)) != 0)
        clsInit.cProfile.AddWarningToOperation(this.ShowWarningOPMessage(buLangTranslate.preSentences.ToolDiameterLowerForThisOperation), ref OP);
      if ((OP.Tool == null ? 0 : (buCompare5.GT(OP.Tool.Geometry.Diameter, OP.OperationData.HoleData.TappingDiameter) ? 1 : 0)) != 0)
        clsInit.cProfile.AddWarningToOperation(this.ShowWarningOPMessage(buLangTranslate.preSentences.ToolDiameterGreaterForThisOperation), ref OP);
      if ((OP.Tool == null ? 0 : (buCompare5.LT(OP.Tool.Geometry.Diameter, OP.OperationData.HoleData.TappingDiameter) ? 1 : 0)) != 0)
        clsInit.cProfile.AddWarningToOperation(this.ShowWarningOPMessage(buLangTranslate.preSentences.ToolDiameterLowerForThisOperation), ref OP);
    }
    if (OP.Action == actionTypeBU.profileCircle && OP.OperationData.CircleData.CircleDiameter < OP.Tool.Geometry.Diameter)
      clsInit.cProfile.AddWarningToOperation(this.ShowWarningOPMessage(buLangTranslate.preSentencesProfile.OperationDiamterLowerThenToolDiameter), ref OP);
    if (OP.Action == actionTypeBU.profileRectangle && OP.OperationData.RectangleData.RectangleRadius > 0.0 & OP.OperationData.RectangleData.RectangleRadius < OP.Tool.Geometry.Diameter / 2.0)
      clsInit.cProfile.AddWarningToOperation(this.ShowWarningOPMessage(buLangTranslate.preSentencesProfile.ToolRadiusIsHigherOperationRadius), ref OP);
    if (OP.Action == actionTypeBU.profileNotch)
    {
      if (OP.OperationData.NotchData.NotchOPType == ProfileNotchOperationType.Length && OP.OperationData.NotchData.NotchWidth < OP.ToolNotch.Geometry.Diameter + 4.0)
        clsInit.cProfile.AddWarningToOperation(this.ShowWarningOPMessage(buLangTranslate.preSentencesProfile.NotchWidthTooSmall), ref OP);
      if (OP.OperationData.NotchData.NotchOPType == ProfileNotchOperationType.Horizontal && profileItem.ProfileMaxPoint.Z + profileItem.SupportBlock.SupportBlockZHeight < buProfileCalc.varProfileClamperSettings.ClamperMaxHeight)
        clsInit.cProfile.AddWarningToOperation(this.ShowWarningOPMessage(buLangTranslate.preSentencesProfile.ProfileHeightIsLowerThenFixtureForThisOperation), ref OP);
    }
    if (OP.Tool != null)
    {
      if (OP.OperationData.selectedPlaneName == planeNames.Back)
      {
        if (profileItem.SupportBlock.SupportBlockY2BackWidth > 0.0 & profileItem.SupportBlock.SupportBlockY2BackWidth > OP.Tool.Geometry.Length - Math.Abs(OP.OperationData.Depth.Depth))
          clsInit.cProfile.AddWarningToOperation(this.ShowWarningOPMessage($"{buLangTranslate.preDef.Back} {buLangTranslate.preSentencesProfile.SupportBlockWidthTooHigh}"), ref OP);
        if (profileItem.SupportBlock.SupportBlockY2BackHeight > 0.0 & OP.MinPoint.Z < profileItem.SupportBlock.SupportBlockY2BackHeight)
          clsInit.cProfile.AddWarningToOperation(this.ShowWarningOPMessage($"{buLangTranslate.preDef.Back} {buLangTranslate.preSentencesProfile.SupportBlockWidthTooHigh}"), ref OP);
      }
      if (OP.OperationData.selectedPlaneName == planeNames.Front)
      {
        if (profileItem.SupportBlock.SupportBlockY1FrontWidth > 0.0 & profileItem.SupportBlock.SupportBlockY1FrontWidth > OP.Tool.Geometry.Length - Math.Abs(OP.OperationData.Depth.Depth))
          clsInit.cProfile.AddWarningToOperation(this.ShowWarningOPMessage($"{buLangTranslate.preDef.Front} {buLangTranslate.preSentencesProfile.SupportBlockWidthTooHigh}"), ref OP);
        if (profileItem.SupportBlock.SupportBlockY1FrontHeight > 0.0 & OP.MinPoint.Z < profileItem.SupportBlock.SupportBlockY1FrontHeight)
          clsInit.cProfile.AddWarningToOperation(this.ShowWarningOPMessage($"{buLangTranslate.preDef.Front} {buLangTranslate.preSentencesProfile.SupportBlockWidthTooHigh}"), ref OP);
      }
    }
    if (OP.OperationData.EachLayer & OP.OperationData.DepthValues.Count == 0 & OP.OperationData.selectedPlaneName != planeNames.Free)
      clsInit.cProfile.AddWarningToOperation(this.ShowWarningOPMessage(buLangTranslate.preSentencesProfile.NoCalculatedDepths), ref OP);
    List<string> Messages = new List<string>();
    if (!clsInit.cProfile.isToolSuitableForOperation(OP, ref Messages))
    {
      if (Messages.Count == 0)
        clsInit.cProfile.AddErrorToOperation(this.ShowErrorOPMessage(buLangTranslate.preSentencesProfile.ToolisnotSuitableforthisOperation), ref OP);
      for (int index = 0; index <= Messages.Count - 1; ++index)
        clsInit.cProfile.AddErrorToOperation(this.ShowErrorOPMessage(Messages[index]), ref OP);
    }
    if (OP.Action == actionTypeBU.profileHole && buProfileCalc.varProfileSettings.alarmIfToolDiaDifferentThenHoleDia)
    {
      if ((OP.Tool == null ? 0 : (buCompare5.GT(OP.Tool.Geometry.Diameter, ((buEyeBaseVer5.Apps.ProfileOperationHole) OP).Diameter) ? 1 : 0)) != 0)
        clsInit.cProfile.AddErrorToOperation(this.ShowErrorOPMessage(buLangTranslate.preSentences.ToolDiameterGreaterForThisOperation), ref OP);
      if ((OP.Tool == null ? 0 : (buCompare5.LT(OP.Tool.Geometry.Diameter, ((buEyeBaseVer5.Apps.ProfileOperationHole) OP).Diameter) ? 1 : 0)) != 0)
        clsInit.cProfile.AddErrorToOperation(this.ShowErrorOPMessage(buLangTranslate.preSentences.ToolDiameterLowerForThisOperation), ref OP);
    }
    if (OP.EntityMultiCam.Count == 0)
      clsInit.cProfile.AddErrorToOperation(this.ShowErrorOPMessage(buLangTranslate.preSentencesProfile.NoToolPathAvailableCheckYourToolDataorParameters), ref OP);
    if (ccVars.CharLibList.Count == 0 & OP.Action == actionTypeBU.profileWireText)
      clsInit.cProfile.AddErrorToOperation(this.ShowErrorOPMessage(buLangTranslate.preSentences.NoWireframeLibraryCharsAvailable), ref OP);
    if ((OP.Tool == null ? 0 : (OP.Tool.CamData.SpindleSpeed <= 0.0 ? 1 : 0)) != 0)
      clsInit.cProfile.AddErrorToOperation(this.ShowErrorOPMessage(buLangTranslate.preSentences.SpindleSpeedIsZero), ref OP);
    if ((OP.Tool == null ? 0 : (OP.Tool.CamData.SpindleSpeed > 0.0 & OP.Tool.CamData.SpindleSpeed <= buProfileCalc.varProfileSettings.MinSpindleSpeed ? 1 : 0)) != 0)
      clsInit.cProfile.AddErrorToOperation(this.ShowErrorOPMessage(buLangTranslate.preSentences.SpindleSpeedLowerThenMinLimit), ref OP);
    if (OP.OperationData.OperationType == ProfileOperationTypes.Notch & buProfileCalc.varProfileSettings.NotchVerticalForbiddenAtSide && this.OPData.NotchData.NotchOPType == ProfileNotchOperationType.Vertical)
    {
      if (profileItem.XReferanceLocation == LeftRightType.Left & this.OPData.NotchData.NotchLocation == ProfileNotchLocationType.Left)
      {
        clsInit.cProfile.AddErrorToOperation(this.ShowErrorOPMessage(buLangTranslate.preSentencesProfile.YouCantAddThisNotchOperationThisSide), ref OP);
        return;
      }
      if (profileItem.XReferanceLocation == LeftRightType.Right & this.OPData.NotchData.NotchLocation == ProfileNotchLocationType.Right)
      {
        clsInit.cProfile.AddErrorToOperation(this.ShowErrorOPMessage(buLangTranslate.preSentencesProfile.YouCantAddThisNotchOperationThisSide), ref OP);
        return;
      }
    }
    if (OP.OperationData.selectedPlaneName == planeNames.Free)
    {
      double num = clsInit.cVector5.PointAngle(new Point3D(OP.OperationData.selectedPlane.Equation.X, OP.OperationData.selectedPlane.Equation.Y, OP.OperationData.selectedPlane.Equation.Z), new Point3D(), Plane.YZ);
      if (num < 0.0 | num > 180.0)
        clsInit.cProfile.AddErrorToOperation(this.ShowErrorOPMessage(buLangTranslate.preSentencesProfile.ThisPlaneIsNotSuitable), ref OP);
    }
    if (OP.Action == actionTypeBU.profileNotch && OP.warningList.Count > 0 | OP.infoList.Count > 0 | OP.errorList.Count > 0)
      this.FrmNotchList.dgv_list.Visible = true;
    if (OP.Action == actionTypeBU.profileNotch || !(OP.warningList.Count > 0 | OP.infoList.Count > 0 | OP.errorList.Count > 0))
      return;
    this.FrmOperationList.dgv_list.Visible = true;
  }

  public void doGetBottomOperations(buEyeBaseVer5.Apps.ProfileItem refItem, ref List<ProfileItemCalc> devidedItems)
  {
    devidedItems.Clear();
    devidedItems = new List<ProfileItemCalc>();
    ProfileItemCalc profileItemCalc1 = new ProfileItemCalc(refItem, true);
    profileItemCalc1.CalcType = ProfileExcType.Normal;
    for (int index = profileItemCalc1.calcOperations.Count - 1; index >= 0; --index)
    {
      if (profileItemCalc1.calcOperations[index].OperationData.selectedPlaneName == planeNames.Bottom)
        profileItemCalc1.calcOperations.RemoveAt(index);
    }
    devidedItems.Add(profileItemCalc1);
    ProfileItemCalc profileItemCalc2 = new ProfileItemCalc(refItem, true);
    profileItemCalc2.CalcType = ProfileExcType.NormalBottom;
    for (int index = profileItemCalc2.calcOperations.Count - 1; index >= 0; --index)
    {
      if (profileItemCalc2.calcOperations[index].OperationData.selectedPlaneName == planeNames.Top | profileItemCalc2.calcOperations[index].OperationData.selectedPlaneName == planeNames.Front | profileItemCalc2.calcOperations[index].OperationData.selectedPlaneName == planeNames.Back | profileItemCalc2.calcOperations[index].OperationData.selectedPlaneName == planeNames.Free)
        profileItemCalc2.calcOperations.RemoveAt(index);
    }
    devidedItems.Add(profileItemCalc2);
  }

  public void doSetPriority()
  {
    buEyeBaseVer5.Apps.ProfileItem curItem = clsInit.cProfile.SelectActiveProfile(this.activeProfile.FirstItem, this.activeProfile.SecondItem, ref buProfileCalc.varProfileRunSettings.activeProfileIndex);
    if (curItem == null)
      return;
    if (buProfileCalc.varProfileRunSettings.SelectMode && clsInit.cProfile.GetSelectedOperationCount(curItem) == 0)
    {
      buString5.MessageBoxWarning(buLangTranslate.preSentencesProfile.SelectionModeActiveNoOperationSelected);
    }
    else
    {
      if (!(buProfileCalc.varProfileRunSettings.activeOPIndex >= 0 & buProfileCalc.varProfileRunSettings.activeOPIndex <= curItem.Operations.Count - 1))
        return;
      F_ProfilePriority fProfilePriority = new F_ProfilePriority();
      fProfilePriority.Priority = curItem.Operations[buProfileCalc.varProfileRunSettings.activeOPIndex].Priority;
      fProfilePriority.Init();
      int num = (int) fProfilePriority.ShowDialog();
      if (fProfilePriority.Properties.Result != DialogResult.OK)
        return;
      this.bUndoBuffer = true;
      if (!buProfileCalc.varProfileRunSettings.SelectMode)
      {
        curItem.Operations[buProfileCalc.varProfileRunSettings.activeOPIndex].Priority = fProfilePriority.Priority;
      }
      else
      {
        for (int index = curItem.Operations.Count - 1; index >= 0; --index)
        {
          if (curItem.Operations[index].Selected)
            curItem.Operations[index].Priority = fProfilePriority.Priority;
        }
      }
      this.ProfileTreeUpdate();
    }
  }

  public void doSetActiveProfileOP(int ProfileIndex, int OperationIndex)
  {
    ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.ClearSelection();
    this.selectedEntities.Clear();
    buProfileCalc.varProfileRunSettings.activeOPIndex = OperationIndex;
    if (ProfileIndex == 0 && (OperationIndex < 0 || this.activeProfile.FirstItem == null ? 0 : (OperationIndex <= this.activeProfile.FirstItem.Operations.Count - 1 ? 1 : 0)) != 0)
      this.doSetActiveProfileOP(this.activeProfile.FirstItem, OperationIndex);
    if (ProfileIndex == 1 && (OperationIndex < 0 || this.activeProfile.SecondItem == null ? 0 : (OperationIndex <= this.activeProfile.SecondItem.Operations.Count - 1 ? 1 : 0)) != 0)
      this.doSetActiveProfileOP(this.activeProfile.SecondItem, OperationIndex);
    ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Invalidate();
  }

  public void doSetActiveProfileOP(buEyeBaseVer5.Apps.ProfileItem Item, int OperationIndex)
  {
    if (ccVars.Action == actionTypeBU.None)
      buProfileCalc.varProfileRunSettings.activeOPIndex = OperationIndex;
    buProfileCalc.varProfileRunSettings.activeOPName = Item.Operations[OperationIndex].Name;
    this.activeOP = new buEyeBaseVer5.Apps.ProfileOperation();
    buEyeBaseVer5.Apps.ProfileOperation.Copy(Item.Operations[OperationIndex], ref this.activeOP);
    for (int index = 0; index <= ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Count - 1; ++index)
    {
      CustomData entityData = ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index].EntityData as CustomData;
      if (entityData.typeDefination == entityTypeDefination.ProfileOperation)
      {
        ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index].ColorMethod = colorMethodType.byLayer;
        if (!clsInit.cProfile.isOperationEnableFromName(Item, entityData.ActionName))
        {
          ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index].ColorMethod = colorMethodType.byEntity;
          ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index].Color = buProfileCalc.varProfileVisualSettings.OperationDisableColor;
        }
        if (entityData.ActionName == this.activeOP.Name)
        {
          ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index].ColorMethod = colorMethodType.byEntity;
          ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index].Color = buProfileCalc.varProfileVisualSettings.OperationSelectedColor;
          this.selectedEntities.Add(buVector5.CopyEntities(ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index]));
        }
      }
    }
  }

  public void doOperationFromFile()
  {
    OpenFileDialog openFileDialog = new OpenFileDialog();
    openFileDialog.InitialDirectory = buProfileCalc.varProfileRunSettings.pathSaveProfiles;
    openFileDialog.Filter = "Profile Files (*.buprofile)|*.buprofile";
    openFileDialog.FilterIndex = 1;
    if (openFileDialog.ShowDialog() != DialogResult.OK)
      return;
    buProfileCalc.varProfileRunSettings.pathSaveProfiles = buFile5.GetPath(openFileDialog.FileName);
    buEyeBaseVer5.Apps.ProfileItem profileItem = new buEyeBaseVer5.Apps.ProfileItem();
    ArrayList StringList = new ArrayList();
    buFile5.OpenFromFile(openFileDialog.FileName, ref StringList);
    List<string> CalcList1 = new List<string>();
    List<string> CalcList2 = new List<string>();
    buStatics.ListToSpecificList("<FirstItem>", "</FirstItem>", true, StringList, ref CalcList1);
    buStatics.ListToSpecificList("<SecondItem>", "</SecondItem>", true, StringList, ref CalcList2);
    if (buProfileCalc.varProfileRunSettings.activeProfileIndex == 0 & this.activeProfile.FirstItem != null)
      this.doOperationFromFile(CalcList1, CalcList2, LeftRightType.Left, ref this.activeProfile.FirstItem);
    if (buProfileCalc.varProfileRunSettings.activeProfileIndex == 1 & this.activeProfile.SecondItem != null)
      this.doOperationFromFile(CalcList1, CalcList2, LeftRightType.Right, ref this.activeProfile.SecondItem);
    clsInit.appCommand.cmdViewZoomFit();
  }

  public void doOperationFromFile(
    List<string> SLFirst,
    List<string> SLSecond,
    LeftRightType LeftRight,
    ref buEyeBaseVer5.Apps.ProfileItem Item)
  {
    if (SLFirst.Count > 0)
    {
      buFile5.SaveToFile(SLFirst, AppPath.Base + "\\temp.job");
      Item.XReferanceLocation = LeftRight;
      bool clearAllProfiles = buProfileCalc.varProfileSettings.JobOpenClearAllProfiles;
      buProfileCalc.varProfileSettings.JobOpenClearAllProfiles = false;
      this.OpenProfileJobFile(AppPath.Base + "\\temp.job", true, true, false, ref Item, false);
      buProfileCalc.varProfileSettings.JobOpenClearAllProfiles = clearAllProfiles;
      this.ProfileTreeUpdate();
    }
    else
    {
      if (SLSecond.Count <= 0)
        return;
      for (int index = 0; index <= SLSecond.Count - 1; ++index)
      {
        if (SLFirst[index].IndexOf("XReferanceLocation") >= 0)
        {
          SLFirst[index] = SLFirst[index].Replace("Right", "Left");
          index = SLFirst.Count;
        }
      }
      buFile5.SaveToFile(SLSecond, AppPath.Base + "\\temp.job");
      Item.XReferanceLocation = LeftRight;
      bool clearAllProfiles = buProfileCalc.varProfileSettings.JobOpenClearAllProfiles;
      buProfileCalc.varProfileSettings.JobOpenClearAllProfiles = false;
      this.OpenProfileJobFile(AppPath.Base + "\\temp.job", true, true, false, ref Item, false);
      buProfileCalc.varProfileSettings.JobOpenClearAllProfiles = clearAllProfiles;
      this.ProfileTreeUpdate();
    }
  }

  public void doGCodeToSimulation(ref buEyeBaseVer5.Apps.ProfileItem Item)
  {
    if (Item == null)
      return;
    Item.isGCodeSimMoveCreated = false;
    ArrayList GCodes = new ArrayList();
    clsInit.appProfile.doCreateCode(Item, ccVars.PostActive.Mode, ref GCodes, 0, false);
    GCodeToSimulationConversionSettings Settings = new GCodeToSimulationConversionSettings();
    Settings.AddMCodes = true;
    Settings.ClamperCount = Item.MaxClamperNumber;
    Settings.G53Positions.Z = buProfileCalc.varProfileSettings.ParkPositionZ;
    Settings.StartPositions = new Pnt6D(buProfileCalc.varProfileSettings.ParkPositionX, buProfileCalc.varProfileSettings.ParkPositionY, buProfileCalc.varProfileSettings.ParkPositionZ, 0.0, 0.0, 0.0);
    Settings.UseStartPosition = true;
    if (Item.XReferanceLocation == LeftRightType.Left && buProfileCalc.varProfileSettings.ChangeG2G3DirForLeftRefProfile)
    {
      Settings.ReverseG2 = true;
      Settings.ReverseG3 = true;
    }
    if (Item.XReferanceLocation == LeftRightType.Right)
    {
      Settings.StartPositions = new Pnt6D(-(buProfileCalc.varProfileSettings.MachineLength - buProfileCalc.varProfileSettings.ParkPositionX), buProfileCalc.varProfileSettings.ParkPositionY, buProfileCalc.varProfileSettings.ParkPositionZ, 0.0, 0.0, 0.0);
      if (buProfileCalc.varProfileSettings.ChangeG2G3DirForRightRefProfile)
      {
        Settings.ReverseG2 = true;
        Settings.ReverseG3 = true;
      }
      Settings.CommandList = new List<string>();
      Settings.CommandList.Add("RightProfile");
    }
    buString5.ListToSpecificList("<GCodes>", "</GCodes>", false, GCodes, ref Item.GCodeList);
    if (Item.GCodeList.Count == 0 & GCodes.Count > 0)
    {
      for (int index = 0; index <= GCodes.Count - 1; ++index)
        Item.GCodeList.Add(GCodes[index].ToString());
    }
    List<Pnt6DSimMove> pnt6DsimMoveList = new List<Pnt6DSimMove>();
    if (ccVars.PostActive.Mode == "YilmazMode1")
      this.method_0(ref Item, Settings, ref this.lastSimTool);
    if (ccVars.PostActive.Mode == "KabanMode1")
    {
      Settings.CommentChar = "(";
      this.GCodeToSimulationKabanMode1(ref Item, Settings, ref this.lastSimTool);
    }
    if (ccVars.PostActive.Mode == "KabanMode2")
    {
      Settings.CommentChar = "(";
      this.GCodeToSimulationKabanMode2(ref Item, Settings, ref this.lastSimTool);
    }
    if (ccVars.PostActive.Mode == "InfiniteMode1")
    {
      Settings.CommentChar = "(";
      this.GCodeToSimulationInfiniteMode1(ref Item, Settings, ref this.lastSimTool);
    }
    if (Item.XReferanceLocation == LeftRightType.Right && (this.activeProfile.FirstItem == null ? 0 : (this.activeProfile.FirstItem.Enable ? 1 : 0)) != 0)
    {
      List<ProfileItemCalc> calculationData = this.activeProfile.FirstItem.CalculationData;
      if (calculationData.Count > 0 && calculationData[calculationData.Count - 1].SimMoves.Count > 0)
      {
        Pnt6DSimMove pnt6DsimMove = new Pnt6DSimMove(calculationData[calculationData.Count - 1].SimMoves[calculationData[calculationData.Count - 1].SimMoves.Count - 1]);
        pnt6DsimMove.X -= buProfileCalc.varProfileSettings.MachineLength - Item.Length;
        pnt6DsimMoveList.Insert(0, pnt6DsimMove);
      }
    }
    Item.isGCodeSimMoveCreated = true;
  }

  public void doSimulationDevidedMoves(
    List<Pnt6DSimMove> tempSimMoves,
    int indexCalcData,
    ref buEyeBaseVer5.Apps.ProfileItem Item)
  {
    clsInit.cCam5.DevideSimPoints(false, ref tempSimMoves);
    this.list_4.Clear();
    if (!(Item.CalculationData.Count > 0 & indexCalcData >= 0 & indexCalcData <= Item.CalculationData.Count - 1))
      return;
    Item.CalculationData[indexCalcData].SimMoves.Clear();
    for (int index1 = 0; index1 <= tempSimMoves.Count - 1; ++index1)
    {
      bool flag = false;
      if (tempSimMoves[index1].Clampers != null && tempSimMoves[index1].Clampers.Count > 0 & this.list_4.Count > 0 && tempSimMoves[index1].Clampers.Count == this.list_4.Count)
      {
        for (int index2 = 0; index2 <= tempSimMoves[index1].Clampers.Count - 1; ++index2)
        {
          if (!buCompare5.EQ(tempSimMoves[index1].Clampers[index2], this.list_4[index2].XPosition, 0.01))
            flag = true;
        }
      }
      if (flag)
      {
        double[,] numArray = new double[tempSimMoves[index1].Clampers.Count, 10];
        for (int index3 = 0; index3 <= tempSimMoves[index1].Clampers.Count - 1; ++index3)
        {
          List<double> Values = new List<double>();
          buNumeric5.DevideMinMaxValueByNumber(this.list_4[index3].XPosition, tempSimMoves[index1].Clampers[index3], 10, ref Values);
          for (int index4 = 0; index4 <= Values.Count - 1; ++index4)
            numArray[index3, index4] = Values[index4];
        }
        if (numArray.Length > 0)
        {
          for (int index5 = 0; index5 < 10; ++index5)
          {
            Pnt6DSimMove pnt6DsimMove = new Pnt6DSimMove(tempSimMoves[index1 - 1]);
            if (pnt6DsimMove.Clampers != null)
              pnt6DsimMove.Clampers.Clear();
            else
              pnt6DsimMove.Clampers = new List<double>();
            List<buEyeBaseVer5.Apps.ProfileClamper> profileClamperList = new List<buEyeBaseVer5.Apps.ProfileClamper>();
            for (int index6 = 0; index6 <= tempSimMoves[index1].Clampers.Count - 1; ++index6)
              pnt6DsimMove.Clampers.Add(numArray[index6, index5]);
            if (pnt6DsimMove.Clampers.Count > 0)
              Item.CalculationData[indexCalcData].SimMoves.Add(pnt6DsimMove);
          }
        }
      }
      if (tempSimMoves[index1].Clampers != null && tempSimMoves[index1].Clampers.Count > 0)
      {
        this.list_4 = new List<buEyeBaseVer5.Apps.ProfileClamper>();
        for (int index7 = 0; index7 <= tempSimMoves[index1].Clampers.Count - 1; ++index7)
          this.list_4.Add(new buEyeBaseVer5.Apps.ProfileClamper(tempSimMoves[index1].Clampers[index7]));
      }
      Item.CalculationData[indexCalcData].SimMoves.Add(new Pnt6DSimMove(tempSimMoves[index1]));
    }
  }

