  public void doJobListChanged(int Index)
  {
    if (!(Index >= 0 & Index <= this.Jobs.Count - 1))
      return;
    this.DrawPreview(this.Jobs[Index], new List<Entity>(), false);
  }

  public void doJobListDelete(int Index)
  {
    if (!(Index >= 0 & Index <= this.Jobs.Count - 1) || buString5.MessageBoxQuestion(buProfile.LangProfileMessage[19]) != DialogResult.Yes)
      return;
    this.Jobs.RemoveAt(Index);
    this.frmERPList.lst_items.Items.RemoveAt(Index);
    --Index;
    if (Index < 0)
      Index = 0;
    if (this.Jobs.Count > 0)
    {
      this.DrawPreview(this.Jobs[Index], new List<Entity>(), false);
    }
    else
    {
      this.frmERPList.viewportPort.Entities.Clear();
      this.frmERPList.viewportPort.Invalidate();
    }
  }

  public void doJobListDeleteAll()
  {
    if (buString5.MessageBoxQuestion(buProfile.LangProfileMessage[27]) != DialogResult.Yes)
      return;
    this.Jobs.Clear();
    this.frmERPList.lst_items.Items.Clear();
    this.frmERPList.viewportPort.Entities.Clear();
    this.frmERPList.viewportPort.Invalidate();
  }

  public void doJobListSave(string Filename)
  {
    ArrayList StringList = new ArrayList();
    for (int index = 0; index <= this.Jobs.Count - 1; ++index)
    {
      StringList.Add((object) "<JobList>");
      StringList.AddRange((ICollection) buEyeBaseVer5.Apps.ProfileItem.ToDef(this.Jobs[index], 2));
      StringList.Add((object) "</JobList>");
    }
    buFile5.SaveToFile(StringList, Filename);
  }

  public void doJobListOpen(string Filename)
  {
    ArrayList StringList = new ArrayList();
    buFile5.OpenFromFile(Filename, ref StringList);
    buSystem.Cancel = false;
    if (StringList.Count <= 0)
      return;
    buProfileCalc.varProfileRunSettings.pathJobList = this.frmERPList.pathString;
    this.SaveByTick = true;
    buEyeBaseVer5.Apps.ProfileItem profileItem1 = (buEyeBaseVer5.Apps.ProfileItem) null;
    buEyeBaseVer5.Apps.ProfileItem profileItem2 = (buEyeBaseVer5.Apps.ProfileItem) null;
    if (this.activeProfile.FirstItem != null)
      profileItem1 = new buEyeBaseVer5.Apps.ProfileItem(this.activeProfile.FirstItem);
    if (this.activeProfile.SecondItem != null)
      profileItem2 = new buEyeBaseVer5.Apps.ProfileItem(this.activeProfile.SecondItem);
    this.frmERPList.Visible = false;
    buProfileCalc.varTemps.ShowProgressCam = false;
    if (clsItem.FrmProgress == null)
    {
      this.calculationEventArg_0 = new CalculationEventArg();
      clsItem.FrmProgress = new F_ProgressCalculation();
    }
    clsItem.FrmProgress.TopMost = true;
    clsItem.FrmProgress.Show();
    clsItem.FrmMain.Show();
    clsItem.FrmMain.Focus();
    this.Jobs.Clear();
    List<List<string>> CalcList = new List<List<string>>();
    buStatics.ListToSpecificList("<JobList>", "</JobList>", false, StringList, ref CalcList);
    for (int index = 0; index <= CalcList.Count - 1; ++index)
    {
      if (!buSystem.Cancel)
      {
        this.calculationEventArg_0.OverallProgressPercentage = Convert.ToDouble(index + 1) / Convert.ToDouble(CalcList.Count) * 100.0;
        clsInit.appCommand.CalculationInProgressCmd(this.calculationEventArg_0);
        ArrayList AL = new ArrayList();
        AL.AddRange((ICollection) CalcList[index]);
        buEyeBaseVer5.Apps.ProfileItem Profile = new buEyeBaseVer5.Apps.ProfileItem();
        buEyeBaseVer5.Apps.ProfileItem.Decode(AL, ref Profile);
        this.OpenProfileJobFile("", true, true, false, ref Profile, false, false);
        this.Jobs.Add(Profile);
      }
      else
      {
        clsItem.FrmProgress.Visible = false;
        buSystem.Cancel = false;
        return;
      }
    }
    this.activeProfile.FirstItem = profileItem1;
    this.activeProfile.SecondItem = profileItem2;
    this.DrawActiveProfile();
    this.DrawPreview(new List<Entity>());
    this.ProfileTreeUpdate();
    clsItem.FrmProgress.Visible = false;
    buProfileCalc.varTemps.ShowProgressCam = true;
    this.calculationEventArg_0 = new CalculationEventArg();
    this.frmERPList.Visible = true;
    this.cmdJobList();
  }

  public void doCreateProfile(ref buEyeBaseVer5.Apps.ProfileItem Profile, bool isNewProfile)
  {
    if (Profile == null)
      return;
    if (!buProfileCalc.varProfileSettings.RightProfileActive)
      this.activeProfile.SecondItem = (buEyeBaseVer5.Apps.ProfileItem) null;
    Point3D MinPoint1 = new Point3D();
    Point3D MidPoint = new Point3D();
    Point3D MaxPoint1 = new Point3D();
    this.ProfileOffsetCalculation(ref Profile.ProfileOffset, Profile);
    clsInit.cProfile.BoxSizeProfile(Profile, ref MinPoint1, ref MidPoint, ref MaxPoint1);
    clsInit.cProfile.CreateProfileFromDrawing(ref Profile, Plane.YZ, Profile.ProfileOffset, isNewProfile, buProfileCalc.varProfileSettings, buProfileCalc.varProfileVisualSettings, buProfileCalc.varProfileSettings.ProfileDrawingRefThickness, buProfileCalc.varProfileSettings.MinProfileFilterLength);
    if (Profile.Drawings.Count == 0 || Profile.Drawings[0].SolidEntity == null)
      return;
    Profile.TotalOffset.Z = Profile.SupportBlock.SupportBlockZHeight;
    Profile.TotalOffset.Y = -Profile.SupportBlock.SupportBlockY2BackWidth;
    ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Clear();
    ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.RegenAllCurved();
    ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Regen();
    ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Invalidate();
    Point3D MinPoint2 = new Point3D();
    MidPoint = new Point3D();
    Point3D MaxPoint2 = new Point3D();
    clsInit.cProfile.BoxSizeProfile(Profile, ref MinPoint2, ref MidPoint, ref MaxPoint2);
    Profile.ProfileCenterPoint = buVector5.ToPoint3D(MidPoint);
    Profile.ProfileMinPoint = buVector5.ToPoint3D(MinPoint2);
    Profile.ProfileMaxPoint = buVector5.ToPoint3D(MaxPoint2);
    Profile.ProfileMaxPoint.X = Profile.Length;
    if (Profile.ItemName.Trim().Length == 0)
    {
      Profile.ItemName = "ProfileItem" + this.counterProfile.ToString();
      ++this.counterProfile;
    }
    for (int index = 0; index <= Profile.Drawings.Count - 1; ++index)
    {
      Entity entity = (Entity) null;
      buEntity.Copy(Profile.Drawings[index].SolidEntity, ref entity);
      this.CreateProfileEntity(ref entity, Profile.TextureName, Profile.ItemName, Profile.Enable, Profile.colorProfile);
    }
    if (Profile.LeftAngleEntity != null & buProfileCalc.varProfileSettings.ShowProfileAngleDrawing)
      this.CreateProfileEntity(ref Profile.LeftAngleEntity, Profile.TextureName, Profile.ItemName, Profile.Enable, Profile.colorProfile);
    if (Profile.RightAngleEntity != null & buProfileCalc.varProfileSettings.ShowProfileAngleDrawing)
      this.CreateProfileEntity(ref Profile.RightAngleEntity, Profile.TextureName, Profile.ItemName, Profile.Enable, Profile.colorProfile);
    if (Profile.ProfileReferanceEntity != null)
      this.CreateProfileEntity(ref Profile.ProfileReferanceEntity, Profile.TextureName, Profile.ItemName, Profile.Enable, Profile.colorProfile);
    if (Profile.XReferanceLocation == LeftRightType.Left)
    {
      this.activeProfile.FirstItem = new buEyeBaseVer5.Apps.ProfileItem(Profile);
      buProfileCalc.varProfileRunSettings.activeProfileIndex = 0;
      this.activeItem = this.activeProfile.FirstItem;
    }
    if (Profile.XReferanceLocation == LeftRightType.Right)
    {
      this.activeProfile.SecondItem = new buEyeBaseVer5.Apps.ProfileItem(Profile);
      buProfileCalc.varProfileRunSettings.activeProfileIndex = 1;
      this.activeItem = this.activeProfile.SecondItem;
    }
    this.bUndoBuffer = true;
    this.ProfileTreeUpdate();
    ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Invalidate();
    if (buProfileCalc.varProfileRunSettings.activeProfileIndex != -1)
      return;
    buProfileCalc.varProfileRunSettings.activeProfileIndex = 0;
  }

  public void doSetActiveProfile(int ItemIndex)
  {
    if (ccVars.Pages.Count == 0 || ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Count > 0 && ItemIndex == buProfileCalc.varProfileRunSettings.activeProfileIndex && clsItem.ModelMainPreview.Entities.Count > 0)
      return;
    ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.ClearSelection();
    this.selectedEntities.Clear();
    if (!(ItemIndex >= 0 & ItemIndex <= 1))
      return;
    buProfileCalc.varProfileRunSettings.activeProfileIndex = ItemIndex;
    this.DrawActiveProfile();
    if (buProfileCalc.varProfileRunSettings.activeProfileIndex == 0)
    {
      this.activeItem = this.activeProfile.FirstItem;
      this.DrawPreview(this.activeProfile.FirstItem, new List<Entity>());
      if (this.activeProfile.FirstItem != null)
      {
        for (int index = 0; index <= this.activeProfile.FirstItem.Drawings.Count - 1; ++index)
          this.selectedEntities.Add(buVector5.CopyEntities(this.activeProfile.FirstItem.Drawings[index].SolidEntity));
        buProfileCalc.varProfileRunSettings.ShapeDataParameters.SizeMaterailWidth = this.activeProfile.FirstItem.Length;
        buProfileCalc.varProfileRunSettings.ShapeDataParameters.SizeMaterailHeight = this.activeProfile.FirstItem.Width;
        buProfileCalc.varProfileRunSettings.ShapeDataParameters.SizeMaterailDepth = this.activeProfile.FirstItem.Height;
      }
      clsItem.FrmProfileJob.tree_jobs.Nodes[0].Nodes[0].ForeColor = buProfileCalc.varProfileVisualSettings.TreeItemSelectedColor;
    }
    if (buProfileCalc.varProfileRunSettings.activeProfileIndex == 1)
    {
      if (this.activeProfile.SecondItem != null)
      {
        this.activeItem = this.activeProfile.SecondItem;
        this.DrawPreview(this.activeProfile.SecondItem, new List<Entity>());
        for (int index = 0; index <= this.activeProfile.SecondItem.Drawings.Count - 1; ++index)
          this.selectedEntities.Add(buVector5.CopyEntities(this.activeProfile.SecondItem.Drawings[index].SolidEntity));
        buProfileCalc.varProfileRunSettings.ShapeDataParameters.SizeMaterailWidth = this.activeProfile.SecondItem.Length;
        buProfileCalc.varProfileRunSettings.ShapeDataParameters.SizeMaterailHeight = this.activeProfile.SecondItem.Width;
        buProfileCalc.varProfileRunSettings.ShapeDataParameters.SizeMaterailDepth = this.activeProfile.SecondItem.Height;
      }
      clsItem.FrmProfileJob.tree_jobs.Nodes[0].Nodes[1].ForeColor = buProfileCalc.varProfileVisualSettings.TreeItemSelectedColor;
    }
    clsItem.ModelMainPreview.ZoomFit();
    clsItem.ModelMainPreview.Invalidate();
    this.activeOP = (buEyeBaseVer5.Apps.ProfileOperation) null;
  }

  public void doDeleteProfile(int ProfileIndex)
  {
    if (ProfileIndex < 0)
      return;
    this.bUndoBuffer = true;
    if (ProfileIndex == 0)
      this.activeProfile.FirstItem = (buEyeBaseVer5.Apps.ProfileItem) null;
    if (ProfileIndex == 1)
      this.activeProfile.SecondItem = (buEyeBaseVer5.Apps.ProfileItem) null;
    this.DrawActiveProfile();
    this.DrawPreview(new List<Entity>());
    this.ProfileTreeUpdate();
  }

  public void doEditProfile(int ProfileIndex)
  {
    try
    {
      buProfileCalc.varProfileRunSettings.IncrementalMode = false;
      if (ProfileIndex == 0)
        this.doEditProfile(this.activeProfile.FirstItem);
      if (ProfileIndex != 1)
        return;
      this.doEditProfile(this.activeProfile.SecondItem);
    }
    catch (Exception ex)
    {
      string str = "";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, true, str);
    }
  }

  public void doEditProfile(buEyeBaseVer5.Apps.ProfileItem Item)
  {
    this.bUndoBuffer = true;
    List<buEyeBaseVer5.Apps.ProfileOperation> CopiedOperation = new List<buEyeBaseVer5.Apps.ProfileOperation>();
    buEyeBaseVer5.Apps.ProfileOperation.Copy(Item.Operations, ref CopiedOperation);
    bool BoxProfile = false;
    if (Item.ProfileType != ProfileNewType.Drawing)
      BoxProfile = true;
    if (!this.cmdAddProfile(Item, BoxProfile))
      return;
    buEyeBaseVer5.Apps.ProfileItem profileItem = clsInit.cProfile.SelectActiveProfile(this.activeProfile.FirstItem, this.activeProfile.SecondItem, ref buProfileCalc.varProfileRunSettings.activeProfileIndex);
    for (int index = 0; index <= CopiedOperation.Count - 1; ++index)
    {
      this.ToolChangeForced = true;
      clsInit.cProfile.ProfileCamDataToCamParameter(CopiedOperation[index].CamOPData, ref CopiedOperation[index].OperationData.CamParMilling);
      buProfileCalc.varProfileRunSettings.OPData.selectedPlane = (Plane) CopiedOperation[index].OperationData.selectedPlane.Clone();
      ShapeUpdateArg Data2 = new ShapeUpdateArg()
      {
        Finished = true,
        Parameters = new ShapeRuntimeData(buProfileCalc.varProfileRunSettings.ShapeDataParameters),
        ToolName = CopiedOperation[index].Tool.Data.Name,
        ToolChangeForced = true
      };
      Data2.Parameters.Priority = CopiedOperation[index].Priority;
      Data2.Tool = new ToolBase5(CopiedOperation[index].Tool);
      this.OPPriority = CopiedOperation[index].Priority;
      SizeObject Size = new SizeObject(profileItem.Length, profileItem.Width, profileItem.Height);
      buShape buShape = new buShape();
      buShape.BasePoint = new Point3D(CopiedOperation[index].OperationData.basePosition.X, Math.Abs(CopiedOperation[index].OperationData.basePosition.Y), CopiedOperation[index].OperationData.basePosition.Z);
      if (buCompare5.EQ(buShape.BasePoint.X, 0.0) & buCompare5.EQ(buShape.BasePoint.Y, 0.0) & buCompare5.EQ(buShape.BasePoint.Y, 0.0))
      {
        buShape.BasePoint.X = CopiedOperation[index].OperationData.Position.X;
        buShape.BasePoint.Y = CopiedOperation[index].OperationData.Position.Y;
        buShape.BasePoint.Z = CopiedOperation[index].OperationData.Position.Z;
        buShape.Corner = CornerLocation.LeftTop;
      }
      clsInit.cVector5.CoordinateFromPlaneAndCorner(Size, CopiedOperation[index].OperationData.Corner, buConversion5.PlaneNamesToPlaneBoxNames(CopiedOperation[index].OperationData.selectedPlaneName), ref buShape, ref CopiedOperation[index].OperationData.Position, this.shapeCreateParameters_0.SingX, this.shapeCreateParameters_0.SingY);
      clsInit.cVector5.CoordinateFromPlaneAndCorner(Size, CopiedOperation[index].OperationData.Corner, buConversion5.PlaneNamesToPlaneBoxNames(CopiedOperation[index].OperationData.selectedPlaneName), ref new buShape()
      {
        BasePoint = new Point3D(CopiedOperation[index].OperationData.basePosition.X, CopiedOperation[index].OperationData.basePosition.Y, CopiedOperation[index].OperationData.basePosition.Z)
      }, ref CopiedOperation[index].OperationData.Position, this.shapeCreateParameters_0.SingX, this.shapeCreateParameters_0.SingY);
      this.OnlineOperation((object) null, (object) Data2, (object) CopiedOperation[index].OperationData);
    }
    this.RearrangeOperationID();
    this.ProfileTreeUpdate();
    this.ToolChangeForced = false;
  }

  public void doEditDxf(object Data1, object Data2)
  {
    if (Data1 == null || Data1.ToString().Length <= 0)
      return;
    FileInfo fileInfo = new FileInfo(Data1.ToString());
    if (!fileInfo.Exists)
      return;
    clsItem.frmEditor = new F_Editor();
    clsVar.varEditorRuntimeSet.isFoamMode = false;
    clsVar.varEditorRuntimeSet.isSewingMode = false;
    clsVar.varEditorRuntimeSet.isSketchMode = false;
    clsItem.frmEditor.PropertiesForm.FormCloseMode = FormCloseModeType.Invisible;
    clsItem.frmEditor.fileName = fileInfo.FullName;
    clsItem.frmEditor.OpenCommands.Add("MoveZero");
    clsItem.frmEditor.OpenCommands.Add("SetViewTop");
    clsItem.frmEditor.OpenCommands.Add("ZoomFit");
    clsItem.frmEditor.OpenCommands.Add("Invalidate");
    clsItem.frmEditor.Init();
    int num = (int) clsItem.frmEditor.ShowDialog();
  }

  public void doUnSelectProfile(int ProfileIndex)
  {
    try
    {
      if (ProfileIndex == 0)
      {
        for (int index = 0; index <= this.activeProfile.FirstItem.Operations.Count - 1; ++index)
          this.activeProfile.FirstItem.Operations[index].Selected = false;
        if (ProfileIndex >= 0 & ProfileIndex <= clsItem.FrmProfileJob.tree_jobs.Nodes[0].Nodes.Count - 1)
        {
          for (int index = 0; index <= clsItem.FrmProfileJob.tree_jobs.Nodes[0].Nodes[ProfileIndex].Nodes.Count - 1; ++index)
            clsItem.FrmProfileJob.tree_jobs.Nodes[0].Nodes[ProfileIndex].Nodes[index].Checked = false;
        }
      }
      if (ProfileIndex != 1)
        return;
      for (int index = 0; index <= this.activeProfile.SecondItem.Operations.Count - 1; ++index)
        this.activeProfile.SecondItem.Operations[index].Selected = false;
      if (!(ProfileIndex >= 0 & ProfileIndex <= clsItem.FrmProfileJob.tree_jobs.Nodes[0].Nodes.Count - 1))
        return;
      for (int index = 0; index <= clsItem.FrmProfileJob.tree_jobs.Nodes[0].Nodes[ProfileIndex].Nodes.Count - 1; ++index)
        clsItem.FrmProfileJob.tree_jobs.Nodes[0].Nodes[ProfileIndex].Nodes[index].Checked = false;
    }
    catch (Exception ex)
    {
      string str = "";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, true, str);
    }
  }

