  public void doDevideProfileItemByLength(
    buEyeBaseVer5.Apps.ProfileItem refItem,
    double DevideLength,
    ref List<ProfileItemCalc> devidedItems)
  {
    ProfileItemCalc profileItemCalc1 = (ProfileItemCalc) null;
    devidedItems.Clear();
    devidedItems = new List<ProfileItemCalc>();
    double num1 = DevideLength;
    if (DevideLength >= refItem.Length)
      return;
    for (int index = 0; index <= refItem.Operations.Count - 1; ++index)
    {
      if (refItem.Operations[index].MinPoint.X < DevideLength & DevideLength < refItem.Operations[index].MaxPoint.X)
        num1 = refItem.Operations[index].MinPoint.X - 50.0;
    }
    ProfileItemCalc profileItemCalc2 = new ProfileItemCalc(refItem);
    profileItemCalc2.Length = DevideLength;
    profileItemCalc2.SimMoves = new List<Pnt6DSimMove>();
    profileItemCalc2.OriginalIsLongProfile = true;
    ProfileItemCalc profileItemCalc3 = new ProfileItemCalc(refItem);
    profileItemCalc3.XReferanceLocation = LeftRightType.Right;
    profileItemCalc3.Length = refItem.Length - DevideLength;
    profileItemCalc3.SimMoves = new List<Pnt6DSimMove>();
    profileItemCalc3.OriginalIsLongProfile = true;
    for (int index1 = 0; index1 <= refItem.Operations.Count - 1; ++index1)
    {
      if (refItem.Operations[index1].MinPoint.X < num1 & refItem.Operations[index1].MaxPoint.X < num1)
      {
        GProfileOperation gprofileOperation = new GProfileOperation(refItem.Operations[index1]);
        if (gprofileOperation.OperationData.selectedPlaneName != planeNames.Bottom)
        {
          profileItemCalc2.calcOperations.Add(gprofileOperation);
        }
        else
        {
          if (profileItemCalc1 == null)
          {
            profileItemCalc1 = new ProfileItemCalc(refItem);
            profileItemCalc1.Length = num1;
            profileItemCalc1.SimMoves = new List<Pnt6DSimMove>();
          }
          clsInit.cVector5.Rotate(new Point3D(0.0, -refItem.Width / 2.0, refItem.Height / 2.0), 180.0, Vector3D.AxisX, ref gprofileOperation.EntityMultiCam);
          profileItemCalc1.calcOperations.Add(gprofileOperation);
          profileItemCalc1.CalcType = ProfileExcType.NormalBottom;
        }
      }
      if (refItem.Operations[index1].MinPoint.X > num1 & refItem.Operations[index1].MaxPoint.X > num1)
      {
        GProfileOperation gprofileOperation = new GProfileOperation(refItem.Operations[index1]);
        double num2 = gprofileOperation.SizePoint.MaxPoint.X - gprofileOperation.OperationData.Position.X;
        double num3 = gprofileOperation.SizePoint.MinPoint.X - gprofileOperation.OperationData.Position.X;
        gprofileOperation.XReferanceLocation = LeftRightType.Right;
        if (gprofileOperation.OperationData.Corner == CornerLocation.LeftBottom | gprofileOperation.OperationData.Corner == CornerLocation.LeftCenter | gprofileOperation.OperationData.Corner == CornerLocation.LeftTop)
        {
          gprofileOperation.OperationData.Corner = CornerLocation.LeftTop;
          gprofileOperation.OperationData.Position.X = refItem.Length - gprofileOperation.OperationData.Position.X;
          gprofileOperation.OperationData.basePosition.X = refItem.Length - gprofileOperation.OperationData.basePosition.X;
        }
        if (gprofileOperation.OperationData.Corner == CornerLocation.RightTop)
        {
          gprofileOperation.OperationData.Corner = CornerLocation.LeftTop;
          gprofileOperation.OperationData.Position.X = gprofileOperation.OperationData.basePosition.X;
        }
        if (gprofileOperation.OperationData.Corner == CornerLocation.RightBottom)
        {
          gprofileOperation.OperationData.Corner = CornerLocation.LeftBottom;
          gprofileOperation.OperationData.Position.X = gprofileOperation.OperationData.basePosition.X;
        }
        if (gprofileOperation.OperationData.Corner == CornerLocation.RightTop)
        {
          gprofileOperation.OperationData.Corner = CornerLocation.LeftTop;
          gprofileOperation.OperationData.Position.X = gprofileOperation.OperationData.basePosition.X;
        }
        clsInit.cVector5.Move(-DevideLength, 0.0, 0.0, ref gprofileOperation.EntityMultiCam);
        gprofileOperation.SizePoint.MinPoint.X = gprofileOperation.OperationData.Position.X + num3;
        gprofileOperation.SizePoint.MaxPoint.X = gprofileOperation.OperationData.Position.X + num2;
        if (gprofileOperation.OperationData.OperationType == ProfileOperationTypes.Notch)
        {
          for (int index2 = 0; index2 <= gprofileOperation.CamCalculation.Count - 1; ++index2)
          {
            for (int index3 = 0; index3 <= gprofileOperation.CamCalculation[index2].CamPoints.Count - 1; ++index3)
            {
              for (int index4 = 0; index4 <= gprofileOperation.CamCalculation[index2].CamPoints[index3].Points.Count - 1; ++index4)
                gprofileOperation.CamCalculation[index2].CamPoints[index3].Points[index4].P9.X -= DevideLength;
            }
          }
        }
        profileItemCalc3.calcOperations.Add(gprofileOperation);
      }
    }
    if (!(profileItemCalc2 != null & profileItemCalc3 != null))
      return;
    profileItemCalc3.CalcType = ProfileExcType.LongSecondPart;
    profileItemCalc3.XReferanceLocation = LeftRightType.Right;
    profileItemCalc3.LongProfileFirstPartLength = profileItemCalc2.Length;
    devidedItems.Add(profileItemCalc2);
    if (profileItemCalc1 != null)
      devidedItems.Add(profileItemCalc1);
    devidedItems.Add(profileItemCalc3);
  }

  public void doDevideProfileItemByLength(
    buEyeBaseVer5.Apps.ProfileItem refItem,
    double DevideLength,
    ref buEyeBaseVer5.Apps.ProfileItem firstItem,
    ref buEyeBaseVer5.Apps.ProfileItem secondItem)
  {
    double num1 = DevideLength;
    if (DevideLength >= refItem.Length)
      return;
    for (int index = 0; index <= refItem.Operations.Count - 1; ++index)
    {
      if (refItem.Operations[index].MinPoint.X < DevideLength & DevideLength < refItem.Operations[index].MaxPoint.X)
        num1 = refItem.Operations[index].MinPoint.X - 50.0;
    }
    firstItem = new buEyeBaseVer5.Apps.ProfileItem(refItem);
    firstItem.Operations.Clear();
    firstItem.Length = DevideLength;
    secondItem = new buEyeBaseVer5.Apps.ProfileItem(refItem);
    secondItem.Operations.Clear();
    secondItem.XReferanceLocation = LeftRightType.Right;
    secondItem.Length = refItem.Length - DevideLength;
    for (int index = 0; index <= refItem.Operations.Count - 1; ++index)
    {
      if (refItem.Operations[index].MinPoint.X < num1 & refItem.Operations[index].MaxPoint.X < num1)
      {
        buEyeBaseVer5.Apps.ProfileOperation CopiedOperation = new buEyeBaseVer5.Apps.ProfileOperation();
        buEyeBaseVer5.Apps.ProfileOperation.Copy(refItem.Operations[index], ref CopiedOperation);
        firstItem.Operations.Add(CopiedOperation);
      }
      if (refItem.Operations[index].MinPoint.X > num1 & refItem.Operations[index].MaxPoint.X > num1)
      {
        buEyeBaseVer5.Apps.ProfileOperation CopiedOperation = new buEyeBaseVer5.Apps.ProfileOperation();
        buEyeBaseVer5.Apps.ProfileOperation.Copy(refItem.Operations[index], ref CopiedOperation);
        double num2 = refItem.Length - DevideLength;
        clsInit.cVector5.Move(-DevideLength, 0.0, 0.0, ref CopiedOperation.EntityMultiCam);
        double num3 = CopiedOperation.OperationData.Position.X - num2;
        CopiedOperation.OperationData.Position.X = num2;
        CopiedOperation.MinPoint.X -= num3;
        CopiedOperation.MaxPoint.X -= num3;
        secondItem.Operations.Add(CopiedOperation);
      }
    }
  }

  public void doAddSupportBlockOffsets(ref buEyeBaseVer5.Apps.ProfileItem Item)
  {
    for (int index1 = 0; index1 <= Item.CalculationData.Count - 1; ++index1)
    {
      for (int index2 = 0; index2 <= Item.CalculationData[index1].calcOperations.Count - 1; ++index2)
      {
        for (int index3 = 0; index3 <= Item.CalculationData[index1].calcOperations[index2].CamCalculation.Count - 1; ++index3)
        {
          camTp camTp = Item.CalculationData[index1].calcOperations[index2].CamCalculation[index3];
          for (int index4 = 0; index4 <= camTp.CamPoints.Count - 1; ++index4)
          {
            for (int index5 = 0; index5 <= camTp.CamPoints[index4].Points.Count - 1; ++index5)
            {
              Pnt9D p9 = camTp.CamPoints[index4].Points[index5].P9;
              p9.Z += Item.SupportBlock.SupportBlockZHeight;
              if (p9.Z > buProfileCalc.varProfileSettings.MaxZMove)
                p9.Z = buProfileCalc.varProfileSettings.MaxZMove;
              p9.Y -= Item.SupportBlock.SupportBlockY2BackWidth;
            }
          }
        }
      }
    }
  }

