  public void doEnableDisableProfile(int indexProfile, bool Status)
  {
    if (buProfileCalc.varProfileRunSettings.activeProfileIndex == 0)
    {
      if (this.activeProfile.FirstItem == null)
        return;
      buEyeBaseVer5.Apps.ProfileItem firstItem = this.activeProfile.FirstItem;
      firstItem.Enable = Status;
      firstItem.IsClamperDone = false;
      this.activeProfile.isSimulationDone = false;
      if (firstItem.Enable)
      {
        clsItem.FrmProfileJob.tree_jobs.Nodes[0].Nodes[buProfileCalc.varProfileRunSettings.activeProfileIndex].ImageIndex = 30;
        clsItem.FrmProfileJob.tree_jobs.Nodes[0].Nodes[buProfileCalc.varProfileRunSettings.activeProfileIndex].SelectedImageIndex = 30;
      }
      else
      {
        clsItem.FrmProfileJob.tree_jobs.Nodes[0].Nodes[buProfileCalc.varProfileRunSettings.activeProfileIndex].ImageIndex = 40;
        clsItem.FrmProfileJob.tree_jobs.Nodes[0].Nodes[buProfileCalc.varProfileRunSettings.activeProfileIndex].SelectedImageIndex = 40;
      }
    }
    if (buProfileCalc.varProfileRunSettings.activeProfileIndex != 1 || this.activeProfile.SecondItem == null)
      return;
    buEyeBaseVer5.Apps.ProfileItem secondItem = this.activeProfile.SecondItem;
    secondItem.Enable = Status;
    secondItem.IsClamperDone = false;
    this.activeProfile.isSimulationDone = false;
    if (secondItem.Enable)
    {
      clsItem.FrmProfileJob.tree_jobs.Nodes[0].Nodes[buProfileCalc.varProfileRunSettings.activeProfileIndex].ImageIndex = 31 /*0x1F*/;
      clsItem.FrmProfileJob.tree_jobs.Nodes[0].Nodes[buProfileCalc.varProfileRunSettings.activeProfileIndex].SelectedImageIndex = 31 /*0x1F*/;
    }
    else
    {
      clsItem.FrmProfileJob.tree_jobs.Nodes[0].Nodes[buProfileCalc.varProfileRunSettings.activeProfileIndex].ImageIndex = 41;
      clsItem.FrmProfileJob.tree_jobs.Nodes[0].Nodes[buProfileCalc.varProfileRunSettings.activeProfileIndex].SelectedImageIndex = 41;
    }
  }

  public void doCheckProfileWarnings(ref buEyeBaseVer5.Apps.ProfileItem Item)
  {
    if (Item != null)
      Item.warningAllList.Clear();
    clsInit.cProfile.AddOperationListsToProfileLists(ref Item);
    if (!Item.isCollisionControlDone)
      clsInit.cProfile.AddWarningToProfile(buLangTranslate.preSentencesProfile.NoCollisionControlDone, ref Item);
    if (!Item.isSimulationDone)
      clsInit.cProfile.AddWarningToProfile(buLangTranslate.preSentencesProfile.NoSimulationDone, ref Item);
    if (Item.IsClamperDone)
      return;
    clsInit.cProfile.AddWarningToProfile(buLangTranslate.preSentencesProfile.NoClamperCalculationDone, ref Item);
  }

  public void doCheckProfileError()
  {
    if (this.activeProfile.FirstItem != null)
      this.activeProfile.FirstItem.errorAllList.Clear();
    if (this.activeProfile.SecondItem != null)
      this.activeProfile.SecondItem.errorAllList.Clear();
    bool flag1 = false;
    bool flag2 = false;
    if ((this.activeProfile.FirstItem == null ? 0 : (this.activeProfile.FirstItem.Enable ? 1 : 0)) != 0)
    {
      flag1 = true;
      if (this.activeProfile.FirstItem.isCollisionOnlineAvailable)
        clsInit.cProfile.AddErrorToProfile(buLangTranslate.preSentencesProfile.OnlineCollisionDetected, ref this.activeProfile.FirstItem);
      if (this.activeProfile.FirstItem.isCollisionOfflineAvailable)
        clsInit.cProfile.AddErrorToProfile(buLangTranslate.preSentencesProfile.OfflineCollisionDetected, ref this.activeProfile.FirstItem);
    }
    if ((this.activeProfile.SecondItem == null ? 0 : (this.activeProfile.SecondItem.Enable ? 1 : 0)) != 0)
    {
      flag2 = true;
      if (this.activeProfile.SecondItem.isCollisionOnlineAvailable)
        clsInit.cProfile.AddErrorToProfile(buLangTranslate.preSentencesProfile.OnlineCollisionDetected, ref this.activeProfile.SecondItem);
      if (this.activeProfile.SecondItem.isCollisionOfflineAvailable)
        clsInit.cProfile.AddErrorToProfile(buLangTranslate.preSentencesProfile.OfflineCollisionDetected, ref this.activeProfile.SecondItem);
    }
    if (flag1 & flag2)
    {
      if (this.activeProfile.FirstItem.Length + this.activeProfile.SecondItem.Length <= buProfileCalc.varProfileSettings.MachineLength)
        return;
      clsInit.cProfile.AddErrorToProfile(buLangTranslate.preSentencesProfile.BothProfileLengthCanNotBeBiggerThenMachineOperationLength, ref this.activeProfile.FirstItem);
      clsInit.cProfile.AddErrorToProfile(buLangTranslate.preSentencesProfile.BothProfileLengthCanNotBeBiggerThenMachineOperationLength, ref this.activeProfile.SecondItem);
    }
    else if (flag1 & !flag2)
    {
      if (this.activeProfile.FirstItem.Length <= buProfileCalc.varProfileSettings.MachineLength * 2.0)
        return;
      clsInit.cProfile.AddErrorToProfile(buLangTranslate.preSentencesProfile.ProfileLengthisBiggerThenLimit, ref this.activeProfile.FirstItem);
    }
    else
    {
      if (!(!flag1 & flag2) || this.activeProfile.SecondItem.Length <= buProfileCalc.varProfileSettings.MachineLength * 2.0)
        return;
      clsInit.cProfile.AddErrorToProfile(buLangTranslate.preSentencesProfile.ProfileLengthisBiggerThenLimit, ref this.activeProfile.SecondItem);
    }
  }

