  public void doGeneralTick(int TickCount)
  {
    if (TickCount % 300 == 0 && this.SaveByTick)
    {
      this.SaveProfileFile();
      this.SaveByTick = false;
    }
    if ((1 & (buProfileCalc.varProfileSettings.AutoSave ? 1 : 0)) == 0)
      return;
    DateTime dateTime = new DateTime();
    if (!(DateTime.Now.Subtract(this.lastDate).TotalSeconds > (double) buProfileCalc.varProfileSettings.AutoSaveTimeSec & ccVars.Action == actionTypeBU.None))
      return;
    if (this.cntAutoSave > buProfileCalc.varProfileSettings.AutoSaveMaxCount)
      this.cntAutoSave = 1;
    DirectoryInfo directoryInfo = new DirectoryInfo(AppPath.Base + "\\AutoSave");
    if (!directoryInfo.Exists)
      directoryInfo.Create();
    if (!(this.activeProfile.FirstItem != null | this.activeProfile.SecondItem != null))
      return;
    int num1 = 0;
    if (this.activeProfile.FirstItem != null)
      num1 += this.activeProfile.FirstItem.Operations.Count;
    if (this.activeProfile.SecondItem != null)
      num1 += this.activeProfile.SecondItem.Operations.Count;
    if (num1 > 0)
    {
      string str = "";
      if (buProfileCalc.varProfileSettings.AutoSaveWithTimeFileName)
      {
        string[] strArray = new string[6];
        strArray[0] = "_H";
        DateTime now = DateTime.Now;
        int num2 = now.Hour;
        strArray[1] = num2.ToString("D2");
        strArray[2] = "M";
        now = DateTime.Now;
        num2 = now.Minute;
        strArray[3] = num2.ToString("D2");
        strArray[4] = "S";
        now = DateTime.Now;
        num2 = now.Second;
        strArray[5] = num2.ToString("D2");
        str = string.Concat(strArray);
      }
      this.SaveProfileJobFile($"{directoryInfo.FullName}\\AutoSave{this.cntAutoSave.ToString()}{str}.buprofile", false);
      ++this.cntAutoSave;
    }
    this.lastDate = DateTime.Now;
  }

  public void ProgramClosing()
  {
    if (!buProfileCalc.varProfileSettings.SaveCurrentProfilesWhileProgramClosing)
      return;
    DirectoryInfo directoryInfo = new DirectoryInfo(AppPath.Base + "\\AutoSave");
    if (!directoryInfo.Exists)
      directoryInfo.Create();
    if (!(this.activeProfile.FirstItem != null | this.activeProfile.SecondItem != null))
      return;
    int num = 0;
    if (this.activeProfile.FirstItem != null)
      num += this.activeProfile.FirstItem.Operations.Count;
    if (this.activeProfile.SecondItem != null)
      num += this.activeProfile.SecondItem.Operations.Count;
    if (num <= 0)
      return;
    this.SaveProfileJobFile(AppPath.Base + "\\AutoSave\\LastJobOperations.buprofile", false);
  }

