  public void doFindPlane(Brep.Face face, bool RunOperation, bool AddList)
  {
    if (face == null)
      return;
    Surface[] surface = face.ConvertToSurface();
    if (surface != null && surface.Length != 0 && surface[0] is TabulatedSurface)
    {
      TabulatedSurface tabulatedSurface = surface[0] as TabulatedSurface;
      if (tabulatedSurface.BoxMax == (Point3D) null)
        tabulatedSurface.Regen(0.1);
      double Length = tabulatedSurface.BoxMax.X - tabulatedSurface.BoxMin.X;
      ICurve directrix = tabulatedSurface.Directrix;
      double Height = Point3D.Distance(directrix.StartPoint, directrix.EndPoint);
      Point3D Val1 = new Point3D(0.0, directrix.StartPoint.Y, directrix.StartPoint.Z);
      Point3D Val2 = new Point3D(0.0, directrix.EndPoint.Y, directrix.EndPoint.Z);
      if (Val2.Z < Val1.Z)
      {
        Val1 = new Point3D(0.0, directrix.EndPoint.Y, directrix.EndPoint.Z);
        Val2 = new Point3D(0.0, directrix.StartPoint.Y, directrix.StartPoint.Z);
      }
      double num1 = clsInit.cVector5.PointAngle(Val2, Val1, Plane.YZ);
      double num2 = num1;
      if (num1 > 90.0)
      {
        num2 = 90.0 - num1;
        buEyeShotFunctions.ExchangeTwoVaues(ref Val1, ref Val2);
      }
      Plane checkPlane = new Plane(Val1, Vector3D.AxisX, Vector3D.AxisY);
      checkPlane.Rotate(buConversion5.DegreeToRadian(num2), Vector3D.AxisX, Val1);
      SelectedPlaneInfo P = new SelectedPlaneInfo();
      clsInit.cVector5.PlaneCreate(ProfilePlaneDef.None, -1, true, Val1, num2, Length, Height, buProfileCalc.varProfileSettings.PlaneThickness, buProfileCalc.varUCSData, ref P);
      buProfileCalc.varProfileRunSettings.selectedFreePlaneLength = directrix.Length();
      if (!AddList)
      {
        if (RunOperation)
          this.activeProfile.FirstItem.selectedFreePlanes.Clear();
        if (this.activeProfile.FirstItem.selectedFreePlanes.Count == 0)
        {
          this.activeProfile.FirstItem.selectedFreePlanes.Add(P);
          ccVars.selectedFace = (Brep.Face) null;
        }
        else
        {
          bool flag = false;
          for (int index = 0; index <= this.activeProfile.FirstItem.selectedFreePlanes.Count - 1; ++index)
          {
            if (clsInit.cVector5.isPlanesSame(this.activeProfile.FirstItem.selectedFreePlanes[index].refPlane, checkPlane))
              flag = true;
          }
          if (!flag)
            this.activeProfile.FirstItem.selectedFreePlanes.Add(P);
          ccVars.selectedFace = (Brep.Face) null;
        }
        if (RunOperation)
        {
          buProfileCalc.varProfileRunSettings.OPData.selectedPlaneName = planeNames.Free;
          buProfileCalc.varProfileRunSettings.OPData.selectedPlane = checkPlane;
          buProfileCalc.varProfileRunSettings.OPData.selectedPlaneInfo = P;
          this.planeLastSelected = (Plane) checkPlane.Clone();
          buProfileCalc.varProfileRunSettings.OPData.Position.Y = 0.0;
          this.cmdOperationMenu();
        }
      }
      else
      {
        DialogBoxText dialogBoxText = new DialogBoxText();
        dialogBoxText.Caption = $"{AppLanguage.CadCamDynamic[43]} {AppLanguage.CadCamDynamic[40]}";
        dialogBoxText.Text = $"{AppLanguage.CadCamDynamic[43]} {AppLanguage.CadCamDynamic[40]}";
        dialogBoxText.Init("");
        int num3 = (int) dialogBoxText.ShowDialog();
        if (dialogBoxText.Result == DialogResult.OK)
        {
          P.Explanation = dialogBoxText.Value;
          if (clsProfile.selectedPlanes.Count == 0)
          {
            this.AddPlane(P);
            ccVars.selectedFace = (Brep.Face) null;
          }
          else
          {
            bool flag = false;
            for (int index = 0; index <= clsProfile.selectedPlanes.Count - 1; ++index)
            {
              if (clsInit.cVector5.isPlanesSame(clsProfile.selectedPlanes[index].refPlane, checkPlane))
                flag = true;
            }
            if (!flag)
              this.AddPlane(P);
            ccVars.selectedFace = (Brep.Face) null;
          }
        }
        if (RunOperation)
        {
          buProfileCalc.varProfileRunSettings.OPData.selectedPlaneName = planeNames.Free;
          buProfileCalc.varProfileRunSettings.OPData.selectedPlane = checkPlane;
          buProfileCalc.varProfileRunSettings.OPData.selectedPlaneInfo = P;
          this.planeLastSelected = (Plane) checkPlane.Clone();
          buProfileCalc.varProfileRunSettings.OPData.Position.Y = 0.0;
          this.cmdOperationMenu();
        }
      }
    }
    if (RunOperation)
      return;
    clsInit.appCommand.Reset();
  }

  public void doUndoRedoGetBack(UndoV5 undo)
  {
    if (undo.Profiles == null)
      return;
    if (undo.Profiles != null)
    {
      this.activeProfile = new ProfileBase(undo.Profiles);
      if (this.activeProfile.FirstItem == null & this.activeProfile.SecondItem == null)
      {
        buProfileCalc.varProfileRunSettings.activeProfileIndex = -1;
        this.DrawActiveProfile();
        this.DrawPreview(new List<Entity>());
      }
      else if (this.activeProfile.FirstItem != null & this.activeProfile.SecondItem == null)
      {
        buProfileCalc.varProfileRunSettings.activeProfileIndex = 0;
        this.DrawActiveProfile();
        this.DrawPreview(new List<Entity>());
      }
      else if (this.activeProfile.FirstItem == null & this.activeProfile.SecondItem != null)
      {
        buProfileCalc.varProfileRunSettings.activeProfileIndex = 1;
        this.DrawActiveProfile();
        this.DrawPreview(new List<Entity>());
      }
      else
      {
        this.DrawActiveProfile();
        this.DrawPreview(new List<Entity>());
      }
    }
    this.ProfileTreeUpdate();
  }

