  public void doCopyClamperPositionToNextIfSame(
    buEyeBaseVer5.Apps.ProfileItem Profile,
    List<buEyeBaseVer5.Apps.ProfileClamper> OldClampersPos,
    List<buEyeBaseVer5.Apps.ProfileClamper> NewClampersPos,
    int indexOperation)
  {
    for (int index1 = indexOperation + 1; index1 <= Profile.CalculationData[buProfileCalc.varProfileRunSettings.activeCalcDataIndex].calcOperations.Count - 1; ++index1)
    {
      bool flag = true;
      if (OldClampersPos.Count != Profile.CalculationData[buProfileCalc.varProfileRunSettings.activeCalcDataIndex].calcOperations[index1].Clampers.Count)
        flag = false;
      for (int index2 = 0; index2 <= OldClampersPos.Count - 1; ++index2)
      {
        if (index2 <= Profile.CalculationData[buProfileCalc.varProfileRunSettings.activeCalcDataIndex].calcOperations[index1].Clampers.Count - 1 && !buCompare5.EQ(Profile.CalculationData[buProfileCalc.varProfileRunSettings.activeCalcDataIndex].calcOperations[index1].Clampers[index2].XPosition + Profile.CalculationData[buProfileCalc.varProfileRunSettings.activeCalcDataIndex].calcOperations[index1].Clampers[index2].XOffset, OldClampersPos[index2].XPosition + OldClampersPos[index2].XOffset))
          flag = false;
      }
      if (flag)
      {
        for (int index3 = 0; index3 <= NewClampersPos.Count - 1; ++index3)
        {
          Profile.CalculationData[buProfileCalc.varProfileRunSettings.activeCalcDataIndex].calcOperations[index1].Clampers[index3].XPosition = NewClampersPos[index3].XPosition;
          Profile.CalculationData[buProfileCalc.varProfileRunSettings.activeCalcDataIndex].calcOperations[index1].Clampers[index3].XOffset = NewClampersPos[index3].XOffset;
        }
      }
    }
  }

  public void doPatternCopy()
  {
    buEyeBaseVer5.Apps.ProfileItem Profile = clsInit.cProfile.SelectActiveProfile(this.activeProfile.FirstItem, this.activeProfile.SecondItem, ref buProfileCalc.varProfileRunSettings.activeProfileIndex);
    if (Profile == null)
      return;
    this.bUndoBuffer = true;
    if (Profile != null && buProfileCalc.varProfileRunSettings.PatternCopyCount > 0 & buProfileCalc.varProfileRunSettings.PatternCopyDistance > 0.0)
    {
      int count = Profile.Operations.Count;
      double x1 = 0.0;
      double x2 = buProfileCalc.varProfileRunSettings.OPData.Position.X;
      for (int index1 = 1; index1 <= buProfileCalc.varProfileRunSettings.PatternCopyCount; ++index1)
      {
        for (int index2 = 0; index2 <= count - 1; ++index2)
        {
          this.UndoDontProfile = true;
          buEyeBaseVer5.Apps.ProfileOperation CopiedOperation = new buEyeBaseVer5.Apps.ProfileOperation();
          buEyeBaseVer5.Apps.ProfileOperation.Copy(Profile.Operations[index2], ref CopiedOperation);
          double num = (buProfileCalc.varProfileRunSettings.PatternCopyDistance + buProfileCalc.varProfileRunSettings.PatternCopyCutSpace) * (double) index1;
          CopiedOperation.OperationData.Position.X += num;
          buProfileCalc.varProfileRunSettings.OPData.selectedPlane = (Plane) CopiedOperation.OperationData.selectedPlane.Clone();
          ProfileOnlineOpOptions profileOnlineOpOptions = new ProfileOnlineOpOptions();
          if (index1 < buProfileCalc.varProfileRunSettings.PatternCopyCount)
            this.OnlineOperation((object) null, (object) new ShapeUpdateArg()
            {
              Parameters = new ShapeRuntimeData(buProfileCalc.varProfileRunSettings.ShapeDataParameters),
              Finished = true,
              Tool = new ToolBase5(CopiedOperation.Tool)
            }, (object) CopiedOperation.OperationData);
        }
        x1 = index1 != 1 ? x1 + buProfileCalc.varProfileRunSettings.PatternCopyDistance + buProfileCalc.varProfileRunSettings.PatternCopyCutSpace : buProfileCalc.varProfileRunSettings.PatternCopyDistance + buProfileCalc.varProfileRunSettings.PatternCopyCutSpace / 2.0;
        Point3D CenterPoint = new Point3D(x1, -Profile.Width / 2.0, Profile.Height / 2.0);
        Mesh entMesh = (Mesh) null;
        if (buProfileCalc.varProfileRunSettings.PatternCopyCutSpace > 0.0)
        {
          buEyeShotFunctions.CreateBoxWithCenter(CenterPoint, buProfileCalc.varProfileRunSettings.PatternCopyCutSpace, Profile.Width, Profile.Height, true, ref entMesh);
          if (entMesh != null)
          {
            if (Profile.auxEntities == null)
              Profile.auxEntities = new List<Entity>();
            entMesh.EntityData = (object) new CustomData()
            {
              typeDefination = entityTypeDefination.ProfileSeperator,
              ID = Profile.Operations[0].ID,
              EntityName = Profile.Operations[0].ProfileName,
              ActionName = Profile.Operations[0].Name
            };
            Profile.auxEntities.Add((Entity) entMesh);
          }
        }
      }
      this.RearrangeOperationID();
      clsInit.appCommand.Reset();
      this.DrawPreview(Profile, new List<Entity>());
      this.DrawActiveProfile();
      buProfileCalc.varProfileRunSettings.OPData.Position.X = x2;
    }
    this.UndoDontProfile = false;
  }

  public void doCopy()
  {
    buEyeBaseVer5.Apps.ProfileItem profileItem = clsInit.cProfile.SelectActiveProfile(this.activeProfile.FirstItem, this.activeProfile.SecondItem, ref buProfileCalc.varProfileRunSettings.activeProfileIndex);
    if (profileItem == null || profileItem == null)
      return;
    if (buProfileCalc.varProfileRunSettings.SelectMode && clsInit.cProfile.GetSelectedOperationCount(profileItem) == 0)
    {
      buString5.MessageBoxWarning(buLangTranslate.preSentencesProfile.SelectionModeActiveNoOperationSelected);
    }
    else
    {
      F_ProfileCopy fProfileCopy = new F_ProfileCopy();
      fProfileCopy.Profile = new buEyeBaseVer5.Apps.ProfileItem(profileItem);
      fProfileCopy.UseOriginalPlane = buProfileCalc.varProfileRunSettings.CopyMoveUseOriginalePlane;
      fProfileCopy.Count = buProfileCalc.varProfileRunSettings.CopyCount;
      fProfileCopy.DistanceHor = buProfileCalc.varProfileRunSettings.CopyDistanceHor;
      fProfileCopy.DistanceVer = buProfileCalc.varProfileRunSettings.CopyDistanceVer;
      fProfileCopy.UseDistance = buProfileCalc.varProfileRunSettings.CopyUseDistance;
      fProfileCopy.selectedPlanes.Clear();
      for (int index = 0; index <= clsProfile.selectedPlanes.Count - 1; ++index)
        fProfileCopy.selectedPlanes.Add(new SelectedPlaneInfo(clsProfile.selectedPlanes[index]));
      fProfileCopy.OperationData = new buEyeBaseVer5.Apps.ProfileOperationData(profileItem.Operations[buProfileCalc.varProfileRunSettings.activeOPIndex].OperationData);
      fProfileCopy.Init();
      int num1 = (int) fProfileCopy.ShowDialog();
      if (fProfileCopy.Properties.Result != DialogResult.OK)
        return;
      this.SaveByTick = true;
      buProfileCalc.varProfileRunSettings.CopyCount = fProfileCopy.Count;
      buProfileCalc.varProfileRunSettings.CopyDistanceHor = fProfileCopy.DistanceHor;
      buProfileCalc.varProfileRunSettings.CopyDistanceVer = fProfileCopy.DistanceVer;
      buProfileCalc.varProfileRunSettings.CopyUseDistance = fProfileCopy.UseDistance;
      buProfileCalc.varProfileRunSettings.CopyMoveUseOriginalePlane = fProfileCopy.UseOriginalPlane;
      this.bUndoBuffer = true;
      this.ToolChangeForced = true;
      int activeOpIndex = buProfileCalc.varProfileRunSettings.activeOPIndex;
      double num2 = fProfileCopy.OperationData.basePosition.X - profileItem.Operations[buProfileCalc.varProfileRunSettings.activeOPIndex].OperationData.basePosition.X;
      double num3 = fProfileCopy.OperationData.basePosition.Y - profileItem.Operations[buProfileCalc.varProfileRunSettings.activeOPIndex].OperationData.basePosition.Y;
      if (buProfileCalc.varProfileRunSettings.CopyUseDistance)
      {
        num2 = buProfileCalc.varProfileRunSettings.CopyDistanceHor;
        num3 = buProfileCalc.varProfileRunSettings.CopyDistanceVer;
      }
      List<buEyeBaseVer5.Apps.ProfileOperation> profileOperationList = new List<buEyeBaseVer5.Apps.ProfileOperation>();
      if (!buProfileCalc.varProfileRunSettings.SelectMode)
      {
        profileOperationList.Add(profileItem.Operations[activeOpIndex]);
      }
      else
      {
        for (int index = 0; index <= profileItem.Operations.Count - 1; ++index)
        {
          if (profileItem.Operations[index].Selected)
            profileOperationList.Add(profileItem.Operations[index]);
        }
      }
      double num4 = 1.0;
      ProfileTempVars.SelectedOperations.Clear();
      for (int index1 = 1; index1 <= buProfileCalc.varProfileRunSettings.CopyCount; ++index1)
      {
        for (int index2 = 0; index2 <= profileOperationList.Count - 1; ++index2)
        {
          buEyeBaseVer5.Apps.ProfileOperationData OPData = new buEyeBaseVer5.Apps.ProfileOperationData(profileOperationList[index2].OperationData);
          buEyeBaseVer5.Apps.ProfileOperation CopiedOperation = new buEyeBaseVer5.Apps.ProfileOperation();
          buEyeBaseVer5.Apps.ProfileOperation.Copy(profileOperationList[index2], ref CopiedOperation);
          if (CopiedOperation.OperationData.ManuelZEnable)
          {
            clsInit.cProfile.ManuelZValueFromPlaneChange(profileItem, CopiedOperation, OPData.selectedPlaneName, fProfileCopy.OperationData.ManuelZVal, ref CopiedOperation.OperationData.ManuelZVal);
            OPData.ManuelZVal = CopiedOperation.OperationData.ManuelZVal;
          }
          CopiedOperation.OperationData.ManuelZVal = 0.0;
          fProfileCopy.OperationData.ManuelZVal = 0.0;
          OPData.basePosition.X += num2 * num4;
          OPData.basePosition.Y += num3 * num4;
          if (!buProfileCalc.varProfileRunSettings.CopyMoveUseOriginalePlane)
            OPData.selectedPlaneName = fProfileCopy.OperationData.selectedPlaneName;
          OPData.DepthForced = OPData.selectedPlaneName == CopiedOperation.OperationData.selectedPlaneName;
          if (!buCompare5.EQ(num2, 0.0) | !buCompare5.EQ(num3, 0.0) | CopiedOperation.OperationData.selectedPlaneName != OPData.selectedPlaneName)
            this.doCopyApply(CopiedOperation, OPData);
        }
        ++num4;
      }
    }
  }

