  public void doMirror(ProfileMirror MirrorData)
  {
    buEyeBaseVer5.Apps.ProfileItem curItem = clsInit.cProfile.SelectActiveProfile(this.activeProfile.FirstItem, this.activeProfile.SecondItem, ref buProfileCalc.varProfileRunSettings.activeProfileIndex);
    if (curItem == null)
      return;
    if (buProfileCalc.varProfileRunSettings.SelectMode && clsInit.cProfile.GetSelectedOperationCount(curItem) == 0)
    {
      buString5.MessageBoxWarning(buLangTranslate.preSentencesProfile.SelectionModeActiveNoOperationSelected);
    }
    else
    {
      ProfileTempVars.SelectedOperations.Clear();
      if (curItem.Operations[buProfileCalc.varProfileRunSettings.activeOPIndex] is buEyeBaseVer5.Apps.ProfileOperationNotch)
      {
        buEyeBaseVer5.Apps.ProfileOperation CopiedOperation = new buEyeBaseVer5.Apps.ProfileOperation();
        buEyeBaseVer5.Apps.ProfileOperation.Copy(curItem.Operations[buProfileCalc.varProfileRunSettings.activeOPIndex], ref CopiedOperation);
        ShapeUpdateArg Data2 = new ShapeUpdateArg()
        {
          Parameters = new ShapeRuntimeData(buProfileCalc.varProfileRunSettings.ShapeDataParameters),
          Finished = true,
          Tool = new ToolBase5(curItem.Operations[buProfileCalc.varProfileRunSettings.activeOPIndex].ToolNotch)
        };
        Data2.Parameters.NotchSideLocation = ProfileNotchLocationType.Right;
        CopiedOperation.OperationData.NotchData.NotchLocation = ProfileNotchLocationType.Right;
        if (CopiedOperation.OperationData.NotchData.NotchLocation == ProfileNotchLocationType.Left)
          CopiedOperation.OperationData.NotchData.NotchLocation = ProfileNotchLocationType.Right;
        else if (CopiedOperation.OperationData.NotchData.NotchLocation == ProfileNotchLocationType.Right)
          CopiedOperation.OperationData.NotchData.NotchLocation = ProfileNotchLocationType.Left;
        else if (CopiedOperation.OperationData.NotchData.NotchLocation == ProfileNotchLocationType.Front)
          CopiedOperation.OperationData.NotchData.NotchLocation = ProfileNotchLocationType.Back;
        else if (CopiedOperation.OperationData.NotchData.NotchLocation == ProfileNotchLocationType.Back)
          CopiedOperation.OperationData.NotchData.NotchLocation = ProfileNotchLocationType.Front;
        this.OnlineOperation((object) null, (object) Data2, (object) CopiedOperation.OperationData);
        ProfileTempVars.MultiOperationStarted = false;
      }
      else if (!buProfileCalc.varProfileRunSettings.SelectMode)
      {
        buEyeBaseVer5.Apps.ProfileOperation CopiedOperation = new buEyeBaseVer5.Apps.ProfileOperation();
        buEyeBaseVer5.Apps.ProfileOperation.Copy(curItem.Operations[buProfileCalc.varProfileRunSettings.activeOPIndex], ref CopiedOperation);
        this.doMirrorApply(MirrorData, CopiedOperation, ref curItem);
      }
      else
      {
        for (int index = 0; index <= curItem.Operations.Count - 1; ++index)
        {
          if (curItem.Operations[index].Selected)
          {
            buEyeBaseVer5.Apps.ProfileOperation CopiedOperation = new buEyeBaseVer5.Apps.ProfileOperation();
            buEyeBaseVer5.Apps.ProfileOperation.Copy(curItem.Operations[index], ref CopiedOperation);
            this.doMirrorApply(MirrorData, CopiedOperation, ref curItem);
          }
        }
      }
    }
  }

  public void doMirrorApply(
    ProfileMirror MirrorData,
    buEyeBaseVer5.Apps.ProfileOperation mirroredOP,
    ref buEyeBaseVer5.Apps.ProfileItem curItem)
  {
    try
    {
      if (MirrorData.MirrorAxis == MirrorAxisXYType.X)
        clsInit.cVector5.MirrorCornerLocation(mirroredOP.OperationData.Corner, VectorXYType.YVector, ref mirroredOP.OperationData.Corner);
      else if (!buProfileCalc.varProfileSettings.OperationFrontBackMirrorYDirToAnotherPlane)
        clsInit.cVector5.MirrorCornerLocation(mirroredOP.OperationData.Corner, VectorXYType.XVector, ref mirroredOP.OperationData.Corner);
      else if (mirroredOP.OperationData.selectedPlaneName == planeNames.Top | mirroredOP.OperationData.selectedPlaneName == planeNames.Bottom | mirroredOP.OperationData.selectedPlaneName == planeNames.Free)
        clsInit.cVector5.MirrorCornerLocation(mirroredOP.OperationData.Corner, VectorXYType.XVector, ref mirroredOP.OperationData.Corner);
      Point3D point3D1 = new Point3D();
      Plane planeMirror = Plane.XY;
      double num = MirrorData.MirrorDistance;
      Point3D point3D2 = Point3D.MidPoint(mirroredOP.MinPoint, mirroredOP.MaxPoint);
      Point3D BasePoint = new Point3D(mirroredOP.MinPoint.X, mirroredOP.MinPoint.Y, mirroredOP.MinPoint.Z);
      Point3D MirrorPoint = new Point3D(mirroredOP.MinPoint.X, mirroredOP.MinPoint.Y, mirroredOP.MinPoint.Z);
      if (MirrorData.MirrorLocation == MinCenterMaxType.Max)
      {
        BasePoint = new Point3D(mirroredOP.MaxPoint.X, mirroredOP.MaxPoint.Y, mirroredOP.MaxPoint.Z);
        MirrorPoint = new Point3D(mirroredOP.MaxPoint.X, mirroredOP.MaxPoint.Y, mirroredOP.MaxPoint.Z);
      }
      if (MirrorData.MirrorLocation == MinCenterMaxType.Center)
      {
        BasePoint = new Point3D(point3D2.X, point3D2.Y, point3D2.Z);
        MirrorPoint = new Point3D(point3D2.X, point3D2.Y, point3D2.Z);
      }
      if (mirroredOP.OperationData.selectedPlaneName == planeNames.Front)
        planeMirror = Plane.XZ;
      if (mirroredOP.OperationData.selectedPlaneName == planeNames.Back)
        planeMirror = Plane.XZ;
      if (MirrorData.Mode == MirrorModeType.FromCenter)
      {
        num = 0.0;
        if (mirroredOP.OperationData.selectedPlaneName == planeNames.Top)
        {
          BasePoint = new Point3D(curItem.Length / 2.0, -curItem.Width / 2.0, curItem.Height);
          MirrorPoint = new Point3D(curItem.Length / 2.0, -curItem.Width / 2.0, curItem.Height);
        }
        if (mirroredOP.OperationData.selectedPlaneName == planeNames.Front)
        {
          BasePoint = new Point3D(curItem.Length / 2.0, -curItem.Width, curItem.Height / 2.0);
          MirrorPoint = new Point3D(curItem.Length / 2.0, -curItem.Width, curItem.Height / 2.0);
        }
        if (mirroredOP.OperationData.selectedPlaneName == planeNames.Back)
        {
          BasePoint = new Point3D(curItem.Length / 2.0, 0.0, curItem.Height / 2.0);
          MirrorPoint = new Point3D(curItem.Length / 2.0, 0.0, curItem.Height / 2.0);
        }
      }
      if (MirrorData.MirrorAxis == MirrorAxisXYType.X)
      {
        if (mirroredOP.OperationData.selectedPlaneName == planeNames.Top)
        {
          MirrorPoint.Y += 10.0;
          MirrorPoint.X += num;
          BasePoint.X += num;
        }
        if (mirroredOP.OperationData.selectedPlaneName == planeNames.Front | mirroredOP.OperationData.selectedPlaneName == planeNames.Back)
        {
          MirrorPoint.Z += 10.0;
          MirrorPoint.X += num;
          BasePoint.X += num;
        }
      }
      if (MirrorData.MirrorAxis == MirrorAxisXYType.Y)
      {
        if (mirroredOP.OperationData.selectedPlaneName == planeNames.Top)
        {
          MirrorPoint.X += 10.0;
          MirrorPoint.Y += num;
          BasePoint.Y += num;
        }
        if (mirroredOP.OperationData.selectedPlaneName == planeNames.Front | mirroredOP.OperationData.selectedPlaneName == planeNames.Back)
        {
          MirrorPoint.X += 10.0;
          MirrorPoint.Z += num;
          BasePoint.Z += num;
        }
      }
      mirroredOP.OperationData.DepthForced = true;
      if (MirrorData.Mode == MirrorModeType.FromCenter & (mirroredOP.OperationData.selectedPlaneName == planeNames.Front | mirroredOP.OperationData.selectedPlaneName == planeNames.Back) & MirrorData.MirrorAxis == MirrorAxisXYType.Y & buProfileCalc.varProfileSettings.OperationFrontBackMirrorYDirToAnotherPlane)
      {
        mirroredOP.OperationData.DepthForced = false;
        if (mirroredOP.OperationData.selectedPlaneName == planeNames.Front)
          mirroredOP.OperationData.selectedPlaneName = planeNames.Back;
        else if (mirroredOP.OperationData.selectedPlaneName == planeNames.Back)
          mirroredOP.OperationData.selectedPlaneName = planeNames.Front;
      }
      else
      {
        Point3D mirrorPoint = new Point3D();
        clsInit.cVector5.Mirror(BasePoint, MirrorPoint, planeMirror, mirroredOP.OperationData.Position, ref mirrorPoint);
        mirroredOP.OperationData.Position = buVector5.ToPoint3D(mirrorPoint);
        if (mirroredOP.OperationData.OperationType == ProfileOperationTypes.Barrel && MirrorData.MirrorAxis == MirrorAxisXYType.X)
        {
          mirroredOP.OperationData.BarelData.BarrelAngle += 180.0;
          if (mirroredOP.OperationData.BarelData.BarrelAngle > 360.0)
            mirroredOP.OperationData.BarelData.BarrelAngle -= 360.0;
        }
        if (mirroredOP.OperationData.OperationType == ProfileOperationTypes.FreeDraw)
        {
          this.shapeCreateParameters_0.entitiesCurveList.Clear();
          for (int index = 0; index <= mirroredOP.EntityMultiXYPlane.Count - 1; ++index)
          {
            EntitiesList entitiesList = new EntitiesList();
            buEntity buEntity = (buEntity) null;
            buEntity.Copy(mirroredOP.EntityMultiXYPlane[index], ref buEntity);
            clsInit.cVector5.Mirror(BasePoint, MirrorPoint, planeMirror, ref buEntity);
            entitiesList.Entities.Add(buEntity);
            this.shapeCreateParameters_0.entitiesCurveList.Add(entitiesList);
          }
          buProfileCalc.varProfileRunSettings.FreeDrawOrjinalWidth = mirroredOP.OperationData.FreeDrawData.FreeDrawWidth;
          buProfileCalc.varProfileRunSettings.FreeDrawOrjinalHeight = mirroredOP.OperationData.FreeDrawData.FreeDrawHeight;
        }
      }
      buShape buShape = new buShape();
      buShape.BasePoint = new Point3D(mirroredOP.OperationData.basePosition.X, Math.Abs(mirroredOP.OperationData.basePosition.Y), mirroredOP.OperationData.basePosition.Z);
      if (buCompare5.EQ(buShape.BasePoint.X, 0.0) & buCompare5.EQ(buShape.BasePoint.Y, 0.0) & buCompare5.EQ(buShape.BasePoint.Y, 0.0))
      {
        buShape.BasePoint.X = mirroredOP.OperationData.Position.X;
        buShape.BasePoint.Y = mirroredOP.OperationData.Position.Y;
        buShape.BasePoint.Z = mirroredOP.OperationData.Position.Z;
        buShape.Corner = CornerLocation.LeftTop;
      }
      clsInit.cVector5.CoordinateFromPlaneAndCorner(new SizeObject(curItem.Length, curItem.Width, curItem.Height), mirroredOP.OperationData.Corner, buConversion5.PlaneNamesToPlaneBoxNames(mirroredOP.OperationData.selectedPlaneName), ref buShape, ref mirroredOP.OperationData.Position, this.shapeCreateParameters_0.SingX, this.shapeCreateParameters_0.SingY);
      this.bUndoBuffer = true;
      ShapeUpdateArg Data2 = new ShapeUpdateArg()
      {
        Parameters = new ShapeRuntimeData(buProfileCalc.varProfileRunSettings.ShapeDataParameters)
      };
      Data2.Parameters.selectedPlane = buConversion5.PlaneNamesToPlaneBoxNames(mirroredOP.OperationData.selectedPlaneName);
      Data2.Finished = true;
      Data2.ToolFound = true;
      Data2.Tool = new ToolBase5(mirroredOP.Tool);
      Data2.Parameters.Priority = mirroredOP.Priority;
      ProfileTempVars.OperationDepths.Clear();
      DepthPositions.Copy(mirroredOP.OperationData.DepthValues, ref ProfileTempVars.OperationDepths);
      this.OnlineOperation((object) null, (object) Data2, (object) mirroredOP.OperationData);
    }
    catch (Exception ex)
    {
    }
  }

  public void doArray()
