        this.OnlineOperation((object) null, (object) Data2, (object) OP.OperationData);
      }
      ProfileTempVars.OperationEditing = false;
      this.doReset();
    }
  }

  public void ThreadCalculationLoop()
  {
    while (true)
    {
      if (this.bUndoBuffer)
        goto label_2;
label_1:
      Thread.Sleep(1);
      continue;
label_2:
      this.UndoBuffer();
      this.bUndoBuffer = false;
      goto label_1;
    }
  }

