  public void doCalculateCamPointsKabanMode1(
    ref camTp C,
    ref buEyeBaseVer5.Apps.ProfileItem Item,
    ref GProfileOperation OP,
    ref TpPnt9D lastCamP9,
    int i,
    int y,
    bool ToolMilling,
    double ZParkPosAfterKinematic,
    bool CreateGCode)
  {
    if (ToolMilling)
    {
      for (int index1 = 0; index1 <= C.CamPoints.Count - 1; ++index1)
      {
        for (int index2 = 0; index2 <= C.CamPoints[index1].Points.Count - 1; ++index2)
        {
          Pnt9D pnt9D = new Pnt9D(C.CamPoints[index1].Points[index2].P9);
          OrientationAngle Orientation = new OrientationAngle(C.CamPoints[index1].Points[index2].P9.A, 0.0, 0.0);
          if (Item.CalculationData[y].calcOperations[i].OperationData.selectedPlaneName == planeNames.Front | Item.CalculationData[y].calcOperations[i].OperationData.selectedPlaneName == planeNames.Back && buCompare5.EQ(Orientation.A, 0.0) & C.CamPoints[index1].Points[index2].EnableAxes.Y)
          {
            if (Item.CalculationData[y].calcOperations[i].OperationData.selectedPlaneName == planeNames.Back)
              Orientation.A = -90.0;
            if (Item.CalculationData[y].calcOperations[i].OperationData.selectedPlaneName == planeNames.Front)
              Orientation.A = 90.0;
          }
          Point3D MovePoint = new Point3D(C.CamPoints[index1].Points[index2].P9.X, C.CamPoints[index1].Points[index2].P9.Y, C.CamPoints[index1].Points[index2].P9.Z);
          Pnt6D CalcPoint = new Pnt6D();
          clsInit.cKinematic5.ForwardKinematix4Ax(C.Tool.Geometry.TotalLength, ccVars.KinematicOrjinal, VectorType.XVector, Orientation, MovePoint, ref CalcPoint);
          Pnt9D Pnt = new Pnt9D(CalcPoint.X, CalcPoint.Y, CalcPoint.Z, CalcPoint.A, CalcPoint.B, CalcPoint.C);
          if (Item.CalculationData[y].calcOperations[i].OperationData.selectedPlaneName == planeNames.Top)
            C.CamPoints[index1].Points[index2].PlungeAxis = "Z";
          if (Item.CalculationData[y].calcOperations[i].OperationData.selectedPlaneName == planeNames.Front | Item.CalculationData[y].calcOperations[i].OperationData.selectedPlaneName == planeNames.Back)
            C.CamPoints[index1].Points[index2].PlungeAxis = "Y";
          if (Item.CalculationData[y].calcOperations[i].OperationData.selectedPlaneName == planeNames.Free)
            C.CamPoints[index1].Points[index2].PlungeAxis = "";
          if (OP.OperationData.OperationType == ProfileOperationTypes.Tapping && C.CamPoints[index1].Points[index2].PlungeAxisMovement)
          {
            C.CamPoints[index1].Points[index2].Type = 0;
            double num = OP.OperationData.HoleData.TappingDepth;
            if (OP.OperationData.selectedPlaneName == planeNames.Top && index2 > 0)
              num = C.CamPoints[index1].Points[index2 - 1].P9.Z - Pnt.Z;
            if (OP.OperationData.selectedPlaneName == planeNames.Front | OP.OperationData.selectedPlaneName == planeNames.Back && index2 > 0)
              num = Math.Abs(C.CamPoints[index1].Points[index2 - 1].P9.Y - Pnt.Y);
            C.CamPoints[index1].Points[index2].OverWriteString = $"M80 X{OP.OperationData.HoleData.TappingPitch.ToString("f2")} Y{(-num).ToString("f2")} Z{OP.Tool.CamData.SpindleSpeed.ToString("")}";
          }
          C.CamPoints[index1].Points[index2].P9 = new Pnt9D(Pnt);
        }
      }
      lastCamP9 = C.CamPoints[C.CamPoints.Count - 1].Points[C.CamPoints[C.CamPoints.Count - 1].Points.Count - 1];
    }
    else
    {
      for (int index3 = 0; index3 <= C.CamPoints.Count - 1; ++index3)
      {
        for (int index4 = 0; index4 <= C.CamPoints[index3].Points.Count - 1; ++index4)
        {
          if (Item.CalculationData[y].calcOperations[i].OperationData.NotchData.NotchOPType == ProfileNotchOperationType.Side | Item.CalculationData[y].calcOperations[i].OperationData.NotchData.NotchOPType == ProfileNotchOperationType.Length)
          {
            Pnt9D Pnt = new Pnt9D(C.CamPoints[index3].Points[index4].P9);
            double num = ccVars.KinematicOrjinal.RotateCenterOffsetOfA.Z + C.Tool.Geometry.TotalLength;
            Pnt.Z += num;
            C.CamPoints[index3].Points[index4].PlungeAxis = "X";
            C.CamPoints[index3].Points[index4].P9 = new Pnt9D(Pnt);
          }
          if (Item.CalculationData[y].calcOperations[i].OperationData.NotchData.NotchOPType == ProfileNotchOperationType.Vertical)
          {
            Pnt9D Pnt = new Pnt9D(C.CamPoints[index3].Points[index4].P9);
            if (Item.CalculationData[y].calcOperations[i].OperationData.selectedPlaneName == planeNames.Front | Item.CalculationData[y].calcOperations[i].OperationData.selectedPlaneName == planeNames.Back)
            {
              double num = (ccVars.KinematicOrjinal.RotateCenterOffsetOfA.Z + C.Tool.Geometry.TotalLength) * Math.Sin(buConversion5.DegreeToRadian(Pnt.A));
              Pnt.Y -= num;
              C.CamPoints[index3].Points[index4].PlungeAxis = "X";
            }
            if (index4 == C.CamPoints[index3].Points.Count - 1)
              Pnt.Z = ZParkPosAfterKinematic;
            C.CamPoints[index3].Points[index4].P9 = new Pnt9D(Pnt);
          }
          if (Item.CalculationData[y].calcOperations[i].OperationData.NotchData.NotchOPType == ProfileNotchOperationType.Horizontal)
          {
            Pnt9D Pnt = new Pnt9D(C.CamPoints[index3].Points[index4].P9);
            double num = (ccVars.KinematicOrjinal.RotateCenterOffsetOfA.Z + C.Tool.Geometry.TotalLength) * Math.Sin(buConversion5.DegreeToRadian(Pnt.A));
            Pnt.Y -= num;
            C.CamPoints[index3].Points[index4].PlungeAxis = "Z";
            C.CamPoints[index3].Points[index4].P9 = new Pnt9D(Pnt);
          }
        }
      }
    }
    if (Item.CalculationData[y].XReferanceLocation == LeftRightType.Right & CreateGCode)
    {
      for (int index5 = 0; index5 <= C.CamPoints.Count - 1; ++index5)
      {
        for (int index6 = 0; index6 <= C.CamPoints[index5].Points.Count - 1; ++index6)
        {
          Pnt9D p9 = C.CamPoints[index5].Points[index6].P9;
          if (buProfileCalc.varProfileSettings.RightProfileMakeAsMirror)
            p9.X -= Item.CalculationData[y].Length;
          else
            p9.X = buProfileCalc.varProfileSettings.MachineLength - Item.CalculationData[y].Length + p9.X;
          if (buProfileCalc.varProfileSettings.ChangeG2G3DirForRightRefProfile)
          {
            if (C.CamPoints[index5].Points[index6].Type == 2)
              C.CamPoints[index5].Points[index6].Type = 3;
            else if (C.CamPoints[index5].Points[index6].Type == 3)
              C.CamPoints[index5].Points[index6].Type = 2;
          }
        }
      }
    }
    if (Item.CalculationData[y].XReferanceLocation == LeftRightType.Left & CreateGCode)
    {
      for (int index7 = 0; index7 <= C.CamPoints.Count - 1; ++index7)
      {
        for (int index8 = 0; index8 <= C.CamPoints[index7].Points.Count - 1; ++index8)
        {
          Pnt9D p9 = C.CamPoints[index7].Points[index8].P9;
          if (buProfileCalc.varProfileSettings.ChangeG2G3DirForLeftRefProfile)
          {
            if (C.CamPoints[index7].Points[index8].Type == 2)
              C.CamPoints[index7].Points[index8].Type = 3;
            else if (C.CamPoints[index7].Points[index8].Type == 3)
              C.CamPoints[index7].Points[index8].Type = 2;
          }
        }
      }
    }
    Item.CalculationData[y].Cams.Add(C);
  }

  public void doSaveGcodeKabanMode1(bool ShowCode)
  {
    try
    {
      if (clsVar.appModes_0.DemoMode)
      {
        int num1 = (int) MessageBox.Show(buLangTranslate.preSentences.NotAvailableDemoMode);
      }
      else if (ccVars.Pages.Count <= 0)
        buString5.MessageBoxWarning(AppLanguage.Messages[9]);
      else if (this.activeProfile.FirstItem == null & this.activeProfile.SecondItem == null)
        buString5.MessageBoxWarning(buProfile.LangProfileMessage[12]);
      else if (!this.activeProfile.isSimulationDone & AppSecurity.PasswordLevel == 0)
      {
        buString5.MessageBoxWarning(buProfile.LangProfileMessage[13]);
      }
      else
      {
        bool flag = false;
        bool SecondAvailable = false;
        if ((this.activeProfile.FirstItem == null || !this.activeProfile.FirstItem.Enable ? 0 : (this.activeProfile.FirstItem.Operations.Count > 0 ? 1 : 0)) != 0)
          flag = true;
        if ((this.activeProfile.SecondItem == null || !this.activeProfile.SecondItem.Enable ? 0 : (this.activeProfile.SecondItem.Operations.Count > 0 ? 1 : 0)) != 0)
          SecondAvailable = true;
        if (flag && this.activeProfile.FirstItem.isError)
          buString5.MessageBoxWarning($"{buLangTranslate.preDef.First} {buLangTranslate.preDef.Profile} {buProfile.LangProfileMessage[14]}");
        else if (SecondAvailable && this.activeProfile.SecondItem.isError)
        {
          buString5.MessageBoxWarning($"{buLangTranslate.preDef.Second} {buLangTranslate.preDef.Profile} {buProfile.LangProfileMessage[14]}");
        }
        else
        {
          SaveFileDialog saveFileDialog = new SaveFileDialog();
          saveFileDialog.InitialDirectory = clsVar.varInterface.pathGCode;
          saveFileDialog.Filter = $"{ccVars.PostActive.FileExplanation} ({ccVars.PostActive.FileExtension})|{ccVars.PostActive.FileExtension}";
          saveFileDialog.FilterIndex = 1;
          DialogResult dialogResult = DialogResult.None;
          if (!ShowCode)
            dialogResult = saveFileDialog.ShowDialog();
          if (!(dialogResult == DialogResult.OK | ShowCode))
            return;
          string FileName = $"{buFile5.GetPath(saveFileDialog.FileName)}\\{buFile5.getFileNameWithoutExtension(saveFileDialog.FileName)}.stl";
          if (buProfileCalc.varProfileSettings.SaveStlFileWhileCreatingCode)
            buFile5.SaveStl((Design) ccVars.Pages[ccVars.PageIndex].Form.viewportcad, FileName);
          if (buProfileCalc.varProfileSettings.SaveImageFileWhileCreatingCode)
          {
            string filePath = $"{buFile5.GetPath(saveFileDialog.FileName)}\\{buFile5.getFileNameWithoutExtension(saveFileDialog.FileName)}.png";
            ccVars.Pages[ccVars.PageIndex].Form.viewportcad.WriteToFileRaster((float) buProfileCalc.varProfileSettings.ImageScaleFactor, filePath, ImageFormat.Png);
          }
          ArrayList GCodes1 = new ArrayList();
          ArrayList GCodes2 = new ArrayList();
          int num2 = 0;
          buProfileCalc.varTemps.LastGCodeLine = 0;
          ccVars.PostActive.NumberDef.Start = 10.0;
          ProfileTempVars.LastClampers.Clear();
          if (flag)
          {
            this.doCreateCode(this.activeProfile.FirstItem, ccVars.PostActive.Mode, ref GCodes1, 0, SecondAvailable, true, ShowCode);
            int num3 = num2 + 1;
          }
          if (SecondAvailable)
            this.doCreateCode(this.activeProfile.SecondItem, ccVars.PostActive.Mode, ref GCodes2, 1, false, true, ShowCode);
          if (flag & SecondAvailable)
          {
            ArrayList CalcList1 = new ArrayList();
            ArrayList CalcList2 = new ArrayList();
            ArrayList CalcList3 = new ArrayList();
            ArrayList CalcList4 = new ArrayList();
            buString5.ListToSpecificList("<GCodes>", "</GCodes>", false, GCodes1, ref CalcList1);
            buString5.ListToSpecificList("<GCodes>", "</GCodes>", false, GCodes2, ref CalcList2);
            buString5.ListToSpecificList("<ProfileCode>", "</ProfileCode>", false, GCodes1, ref CalcList3);
            buString5.ListToSpecificList("<ProfileCode>", "</ProfileCode>", false, GCodes2, ref CalcList4);
            GCodes1.AddRange((ICollection) GCodes2);
          }
          else
            GCodes1.AddRange((ICollection) GCodes2);
          if (this.activeProfile.GCodes == null)
            this.activeProfile.GCodes = new ArrayList();
          this.activeProfile.GCodes.Clear();
          this.activeProfile.GCodes = buString5.Copy(GCodes1);
          clsVar.varInterface.pathGCode = buFile5.GetPath(saveFileDialog.FileName);
          if (!ShowCode)
          {
            buFile5.SaveToFile(GCodes1, saveFileDialog.FileName);
          }
          else
          {
            F_Notepad fNotepad = new F_Notepad();
            fNotepad.Init(GCodes1);
            fNotepad.Show();
          }
          GCodes1.Clear();
          clsFiles.SaveParameter();
        }
      }
    }
    catch (Exception ex)
    {
      buLog.addLog("", "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, true, "");
    }
  }

  public void doAddInfoCodeKabanMode1(
    ref buEyeBaseVer5.Apps.ProfileItem Item,
    ref PostProcessor tempPost,
    int ProfileIndex,
    double ZParkPosAfterKinematic,
    bool AddToolInfo)
  {
    if (ProfileIndex == 0)
    {
      if (buProfileCalc.varProfileSettings.ShowSupportBlockInfoAtGCode)
        clsInit.cProfile.InsertSupportBlockInfoToGCode(Item, 1, ref tempPost, "(", ")");
      if (buProfileCalc.varProfileSettings.ShowProfileInfoAtGCode)
        clsInit.cProfile.InsertProfileInfoToGCode(Item, 1, ref tempPost, "(", ")");
      string str = "Left";
      if (this.activeProfile.FirstItem != null & this.activeProfile.SecondItem != null)
        str = "Left/Right";
      else if (this.activeProfile.FirstItem == null & this.activeProfile.SecondItem != null)
        str = "Right";
      tempPost.StartLines.Insert(1, (object) $"(Stoper Side = {str} )");
      tempPost.StartLines.Add((object) ("G0 Z" + ZParkPosAfterKinematic.ToString("f2")));
    }
    if (ProfileIndex == 1)
    {
      if (this.activeProfile.FirstItem != null)
      {
        tempPost.StartLines.Clear();
      }
      else
      {
        string str = "Right";
        tempPost.StartLines.Insert(1, (object) $"(Stoper Side = {str} )");
        tempPost.StartLines.Add((object) ("G0 Z" + ZParkPosAfterKinematic.ToString("f2")));
      }
      if (buProfileCalc.varProfileSettings.ShowSupportBlockInfoAtGCode)
        clsInit.cProfile.InsertSupportBlockInfoToGCode(Item, 1, ref tempPost, "(", ")");
      if (buProfileCalc.varProfileSettings.ShowProfileInfoAtGCode)
        clsInit.cProfile.InsertProfileInfoToGCode(Item, 1, ref tempPost, "(", ")");
      if (buProfileCalc.varTemps.LastGCodeLine > 0)
        tempPost.NumberDef.Start = (double) buProfileCalc.varTemps.LastGCodeLine + tempPost.NumberDef.Step;
    }
    if (!AddToolInfo)
      return;
    tempPost.StartLines.Insert(1, (object) ("#820=" + Item.Width.ToString("f2")));
    tempPost.StartLines.Insert(2, (object) ("#821=" + Item.Height.ToString("f2")));
    int index1 = 3;
    List<ToolBase5> toolBase5List = new List<ToolBase5>();
    for (int index2 = 0; index2 <= Item.Operations.Count - 1; ++index2)
    {
      bool flag1 = false;
      if (Item.Operations[index2].OperationData.OperationType == ProfileOperationTypes.Notch)
      {
