                if (ProfileTempVars.LastClampers.Count == Item.CalculationData[index1].calcOperations[index2].Clampers.Count)
                {
                  for (int index8 = 0; index8 <= Item.CalculationData[index1].calcOperations[index2].Clampers.Count - 1; ++index8)
