                      C.AfterCodes.Add((object) $"G0 Z{ZParkPosAfterKinematic.ToString("f2")} ( go Z-save )");
                      C.AfterCodes.Add((object) $"G0 X{buProfileCalc.varProfileSettings.ParkPositionX.ToString("f2")} Y{buProfileCalc.varProfileSettings.ParkPositionY.ToString("f2")} G0 A0  ( X Y A Go Park Position )");
                      C.AfterCodes.Add((object) "M40 M41 M42 M43");
