                      continue;
                    case 1:
                      C.AfterCodes.Add((object) "M05 ( Stop Spindle )");
                      C.AfterCodes.Add((object) $"G0 Z{ZParkPosAfterKinematic.ToString("f2")} ( go Z-save )");
                      C.AfterCodes.Add((object) $"G0 X{buProfileCalc.varProfileSettings.ParkPositionX.ToString("f2")} Y{buProfileCalc.varProfileSettings.ParkPositionY.ToString("f2")} G0 A0  ( X Y A Go Park Position )");
                      C.AfterCodes.Add((object) "M40 M41 M42 M43");
                      C.AfterCodes.Add((object) "M44 M45");
                      C.AfterCodes.Add((object) "M30");
                      continue;
                    default:
                      continue;
                  }
                }
              }
            }
            else if (index2 == Item.CalculationData[index1].calcOperations.Count - 1)
            {
              switch (ProfileIndex)
              {
                case 0:
                  if (SecondAvailable)
                  {
                    C.AfterCodes.Add((object) "M05 ( Stop Spindle )");
                    C.AfterCodes.Add((object) $"G0 Z{ZParkPosAfterKinematic.ToString("f2")} ( go Z-save )");
                    C.AfterCodes.Add((object) $"G0 X{buProfileCalc.varProfileSettings.ParkPositionX.ToString("f2")} Y{buProfileCalc.varProfileSettings.ParkPositionY.ToString("f2")} G0 A0  ( X Y A Go Park Position )");
                    continue;
                  }
                  C.AfterCodes.Add((object) "M05 ( Stop Spindle )");
                  C.AfterCodes.Add((object) $"G0 Z{ZParkPosAfterKinematic.ToString("f2")} ( go Z-save )");
                  C.AfterCodes.Add((object) $"G0 X{buProfileCalc.varProfileSettings.ParkPositionX.ToString("f2")} Y{buProfileCalc.varProfileSettings.ParkPositionY.ToString("f2")} G0 A0  ( X Y A Go Park Position )");
                  C.AfterCodes.Add((object) "M40 M41 M42 M43");
                  C.AfterCodes.Add((object) "M44 M45");
                  C.AfterCodes.Add((object) "M30");
                  continue;
                case 1:
                  C.AfterCodes.Add((object) "M05 ( Stop Spindle )");
                  C.AfterCodes.Add((object) $"G0 Z{ZParkPosAfterKinematic.ToString("f2")} ( go Z-save )");
                  C.AfterCodes.Add((object) $"G0 X{buProfileCalc.varProfileSettings.ParkPositionX.ToString("f2")} Y{buProfileCalc.varProfileSettings.ParkPositionY.ToString("f2")} G0 A0  ( X Y A Go Park Position )");
                  C.AfterCodes.Add((object) "M40 M41 M42 M43");
                  C.AfterCodes.Add((object) "M44 M45");
                  C.AfterCodes.Add((object) "M30");
                  continue;
                default:
                  continue;
              }
            }
          }
        }
      }
      if (!buProfileCalc.varProfileSettings.AutoCloseWater)
      {
        Item.CalculationData[index1].Cams[Item.CalculationData[index1].Cams.Count - 1].CamPoints[Item.CalculationData[index1].Cams[Item.CalculationData[index1].Cams.Count - 1].CamPoints.Count - 1].AfterCodes.Add((object) "M9 (Cooler Off)");
      }
      else
      {
