    }
    if (buProfileCalc.varProfileSettings.ParabolicMoveBetweenPlanes)
      this.doCreateParabolicMoves(ref Item);
    PostProcessor tempPost = new PostProcessor(ccVars.PostActive);
    this.doAddInfoCodeKabanMode2(ref Item, ref tempPost, ProfileIndex, ZParkPosAfterKinematic, AddToolInfo);
    if (SecondAvailable)
      tempPost.EndLines.Clear();
    GCodeStr = "";
    ArrayList arrayList1 = new ArrayList();
    tempPost.PositionDef.PositionType = PositionPostType.G90;
    if (buProfileCalc.varProfileSettings.G91Mode)
    {
      tempPost.PositionDef.PositionType = PositionPostType.G91AfterG0;
      tempPost.PositionDef.G90Def.Clear();
      tempPost.PositionDef.G90Def.Add("G90");
      tempPost.PositionDef.G91Def.Clear();
      tempPost.PositionDef.G91Def.Add("G91");
    }
    for (int index10 = 0; index10 <= Item.CalculationData.Count - 1; ++index10)
    {
      if (index10 > 0)
        tempPost.StartLines.Clear();
      Item.CalculationData[index10].GCodesItem.Clear();
      for (int index11 = 0; index11 <= Item.CalculationData[index10].Cams.Count - 1; ++index11)
      {
        Item.CalculationData[index10].Cams[index11].ToolPreCodes.Add((object) $"( Tool No : {Item.CalculationData[index10].Cams[index11].Tool.Data.No.ToString()} - {Item.CalculationData[index10].Cams[index11].Tool.Data.Name} )");
        Item.CalculationData[index10].Cams[index11].SpindlePreCodes.Clear();
        Item.CalculationData[index10].Cams[index11].SpindlePreCodes.Add((object) $"( Start Spindle : {Item.CalculationData[index10].Cams[index11].Tool.CamData.SpindleSpeed.ToString()} Rpm )");
