        tempPost.NumberDef.Start = 10.0;
      clsInit.cGcodeCreate.CreatGCode(Item.CalculationData[index10].Cams, tempPost, ref Lines);
      buString5.StringToListByNewLine(Lines, ref Item.CalculationData[index10].GCodesItem);
      if (Item.CalculationData[index10].GCodesItem.Count > 1)
      {
        if (Item.CalculationData[index10].GCodesItem[Item.CalculationData[index10].GCodesItem.Count - 1].ToString().Trim().Length == 0)
          Item.CalculationData[index10].GCodesItem.RemoveAt(Item.CalculationData[index10].GCodesItem.Count - 1);
        if (Item.CalculationData[index10].GCodesItem[Item.CalculationData[index10].GCodesItem.Count - 1].ToString().Trim().Length == 0)
          Item.CalculationData[index10].GCodesItem.RemoveAt(Item.CalculationData[index10].GCodesItem.Count - 1);
      }
      if (Item.CalculationData[index10].GCodesItem.Count > 1)
      {
        double num = 0.0;
        if (Item.CalculationData[index10].GCodesItem[Item.CalculationData[index10].GCodesItem.Count - 1].ToString().Trim().Length > 0)
        {
          buString5.ReadCharValue(Item.CalculationData[index10].GCodesItem[Item.CalculationData[index10].GCodesItem.Count - 1].ToString(), "N", ref num);
          buProfileCalc.varTemps.LastGCodeLine = (int) num;
        }
        else if (Item.CalculationData[index10].GCodesItem[Item.CalculationData[index10].GCodesItem.Count - 2].ToString().Trim().Length > 0)
        {
          buString5.ReadCharValue(Item.CalculationData[index10].GCodesItem[Item.CalculationData[index10].GCodesItem.Count - 2].ToString(), "N", ref num);
          buProfileCalc.varTemps.LastGCodeLine = (int) num;
        }
        GCodeStr = GCodeStr.Length <= 0 ? buString5.StringListToString(Item.CalculationData[index10].GCodesItem, true) : GCodeStr + Environment.NewLine + buString5.StringListToString(Item.CalculationData[index10].GCodesItem, true);
      }
    }
    if (clsItem.FrmProgress == null)
      return;
    clsItem.FrmProgress.Visible = false;
  }

  public void doCalculateCamPointsKabanMode2(
    ref camTp C,
    ref buEyeBaseVer5.Apps.ProfileItem Item,
    ref GProfileOperation OP,
    ref TpPnt9D lastCamP9,
    int i,
    int y,
    bool ToolMilling,
    double ZParkPosAfterKinematic,
    bool CreateGCode)
  {
    if (ToolMilling)
    {
      for (int index1 = 0; index1 <= C.CamPoints.Count - 1; ++index1)
      {
        for (int index2 = 0; index2 <= C.CamPoints[index1].Points.Count - 1; ++index2)
        {
          Pnt9D pnt9D = new Pnt9D(C.CamPoints[index1].Points[index2].P9);
          OrientationAngle Orientation = new OrientationAngle(C.CamPoints[index1].Points[index2].P9.A, 0.0, 0.0);
          Point3D MovePoint = new Point3D(C.CamPoints[index1].Points[index2].P9.X, C.CamPoints[index1].Points[index2].P9.Y, C.CamPoints[index1].Points[index2].P9.Z);
          Pnt6D CalcPoint = new Pnt6D();
          clsInit.cKinematic5.ForwardKinematix4Ax(C.Tool.Geometry.TotalLength, ccVars.KinematicOrjinal, VectorType.XVector, Orientation, MovePoint, ref CalcPoint);
          Pnt9D Pnt = new Pnt9D(CalcPoint.X, CalcPoint.Y, CalcPoint.Z, CalcPoint.A, CalcPoint.B, CalcPoint.C);
          if (Item.CalculationData[y].calcOperations[i].OperationData.selectedPlaneName == planeNames.Top)
          {
            C.CamPoints[index1].Points[index2].PostOffsets.Z = -Item.ProfileMaxPoint.Z;
            if (index1 == 0 & index2 == 0)
            {
              C.CamPoints[index1].PreCodes.Add((object) $"G68.2 P1 X0 Y0 Z{Item.ProfileMaxPoint.Z.ToString()} I0 J0 K0                 (side transformation on)");
              C.CamPoints[index1].PreCodes.Add((object) "#800=0");
              C.CamPoints[index1].PreCodes.Add((object) "#801=0");
              C.CamPoints[index1].PreCodes.Add((object) ("#802=" + Item.ProfileMaxPoint.Z.ToString("f2")));
              C.CamPoints[index1].PreCodes.Add((object) "#803=0");
              C.CamPoints[index1].PreCodes.Add((object) "#804=0");
              C.CamPoints[index1].PreCodes.Add((object) "#805=0");
              C.CamPoints[index1].PreCodes.Add((object) "G53.1 P2");
              C.CamPoints[index1].PreCodes.Add((object) "806=2");
              C.CamPoints[index1].PreCodes.Add((object) "G43 H1");
              C.CamPoints[index1].PreCodes.Add((object) "#807=1");
            }
            C.CamPoints[index1].Points[index2].PlungeAxis = "Z";
          }
          if (Item.CalculationData[y].calcOperations[i].OperationData.selectedPlaneName == planeNames.Front)
          {
            C.CamPoints[index1].Points[index2].PostOffsets.Z = Item.ProfileMaxPoint.Z;
            C.CamPoints[index1].Points[index2].YChar = "Z";
            C.CamPoints[index1].Points[index2].ZChar = "Y";
            if (index1 == 0 & index2 == 0)
            {
              C.CamPoints[index1].PreCodes.Add((object) $"G68.2 P1 X0 Y0 Z{Item.ProfileMaxPoint.Z.ToString()} I90 J0 K0                 (side transformation on)");
              C.CamPoints[index1].PreCodes.Add((object) "#800=0");
              C.CamPoints[index1].PreCodes.Add((object) "#801=0");
              C.CamPoints[index1].PreCodes.Add((object) ("#802=" + Item.ProfileMaxPoint.Z.ToString("f2")));
              C.CamPoints[index1].PreCodes.Add((object) "#803=90");
              C.CamPoints[index1].PreCodes.Add((object) "#804=0");
              C.CamPoints[index1].PreCodes.Add((object) "#805=0");
              C.CamPoints[index1].PreCodes.Add((object) "G53.1 P2");
              C.CamPoints[index1].PreCodes.Add((object) "806=2");
              C.CamPoints[index1].PreCodes.Add((object) "G43 H1");
              C.CamPoints[index1].PreCodes.Add((object) "#807=1");
            }
            C.CamPoints[index1].Points[index2].PlungeAxis = "Y";
          }
          if (Item.CalculationData[y].calcOperations[i].OperationData.selectedPlaneName == planeNames.Back)
          {
            C.CamPoints[index1].Points[index2].PostOffsets.Z = Item.ProfileMaxPoint.Z;
            C.CamPoints[index1].Points[index2].YChar = "Z";
            C.CamPoints[index1].Points[index2].ZChar = "Y";
            if (index1 == 0 & index2 == 0)
            {
              C.CamPoints[index1].PreCodes.Add((object) $"G68.2 P1 X0 Y0 Z{Item.ProfileMaxPoint.Z.ToString()} I-90 J0 K0                 (side transformation on)");
              C.CamPoints[index1].PreCodes.Add((object) "#800=0");
              C.CamPoints[index1].PreCodes.Add((object) "#801=0");
              C.CamPoints[index1].PreCodes.Add((object) ("#802=" + Item.ProfileMaxPoint.Z.ToString("f2")));
              C.CamPoints[index1].PreCodes.Add((object) "#803=-90");
              C.CamPoints[index1].PreCodes.Add((object) "#804=0");
              C.CamPoints[index1].PreCodes.Add((object) "#805=0");
              C.CamPoints[index1].PreCodes.Add((object) "G53.1 P2");
              C.CamPoints[index1].PreCodes.Add((object) "806=2");
              C.CamPoints[index1].PreCodes.Add((object) "G43 H1");
              C.CamPoints[index1].PreCodes.Add((object) "#807=1");
            }
            C.CamPoints[index1].Points[index2].PlungeAxis = "Y";
          }
          if (Item.CalculationData[y].calcOperations[i].OperationData.selectedPlaneName == planeNames.Free)
            C.CamPoints[index1].Points[index2].PlungeAxis = "";
          if (OP.OperationData.OperationType == ProfileOperationTypes.Tapping && C.CamPoints[index1].Points[index2].PlungeAxisMovement)
          {
            C.CamPoints[index1].Points[index2].Type = 0;
            double num = OP.OperationData.HoleData.TappingDepth;
            if (OP.OperationData.selectedPlaneName == planeNames.Top && index2 > 0)
              num = C.CamPoints[index1].Points[index2 - 1].P9.Z - Pnt.Z;
            if (OP.OperationData.selectedPlaneName == planeNames.Front | OP.OperationData.selectedPlaneName == planeNames.Back && index2 > 0)
              num = Math.Abs(C.CamPoints[index1].Points[index2 - 1].P9.Y - Pnt.Y);
            C.CamPoints[index1].Points[index2].OverWriteString = $"M80 X{OP.OperationData.HoleData.TappingPitch.ToString("f2")} Y{(-num).ToString("f2")} Z{OP.Tool.CamData.SpindleSpeed.ToString("")}";
          }
          C.CamPoints[index1].Points[index2].P9 = new Pnt9D(Pnt);
          if (index1 == C.CamPoints.Count - 1 & index2 == C.CamPoints[index1].Points.Count - 1)
          {
            C.CamPoints[index1].Points[index2].PreCodes.Add((object) "G90");
            C.CamPoints[index1].Points[index2].PreCodes.Add((object) "G69");
            C.CamPoints[index1].Points[index2].PreCodes.Add((object) "G05 P0");
            C.CamPoints[index1].Points[index2].PreCodes.Add((object) "G49");
          }
        }
      }
      lastCamP9 = C.CamPoints[C.CamPoints.Count - 1].Points[C.CamPoints[C.CamPoints.Count - 1].Points.Count - 1];
    }
    else
    {
      for (int index3 = 0; index3 <= C.CamPoints.Count - 1; ++index3)
      {
        for (int index4 = 0; index4 <= C.CamPoints[index3].Points.Count - 1; ++index4)
        {
          if (Item.CalculationData[y].calcOperations[i].OperationData.NotchData.NotchOPType == ProfileNotchOperationType.Side | Item.CalculationData[y].calcOperations[i].OperationData.NotchData.NotchOPType == ProfileNotchOperationType.Length)
          {
            Pnt9D Pnt = new Pnt9D(C.CamPoints[index3].Points[index4].P9);
            double num = ccVars.KinematicOrjinal.RotateCenterOffsetOfA.Z + C.Tool.Geometry.TotalLength;
            Pnt.Z += num;
            C.CamPoints[index3].Points[index4].PlungeAxis = "X";
            C.CamPoints[index3].Points[index4].P9 = new Pnt9D(Pnt);
          }
          if (Item.CalculationData[y].calcOperations[i].OperationData.NotchData.NotchOPType == ProfileNotchOperationType.Vertical)
          {
            Pnt9D Pnt = new Pnt9D(C.CamPoints[index3].Points[index4].P9);
            if (Item.CalculationData[y].calcOperations[i].OperationData.selectedPlaneName == planeNames.Front | Item.CalculationData[y].calcOperations[i].OperationData.selectedPlaneName == planeNames.Back)
            {
              double num = (ccVars.KinematicOrjinal.RotateCenterOffsetOfA.Z + C.Tool.Geometry.TotalLength) * Math.Sin(buConversion5.DegreeToRadian(Pnt.A));
              Pnt.Y -= num;
              C.CamPoints[index3].Points[index4].PlungeAxis = "X";
            }
            if (index4 == C.CamPoints[index3].Points.Count - 1)
              Pnt.Z = ZParkPosAfterKinematic;
            C.CamPoints[index3].Points[index4].P9 = new Pnt9D(Pnt);
          }
          if (Item.CalculationData[y].calcOperations[i].OperationData.NotchData.NotchOPType == ProfileNotchOperationType.Horizontal)
          {
            Pnt9D Pnt = new Pnt9D(C.CamPoints[index3].Points[index4].P9);
            double num = (ccVars.KinematicOrjinal.RotateCenterOffsetOfA.Z + C.Tool.Geometry.TotalLength) * Math.Sin(buConversion5.DegreeToRadian(Pnt.A));
            Pnt.Y -= num;
            C.CamPoints[index3].Points[index4].PlungeAxis = "Z";
            C.CamPoints[index3].Points[index4].P9 = new Pnt9D(Pnt);
          }
        }
      }
    }
    if (Item.CalculationData[y].XReferanceLocation == LeftRightType.Right & CreateGCode)
    {
