  }

  public void doSaveGcodeKabanMode2(bool ShowCode)
  {
    try
    {
      if (clsVar.appModes_0.DemoMode)
      {
        int num1 = (int) MessageBox.Show(buLangTranslate.preSentences.NotAvailableDemoMode);
      }
      else if (ccVars.Pages.Count <= 0)
        buString5.MessageBoxWarning(AppLanguage.Messages[9]);
      else if (this.activeProfile.FirstItem == null & this.activeProfile.SecondItem == null)
        buString5.MessageBoxWarning(buProfile.LangProfileMessage[12]);
      else if (!this.activeProfile.isSimulationDone & AppSecurity.PasswordLevel == 0)
      {
        buString5.MessageBoxWarning(buProfile.LangProfileMessage[13]);
      }
      else
      {
        bool flag = false;
        bool SecondAvailable = false;
        if ((this.activeProfile.FirstItem == null || !this.activeProfile.FirstItem.Enable ? 0 : (this.activeProfile.FirstItem.Operations.Count > 0 ? 1 : 0)) != 0)
          flag = true;
        if ((this.activeProfile.SecondItem == null || !this.activeProfile.SecondItem.Enable ? 0 : (this.activeProfile.SecondItem.Operations.Count > 0 ? 1 : 0)) != 0)
          SecondAvailable = true;
        if (flag && this.activeProfile.FirstItem.isError)
          buString5.MessageBoxWarning($"{buLangTranslate.preDef.First} {buLangTranslate.preDef.Profile} {buProfile.LangProfileMessage[14]}");
        else if (SecondAvailable && this.activeProfile.SecondItem.isError)
        {
          buString5.MessageBoxWarning($"{buLangTranslate.preDef.Second} {buLangTranslate.preDef.Profile} {buProfile.LangProfileMessage[14]}");
        }
        else
        {
          SaveFileDialog saveFileDialog = new SaveFileDialog();
          saveFileDialog.InitialDirectory = clsVar.varInterface.pathGCode;
          saveFileDialog.Filter = $"{ccVars.PostActive.FileExplanation} ({ccVars.PostActive.FileExtension})|{ccVars.PostActive.FileExtension}";
          saveFileDialog.FilterIndex = 1;
          DialogResult dialogResult = DialogResult.None;
          if (!ShowCode)
            dialogResult = saveFileDialog.ShowDialog();
          if (!(dialogResult == DialogResult.OK | ShowCode))
            return;
          string FileName = $"{buFile5.GetPath(saveFileDialog.FileName)}\\{buFile5.getFileNameWithoutExtension(saveFileDialog.FileName)}.stl";
          if (buProfileCalc.varProfileSettings.SaveStlFileWhileCreatingCode)
            buFile5.SaveStl((Design) ccVars.Pages[ccVars.PageIndex].Form.viewportcad, FileName);
          if (buProfileCalc.varProfileSettings.SaveImageFileWhileCreatingCode)
          {
            string filePath = $"{buFile5.GetPath(saveFileDialog.FileName)}\\{buFile5.getFileNameWithoutExtension(saveFileDialog.FileName)}.png";
            ccVars.Pages[ccVars.PageIndex].Form.viewportcad.WriteToFileRaster((float) buProfileCalc.varProfileSettings.ImageScaleFactor, filePath, ImageFormat.Png);
          }
          ArrayList GCodes1 = new ArrayList();
          ArrayList GCodes2 = new ArrayList();
          int num2 = 0;
          buProfileCalc.varTemps.LastGCodeLine = 0;
          ccVars.PostActive.NumberDef.Start = 10.0;
          ProfileTempVars.LastClampers.Clear();
          if (flag)
          {
            this.doCreateCode(this.activeProfile.FirstItem, ccVars.PostActive.Mode, ref GCodes1, 0, SecondAvailable, true, ShowCode);
            int num3 = num2 + 1;
          }
          if (SecondAvailable)
            this.doCreateCode(this.activeProfile.SecondItem, ccVars.PostActive.Mode, ref GCodes2, 1, false, true, ShowCode);
          if (flag & SecondAvailable)
          {
            ArrayList CalcList1 = new ArrayList();
            ArrayList CalcList2 = new ArrayList();
            ArrayList CalcList3 = new ArrayList();
            ArrayList CalcList4 = new ArrayList();
            buString5.ListToSpecificList("<GCodes>", "</GCodes>", false, GCodes1, ref CalcList1);
            buString5.ListToSpecificList("<GCodes>", "</GCodes>", false, GCodes2, ref CalcList2);
            buString5.ListToSpecificList("<ProfileCode>", "</ProfileCode>", false, GCodes1, ref CalcList3);
            buString5.ListToSpecificList("<ProfileCode>", "</ProfileCode>", false, GCodes2, ref CalcList4);
            GCodes1.AddRange((ICollection) GCodes2);
          }
          else
            GCodes1.AddRange((ICollection) GCodes2);
          if (this.activeProfile.GCodes == null)
            this.activeProfile.GCodes = new ArrayList();
          this.activeProfile.GCodes.Clear();
          this.activeProfile.GCodes = buString5.Copy(GCodes1);
          clsVar.varInterface.pathGCode = buFile5.GetPath(saveFileDialog.FileName);
          if (!ShowCode)
          {
            buFile5.SaveToFile(GCodes1, saveFileDialog.FileName);
          }
          else
          {
            F_Notepad fNotepad = new F_Notepad();
            fNotepad.Init(GCodes1);
            fNotepad.Show();
          }
          GCodes1.Clear();
          clsFiles.SaveParameter();
        }
      }
    }
    catch (Exception ex)
    {
      buLog.addLog("", "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, true, "");
    }
  }

